#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0 0x4000   // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0200 // PGA = ±4.096V
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0060  // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACTV_LOW 0x0000 // Active low comparator polarity
#define CONFIG_COMP_LAT_NON_LATCH 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADS1115
int16_t read_register(int handle, uint8_t reg) {
    char buf[2];
    buf[0] = reg;
    if (i2cWriteI2CBlockData(handle, reg, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %d\n", reg);
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading register: %d\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to write a 16-bit value to the ADS1115
int write_register(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteI2CBlockData(handle, reg, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register: %d\n", reg);
        return -1;
    }
    return 0;
}

// Function to configure the ADS1115
int configure_ads1115(int handle) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;
    if (write_register(handle, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        return -1;
    }
    return 0;
}

// Function to read the current from the MLX91219
float read_current(int handle) {
    // Start a single conversion
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACTV_LOW | CONFIG_COMP_LAT_NON_LATCH | CONFIG_COMP_QUE_DISABLE;
    if (write_register(handle, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Error starting conversion\n");
        return -1.0;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    int16_t raw_value = read_register(handle, ADS1115_REG_CONVERT);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading conversion result\n");
        return -1.0;
    }

    // Convert raw value to current (Amperes)
    float current = (float)raw_value * 4.096 / 32768.0 * 1000.0 / 40.0;
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float current = read_current(i2c_handle);
        if (current != -1.0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading current\n");
        }

        gpioDelay(500000); // 500ms
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

