#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define SPI_CE 0 // CE0

// Define SPI parameters
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define temperature range
#define MIN_TEMP 10.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    return MIN_TEMP + (float)adc_value * (MAX_TEMP - MIN_TEMP) / 1023.0;
}

// Function to log data to CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set flame sensor pin as input
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read MCP3008 ADC
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read MCP3008, skipping log entry\n");
            gpioDelay(1000); // Wait 1 second
            continue; // Skip to the next iteration
        }

        // Calculate temperature
        float temperature = calculate_temperature(adc_value);

        // Log data
        log_data(flame_detected, temperature);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

