#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000 // Start single conversion
#define ADS1115_CONFIG_GAIN_4_096 0x0200 // Gain = ±4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128 0x0060      // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

#define TEMP_THRESHOLD 60.0
#define FLAME_THRESHOLD 0 // Flame detected when LOW
#define DEBOUNCE_DELAY 50 // Debounce delay in milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned long last_flame_time = 0;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int init_ads1115();
int read_flame_sensor();
float read_temperature();
void flame_isr(int gpio, int level, unsigned int tick, void *user);
void log_event(const char *message);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);

// Function to initialize GPIO
int init_gpio() {
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
  gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor
  gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
  gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

  return 0;
}

// Function to initialize I2C
int init_i2c() {
  i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
  if (i2c_handle < 0) {
    fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
    return 1;
  }
  return 0;
}

// Function to initialize ADS1115
int init_ads1115() {
  uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_GAIN_4_096 |
                    ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128 |
                    ADS1115_CONFIG_COMP_QUE_DISABLE;

  // Write the configuration to the ADS1115
  char buf[3];
  buf[0] = ADS1115_CONFIG_REG;
  buf[1] = (config >> 8) & 0xFF; // MSB
  buf[2] = config & 0xFF;        // LSB

  int result = i2cWriteDevice(i2c_handle, buf, 3);
  if (result != 0) {
    fprintf(stderr, "Failed to write to ADS1115: %d\n", result);
    return 1;
  }

  return 0;
}

// Function to read flame sensor
int read_flame_sensor() {
  return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to read temperature from ADS1115
float read_temperature() {
  // Start a single conversion
  uint16_t config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_GAIN_4_096 |
                    ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128 |
                    ADS1115_CONFIG_COMP_QUE_DISABLE;

  char buf[3];
  buf[0] = ADS1115_CONFIG_REG;
  buf[1] = (config >> 8) & 0xFF; // MSB
  buf[2] = config & 0xFF;        // LSB

  int result = i2cWriteDevice(i2c_handle, buf, 3);
  if (result != 0) {
    fprintf(stderr, "Failed to write to ADS1115 for conversion: %d\n", result);
    return NAN; // Return NaN on error
  }

  // Wait for conversion to complete (at least 8.5ms for 128 SPS)
  gpioDelay(10); // Wait 10ms

  // Read the conversion result
  char read_buf[2];
  buf[0] = ADS1115_CONVERSION_REG;
  result = i2cWriteDevice(i2c_handle, buf, 1);
  if (result != 0) {
    fprintf(stderr, "Failed to write to ADS1115 for read: %d\n", result);
    return NAN; // Return NaN on error
  }

  result = i2cReadDevice(i2c_handle, read_buf, 2);
  if (result != 2) {
    fprintf(stderr, "Failed to read from ADS1115: %d\n", result);
    return NAN; // Return NaN on error
  }

  int16_t raw_value = (read_buf[0] << 8) | read_buf[1];

  // Convert raw value to voltage (0-3.3V)
  float voltage = (float)raw_value * 4.096 / 32768.0;

  // Map voltage to temperature (20°C - 80°C)
  float temperature = 20.0 + (voltage / 3.3) * 60.0;

  return temperature;
}

// Interrupt service routine for flame sensor
void flame_isr(int gpio, int level, unsigned int tick, void *user) {
  unsigned long current_time = gpioTick();
  if (level == 0) { // Falling edge detected
    if (current_time - last_flame_time > DEBOUNCE_DELAY * 1000) {
      last_flame_time = current_time;
      // Flame detected after debouncing
      float temperature = read_temperature();
      if (!isnan(temperature)) {
        if (temperature > TEMP_THRESHOLD) {
          // Both flame and temperature exceed threshold
          time_t now = time(NULL);
          struct tm *tstruct = localtime(&now);
          char buf[80];
          strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
          char log_message[256];
          snprintf(log_message, sizeof(log_message), "%s - Fire detected! Flame and temperature exceeded threshold. Temperature: %.2f\u00b0C\n", buf, temperature);
          log_event(log_message);
          activate_buzzer();
          gpioDelay(2000); // Buzzer for 2 seconds
          deactivate_buzzer();
        } else {
          // Only flame detected
          time_t now = time(NULL);
          struct tm *tstruct = localtime(&now);
          char buf[80];
          strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
          char log_message[256];
          snprintf(log_message, sizeof(log_message), "%s - Flame detected!\n", buf);
          log_event(log_message);
        }
      } else {
        // ADC read error already logged in read_temperature()
      }
    }
  }
}

// Function to log events to file
void log_event(const char *message) {
  if (log_file != NULL) {
    fprintf(log_file, "%s", message);
    fflush(log_file); // Ensure immediate write to file
  } else {
    fprintf(stderr, "Error: Log file not opened.\n");
  }
}

// Function to activate the buzzer
void activate_buzzer() {
  gpioWrite(BUZZER_GPIO, 1); // Set GPIO HIGH
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
  gpioWrite(BUZZER_GPIO, 0); // Set GPIO LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
  running = 0;
  printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
  // Initialize signal handler
  signal(SIGINT, signal_handler);

  // Initialize GPIO
  if (init_gpio() != 0) {
    return 1;
  }

  // Initialize I2C
  if (init_i2c() != 0) {
    gpioTerminate();
    return 1;
  }

  // Initialize ADS1115
  if (init_ads1115() != 0) {
    i2cClose(i2c_handle);
    gpioTerminate();
    return 1;
  }

  // Open log file
  log_file = fopen("fire_log.txt", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 1;
  }

  // Set up interrupt service routine for flame sensor
  gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL);

  printf("Fire detection system started. Press Ctrl+C to exit.\n");

  // Main loop
  while (running) {
    float temperature = read_temperature();
    if (!isnan(temperature)) {
      if (temperature > TEMP_THRESHOLD) {
        // Only temperature exceeds threshold
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "%s - Temperature: %.2f\u00b0C\n", buf, temperature);
        log_event(log_message);
      }
    } else {
      // ADC read error already logged in read_temperature()
    }

    gpioDelay(100); // Poll every 100ms
  }

  // Cleanup
  gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable ISR
  deactivate_buzzer();
  i2cClose(i2c_handle);
  fclose(log_file);
  gpioTerminate();

  printf("Exiting.\n");
  return 0;
}

