#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration defaults
#define DEFAULT_SENSITIVITY 0.100f // 100 mV/A
#define DEFAULT_THRESHOLD 5.0f    // 5.0 A
#define DEFAULT_SPI_DEVICE "/dev/spidev0.0"
#define DEFAULT_GPIO_CHIP "gpiochip4"
#define DEFAULT_GPIO_PIN 18

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Configuration structure
typedef struct {
    float sensitivity;
    float threshold;
    char *spi_device;
    char *gpio_chip_name;
    int gpio_pin;
} Config;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_adc(int fd);
float adc_to_current(int adc_value, float sensitivity);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(int pin, int value);
int gpio_close(void);
void log_data(float current, float threshold, int fan_state);
void signal_handler(int sig);
void cleanup(void);
void parse_arguments(int argc, char *argv[], Config *config);

// SPI initialization function
int spi_init(const char *device) {
    int fd;
    uint8_t mode = 0;
    uint8_t bits = 8;
    uint32_t speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADC read function
int read_adc(int fd) {
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3] = {0};

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value, float sensitivity) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    float current = voltage / sensitivity;
    return current;
}

// GPIO initialization function
int gpio_init(const char *chip_name, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "current_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO close function
int gpio_close(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    return 0;
}

// Log data function
void log_data(float current, float threshold, int fan_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s, Current: %.3f A, Threshold: %.3f A, Fan: %s\n",
            timestamp, current, threshold, fan_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpio_set_value(DEFAULT_GPIO_PIN, 0); // Turn off fan on exit
    }
    gpio_close();
    if (log_file) {
        fclose(log_file);
    }
}

// Parse command-line arguments
void parse_arguments(int argc, char *argv[], Config *config) {
    int opt;

    config->sensitivity = DEFAULT_SENSITIVITY;
    config->threshold = DEFAULT_THRESHOLD;
    config->spi_device = DEFAULT_SPI_DEVICE;
    config->gpio_chip_name = DEFAULT_GPIO_CHIP;
    config->gpio_pin = DEFAULT_GPIO_PIN;

    while ((opt = getopt(argc, argv, "s:t:d:c:p:")) != -1) {
        switch (opt) {
            case 's':
                config->sensitivity = atof(optarg);
                break;
            case 't':
                config->threshold = atof(optarg);
                break;
            case 'd':
                config->spi_device = optarg;
                break;
            case 'c':
                config->gpio_chip_name = optarg;
                break;
            case 'p':
                config->gpio_pin = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold] [-d spi_device] [-c gpio_chip] [-p gpio_pin]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

