    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value, config.sensitivity);

        // Check for sensor absence
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected.\n");
        }

        // Control fan based on current threshold
        int fan_state = (current > config.threshold) ? 1 : 0;
        if (gpio_set_value(config.gpio_pin, fan_state) < 0) {
            fprintf(stderr, "Error setting fan state.\n");
        }

        // Log data
        log_data(current, config.threshold, fan_state);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

