#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CO_CHANNEL 0 // AIN0
#define LOG_FILE "co_log.txt"

// Calibration curve parameters (example values, replace with your sensor's data)
#define A 0.01
#define B 0.5
#define C 10.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ads1115_address;
    char *log_file;
} config_t;

// Function prototypes
int initialize_i2c(config_t *config);
int read_adc(int channel);
float calculate_ppm(int raw_value);
int log_data(float ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure ADS1115 for single-ended mode, 4.096V range, 128 SPS
    // 0x4003:  Single-shot mode, AIN0, +/-4.096V, 128 SPS
    char config_data[3];
    config_data[0] = (0x04 | (CO_CHANNEL << 1)) << 4; // MSB of config register
    config_data[1] = 0x03; // LSB of config register
    config_data[2] = 0x83; // Enable single conversion

    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_data, 3) < 0) {
        fprintf(stderr, "Failed to write to config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc(int channel) {
    // Start a single conversion
    char config_data[3];
    config_data[0] = (0x04 | (channel << 1)) << 4; // MSB of config register
    config_data[1] = 0x03; // LSB of config register
    config_data[2] = 0x83; // Enable single conversion

    if (i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_data, 3) < 0) {
        fprintf(stderr, "Failed to write to config register for conversion\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read conversion register\n");
        return -1;
    }

    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Calculate CO concentration in PPM using a logarithmic curve
float calculate_ppm(int raw_value) {
    // Logarithmic curve: PPM = A * log(B * raw_value + C)
    return A * log(B * raw_value + C);
}

// Log data to file
int log_data(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .log_file = LOG_FILE
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c(&config) != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read raw ADC value
        int raw_value = read_adc(CO_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Try again
        }

        // Calculate PPM
        float ppm = calculate_ppm(raw_value);

        // Log data
        if (log_data(ppm) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("CO concentration: %.2f PPM\n", ppm);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

