#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define I2C addresses for the two microphones
#define MICROPHONE_1_ADDRESS 0x48
#define MICROPHONE_2_ADDRESS 0x49

// Define the I2C bus
#define I2C_BUS 1

// Define the register to read from (0x00)
#define READ_REGISTER 0x00

// Define the microphone sensitivity in dBV/Pa
#define MICROPHONE_SENSITIVITY -38.0

// Define the reference pressure in Pa
#define REFERENCE_PRESSURE 20e-6

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL 100

// Global variables for I2C handles and program state
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_microphone_data(int i2c_handle);
float calculate_sound_pressure_level(int raw_data);
float average_sound_pressure_levels(float level1, float level2);
void log_data(float average_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close I2C handles if they are open
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read microphone data from the I2C bus
int read_microphone_data(int i2c_handle) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, READ_REGISTER, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -999; // Indicate an error
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (buffer[0] << 8) | buffer[1];

    return raw_data;
}

// Function to calculate the sound pressure level in dB
float calculate_sound_pressure_level(int raw_data) {
    // Convert raw data to voltage (assuming 16-bit ADC and 3.3V range)
    float voltage = (float)raw_data / 32767.0 * 3.3;

    // Calculate the sound pressure level in dB
    float sound_pressure_level = 20 * log10(voltage / (REFERENCE_PRESSURE * pow(10, MICROPHONE_SENSITIVITY / 20.0)));

    return sound_pressure_level;
}

// Function to average the sound pressure levels from the two microphones
float average_sound_pressure_levels(float level1, float level2) {
    return (level1 + level2) / 2.0;
}

// Function to log the data to a file
void log_data(float average_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening audio_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, average_level);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for the two microphones
    i2c_handle_1 = i2cOpen(I2C_BUS, MICROPHONE_1_ADDRESS, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, MICROPHONE_2_ADDRESS, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read data from the microphones
        int raw_data_1 = read_microphone_data(i2c_handle_1);
        int raw_data_2 = read_microphone_data(i2c_handle_2);

        // Calculate sound pressure levels
        float level1 = (raw_data_1 == -999) ? -999.0 : calculate_sound_pressure_level(raw_data_1);
        float level2 = (raw_data_2 == -999) ? -999.0 : calculate_sound_pressure_level(raw_data_2);

        // Average the sound pressure levels
        float average_level = average_sound_pressure_levels(level1, level2);

        // Log the data
        log_data(average_level);

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // Convert milliseconds to microseconds
    }

    // Close I2C handles and terminate pigpio (should not reach here if signal handler works)
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

