#define SAMPLE_RATE_MS 1
#define WINDOW_DURATION_MS 100
#define NUM_SAMPLES (WINDOW_DURATION_MS / SAMPLE_RATE_MS)
#define RMS_THRESHOLD 0.7
#define LED_ON_DURATION_MS 500

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int gpio, int on);
void log_data(FILE *fp, time_t timestamp, double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to control the LED
void control_led(int gpio, int on) {
    gpioWrite(gpio, on);
}

// Function to log data to CSV file
void log_data(FILE *fp, time_t timestamp, double mic1_rms, double mic2_rms) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f\n", timestamp_str, mic1_rms, mic2_rms);
    fflush(fp); // Ensure data is written to file immediately
}

