    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error: SPI0 open failed\n");
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // CE1
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error: SPI1 open failed\n");
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Sampling loop
    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    time_t start_time, current_time;
    int sample_index = 0;

    time(&start_time);

    while (!terminate) {
        // Read ADC values
        int mic1_value = read_mcp3008(spi_handle_0, 0);
        int mic2_value = read_mcp3008(spi_handle_1, 0);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on ADC read error
        }

        mic1_samples[sample_index] = mic1_value;
        mic2_samples[sample_index] = mic2_value;

        sample_index++;

        if (sample_index == NUM_SAMPLES) {
            // Calculate RMS values
            double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
            double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

            // Normalize RMS values (assuming 10-bit ADC, 0-1023 range)
            mic1_rms /= 1023.0;
            mic2_rms /= 1023.0;

            // Check threshold and control LED
            if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
                gpioDelay(LED_ON_DURATION_MS * 1000); // Delay for 500 ms
                control_led(LED_GPIO, 0); // Turn LED off
            }

            // Log data
            time(&current_time);
            log_data(log_file, current_time, mic1_rms, mic2_rms);

            // Reset sample index
            sample_index = 0;
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 1 ms
    }

    // Cleanup
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

