#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100
#define OVERCURRENT_THRESHOLD 50.0 // Amperes
#define VREF 5.0 // Reference voltage for ADS1115
#define MAX_CURRENT 100.0 // Maximum current range of the sensor

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void add_to_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    unsigned int os : 1;   // Operational status/single-shot start
    unsigned int mux : 3;  // Input multiplexer configuration
    unsigned int pga : 3;  // Programmable gain amplifier configuration
    unsigned int mode : 1; // Device operating mode
    unsigned int dr : 3;   // Data rate
    unsigned int comp_mode : 1; // Comparator mode
    unsigned int comp_pol : 1; // Comparator polarity
    unsigned int comp_lat : 1; // Comparator latch enabled
    unsigned int comp_que : 2; // Comparator queue/conversion
} ads1115_config_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        int raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            float average_current = calculate_average_current();
            control_led(average_current);
            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read ADS1115 value\n");
        }

        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 128 SPS
    ads1115_config_t config;
    config.os = 1;        // Start single conversion
    config.mux = 4;       // AIN0 (single-ended)
    config.pga = 1;       // +/-4.096V
    config.mode = 0;      // Continuous conversion
    config.dr = 3;        // 128 SPS
    config.comp_mode = 0; // Traditional comparator
    config.comp_pol = 0;  // Active low
    config.comp_lat = 0;  // Non-latching comparator
    config.comp_que = 3;  // Disable comparator

    unsigned short config_value = (config.os << 15) | (config.mux << 12) | (config.pga << 9) | (config.mode << 8) | (config.dr << 5) | (config.comp_mode << 4) | (config.comp_pol << 3) | (config.comp_lat << 2) | config.comp_que;

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return 1;
    }

    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int *raw_value) {
    char buf[1];
    char read_buf[2];

    buf[0] = CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return 1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return 1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw ADC value to current in Amperes
float convert_to_current(int raw_value) {
    float voltage = (float)raw_value / 32767.0 * VREF; // Assuming 16-bit ADC
    float current = (voltage - 0.5) / (4.5 - 0.5) * MAX_CURRENT;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

