    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (tcs34725_read_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

