#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define MCP3008_CS_PIN 8

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables for cleanup
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
int log_moisture_data(float moisture1, float moisture2);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Assert CS line
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS line");
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    // De-assert CS line
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS line");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log moisture data to CSV file
int log_moisture_data(float moisture1, float moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for CS
    cs_line = gpiod_chip_get_line(gpio_chip, MCP3008_CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(cs_line, "moisture_sensor", 1) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Open log file
    log_file = fopen("moisture_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read ADC values
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Map ADC values to moisture percentages
        float moisture1 = map_adc_to_moisture(adc_value1);
        float moisture2 = map_adc_to_moisture(adc_value2);

        // Log moisture data
        if (log_moisture_data(moisture1, moisture2) != 0) {
            fprintf(stderr, "Error logging moisture data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

