    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for CS
    cs_line = gpiod_chip_get_line(gpio_chip, MCP3008_CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(cs_line, "moisture_sensor", 1) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Open log file
    log_file = fopen("moisture_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        close(spi_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(cs_line);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read ADC values
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Map ADC values to moisture percentages
        float moisture1 = map_adc_to_moisture(adc_value1);
        float moisture2 = map_adc_to_moisture(adc_value2);

        // Log moisture data
        if (log_moisture_data(moisture1, moisture2) != 0) {
            fprintf(stderr, "Error logging moisture data. Retrying in 5 seconds.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

