#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 500.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int open_i2c_connection(int bus, int addr);
int read_pressure(int handle, uint16_t *pressure);
float convert_to_kPa(uint16_t raw_value);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(const char* timestamp, float pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Function to open an I2C connection
int open_i2c_connection(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read pressure from the sensor
int read_pressure(int handle, uint16_t *pressure) {
    char buf[2];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            *pressure = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading pressure (register 0x%02X): %d\n", PRESSURE_REG, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to convert raw value to kPa
float convert_to_kPa(uint16_t raw_value) {
    return (raw_value / 65535.0) * SCALE_FACTOR;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Function to log data to a file
int log_data(const char* timestamp, float pressure_kPa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
