    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_pressure;
    float pressure_kPa;
    char timestamp[32];

    // Main loop
    while (!terminate) {
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            get_iso8601_timestamp(timestamp, sizeof(timestamp));
            if (log_data(timestamp, pressure_kPa) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure, skipping logging.\n");
        }

