#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define NUM_SENSORS 2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_ads1115(int channel);
float voltage_to_pressure(int adc_value);
float voltage_to_temperature(int adc_value);
void display_data(float pressure, float temperature);
void control_led(float pressure);
void signal_handler(int signal);
int initialize_i2c();
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function to read from ADS1115
int read_ads1115(int channel) {
    int retries = 3;
    int adc_value = -1;

    // Configuration register value for single-ended mode, AIN0/AIN1, gain 2/3, 128 SPS
    unsigned short config_value;
    if (channel == 0) {
        config_value = 0x4083; // AIN0
    } else {
        config_value = 0x4283; // AIN1
    }

    char config_buf[3];
    config_buf[0] = (config_value >> 8) & 0xFF; // MSB
    config_buf[1] = config_value & 0xFF;      // LSB
    config_buf[2] = 0x00; // Dummy byte for reading conversion register

    while (retries > 0) {
        // Write configuration register
        if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
            fprintf(stderr, "Error writing to ADS1115 config register. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        gpioDelay(10000); // Wait for conversion (at least 8ms for 128 SPS)

        // Read conversion register
        char read_buf[2];
        if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
            fprintf(stderr, "Error reading from ADS1115 conversion register. Retries remaining: %d\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        adc_value = (read_buf[0] << 8) | read_buf[1];
        break; // Success, exit retry loop
    }

    if (adc_value == -1) {
        fprintf(stderr, "Failed to read ADS1115 after multiple retries.\n");
    }

    return adc_value;
}

// Function to convert ADC value to pressure (kPa)
float voltage_to_pressure(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // Vref = 4.096V, 16-bit ADC
    float pressure = voltage * 400.0 / 5.0; // Linear transfer function
    return pressure;
}

// Function to convert ADC value to temperature (°C)
float voltage_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // Vref = 4.096V, 16-bit ADC
    float temperature = (voltage - 1.0) * 100.0; // Linear approximation
    return temperature;
}

// Function to display pressure and temperature data
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
}

// Function to control the warning LED
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO back to input mode
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for the LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn the LED off

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        SensorData sensor_data[NUM_SENSORS];

        // Read pressure from sensor 1 (AIN0)
        int adc_pressure1 = read_ads1115(0);
        if (adc_pressure1 != -1) {
            sensor_data[0].pressure = voltage_to_pressure(adc_pressure1);
        } else {
            sensor_data[0].pressure = -1.0; // Indicate error
        }

        // Read temperature from sensor 1 (AIN1)
        int adc_temperature1 = read_ads1115(1);
        if (adc_temperature1 != -1) {
            sensor_data[0].temperature = voltage_to_temperature(adc_temperature1);
        } else {
            sensor_data[0].temperature = -1.0; // Indicate error
        }

        // Read pressure from sensor 2 (AIN0)
        int adc_pressure2 = read_ads1115(0);
        if (adc_pressure2 != -1) {
            sensor_data[1].pressure = voltage_to_pressure(adc_pressure2);
        } else {
            sensor_data[1].pressure = -1.0; // Indicate error
        }

        // Read temperature from sensor 2 (AIN1)
        int adc_temperature2 = read_ads1115(1);
        if (adc_temperature2 != -1) {
            sensor_data[1].temperature = voltage_to_temperature(adc_temperature2);
        } else {
            sensor_data[1].temperature = -1.0; // Indicate error
        }

        // Display data for sensor 1
        printf("Sensor 1: ");
        if (sensor_data[0].pressure != -1.0 && sensor_data[0].temperature != -1.0) {
            display_data(sensor_data[0].pressure, sensor_data[0].temperature);
            control_led(sensor_data[0].pressure);
        } else {
            fprintf(stderr, "Error reading sensor 1 data.\n");
        }

        // Display data for sensor 2
        printf("Sensor 2: ");
