#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define SENSITIVITY 0.1   // V/kPa
#define OFFSET 0.5        // V
#define MIN_PRESSURE 0.0  // kPa
#define MAX_PRESSURE 100.0 // kPa

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double ref_voltage;
    double sensitivity;
    double offset;
    double min_pressure;
    double max_pressure;
} config_t;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_adc_value();
double convert_to_voltage(int adc_value);
double calculate_pressure(double voltage);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-ended AIN0, 128 SPS, +/- 4.096V
int configure_ads1115() {
    uint16_t config = 0x4003; // Single-shot, AIN0, 128 SPS, +/- 4.096V
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc_value() {
    char buf[1];
    char read_buf[2];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 for conversion register: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Convert ADC value to voltage
double convert_to_voltage(int adc_value) {
    return (adc_value * REF_VOLTAGE) / 32768.0;
}

// Calculate pressure from voltage
double calculate_pressure(double voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Log pressure reading to file
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc_value();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert to voltage
        double voltage = convert_to_voltage(adc_value);

        // Calculate pressure
        double pressure = calculate_pressure(voltage);

        // Validate pressure range
        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            // Log pressure
            log_pressure(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        gpioDelay(1000); // Read at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

