#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define SUPPLY_VOLTAGE 5.0
#define HUMIDITY_THRESHOLD 80.0
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * SUPPLY_VOLTAGE;
    float humidity = (voltage - 0.824) / 0.0315;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * SUPPLY_VOLTAGE;
    float resistance = (SUPPLY_VOLTAGE * 10000.0) / voltage - 10000.0; // Thermistor resistance
    float temperature = 1.0 / (0.001129148 + (0.000234125 + (0.0000000876741 * temperature)) * temperature) - 273.15; // Steinhart-Hart equation
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity exceeded threshold: %.2f%%\" | ssmtp %s", humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error sending email alert (ssmtp returned %d)\n", result);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi()) {
        cleanup();
        return 1;
    }

    fprintf(stderr, "Humidity monitoring started\n");

    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int thermistor_adc = read_mcp3208(MCP3208_CHANNEL_THERMISTOR);

        if (humidity_adc == -1 || thermistor_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(thermistor_adc);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

