#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0 // SPI Mode 0
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define VREF 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 0.3 // 300mV/g = 0.3V/g
#define IMPACT_THRESHOLD 2.0 // g

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int x;
    int y;
    int z;
    double magnitude;
} accelerometer_data_t;

// Function prototypes
int read_adc(int channel);
accelerometer_data_t process_data(int x, int y, int z);
void log_data(accelerometer_data_t data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(8, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(8, 1); // Deassert CS

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to process ADC data and calculate acceleration magnitude
accelerometer_data_t process_data(int x, int y, int z) {
    accelerometer_data_t data;
    data.x = x;
    data.y = y;
    data.z = z;

    // Convert ADC values to voltage
    double voltage_x = (double)x / 1023.0 * VREF;
    double voltage_y = (double)y / 1023.0 * VREF;
    double voltage_z = (double)z / 1023.0 * VREF;

    // Calculate acceleration in g
    double acceleration_x = (voltage_x - ZERO_G_VOLTAGE) / SENSITIVITY;
    double acceleration_y = (voltage_y - ZERO_G_VOLTAGE) / SENSITIVITY;
    double acceleration_z = (voltage_z - ZERO_G_VOLTAGE) / SENSITIVITY;

    // Calculate acceleration magnitude
    data.magnitude = sqrt(acceleration_x * acceleration_x + acceleration_y * acceleration_y + acceleration_z * acceleration_z);

    return data;
}

// Function to log data to file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.4f", timestamp, data.x, data.y, data.z, data.magnitude);
    if (data.magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, ",IMPACT DETECTED");
    }
    fprintf(log_file, "\n");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO8 as output for CS
    gpioSetMode(8, PI_OUTPUT);
    gpioWrite(8, 1); // Deassert CS initially

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x = read_adc(ADC_CHANNEL_X);
        int y = read_adc(ADC_CHANNEL_Y);
        int z = read_adc(ADC_CHANNEL_Z);

        if (x == -1 || y == -1 || z == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Process data
        accelerometer_data_t data = process_data(x, y, z);

        // Log data
        log_data(data);

        // Delay to achieve desired sample rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

