#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel connected to the sensor
#define VREF 3.3f        // ADC reference voltage
#define FLOW_SCALE 5.0f  // Flow rate scale (0-3.3V -> 0-5.0 L/min)
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    float flow_scale;
    char *log_file;
} Config;

// Function prototypes
int spi_init(int channel, int baud);
int spi_read_adc(int channel);
float adc_to_flow(int adc_value);
int log_flow(float flow_rate);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(int channel, int baud) {
    spi_handle = spiOpen(channel, baud, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate
float adc_to_flow(int adc_value) {
    float voltage = (float)adc_value / 1023.0f * VREF;
    float flow_rate = voltage / VREF * FLOW_SCALE;
    return flow_rate;
}

// Log flow rate to file
int log_flow(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 7, ".%06ld", (long)time(NULL) % 1000000); // Add microseconds

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init(SPI_CHANNEL, SPI_BAUD) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stdout, "Flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = spi_read_adc(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float flow_rate = adc_to_flow(adc_value);

            // Validate flow rate
            if (flow_rate >= 0.0f && flow_rate <= 5.0f) {
                if (log_flow(flow_rate) != 0) {
                    fprintf(stderr, "Error: Failed to log flow rate\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid flow rate: %.2f L/min\n", flow_rate);
            }
        }

        sleep(1); // Log every 1 second
    }

    // Cleanup and exit
    cleanup();
    fprintf(stdout, "Flow monitoring stopped.\n");
    return 0;
}

