#include <errno.h>

// I2C address of the ICP-10125 sensor
#define ICP10125_ADDR 0x67

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Measurement command (high-precision)
#define MEASUREMENT_COMMAND 0x6845

// Register addresses (example, adjust based on datasheet)
#define PRESSURE_MSB_REG 0x00
#define PRESSURE_LSB_REG 0x01
#define TEMPERATURE_MSB_REG 0x02
#define TEMPERATURE_LSB_REG 0x03

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold calibration data (example, adjust based on datasheet)
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} calibration_data_t;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int read_sensor_data(int fd, uint8_t *data);
int convert_raw_data(uint8_t *raw_data, calibration_data_t *cal_data, float *temperature, float *pressure);
int log_data(FILE *fp, float temperature, float pressure);
void display_data(float temperature, float pressure);
void signal_handler(int signal);
int initialize_i2c(int bus, int addr);
int read_calibration_data(int fd, calibration_data_t *cal_data);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = reg_addr;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    uint8_t buf[len + 1];
    buf[0] = reg_addr;
    memcpy(buf + 1, data, len);

    if (write(fd, buf, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    uint8_t command[2];
    command[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    command[1] = MEASUREMENT_COMMAND & 0xFF;

    // Send measurement command
    if (i2c_write_bytes(fd, 0x00, command, 2) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    // Wait for conversion to complete (adjust delay as needed)
    usleep(10000); // 10 ms

    // Read 6 bytes of data (pressure MSB, pressure LSB, temperature MSB, temperature LSB, CRC1, CRC2)
    if (i2c_read_bytes(fd, PRESSURE_MSB_REG, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and pressure
int convert_raw_data(uint8_t *raw_data, calibration_data_t *cal_data, float *temperature, float *pressure) {
    // Extract raw pressure and temperature values
    int32_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
