#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define MCP3008 channel assignments
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define sampling rate and buffer size
#define SAMPLE_RATE 8000 // Hz
#define BUFFER_SIZE 1024

// Global variables for signal handling
static volatile int running = 1;
static int spi_handle;

// Structure to hold configuration parameters
typedef struct {
    int gain;
} Config;

// Function prototypes
int read_mcp3008(int channel);
int sample_audio(int *mic1_buffer, int *mic2_buffer, int buffer_size);
int process_audio(int *mic1_buffer, int *mic2_buffer, int *cancellation_buffer, int buffer_size, int gain);
int output_audio(int *cancellation_buffer, int buffer_size);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to sample audio from both microphones
int sample_audio(int *mic1_buffer, int *mic2_buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        int mic1_value = read_mcp3008(MIC1_CHANNEL);
        int mic2_value = read_mcp3008(MIC2_CHANNEL);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error: Failed to read microphone data\n");
            return -1;
        }

        mic1_buffer[i] = mic1_value;
        mic2_buffer[i] = mic2_value;

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }
    return 0;
}

// Function to process audio data (noise cancellation and gain control)
int process_audio(int *mic1_buffer, int *mic2_buffer, int *cancellation_buffer, int buffer_size, int gain) {
    for (int i = 0; i < buffer_size; i++) {
        // Noise cancellation: Subtract microphone 2 from microphone 1
        int difference = mic1_buffer[i] - mic2_buffer[i];

        // Apply gain control
        difference = difference * gain / 100; // Scale gain to 0-100

        // Clamp the value to the valid range (0-1023)
        if (difference < 0) {
            difference = 0;
        } else if (difference > 1023) {
            difference = 1023;
        }

        cancellation_buffer[i] = difference;
    }
    return 0;
}

// Function to output audio data to the terminal in CSV format
int output_audio(int *cancellation_buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        printf("%d\n", cancellation_buffer[i]);
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    Config config;
    config.gain = 100; // Default gain

    if (argc > 1) {
        config.gain = atoi(argv[1]);
        if (config.gain < 0 || config.gain > 100) {
            fprintf(stderr, "Error: Invalid gain value.  Must be between 0 and 100.\n");
            return 1;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Allocate memory for audio buffers
    int *mic1_buffer = malloc(BUFFER_SIZE * sizeof(int));
    int *mic2_buffer = malloc(BUFFER_SIZE * sizeof(int));
    int *cancellation_buffer = malloc(BUFFER_SIZE * sizeof(int));

    if (mic1_buffer == NULL || mic2_buffer == NULL || cancellation_buffer == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Sample audio
        if (sample_audio(mic1_buffer, mic2_buffer, BUFFER_SIZE) != 0) {
            fprintf(stderr, "Error: Audio sampling failed\n");
            break;
        }

        // Process audio
        if (process_audio(mic1_buffer, mic2_buffer, cancellation_buffer, BUFFER_SIZE, config.gain) != 0) {
            fprintf(stderr, "Error: Audio processing failed\n");
            break;
        }

        // Output audio
        if (output_audio(cancellation_buffer, BUFFER_SIZE) != 0) {
            fprintf(stderr, "Error: Audio output failed\n");
            break;
        }
    }

    // Clean up resources
    free(mic1_buffer);
    free(mic2_buffer);
    free(cancellation_buffer);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

