#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <stdbool.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define VREF 3.3
#define FLAME_THRESHOLD 1.0
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_BITS_PER_WORD 8
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float read_ambient_temperature();
float compensate_voltage(float voltage, float temperature);
bool detect_flame(float compensated_voltage);
void control_buzzer(bool flame_detected);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, bool flame_detected);
void signal_handler(int sig);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spi_transfer(tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                log_data(-1, -1.0, -1.0, -1.0, false); // Log error
                control_buzzer(false);
                return -1; // Indicate failure
            }
        } else {
            fprintf(stderr, "SPI transfer failed. Retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read ADC after %d retries\n", MAX_RETRIES);
    log_data(-1, -1.0, -1.0, -1.0, false); // Log error
    control_buzzer(false);
    return -1; // Indicate failure
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return 25.0; // Default temperature
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file. Using default.\n");
        fclose(fp);
        return 25.0; // Default temperature
    }

    fclose(fp);
    return temperature;
}

// Function to compensate voltage
float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Function to detect flame
bool detect_flame(float compensated_voltage) {
    return compensated_voltage > FLAME_THRESHOLD;
}

// Function to control buzzer
void control_buzzer(bool flame_detected) {
    if (flame_detected) {
        if (gpiod_line_set_value(buzzer_line, 1) < 0) {
            perror("Error setting buzzer HIGH");
        }
    } else {
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            perror("Error setting buzzer LOW");
        }
    }
}

// Function to log data
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, bool flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

int main() {
    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(gpio_chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "flame_detector", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (keep_running) {
        // Read ambient temperature
        float temperature = read_ambient_temperature();

        // Read ADC value
        int raw_adc = read_mcp3008(ADC_CHANNEL);
        if (raw_adc == -1) {
            fprintf(stderr, "Failed to read ADC value. Skipping iteration.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
            continue;
        }

        // Calculate voltage
        float voltage = (float)raw_adc / 1023.0 * VREF;

        // Compensate voltage
        float compensated_voltage = compensate_voltage(voltage, temperature);

        // Detect flame
        bool flame_detected = detect_flame(compensated_voltage);

        // Control buzzer
        control_buzzer(flame_detected);

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
    }

    // Cleanup
    gpiod_line_set_value(buzzer_line, 0); // Turn off buzzer
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);

    return 0;
}

