    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    float moisture_threshold;
    int logging_frequency;
    char *recipient_email;
    char *msmtp_config;
} Config;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw);
int log_data(const char *filename, float moisture_percentage);
int send_email_alert(const char *recipient_email, float moisture_percentage, const char *msmtp_config);
void signal_handler(int signal);
void cleanup();
void print_usage(const char *program_name);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    float percentage = (float)(raw_value - min_raw) / (max_raw - min_raw) * 100.0;
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }
    return percentage;
}

// Function to log data to file
int log_data(const char *filename, float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(log_file);
    return 0;
}

