#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 command for single-ended ADC0
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED 0x08

// Calibration values
#define DRY_VALUE 700
#define WET_VALUE 300

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = MCP3008_START_BIT | 0x01; // Start bit + single-ended mode
    tx_buf[1] = (MCP3008_SINGLE_ENDED | (channel << 4)) << 4; // Channel selection
    tx_buf[2] = 0x00; // Dummy byte

