#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // ADC channel connected to MLX90823
#define VREF 3.3 // Reference voltage of MCP3008
#define MIN_PRESSURE 10.0 // Minimum pressure in kPa
#define MAX_PRESSURE 150.0 // Maximum pressure in kPa
#define MIN_VOLTAGE 0.5 // Minimum voltage corresponding to MIN_PRESSURE
#define MAX_VOLTAGE 4.5 // Maximum voltage corresponding to MAX_PRESSURE
#define SENSOR_PRESENT_VOLTAGE_THRESHOLD 0.1 // Voltage threshold to detect sensor presence

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_pressure(float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    float min_pressure;
    float max_pressure;
    float min_voltage;
    float max_voltage;
    float sensor_present_voltage_threshold;
} config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range: %.2f V\n", voltage);
        return -1.0; // Indicate error
    }

    // Linear interpolation
    float pressure = ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
    return pressure;
}

// Function to log pressure reading with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Check for sensor absence
        if (voltage < SENSOR_PRESENT_VOLTAGE_THRESHOLD || voltage > (VREF - SENSOR_PRESENT_VOLTAGE_THRESHOLD)) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected. Voltage: %.2f V\n", voltage);
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Error: Failed to convert voltage to pressure\n");
            continue; // Skip to the next iteration
        }

        // Log pressure reading
        log_pressure(pressure);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Pressure sensor monitoring stopped.\n");
    return 0;
}

