#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define VREF 3.3
#define NUM_CHANNELS 4
#define SAMPLE_INTERVAL_SEC 1
#define CSV_FILE "environmental_data.csv"

// GPIO pin for MCP3008 CS (Chip Select)
#define MCP3008_CS_PIN 8

// Global variables (minimize usage)
static int spi_fd = -1;
static FILE *csv_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
int log_data(double voltages[NUM_CHANNELS]);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);
void spi_cleanup(void);
void file_cleanup(void);

// Structure to hold configuration data
typedef struct {
    char spi_device[20];
    int spi_speed;
    int spi_mode;
    double vref;
    int num_channels;
    int sample_interval_sec;
    char csv_file[50];
    int mcp3008_cs_pin;
} config_t;

// Initialize GPIO
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, MCP3008_CS_PIN);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "mcp3008_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 1) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void gpio_cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

// Initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Cleanup SPI
void spi_cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;                  // Don't care

    // Activate CS
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value (CS low)");
        return -1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        // Deactivate CS even if there's an error
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("gpiod_line_set_value (CS high)");
        }
        return -1;
    }

    // Deactivate CS
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value (CS high)");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * VREF;
}

// Log data to CSV file
int log_data(double voltages[NUM_CHANNELS]) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(csv_file, "%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        fprintf(csv_file, ",%.3f", voltages[i]);
    }
    fprintf(csv_file, "\n");
    fflush(csv_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup file resources
void file_cleanup(void) {
    if (csv_file) {
        fclose(csv_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        spi_cleanup();
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel0,Channel1,Channel2,Channel3\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        double voltages[NUM_CHANNELS];

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Failed to read channel %d\n", i);
                voltages[i] = -1.0; // Indicate error
            } else {
                voltages[i] = adc_to_voltage(adc_value);
            }
        }

        if (log_data(voltages) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    file_cleanup();
    spi_cleanup();
    gpio_cleanup();

    fprintf(stderr, "Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

