// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define LOG_BUFFER_SIZE 20

// VH400 Calibration Values (Example)
#define VH400_DRY_ADC 900
#define VH400_WET_ADC 100

// Data Structures
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[LOG_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
CircularBuffer log_buffer;

// Function Prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void control_pump(int moisture_level);
void add_log_entry(int moisture_level, int pump_state);
void print_log_buffer();
void signal_handler(int signal);

// Function Implementations
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 single-ended read)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float convert_to_moisture(int adc_value) {
    // Linear interpolation between dry and wet values
    float moisture = 100.0 - ((float)(adc_value - VH400_WET_ADC) / (VH400_DRY_ADC - VH400_WET_ADC)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

void control_pump(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump ON\n");
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump OFF\n");
    }
}

void add_log_entry(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    log_buffer.entries[log_buffer.head].timestamp = now;
    log_buffer.entries[log_buffer.head].moisture_level = moisture_level;
    log_buffer.entries[log_buffer.head].pump_state = pump_state;

    log_buffer.head = (log_buffer.head + 1) % LOG_BUFFER_SIZE;
    if (log_buffer.count < LOG_BUFFER_SIZE) {
        log_buffer.count++;
    }
}

