    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize log buffer
    log_buffer.head = 0;
    log_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read moisture level
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float moisture_level = convert_to_moisture(adc_value);
        printf("Moisture Level: %.2f%%\n", moisture_level);

        // Control the pump
        control_pump((int)moisture_level);

        // Add log entry
        add_log_entry((int)moisture_level, pump_state);

        // Print log buffer
        print_log_buffer();

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

