#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MAX30102 I2C address
#define MAX30102_I2C_ADDR 0x57

// MAX30102 register addresses
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVERFLOW_CTR 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF

// Configuration values
#define MODE_SPO2_ONLY 0x03
#define SPO2_ADC_RANGE_4096 0x27
#define LED_CURRENT_24_8MA 0x24

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint32_t red;
    uint32_t ir;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_spo2(uint32_t red, uint32_t ir);
int calculate_heart_rate(uint32_t *ir_data, int data_len);
void log_data(float spo2, int heart_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the MAX30102 sensor
int init_sensor() {
    // Verify sensor presence by reading Part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Clear interrupts
    if (i2cWriteByteData(i2c_handle, REG_INTR_ENABLE_1, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupts\n");
        return -1;
    }

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, MODE_SPO2_ONLY) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode\n");
        return -1;
    }

    // Configure SPO2 settings
    if (i2cWriteByteData(i2c_handle, REG_SPO2_CONFIG, SPO2_ADC_RANGE_4096) < 0) {
        fprintf(stderr, "Error configuring SPO2 settings\n");
        return -1;
    }

    // Set LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, REG_LED1_PA, LED_CURRENT_24_8MA) < 0) {
        fprintf(stderr, "Error setting LED1 current\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED2_PA, LED_CURRENT_24_8MA) < 0) {
        fprintf(stderr, "Error setting LED2 current\n");
        return -1;
    }

    return 0;
}

// Read sensor data from the MAX30102
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, buffer, 6) != 6) {
        fprintf(stderr, "Error reading FIFO data\n");
        return -1;
    }

    data->red = (buffer[0] << 16 | buffer[1] << 8 | buffer[2]) & 0x3FFFF;
    data->ir = (buffer[3] << 16 | buffer[4] << 8 | buffer[5]) & 0x3FFFF;

    return 0;
}

// Calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(uint32_t red, uint32_t ir) {
    // This is a simplified example.  A real implementation would use
    // more sophisticated signal processing and calibration.
    float ratio = (float)red / (float)ir;
    float spo2 = 110.0 - 25.0 * ratio; // Example formula

    // Clamp SpO2 to the range 0-100
    if (spo2 < 0.0) spo2 = 0.0;
    if (spo2 > 100.0) spo2 = 100.0;

    return spo2;
}

// Calculate heart rate using peak detection on the IR signal
int calculate_heart_rate(uint32_t *ir_data, int data_len) {
    // This is a simplified example.  A real implementation would use
    // more sophisticated peak detection algorithms.
    if (data_len < 2) return 0; // Not enough data to calculate heart rate

    int peaks = 0;
    for (int i = 1; i < data_len - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            peaks++;
        }
    }

    // Estimate heart rate (BPM) based on the number of peaks
    // This is a very rough estimate and needs calibration
    int heart_rate = peaks * 60; // Assuming 1 second of data

    return heart_rate;
}

// Log data to a file
void log_data(float spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %d BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    uint32_t ir_data[60]; // Store IR data for 1 second (10 Hz sampling rate)
    int ir_data_index = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate SpO2
            float spo2 = calculate_spo2(sensor_data.red, sensor_data.ir);

            // Store IR data for heart rate calculation
            ir_data[ir_data_index] = sensor_data.ir;
            ir_data_index = (ir_data_index + 1) % 60;

            // Calculate heart rate if we have enough data
            int heart_rate = 0;
            if (ir_data_index == 0) {
                heart_rate = calculate_heart_rate(ir_data, 60);
            }

            // Log data if SpO2 is low or heart rate is high
            if (spo2 < 95.0 || heart_rate > 100) {
                log_data(spo2, heart_rate);
            }

            printf("SpO2: %.2f%%, Heart Rate: %d BPM\n", spo2, heart_rate);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100); // Sample every 100ms (10 Hz)
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

