        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %d BPM\n", timestamp, spo2, heart_rate);
