#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "analog_log.csv"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
char* get_iso8601_timestamp();
void log_data(int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for holding configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    char* log_file_name;
} Config;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    fflush(log_file);

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count, result;

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    for (count = 0; count < RETRY_COUNT; count++) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (result == 3) {
            // Extract the 10-bit ADC value
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (channel %d), retry %d: %d\n", channel, count + 1, result);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries (channel %d)\n", RETRY_COUNT, channel);
    return -1; // Indicate failure
}

// Function to calculate voltage
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
        fflush(log_file); // Ensure data is written to disk immediately
        free(timestamp); // Free the allocated memory
    } else {
        fprintf(stderr, "Failed to get timestamp\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Starting data logging...\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            int adc_value = read_mcp3008(channel);
            if (adc_value != -1) {
                float voltage = calculate_voltage(adc_value);
                log_data(channel, voltage);
                printf("Channel %d: Voltage = %.3f V\n", channel, voltage);
            } else {
                fprintf(stderr, "Failed to read channel %d\n", channel);
            }
        }
        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

