#define THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_buzzer(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the buzzer
void control_buzzer(int state) {
    int result = gpioWrite(BUZZER_GPIO, state);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d (%d)\n", BUZZER_GPIO, result);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    int result = gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output (%d)\n", BUZZER_GPIO, result);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-2 sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            printf("ADC Value: %d\n", adc_value);

            // Control buzzer based on threshold
            if (adc_value < THRESHOLD) {
                control_buzzer(0); // Turn buzzer OFF
            } else {
                control_buzzer(1); // Turn buzzer ON
            }
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is OFF on exit
    gpioTerminate();

    return 0;
}

