#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define RELAY_GPIO 17
#define REED_GPIO 27
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_INTERVAL_MS 50
#define PROXIMITY_THRESHOLD_PERCENT 80
#define PROXIMITY_CHECK_INTERVAL_MS 200
#define RELAY_ON_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_adc(int fd);
int init_gpio(int chip_num, int relay_pin, int reed_pin);
int set_relay_state(int state);
int read_reed_sensor(void);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read ADC value from ADS1115
int read_adc(int fd) {
    uint8_t config[3];
    int16_t value;
    uint8_t read_data[2];

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, +/-4.096V, Continuous)
    config[2] = 0x83; // LSB: 10000011 (128 SPS, Disable comparator)

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    usleep(125000); // 125ms

    // Read the conversion result
    config[0] = 0x00; // Conversion register address
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, read_data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    value = (read_data[0] << 8) | read_data[1];
    return value;
}

// Function to initialize GPIO lines
int init_gpio(int chip_num, int relay_pin, int reed_pin) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip_num);

    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, relay_pin);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, reed_pin);
    if (!reed_line) {
        perror("Error getting reed GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Error requesting relay GPIO line as output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    if (gpiod_line_request_input(reed_line, "reed_sensor") < 0) {
        perror("Error requesting reed GPIO line as input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        gpiod_line_release(reed_line);
        return -1;
    }

    return 0;
}

// Function to set the relay state
int set_relay_state(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Error setting relay GPIO line value");
        return -1;
    }
    return 0;
}

// Function to read the reed sensor state
int read_reed_sensor(void) {
    int value = gpiod_line_get_value(reed_line);
    if (value < 0) {
        perror("Error reading reed GPIO line value");
        return -1;
    }
    return value;
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

