#define BASELINE_SAMPLE_INTERVAL_MS 50
#define PROXIMITY_THRESHOLD_PERCENT 80
#define PROXIMITY_CHECK_INTERVAL_MS 200
#define RELAY_ON_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_adc(int fd);
int init_gpio(int chip_num, int relay_pin, int reed_pin);
int set_relay_state(int state);
int read_reed_sensor(void);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read ADC value from ADS1115
int read_adc(int fd) {
    uint8_t config[3];
    int16_t value;
    uint8_t read_data[2];

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // MSB: 11000011 (Single-ended A0, +/-4.096V, Continuous)
    config[2] = 0x83; // LSB: 10000011 (128 SPS, Disable comparator)

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    usleep(125000); // 125ms

    // Read the conversion result
    config[0] = 0x00; // Conversion register address
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, read_data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    value = (read_data[0] << 8) | read_data[1];
    return value;
}

