    relay_line = gpiod_chip_get_line(gpio_chip, relay_pin);
    if (!relay_line) {
        perror("Error getting relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    reed_line = gpiod_chip_get_line(gpio_chip, reed_pin);
    if (!reed_line) {
        perror("Error getting reed GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
