    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        // De-assert chip select line before returning
        gpiod_line_set_value(cs0_line, 1);
        gpiod_line_set_value(cs1_line, 1);
        gpiod_line_set_value(cs2_line, 1);
        return -1;
    }

    // De-assert chip select line
    ret = gpiod_line_set_value(cs0_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value CS0");
        return -1;
    }
    ret = gpiod_line_set_value(cs1_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value CS1");
        return -1;
    }
    ret = gpiod_line_set_value(cs2_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value CS2");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Function to log data to a CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO lines
    if (cs0_line) {
        gpiod_line_release(cs0_line);
    }
    if (cs1_line) {
        gpiod_line_release(cs1_line);
    }
    if (cs2_line) {
        gpiod_line_release(cs2_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int sensor1_value, sensor2_value, sensor3_value;
    int spi_mode = SPI_MODE;
    int spi_bits_per_word = 8;
    int spi_max_speed_hz = SPI_SPEED;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI_DEVICE");
        return 1;
    }

    // Configure SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits_per_word);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return 1;
    }

    // Configure max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_max_speed_hz);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        close(spi_fd);
        return 1;
    }

    // Get GPIO lines for chip select pins
    cs0_line = gpiod_chip_get_line(gpio_chip, CS0_PIN);
    if (!cs0_line) {
        perror("gpiod_chip_get_line CS0");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }
    cs1_line = gpiod_chip_get_line(gpio_chip, CS1_PIN);
    if (!cs1_line) {
        perror("gpiod_chip_get_line CS1");
        gpiod_line_release(cs0_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }
    cs2_line = gpiod_chip_get_line(gpio_chip, CS2_PIN);
    if (!cs2_line) {
        perror("gpiod_chip_get_line CS2");
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(cs0_line, "soil_moisture", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output CS0");
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }
    ret = gpiod_line_request_output(cs1_line, "soil_moisture", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output CS1");
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }
    ret = gpiod_line_request_output(cs2_line, "soil_moisture", 1);
    if (ret < 0) {
        perror("gpiod_line_request_output CS2");
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(cs0_line);
        gpiod_line_release(cs1_line);
        gpiod_line_release(cs2_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        // Read sensor values
        sensor1_value = read_mcp3008(CS0_PIN, 0);
        sensor2_value = read_mcp3008(CS1_PIN, 0);
        sensor3_value = read_mcp3008(CS2_PIN, 0);

        // Log data
        log_data(log_file, sensor1_value, sensor2_value, sensor3_value);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

