#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DRY_VALUE 200
#define WET_VALUE 800
#define LOG_FILE "irrigation.log"

// Global variables
static int threshold = 30;
static int duration = 10;
static int sleep_interval = 60;
static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < 3; i++) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "SPI read failed (attempt %d): %d", i + 1, result);
            log_message(error_message);
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    log_message("Error: SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = ((float)(adc_value - DRY_VALUE) / (WET_VALUE - DRY_VALUE)) * 100.0;

    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    snprintf(message, sizeof(message), "Pump %s", state ? "activated" : "deactivated");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_message("Error: SPI open failed.");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("System initialized.");
    return 0;
}

// Cleanup function
void cleanup() {
    log_message("Cleaning up...");
    control_pump(0); // Turn off the pump

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    log_message("System shutdown.");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (initialize()) {
        return 1;
    }

    while (!terminate) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message("Error reading ADC value, skipping irrigation cycle.");
            gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        char message[100];
        snprintf(message, sizeof(message), "Moisture: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
        log_message(message);

        // Control the pump based on moisture threshold
        if (moisture_percentage < threshold) {
            log_message("Moisture below threshold, activating pump.");
            control_pump(1); // Activate pump
            gpioDelay(duration * 1000); // Run pump for specified duration
            control_pump(0); // Deactivate pump
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
    }

    cleanup();
    return 0;
}

