#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// I2C device address of the PCF8591
#define PCF8591_ADDR 0x48

// I2C bus file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop to continuously read the AIN0 value
    while (1) {
        // Dummy read to discard the previous conversion result
        if (read(i2c_fd, NULL, 1) < 0) {
            perror("Error during dummy read");
            close(i2c_fd);
            return 1;
        }

        // Read the AIN0 value
        unsigned char value;
        if (read(i2c_fd, &value, 1) < 0) {
            perror("Error reading AIN0 value");
            close(i2c_fd);
            return 1;
        }

        // Print the AIN0 value to stdout
        printf("AIN0 Value: %d\n", value);

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop,
    // but it's good practice to include a cleanup section.
    close(i2c_fd);
    return 0;
}

