#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SHUTDOWN_GPIO 27
#define THRESHOLD_GAUSS 500.0
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 10

// SS49E Sensor Characteristics
#define SS49E_ZERO_FIELD_VOLTAGE 2.5
#define SS49E_SENSITIVITY 0.0014 // 1.4 mV/Gauss = 0.0014 V/Gauss
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_i2c();
int read_adc(int i2c_handle);
float convert_to_voltage(int raw_value);
float calculate_magnetic_field(float voltage);
void update_circular_buffer(float magnetic_field);
float calculate_rolling_average();
void check_threshold(float rolling_average);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion
    // 0b1000001111000000
    // OS = 1 (start single conversion)
    // MUX = 111 (AIN0 - GND)
    // PGA = 001 (FS = +/-4.096V)
    // MODE = 0 (Continuous conversion)
    // DR = 100 (128 SPS)
    // COMP_MODE = 0 (Traditional comparator)
    // COMP_POL = 0 (Active low)
    // COMP_LAT = 0 (Non-latching comparator)
    // COMP_QUE = 11 (Disable comparator)
    uint16_t config = 0x8383; //0b1000001110000011

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write config to ADS1115: %d", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char buf[1];
    buf[0] = CONVERSION_REG;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to write to conversion register: %d", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        syslog(LOG_ERR, "Failed to read from conversion register: %d", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    // ADS1115 is a 16-bit ADC, but only 15 bits are used for the conversion
    // The 16th bit is the sign bit.
    // The voltage range is 0-4.096V, so the resolution is 4.096V / 32768
    float voltage = (float)raw_value * 4.096 / 32768.0;
    return voltage;
}

// Function to calculate magnetic field strength in Gauss
float calculate_magnetic_field(float voltage) {
    float magnetic_field = (voltage - SS49E_ZERO_FIELD_VOLTAGE) / SS49E_SENSITIVITY;
    return magnetic_field;
}

// Function to update the circular buffer
void update_circular_buffer(float magnetic_field) {
    magnetic_field_buffer[buffer_index] = magnetic_field;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to calculate the rolling average of the circular buffer
float calculate_rolling_average() {
    if (buffer_count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / buffer_count;
}

// Function to check if the rolling average exceeds the threshold
void check_threshold(float rolling_average) {
    if (rolling_average > THRESHOLD_GAUSS) {
        syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", rolling_average);
        gpioWrite(SHUTDOWN_GPIO, 1); // Set GPIO HIGH
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(SHUTDOWN_GPIO, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("magnetic_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(SHUTDOWN_GPIO, 0); // Initialize to LOW

    syslog(LOG_INFO, "Magnetic field monitor started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int raw_value = read_adc(i2c_handle);
        if (raw_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        // Convert to voltage
        float voltage = convert_to_voltage(raw_value);

        // Validate voltage
        if (voltage < 0.0 || voltage > VCC) {
            syslog(LOG_ERR, "Invalid voltage reading: %.2f V, skipping sample", voltage);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        // Calculate magnetic field strength
        float magnetic_field = calculate_magnetic_field(voltage);

        // Update circular buffer
        update_circular_buffer(magnetic_field);

        // Calculate rolling average
        float rolling_average = calculate_rolling_average();

        // Check threshold
        check_threshold(rolling_average);

        // Log data
        syslog(LOG_INFO, "Voltage: %.2f V, Magnetic Field: %.2f Gauss, Rolling Average: %.2f Gauss", voltage, magnetic_field, rolling_average);

        // Delay for 1 second
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

