#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION 1000 // ms
#define BLINK_PERIOD 100    // ms (50ms on, 50ms off)

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc(int *raw_value);
double convert_to_gauss(int raw_value);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    unsigned int os : 1;   // Operational status/single-shot start
    unsigned int mux : 3;  // Input multiplexer configuration
    unsigned int pga : 3;  // Programmable gain amplifier configuration
    unsigned int mode : 1; // Device operating mode
    unsigned int dr : 3;   // Data rate
    unsigned int comp_mode : 1; // Comparator mode
    unsigned int comp_pol : 1; // Comparator polarity
    unsigned int comp_lat : 1; // Comparator latch enabled
    unsigned int comp_que : 2; // Comparator queue/conversion
} ads1115_config_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int *raw_value) {
    // Configure ADS1115 for single-ended AIN0, PGA=4.096V, continuous conversion
    ads1115_config_t config;
    config.os = 1;          // Start single conversion
    config.mux = 4;         // AIN0 single-ended
    config.pga = 1;         // +/-4.096V
    config.mode = 0;        // Continuous conversion
    config.dr = 3;          // 128 SPS
    config.comp_mode = 0;   // Traditional comparator
    config.comp_pol = 0;    // Active low
    config.comp_lat = 0;    // Non-latching comparator
    config.comp_que = 3;    // Disable comparator

    unsigned short config_value = (config.os << 15) | (config.mux << 12) | (config.pga << 9) | (config.mode << 8) | (config.dr << 5) | (config.comp_mode << 4) | (config.comp_pol << 3) | (config.comp_lat << 2) | config.comp_que;

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device (conversion register select): %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to convert raw ADC value to Gauss
double convert_to_gauss(int raw_value) {
    // ADS1115 gain = 4.096V, VREF = 4.096V
    // 1 Gauss = 0.001 V
    double voltage = (raw_value / 32767.0) * 4.096; // Assuming 16-bit ADC
    double gauss = (voltage - 1.65) / 0.001;       // 1.65V is zero Gauss
    return gauss;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    control_led(0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
