#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30.0
#define MOISTURE_THRESHOLD_HIGH 35.0

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;
int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
float adc_to_moisture(int adc_value);
void publish_moisture(float moisture);
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);
int mqtt_connect_and_subscribe(void);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %d", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0; // Indicate error
    }

    // Linear mapping: 0 = 100% moisture, 1023 = 0% moisture
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to publish moisture reading to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);

    int result = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(result));
    }
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp((char *)message->payload, "pump_on") == 0) {
                pump_state = 1;
                gpioWrite(PUMP_GPIO, 1); // Activate relay
                syslog(LOG_INFO, "Received pump_on command");
            } else if (strcmp((char *)message->payload, "pump_off") == 0) {
                pump_state = 0;
                gpioWrite(PUMP_GPIO, 0); // Deactivate relay
                syslog(LOG_INFO, "Received pump_off command");
            } else {
                syslog(LOG_WARNING, "Invalid pump control command: %s", (char *)message->payload);
            }
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to connect to MQTT broker and subscribe to topics
int mqtt_connect_and_subscribe(void) {
    int result = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
        return -1;
    }

    result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
    if (result != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(result));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize syslog
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Configure GPIO for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT init failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_message_callback_set(mosq, message_callback);

    if (mqtt_connect_and_subscribe() != 0) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture = adc_to_moisture(adc_value);
            if (moisture >= 0) {
                syslog(LOG_INFO, "Moisture: %.2f%%", moisture);
                publish_moisture(moisture);

                // Pump control logic with hysteresis
                if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                    pump_state = 1;
                    gpioWrite(PUMP_GPIO, 1); // Activate relay
                    syslog(LOG_INFO, "Moisture below threshold, activating pump");
                } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                    pump_state = 0;
                    gpioWrite(PUMP_GPIO, 0); // Deactivate relay
                    syslog(LOG_INFO, "Moisture above threshold, deactivating pump");
                }
            } else {
                syslog(LOG_ERR, "Failed to convert ADC value to moisture");
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        sleep(60); // Read every 60 seconds
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    gpioTerminate();
    closelog();

    return 0;
}

