#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI clock speed (Hz)
#define SPI_SPEED 1000000

// MCP3008 command to read channel 0
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_CHANNEL_0 0x80 // 10000000
#define MCP3008_DUMMY_BYTE 0x00

// VREF
#define VREF 3.3

// Global variable for SPI file descriptor
static int spi_fd = -1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, cleaning up and exiting...\n");
        if (spi_fd != -1) {
            close(spi_fd);
        }
        exit(0);
    }
}

// Function to initialize the SPI device
int spi_init(const char *device, uint8_t mode, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI clock speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from the MCP3008 ADC
