#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
void log_data(float voltage0, float voltage1, float voltage2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
void log_data(float voltage0, float voltage1, float voltage2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltage0, voltage1, voltage2);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("sensor_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open sensor_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data logging... Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from channels 0, 1, and 2
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);

        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
        } else {
            // Convert ADC values to voltages
            float voltage0 = adc_to_voltage(adc_value0);
            float voltage1 = adc_to_voltage(adc_value1);
            float voltage2 = adc_to_voltage(adc_value2);

            // Log data to file
            log_data(voltage0, voltage1, voltage2);
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL * 1000000); // microseconds
    }

    // Clean up resources
    printf("Closing SPI and terminating pigpio...\n");
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

