#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define PWM_FREQUENCY 100 // Hz
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_adc(int channel);
void set_motor_speed(int gpio, int duty_cycle);
void log_event(int adc_value, int duty_cycle);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Read function
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Motor Control function
void set_motor_speed(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Logging function
void log_event(int adc_value, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - ADC Value: %d, Duty Cycle: %d\n", timestamp, adc_value, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop motors
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping iteration\n");
            usleep(10000); // 10 ms
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            int duty_cycle = (int)(((float)adc_value / 1023.0) * 255.0);
            set_motor_speed(MOTOR1_GPIO, duty_cycle);
            set_motor_speed(MOTOR2_GPIO, duty_cycle);
            log_event(adc_value, duty_cycle);
        } else {
            set_motor_speed(MOTOR1_GPIO, 0);
            set_motor_speed(MOTOR2_GPIO, 0);
        }

        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

