int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750(float *lux);
int log_data(float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (spiXfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB (example formula)
float adc_to_db(int adc_value) {
    // This is a placeholder.  You'll need to calibrate this based on your
    // microphone and amplifier setup.
    // Assuming a linear relationship for demonstration purposes.
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float db = 20 * log10(voltage / 0.00002); // Example: 20*log10(Vrms/Vref)
    return db;
}

// Function to read light level from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];

    if (i2cWriteByteData(i2c_fd, 0x00, BH1750_CMD) != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 mode\n");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    if (i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data\n");
        return -1;
    }

