    if (spi_fd < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, BH1750_ADDR, 0); // I2C bus 1, BH1750 address
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    fflush(log_fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        float sound_level_db = (adc_value >= 0) ? adc_to_db(adc_value) : -999.0; // Error value
        float light_level_lux = 0.0;
        int bh1750_error = read_bh1750(&light_level_lux);
        int error_code = (adc_value < 0 || bh1750_error != 0) ? 1 : 0;

        if (log_data(sound_level_db, light_level_lux, error_code) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Sleep for 5 seconds
    }

    // Cleanup
    fclose(log_fp);
    i2cClose(i2c_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

