            time_t now = time(NULL);
            if (now - last_trigger_time >= DEBOUNCE_DELAY) {
                // Activate relay
                control_relay(1);
                log_event("Door opened");
                printf("Door opened (Distance: %.2f cm, ADC: %d)\n", distance, adc_value);
