#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int sensor_values[], int num_sensors);
int map_to_valve_position(float average);
void set_valve_position(int position);
void log_data(int sensor_values[], int num_sensors, float average, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the average of sensor readings
float calculate_average(int sensor_values[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (sensor_values[i] >= 0) { // Only include valid readings
            sum += sensor_values[i];
            valid_count++;
        }
    }

    if (valid_count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return sum / valid_count;
}

// Function to map the average ADC value to a valve position (0-100%)
int map_to_valve_position(float average) {
    // Inverse mapping: higher ADC value (wetter soil) -> lower valve position
    int position = (int)((1023.0 - average) / 1023.0 * 100.0);
    return position;
}

// Function to set the valve position using PWM
void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;

    gpioPWM(VALVE_GPIO, position);
}

// Function to log data to a file
void log_data(int sensor_values[], int num_sensors, float average, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ", timestamp);
    for (int i = 0; i < num_sensors; i++) {
        fprintf(log_file, "%d, ", sensor_values[i]);
    }
    fprintf(log_file, "%.2f, %d\n", average, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor_values[NUM_SENSORS];

    // Main loop
    while (!terminate) {
        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error: Failed to read sensor %d, skipping\n", i);
                sensor_values[i] = -1; // Mark as invalid
            }
        }

        // Calculate average
        float average = calculate_average(sensor_values, NUM_SENSORS);

        // Map to valve position
        int valve_position = map_to_valve_position(average);

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(sensor_values, NUM_SENSORS, average, valve_position);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    set_valve_position(0); // Close the valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

