    gpioTerminate();
    printf("Cleaned up and exiting.\n");
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI command (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int attempts = 0;
    int result = -1;

    while (attempts < RETRY_COUNT) {
        result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", attempts + 1, result);
            attempts++;
            gpioDelay(100 * (1 << attempts)); // Exponential backoff (100ms, 200ms, 400ms, 800ms, 1600ms)
        }
    }

    fprintf(stderr, "SPI transfer failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    // Linear mapping: 0 ADC = 100% moisture, 1023 ADC = 0% moisture
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
