        fprintf(stderr, "Error opening log file: %s\n", config.log_file);
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);

    printf("%s, Moisture: %.2f%%\n", timestamp, moisture_percentage);
}

