#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

// Configuration
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define CONFIG_FILE "theremin_config.txt"
#define DEFAULT_DISTANCE_MIN 2.0
#define DEFAULT_DISTANCE_MAX 20.0
#define DEFAULT_LDR_MIN 0
#define DEFAULT_LDR_MAX 1023
#define DEFAULT_FREQUENCY_MIN 220.0
#define DEFAULT_FREQUENCY_MAX 880.0
#define DEFAULT_DUTY_CYCLE_MIN 0.0
#define DEFAULT_DUTY_CYCLE_MAX 1.0
#define TIMEOUT_US 50000 // 50ms timeout for ultrasonic sensor

// Global variables
volatile sig_atomic_t program_running = 1;
double distance_min = DEFAULT_DISTANCE_MIN;
double distance_max = DEFAULT_DISTANCE_MAX;
int ldr_min = DEFAULT_LDR_MIN;
int ldr_max = DEFAULT_LDR_MAX;
double frequency_min = DEFAULT_FREQUENCY_MIN;
double frequency_max = DEFAULT_FREQUENCY_MAX;
double duty_cycle_min = DEFAULT_DUTY_CYCLE_MIN;
double duty_cycle_max = DEFAULT_DUTY_CYCLE_MAX;
int spi_fd;
int pwm_handle;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
int init_pwm();
double read_distance();
int read_ldr();
double map_distance_to_frequency(double distance);
double map_ldr_to_duty_cycle(int ldr_value);
int set_pwm_frequency(double frequency);
int set_pwm_duty_cycle(double duty_cycle);
int load_config();
int save_config();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    return 0;
}

// Initialize SPI interface
int init_spi() {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Initialize PWM
int init_pwm() {
    pwm_handle = gpioSetPWMfrequency(PWM_PIN, 0); // Initialize with 0 frequency
    if (pwm_handle < 0) {
        fprintf(stderr, "Error setting PWM frequency: %d\n", pwm_handle);
        return -1;
    }
    gpioPWM(PWM_PIN, 0); // Initialize duty cycle to 0
    return 0;
}

// Read distance from HC-SR04 ultrasonic sensor
double read_distance() {
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double time_taken = (double)diff / 1000000.0; // in seconds
    double distance = time_taken * 34300.0 / 2.0; // in cm

    return distance;
}

// Read LDR value from MCP3008 ADC
int read_ldr() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 configuration: single-ended channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Map distance to frequency
double map_distance_to_frequency(double distance) {
    if (distance < 0) return frequency_min; // Handle error case
    return frequency_min + (distance - distance_min) * (frequency_max - frequency_min) / (distance_max - distance_min);
}

// Map LDR value to duty cycle
double map_ldr_to_duty_cycle(int ldr_value) {
    return duty_cycle_min + (ldr_value - ldr_min) * (duty_cycle_max - duty_cycle_min) / (ldr_max - ldr_min);
}

// Set PWM frequency
int set_pwm_frequency(double frequency) {
    int actual_frequency = gpioSetPWMfrequency(PWM_PIN, (int)frequency);
    if (actual_frequency != (int)frequency) {
        fprintf(stderr, "Warning: Requested frequency %f, got %d\n", frequency, actual_frequency);
    }
    return 0;
}

// Set PWM duty cycle
int set_pwm_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;
    gpioPWM(PWM_PIN, (int)(duty_cycle * 255)); // pigpio duty cycle is 0-255
    return 0;
}

// Load configuration from file
int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file, using defaults.\n");
        return -1;
    }

    if (fscanf(fp, "%lf %lf %d %d %lf %lf %lf %lf", &distance_min, &distance_max, &ldr_min, &ldr_max, &frequency_min, &frequency_max, &duty_cycle_min, &duty_cycle_max) != 8) {
        fprintf(stderr, "Error reading config file, using defaults.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Configuration loaded from %s\n", CONFIG_FILE);
    return 0;
}

// Save configuration to file
int save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp == NULL) {
        perror("Error opening config file for writing");
        return -1;
    }

    fprintf(fp, "%lf %lf %d %d %lf %lf %lf %lf", distance_min, distance_max, ldr_min, ldr_max, frequency_min, frequency_max, duty_cycle_min, duty_cycle_max);
    fclose(fp);
    printf("Configuration saved to %s\n", CONFIG_FILE);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    close(spi_fd); // Close SPI device
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (init_gpio() != 0) return 1;
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }
    if (init_pwm() != 0) {
        cleanup();
        return 1;
    }

    // Load configuration
    load_config();

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor data
        double distance = read_distance();
        int ldr_value = read_ldr();

        // Handle sensor errors
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, using previous value.\n");
            // Consider implementing a fallback mechanism here
        }
        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR, using previous value.\n");
            // Consider implementing a fallback mechanism here
        }

        // Map sensor data to audio parameters
        double frequency = map_distance_to_frequency(distance);
        double duty_cycle = map_ldr_to_duty_cycle(ldr_value);

        // Set PWM parameters
        set_pwm_frequency(frequency);
        set_pwm_duty_cycle(duty_cycle);

        gpioDelay(10); // Small delay
    }

    // Save configuration before exiting
    save_config();

    // Cleanup
    cleanup();

    return 0;
}

