    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value1 = -1, adc_value2 = -1;
        float aqi1 = -1.0, aqi2 = -1.0;
        int retry;

        // Read sensor 1 with retry logic
        for (retry = 0; retry < RETRY_COUNT; retry++) {
            adc_value1 = read_mcp3008(0);
            if (adc_value1 >= 0) break; // Success
            fprintf(stderr, "Failed to read sensor 1, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
        if (adc_value1 < 0) {
            fprintf(stderr, "Failed to read sensor 1 after multiple retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                break; // Exit loop if SPI re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Read sensor 2 with retry logic
        for (retry = 0; retry < RETRY_COUNT; retry++) {
            adc_value2 = read_mcp3008(1);
            if (adc_value2 >= 0) break; // Success
            fprintf(stderr, "Failed to read sensor 2, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
        }
        if (adc_value2 < 0) {
            fprintf(stderr, "Failed to read sensor 2 after multiple retries. Re-initializing SPI.\n");
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
                break; // Exit loop if SPI re-initialization fails
            }
            continue; // Skip to the next iteration
        }

        // Convert ADC values to AQI
        aqi1 = adc_to_aqi(adc_value1);
        aqi2 = adc_to_aqi(adc_value2);

        if (aqi1 < 0 || aqi2 < 0) {
            fprintf(stderr, "Error converting ADC to AQI. Skipping this iteration.\n");
            gpioDelay(5000); // Wait 5 seconds before next iteration
            continue;
        }

        // Control the fan based on the average AQI
        float avg_aqi = (aqi1 + aqi2) / 2.0;
        control_fan((int)avg_aqi);

        // Log the data
        log_data(aqi1, aqi2);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

