#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8 // CE0
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1024.0
#define PPM_SCALE 0.5
#define PPM_OFFSET -10.0
#define LOG_FILE "alcohol_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_ppm(int adc_value);
void log_reading(float ppm);
void signal_handler(int sig);
void cleanup(void);
int gpio_init(void);
void gpio_set_low(void);
void gpio_set_high(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended mode + channel
    tx[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx;
    transfer[0].rx_buf = (unsigned long)rx;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// ADC to PPM Conversion
float adc_to_ppm(int adc_value) {
    return (adc_value * PPM_SCALE) + PPM_OFFSET;
}

// Log Reading
void log_reading(float ppm) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, %.2f PPM, ", buf, ppm);

    if (ppm > 50.0) {
        fprintf(log_file, "Alcohol detected! Limit exceeded.\n");
    } else if (ppm < 20.0) {
        fprintf(log_file, "Sobriety confirmed.\n");
    } else {
        fprintf(log_file, "Alcohol level within acceptable range.\n");
    }
    fflush(log_file);
}

// Signal Handler
void signal_handler(int sig) {
