#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channels
#define POTENTIOMETER1_CHANNEL 0
#define POTENTIOMETER2_CHANNEL 1

// Motion Profile
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCELERATION_TIME 2 // seconds
#define CONSTANT_SPEED_TIME 2 // seconds
#define DECELERATION_TIME 2 // seconds
#define PAUSE_TIME 5 // seconds

// Global variables for signal handling
static volatile int running = 1;
static int spi_handle;

// Function prototypes
int read_mcp3008(int channel);
float map_speed_factor(int adc_value);
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed, int direction);
void run_motion_profile(int motor1_enable_pin, int motor1_direction_pin, int motor2_enable_pin, int motor2_direction_pin, float speed_factor1, float speed_factor2);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map ADC value to speed factor using a logarithmic function
float map_speed_factor(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return 0.0;
    }

    // Logarithmic mapping
    float speed_factor = log10(adc_value + 1) / log10(1024); // Scale to 0-1
    return speed_factor;
}

// Function to set motor speed and direction
void set_motor_speed(int motor_enable_pin, int motor_direction_pin, int speed, int direction) {
    gpioWrite(motor_direction_pin, direction);
    gpioPWM(motor_enable_pin, speed);
}

// Function to run the motion profile
void run_motion_profile(int motor1_enable_pin, int motor1_direction_pin, int motor2_enable_pin, int motor2_direction_pin, float speed_factor1, float speed_factor2) {
    // Acceleration
    for (int i = 0; i <= ACCELERATION_TIME * 10; i++) {
        int speed1 = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (float)i / (ACCELERATION_TIME * 10) * speed_factor1);
