// Define GPIO pins
#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Define constants
#define NUM_SAMPLES 5000
#define THRESHOLD_PERCENTAGE 10
#define DEBOUNCE_MS 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_average(int *samples, int num_samples);
int check_threshold(double average, int sample, int threshold_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate the average of an array of samples
double calculate_average(int *samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return sum / num_samples;
}

// Function to check if a sample exceeds the threshold
int check_threshold(double average, int sample, int threshold_percentage) {
    double threshold = average * (1.0 + (double)threshold_percentage / 100.0);
    return (sample > threshold) ? 1 : 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate ambient noise level
    int samples[NUM_SAMPLES];
    printf("Calibrating ambient noise level for 5 seconds...\n");
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC during calibration, exiting\n");
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
        samples[i] = sample;
        gpioDelay(1); // Small delay to avoid overwhelming the ADC
    }

    double average_ambient = calculate_average(samples, NUM_SAMPLES);
    printf("Calibration complete. Average ambient level: %.2f\n", average_ambient);

    // Main loop
    int led_state = 0; // 0 = off, 1 = on
    unsigned long last_toggle_time = 0;

    while (!terminate) {
        int sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Error reading ADC, exiting\n");
            break;
        }

        int threshold_exceeded = check_threshold(average_ambient, sample, THRESHOLD_PERCENTAGE);

        // Debounce and control LED
        if (threshold_exceeded && !led_state) {
            unsigned long current_time = gpioTick();
            if (current_time - last_toggle_time > DEBOUNCE_MS * 1000) { // Convert ms to us
                gpioWrite(LED_PIN, 1); // Turn LED on
                led_state = 1;
                last_toggle_time = current_time;
                printf("Threshold exceeded! Sample: %d, Average: %.2f\n", sample, average_ambient);
            }
        } else if (!threshold_exceeded && led_state) {
            unsigned long current_time = gpioTick();
            if (current_time - last_toggle_time > DEBOUNCE_MS * 1000) {
                gpioWrite(LED_PIN, 0); // Turn LED off
                led_state = 0;
                last_toggle_time = current_time;
            }
        }

        gpioDelay(1); // Small delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

