#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8 // GPIO8 (CE0)
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE) // Nanoseconds
#define MCP3008_CHANNEL 0

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_request_output(const char *chipname, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release(struct gpiod_line *line, struct gpiod_chip *chip);
int log_data(FILE *fp, long long timestamp_ns, int raw_adc_value);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
        .delay_usecs = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request output function
int gpio_request_output(const char *chipname, int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_sampler";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO release function
int gpio_release(struct gpiod_line *line, struct gpiod_chip *chip) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

// Log data function
int log_data(FILE *fp, long long timestamp_ns, int raw_adc_value) {
    if (fprintf(fp, "%lld|%d\n", timestamp_ns, raw_adc_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Request GPIO line
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "audio_sampler";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Sampling loop
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC_RAW, &start_time);
    long long timestamp_ns;
    int raw_adc_value;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    while (!terminate) {
        // Construct SPI message
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended channel 0
        tx_buf[2] = 0x00; // Dummy byte

        // Set CS low
        if (gpio_set_value(gpio_line, 0) < 0) {
            break;
        }

        // Perform SPI transfer
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            gpio_set_value(gpio_line, 1);
            break;
        }

        // Set CS high
        if (gpio_set_value(gpio_line, 1) < 0) {
            break;
        }

        // Parse ADC value
        raw_adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC_RAW, &current_time);
        timestamp_ns = (long long)current_time.tv_sec * 1000000000LL + current_time.tv_nsec;

        // Log data
        if (log_data(log_file, timestamp_ns, raw_adc_value) < 0) {
            break;
        }

        // Calculate sleep time
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

        // Sleep until the next sample deadline
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line != NULL) {
        gpio_release(gpio_line, gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

