#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for MCP3008
#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity and zero-g bias
#define ADXL335_SENSITIVITY 0.300 // 300 mV/g
#define ADXL335_ZERO_G 1.500      // 1.5V

// Define reference voltage
#define VREF 3.3

// Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state variables
float x_state = 0.0, y_state = 0.0, z_state = 0.0;
float x_error_covariance = 1.0, y_error_covariance = 1.0, z_error_covariance = 1.0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_acceleration(int adc_value);
void kalman_filter(float measurement, float *state, float *error_covariance);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate acceleration from ADC value
float calculate_acceleration(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float acceleration = (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Function to implement Kalman filter
void kalman_filter(float measurement, float *state, float *error_covariance) {
    // Prediction step
    float predicted_state = *state;
    float predicted_error_covariance = *error_covariance + PROCESS_NOISE;

    // Update step
    float kalman_gain = predicted_error_covariance / (predicted_error_covariance + MEASUREMENT_NOISE);
    *state = predicted_state + kalman_gain * (measurement - predicted_state);
    *error_covariance = (1 - kalman_gain) * predicted_error_covariance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set initial CS state
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Calculate acceleration values
        float x_acceleration = calculate_acceleration(x_adc);
        float y_acceleration = calculate_acceleration(y_adc);
        float z_acceleration = calculate_acceleration(z_adc);

        // Apply Kalman filter
        kalman_filter(x_acceleration, &x_state, &x_error_covariance);
        kalman_filter(y_acceleration, &y_state, &y_error_covariance);
        kalman_filter(z_acceleration, &z_state, &z_error_covariance);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_state, y_state, z_state);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

