#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define constants for magnetic field calculation
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the digital value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int digital_value) {
    float v_out = (float)digital_value * VCC; // Treat digital value as 0 or 1
    float magnetic_field = (v_out - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

// Function to log the sensor readings to a file
void log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
        } else {
            // Calculate magnetic field strengths
            float sensor1_mT = calculate_magnetic_field(sensor1_value);
            float sensor2_mT = calculate_magnetic_field(sensor2_value);
            float sensor3_mT = calculate_magnetic_field(sensor3_value);

            // Log the data
            log_data(sensor1_mT, sensor2_mT, sensor3_mT);

            // Check for out-of-range values and print warnings
            if (sensor1_mT < -100 || sensor1_mT > 100) {
                fprintf(stderr, "Warning: Sensor 1 value out of range: %.2f mT\n", sensor1_mT);
            }
            if (sensor2_mT < -100 || sensor2_mT > 100) {
                fprintf(stderr, "Warning: Sensor 2 value out of range: %.2f mT\n", sensor2_mT);
            }
            if (sensor3_mT < -100 || sensor3_mT > 100) {
                fprintf(stderr, "Warning: Sensor 3 value out of range: %.2f mT\n", sensor3_mT);
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

