#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

// Define SPI device and parameters
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    int ret = 0;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Open CSV file in append mode
    csv_file = fopen("sensor_data.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    // Write data to CSV file
    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);

    // Close CSV file
    fclose(csv_file);
    csv_file = NULL; // Reset the global pointer

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    // Close CSV file
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("Soil Moisture Monitoring System\n");

    // Main loop
    while (!terminate) {
        int channel0_value, channel1_value, channel2_value;

        // Read ADC values from channels 0, 1, and 2
        channel0_value = read_mcp3008(0);
        channel1_value = read_mcp3008(1);
        channel2_value = read_mcp3008(2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying in 1 second.\n");
        } else {
            // Log data to CSV file
            if (log_data(channel0_value, channel1_value, channel2_value) != 0) {
                fprintf(stderr, "Error logging data. \n");
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

