#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup
    return 0;
}

// Function to parse JSON and extract led_state
int parse_json(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        log_error("Failed to parse JSON");
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state_json)) {
        log_error("led_state is not a boolean");
        cJSON_Delete(json);
        return -1;
    }

    *led_state = cJSON_IsTrue(led_state_json);

    cJSON_Delete(json);
    return 0;
}

// Function to control the LED
void control_led(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
}

// MQTT message callback function
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json(message->payload, &led_state) == 0) {
            control_led(led_state);
        } else {
            log_error("Failed to parse JSON message");
        }
    } else {
        log_error("Empty message received");
    }
}

// MQTT connect callback function
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("Connection failed: " + result);
    }
}

// MQTT disconnect callback function
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_error("Disconnected unexpectedly");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, cleaning up...\n");
}

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize mosquitto
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker with exponential backoff
    int rc = 0;
