#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *sound_sensor_line;
struct gpiod_line *alarm_led_line;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sound sensor value
int read_sound_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sound sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the alarm LED
void control_alarm_led(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Error setting alarm LED value");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line for sound sensor
    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for sound sensor as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sound_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(sound_sensor_line, &config, 0) < 0) {
        perror("Error requesting sound sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        return 1;
    }

    // Get line for alarm LED
    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED line");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        return 1;
    }

    // Request line for alarm LED as output
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(alarm_led_line, &config, 0) < 0) {
        perror("Error requesting alarm LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
        return 1;
    }

    // Main loop
    while (1) {
        int sound_level = read_sound_sensor(sound_sensor_line);
        if (sound_level < 0) {
            // Error reading sound sensor, exit loop
            break;
        }

        printf("Sound Level: %d\n", sound_level);

        if (sound_level == 0) {
            // Sound detected, blink alarm LED for 1 second
            control_alarm_led(alarm_led_line, 1); // Turn LED on
            usleep(1000000); // Wait for 1 second
            control_alarm_led(alarm_led_line, 0); // Turn LED off
        }

        usleep(100000); // Delay for 100 ms
    }

    // Cleanup (in case of error in the loop)
    gpiod_line_release(sound_sensor_line);
    gpiod_line_release(alarm_led_line);
    gpiod_chip_close(chip);

    return 0;
}

