#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <stdbool.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345       // Replace with your server port

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_line *gpio_line = NULL;
struct gpiod_chip *gpio_chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int init_gpio(void);
int detect_vibration(void);
int log_vibration(const char *timestamp);
int send_shutdown_signal(const char *timestamp);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        program_running = 0;
        printf("Signal received, exiting gracefully.\n");
    }
}

// Initialize GPIO
int init_gpio(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration-monitor";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    ret = gpiod_line_request(gpio_line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Detect vibration
int detect_vibration(void) {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_wait(gpio_line, NULL);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        return -1;
    }

    ret = gpiod_line_event_read(gpio_line, &event);
    if (ret < 0) {
        perror("gpiod_line_event_read");
        return -1;
    }

    return 0;
}

// Log vibration event
int log_vibration(const char *timestamp) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }

    fprintf(log_file, "%s Vibration detected!\n", timestamp);
    if (ferror(log_file)) {
        perror("fprintf");
        fclose(log_file);
        return -1;
    }

    fclose(log_file);
    return 0;
}

// Send shutdown signal to server
int send_shutdown_signal(const char *timestamp) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "%s Vibration detected!", timestamp);

    if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        ret = detect_vibration();
        if (ret == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Vibration detected!\n", timestamp);

            if (log_vibration(timestamp) != 0) {
                fprintf(stderr, "Failed to log vibration event.\n");
            }

            if (send_shutdown_signal(timestamp) != 0) {
                fprintf(stderr, "Failed to send shutdown signal.\n");
            }

            // Simulate shutdown (replace with actual shutdown command)
            printf("Simulating shutdown...\n");
            sleep(2); // Simulate shutdown delay
            break;      // Exit the loop after simulating shutdown
        } else if (ret < 0) {
            fprintf(stderr, "Vibration detection failed. Retrying.\n");
            sleep(1); // Wait before retrying
        }
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Vibration monitoring stopped.\n");

    return 0;
}

