#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
static char *get_timestamp(void)
{
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    static char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
    return buf;
}

// Function to read the flame sensor value
static int read_flame_sensor(void)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1; // Indicate error
    }
    return value;
}

// Function to log the flame event to a file
static int log_flame_event(const char *timestamp, int pin, int state)
{
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, pin, state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main(void)
{
    // Install signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input with pull-down resistor
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        char *timestamp = get_timestamp();

        if (log_flame_event(timestamp, GPIO_PIN, flame_detected) != 0) {
            fprintf(stderr, "Error logging flame event.\n");
        }

        if (flame_detected) {
            printf("ALARM: Flame detected!\n");
        }

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

