#define SPI_SPEED 500000 // 500 kHz
#define I2C_BUS 1
#define MCP4725_ADDR 0x62
#define TMP36_VREF 3.3
#define TMP36_SCALE 0.01
#define TMP36_OFFSET 0.0
#define DAC_VREF 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
int celsius_to_dac_voltage(float temperature);
int write_mcp4725(int dac_value);
int log_data(int adc_value, float temperature, float dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * TMP36_VREF;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Function to convert Celsius to DAC voltage
int celsius_to_dac_voltage(float temperature) {
    // Linear mapping: 0C -> 0V, 50C -> 3.3V
    float voltage = temperature / 50.0 * DAC_VREF;
    // Ensure voltage is within 0-3.3V range
    if (voltage < 0.0) voltage = 0.0;
    if (voltage > DAC_VREF) voltage = DAC_VREF;

    // Convert voltage to DAC value (12-bit)
    int dac_value = (int)(voltage / DAC_VREF * 4095.0);
    return dac_value;
}

// Function to write to MCP4725 DAC
int write_mcp4725(int dac_value) {
    char i2c_tx_buf[3];

    // Construct I2C message (MCP4725 datasheet)
    i2c_tx_buf[0] = 0x40; // Write DAC value command
    i2c_tx_buf[1] = (dac_value >> 4) & 0xFF; // MSB
    i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // LSB

    if (i2cWriteDevice(i2c_handle, i2c_tx_buf, 3) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, dac_voltage);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float temperature = adc_to_celsius(adc_value);

        // Convert Celsius to DAC voltage
        int dac_value = celsius_to_dac_voltage(temperature);

        // Write DAC value to MCP4725
        if (write_mcp4725(dac_value) != 0) {
            fprintf(stderr, "Error: Failed to write DAC value\n");
        }

        // Log data
        log_data(adc_value, temperature, temperature / 50.0 * DAC_VREF);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

