#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI mode 0

// Define MCP3008 channels for the sensors
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SENSOR3_CHANNEL 2

// Define the log file name
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(int sensor_number, float moisture_percentage);
void signal_handler(int signal);

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    // Construct the SPI message to send to the MCP3008
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1; // Indicate an error
    }

    // Extract the ADC value from the received data
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    float moisture_percentage = (1.0 - ((float)adc_value / 1023.0)) * 100.0;
    return moisture_percentage;
}

// Function to log the data to a file
void log_data(int sensor_number, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d, Moisture: %.2f%%\n", timestamp, sensor_number, moisture_percentage);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open the SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor 1
        int adc_value1 = read_mcp3008(SENSOR1_CHANNEL);
        if (adc_value1 >= 0) {
            float moisture1 = convert_to_moisture(adc_value1);
            if (moisture1 >= 0.0) {
                log_data(1, moisture1);
            } else {
                fprintf(stderr, "Error: Invalid moisture value for sensor 1\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor 1\n");
        }

        // Read sensor 2
        int adc_value2 = read_mcp3008(SENSOR2_CHANNEL);
        if (adc_value2 >= 0) {
            float moisture2 = convert_to_moisture(adc_value2);
            if (moisture2 >= 0.0) {
                log_data(2, moisture2);
            } else {
                fprintf(stderr, "Error: Invalid moisture value for sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor 2\n");
        }

        // Read sensor 3
        int adc_value3 = read_mcp3008(SENSOR3_CHANNEL);
        if (adc_value3 >= 0) {
            float moisture3 = convert_to_moisture(adc_value3);
            if (moisture3 >= 0.0) {
                log_data(3, moisture3);
            } else {
                fprintf(stderr, "Error: Invalid moisture value for sensor 3\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor 3\n");
        }

        // Sleep for 60 seconds
        gpioDelay(60000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

