#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define LED_GPIO 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY_MS 200
#define LED_ON_DURATION_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void log_event(const char *timestamp);
void signal_handler(int signal);
char* get_timestamp();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer the SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log an event to the log file
void log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s: Sound detected\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to preserve the string across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sound_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int last_trigger_time = 0; // Store the last trigger time

    // Main loop
    while (program_running) {
        // Read sound sensor value
        int sound_level = read_mcp3008(0);

        if (sound_level < 0) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            // Optionally add retry logic here
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Get current timestamp
        char* timestamp = get_timestamp();

        // Check if sound level exceeds threshold
        if (sound_level > SOUND_THRESHOLD) {
            // Debounce check
            int current_time = time(NULL);
            if (current_time - last_trigger_time > DEBOUNCE_DELAY_MS / 1000) {
                // Log event
                log_event(timestamp);

                // Turn on LED
                gpioWrite(LED_GPIO, 1);

                // Wait for 500ms
                gpioDelay(LED_ON_DURATION_MS * 1000); // Convert ms to us

                // Turn off LED
                gpioWrite(LED_GPIO, 0);

                // Update last trigger time
                last_trigger_time = current_time;
            }
        }

        // Wait 10ms
        gpioDelay(10000); // Convert ms to us
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

