#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for motor control
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor run time
#define MOTOR_RUN_TIME 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1; // Indicate error
    }

    // Parse ADC value
    int adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to convert ADC value to rain level
int convert_adc_to_rain_level(int adc_value) {
    // Map ADC value (0-1023) to rain level (0-10)
    // ADC 1023 -> rain level 0 (dry)
    // ADC 0 -> rain level 10 (heaviest rain)
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the DC motor
void control_motor(int direction, int speed) {
    // Set motor direction
    gpioWrite(MOTOR_IN1, direction);
    gpioWrite(MOTOR_IN2, !direction);

    // Set motor speed using PWM
    gpioPWM(MOTOR_ENA, speed);

    // Run motor for specified time
    gpioDelay(MOTOR_RUN_TIME * 1000000); // microseconds

    // Stop the motor
    gpioPWM(MOTOR_ENA, 0);
}

// Function to log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range for motor speed control
    gpioSetPWMrange(MOTOR_ENA, 255);

    // Initialize motor to stopped state
    gpioPWM(MOTOR_ENA, 0);

    // Set initial window state to open
    int window_open = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert ADC value to rain level
        int rain_level = convert_adc_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Control motor based on rain level and window state
        if (rain_level >= RAIN_THRESHOLD && window_open) {
            printf("Closing window...\n");
            control_motor(1, 150); // Forward (close)
            window_open = 0;
        } else if (rain_level < RAIN_THRESHOLD && !window_open) {
            printf("Opening window...\n");
            control_motor(0, 150); // Reverse (open)
            window_open = 1;
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(MOTOR_ENA, 0); // Stop the motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

