// Define GPIO pins
#define MIC_PIN 26
#define LED_PIN 16

// Define ADC parameters
#define ADC_BITS 10
#define ADC_SAMPLES 100

// Define clap detection threshold
#define CLAP_THRESHOLD 700

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_clap_time = 0;

// Function prototypes
int read_adc(int pin, int bits, int samples);
int detect_clap(int adc_value, int threshold);
void control_led(int pin, int state, int duration_ms);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Function to read ADC value using bit-banging
int read_adc(int pin, int bits, int samples) {
    int i, j;
    int adc_value = 0;

    for (i = 0; i < bits; i++) {
        gpioSetMode(pin, PI_OUTPUT);
        gpioWrite(pin, 0);
        gpioDelay(1); // Charge capacitor

        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN);

        unsigned long start_time = gpioTick();
        while (gpioRead(pin) == 0 && (gpioTick() - start_time) < 1000); // Wait for discharge, with timeout

        unsigned long discharge_time = gpioTick() - start_time;

        adc_value += (discharge_time << i);
    }

    return adc_value;
}

// Function to detect clap based on ADC value and threshold
int detect_clap(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Function to control the LED
void control_led(int pin, int state, int duration_ms) {
    gpioWrite(pin, state);
    gpioDelay(duration_ms);
    gpioWrite(pin, 0); // Turn off after duration
}

// Function to print timestamped message
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor for MIC_PIN
    gpioSetPullUpDown(MIC_PIN, PI_PUD_DOWN);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    print_timestamped_message("Clap detector started. Press Ctrl+C to exit.");

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc(MIC_PIN, ADC_BITS, ADC_SAMPLES);

        // Detect clap
        if (detect_clap(adc_value, CLAP_THRESHOLD)) {
            unsigned long current_time = gpioTick();

            // Debounce
            if (current_time - last_clap_time > DEBOUNCE_TIME * 1000) {
                print_timestamped_message("Clap detected!");
                control_led(LED_PIN, 1, 500); // Turn on LED for 500ms
                last_clap_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

