#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"

// Calibration constants
#define A 26.0
#define B -6.0

// Proximity threshold
#define PROXIMITY_THRESHOLD 200.0

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_from_gpio(int gpio_value);
float distance_from_voltage(float voltage);
void log_distance(float distance);
void check_proximity(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
        gpio_unexport(GPIO_PIN);
        exit(0);
    }
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    char export_path[64];
    FILE *fp;

    snprintf(export_path, sizeof(export_path), GPIO_PATH "/export");

    fp = fopen(export_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", export_path, strerror(errno));
        return -1;
    }

    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    char unexport_path[64];
    FILE *fp;

    snprintf(unexport_path, sizeof(unexport_path), GPIO_PATH "/unexport");

    fp = fopen(unexport_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", unexport_path, strerror(errno));
        return -1;
    }

    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[64];
    FILE *fp;

    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/gpio%d/direction", pin);

    fp = fopen(direction_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", direction_path, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Reads the value of the specified GPIO pin (0 or 1)
int gpio_read(int pin) {
    char value_path[64];
    FILE *fp;
    int value;

    snprintf(value_path, sizeof(value_path), GPIO_PATH "/gpio%d/value", pin);

    fp = fopen(value_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", value_path, strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%d", &value) != 1) {
        fprintf(stderr, "Error reading value from %s\n", value_path);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return value;
}

// Converts the GPIO value (0 or 1) to a voltage (0V or 3.3V)
float voltage_from_gpio(int gpio_value) {
    if (gpio_value == 0) {
        return 0.0;
    } else {
        return 3.3;
    }
}

// Converts the voltage to a distance using the formula distance = A / voltage + B
float distance_from_voltage(float voltage) {
    if (voltage == 0.0) {
        return 1000.0; // Return a large value to avoid division by zero
    }
    return A / voltage + B;
}

// Logs the distance to the distance_log.txt file with a timestamp
void log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

// Checks if the distance is below the proximity threshold and prints the appropriate message
void check_proximity(float distance) {
    if (distance < PROXIMITY_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Proximity Sensor\n");

    // Main loop
    while (program_running) {
        int gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d value, retrying in 1 second\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        float voltage = voltage_from_gpio(gpio_value);
        float distance = distance_from_voltage(voltage);

        log_distance(distance);
        check_proximity(distance);

        sleep(1); // Read every 1 second
    }

    // Unexport GPIO pin before exiting
    gpio_unexport(GPIO_PIN);

    return 0;
}

