#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 5.0
#define FULL_SCALE_CURRENT 50.0
#define ZERO_CURRENT_VOLTAGE 2.5
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_US 100000 // 100 ms

// Global variables
static volatile int running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
float voltage_from_adc(int adc_value);
float current_from_voltage(float voltage);
void log_current(float current);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to convert voltage to current
float current_from_voltage(float voltage) {
    if (voltage < 0.0 || voltage > VREF) {
        fprintf(stderr, "Voltage out of range: %.2f V\n", voltage);
        return -1.0; // Indicate error
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (FULL_SCALE_CURRENT / (VREF - ZERO_CURRENT_VOLTAGE));
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Setup function to initialize pigpio and SPI
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue; // Skip to the next sample on error
        }

        // Convert to voltage
        float voltage = voltage_from_adc(adc_value);

        // Convert to current
        float current = current_from_voltage(voltage);
        if (current < 0.0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue; // Skip to the next sample on error
        }

        // Log current
        log_current(current);

        // Delay for sampling interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

