#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Define the GPIO chip number (usually 0 for Raspberry Pi)
#define GPIOCHIP 0

// Debounce parameters
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line;
struct gpiod_line *sensor2_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read a sensor value with debouncing
int read_sensor(struct gpiod_line *line) {
    int values[DEBOUNCE_SAMPLES];
    int i;

    // Read multiple samples
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        values[i] = gpiod_line_get_value(line);
        usleep(DEBOUNCE_DELAY_MS * 1000); // Delay for debouncing
    }

    // Determine the majority value
    int low_count = 0;
    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (values[i] == 0) {
            low_count++;
        }
    }

    if (low_count > DEBOUNCE_SAMPLES / 2) {
        return 0; // Object present (LOW)
    } else {
        return 1; // No object (HIGH)
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);

    if (!sensor1_line || !sensor2_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        perror("Error requesting GPIO line as input (sensor1)");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        perror("Error requesting GPIO line as input (sensor2)");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);

        // Log sensor states
        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_value, sensor2_value);

        // Check for simultaneous object detection
        if (sensor1_value == 0 && sensor2_value == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_chip_close(chip);

    return 0;
}

