    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

