#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam/"
#define DEBOUNCE_DELAY_MS 200
#define POLL_DELAY_MS 50

static volatile int running = 1;

// Function to generate ISO 8601 timestamp
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n --width %d --height %d --immediate", filename, IMAGE_WIDTH, IMAGE_HEIGHT);

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("execl failed");
        exit(1); // Exit with an error code if execl fails
    } else if (pid < 0) {
        // Fork failed
        syslog(LOG_ERR, "Failed to fork process");
        return -1;
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            syslog(LOG_INFO, "Image captured successfully: %s", filename);
            return 0;
        } else {
            syslog(LOG_ERR, "Image capture failed with status: %d", WEXITSTATUS(status));
            return -1;
        }
    }
}

// Function to handle motion detection
void motion_detected() {
    char *timestamp = generate_timestamp();
    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.jpg", IMAGE_DIR, timestamp);

    syslog(LOG_INFO, "Motion detected, capturing image: %s", filename);
    if (capture_image(filename) != 0) {
        syslog(LOG_ERR, "Failed to capture image.");
    }
    free(timestamp);
}

// Function to check if the image directory exists, create it if it doesn't
int check_image_directory() {
    struct stat st = {0};

    if (stat(IMAGE_DIR, &st) == -1) {
        if (mkdir(IMAGE_DIR, 0777) == 0) {
            syslog(LOG_INFO, "Created image directory: %s", IMAGE_DIR);
            return 0;
        } else {
            syslog(LOG_ERR, "Failed to create image directory: %s", IMAGE_DIR);
            return -1;
        }
    } else {
        syslog(LOG_INFO, "Image directory exists: %s", IMAGE_DIR);
        return 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

int main() {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Check image directory
    if (check_image_directory() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO mode and pull-down resistor
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Security camera started");

    int last_state = 0; // Initialize last state

    while (running) {
        int current_state = gpioRead(PIR_GPIO);

        if (current_state != last_state) {
            // State changed, apply debounce
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            int debounced_state = gpioRead(PIR_GPIO);

            if (debounced_state == current_state) {
                // Debounced state is valid
                if (debounced_state == 1) {
                    motion_detected();
                }
                last_state = debounced_state; // Update last state
            }
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Poll every 50ms
    }

    // Cleanup
    gpioTerminate();
    syslog(LOG_INFO, "Security camera stopped");
    closelog();

    return 0;
}

