#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FRAME_BUFFER_COUNT 1

// Structure to hold device information
typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int frame_count;
    char *device_path;
} device_info_t;

// Global array to store device information
device_info_t devices[2];
int num_devices = 0;

// Signal handler flag
volatile sig_atomic_t stop_flag = 0;

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Signal received, stopping...\n");
        stop_flag = 1;
    }
}

// Function to open a V4L2 device
int open_device(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device_path, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize a V4L2 device
int init_device(int fd, int device_index) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = FRAME_BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    devices[device_index].buffer = buffer;
    devices[device_index].buffer_size = buf.length;
    devices[device_index].frame_count = 0;
    devices[device_index].fd = fd;
    devices[device_index].device_path = strdup(devices[device_index].device_path); // Store the device path

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture a frame from a V4L2 device
int capture_frame(int fd, void *buffer, size_t buffer_size, int device_index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1; // Timeout
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN) {
            return -1; // Buffer not ready
        }
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Generate filename
    char filename[50];
    snprintf(filename, sizeof(filename), "image_%04d_%d.pgm", devices[device_index].frame_count + 1, device_index + 1);

    // Write PGM file
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        }
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(buffer, 1, buffer_size, fp);

    fclose(fp);

    devices[device_index].frame_count++;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to close a V4L2 device
int close_device(int fd, int device_index) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    if (devices[device_index].buffer != NULL) {
        if (munmap(devices[device_index].buffer, devices[device_index].buffer_size) == -1) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
        devices[device_index].buffer = NULL;
    }

    if (close(fd) == -1) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }

    free(devices[device_index].device_path);
    devices[device_index].device_path = NULL;

    return 0;
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize devices
    if (argc > 1) {
        devices[0].device_path = argv[1];
        num_devices = 1;
        if (argc > 2) {
            devices[1].device_path = argv[2];
            num_devices = 2;
        }
    } else {
        devices[0].device_path = DEFAULT_DEVICE;
        num_devices = 1;
    }

    for (int i = 0; i < num_devices; i++) {
        devices[i].fd = open_device(devices[i].device_path);
        if (devices[i].fd == -1) {
            // Handle error: close already opened devices
            for (int j = 0; j < i; j++) {
                close_device(devices[j].fd, j);
            }
            return EXIT_FAILURE;
        }

        if (init_device(devices[i].fd, i) == -1) {
            // Handle error: close already opened devices
            close_device(devices[i].fd, i);
            for (int j = 0; j < i; j++) {
                close_device(devices[j].fd, j);
            }
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (!stop_flag) {
        for (int i = 0; i < num_devices; i++) {
            if (capture_frame(devices[i].fd, devices[i].buffer, devices[i].buffer_size, i) == -1) {
                fprintf(stderr, "Error capturing frame from device %s\n", devices[i].device_path);
            }
        }
    }

    // Cleanup
    for (int i = 0; i < num_devices; i++) {
        if (close_device(devices[i].fd, i) == -1) {
            fprintf(stderr, "Error closing device %s during cleanup\n", devices[i].device_path);
        }
    }

    return EXIT_SUCCESS;
}

