#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define LOG_FILE "frame_log.txt"

typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
int fd = -1; // File descriptor for the video device
FILE *log_file = NULL;
int running = 1; // Flag to control the main loop

// Function to handle errors
void error_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Function to initialize the video device
int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    // Open the video device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        error_exit("Cannot open device");
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        error_exit("VIDIOC_QUERYCAP failed");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        exit(EXIT_FAILURE);
    }

    // Set the video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        error_exit("VIDIOC_S_FMT failed");
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        error_exit("VIDIOC_REQBUFS failed");
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer));
