#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FRAME_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV format
#define NUM_BUFFERS 4
#define UDP_PAYLOAD_SIZE 65000
#define HEADER_SIZE 16 // sizeof(FrameHeader)

// Structure to hold frame header information
typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} FrameHeader;

// Global variables (minimize usage)
static int video_fd = -1;
static int socket_fd = -1;
static struct sockaddr_in server_addr;
static unsigned int frame_index = 0;
static volatile sig_atomic_t stop_flag = 0;

// Buffer structure
typedef struct {
    void   *start;
    size_t  length;
} buffer;

static buffer *buffers = NULL;

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd, int width, int height);
int start_capturing(int fd);
int stop_capturing(int fd);
int uninit_device(int fd);
int close_device(int fd);
int create_socket(const char *server_ip, int server_port);
int send_frame(int socket_fd, struct sockaddr_in server_addr, unsigned char *frame_buffer, size_t frame_size, unsigned int frame_index);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d.  Stopping...\n", sig);
    stop_flag = 1;
}

// Open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Initialize the video device
int init_device(int fd, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Start capturing
int start_capturing(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Uninitialize the device
int uninit_device(int fd) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
    }
    free(buffers);
    return 0;
}

// Close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Create a UDP socket
int create_socket(const char *server_ip, int server_port) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(fd);
        return -1;
    }

    return fd;
}

// Send a frame over UDP
int send_frame(int socket_fd, struct sockaddr_in server_addr, unsigned char *frame_buffer, size_t frame_size, unsigned int frame_index) {
    unsigned int num_fragments = (frame_size + UDP_PAYLOAD_SIZE - HEADER_SIZE - 1) / (UDP_PAYLOAD_SIZE - HEADER_SIZE);
    unsigned char *data_ptr = frame_buffer;

    for (unsigned int i = 0; i < num_fragments; i++) {
        FrameHeader header;
        header.frame_index = frame_index;
        header.fragment_index = i;
        header.total_fragments = num_fragments;
        header.payload_size = (i == num_fragments - 1) ? (frame_size - (num_fragments - 1) * (UDP_PAYLOAD_SIZE - HEADER_SIZE)) : (UDP_PAYLOAD_SIZE - HEADER_SIZE);

        unsigned char packet[UDP_PAYLOAD_SIZE];
        memcpy(packet, &header, HEADER_SIZE);
        memcpy(packet + HEADER_SIZE, data_ptr, header.payload_size);

        if (sendto(socket_fd, packet, HEADER_SIZE + header.payload_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            fprintf(stderr, "Error sending data: %s\n", strerror(errno));
            return -1;
        }

        data_ptr += header.payload_size;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (video_fd != -1) {
        stop_capturing(video_fd);
        uninit_device(video_fd);
        close_device(video_fd);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
    video_fd = open_device(DEVICE_NAME);
    if (video_fd < 0) {
        return 1;
    }

    // Initialize the video device
    if (init_device(video_fd, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
        cleanup();
        return 1;
    }

    // Create the UDP socket
    socket_fd = create_socket(server_ip, server_port);
    if (socket_fd < 0) {
        cleanup();
        return 1;
    }

    // Start capturing
    if (start_capturing(video_fd) < 0) {
        cleanup();
        return 1;
    }

    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    // Main loop
    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(video_fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "select interrupted by signal\n");
                break;
            }
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            break;
        }

        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        // Send the frame
        if (send_frame(socket_fd, server_addr, (unsigned char *)buffers[buf.index].start, buffers[buf.index].length, frame_index) < 0) {
            fprintf(stderr, "Error sending frame\n");
            break;
        }

        frame_index++;

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

