#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define OUTPUT_FILE "image.jpg"

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
int                  fd = -1;             // Device file descriptor
struct buffer        *buffers = NULL;      // Array of buffers
unsigned int         n_buffers = 0;      // Number of buffers
FILE                 *fp = NULL;          // File pointer for output

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);
    if (fd != -1) {
        // Stop streaming
        if (ioctl(fd, VIDIOC_STREAMOFF, 0) == -1) {
            perror("VIDIOC_STREAMOFF");
        }

        // Unmap buffers
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (munmap(buffers[i].start, buffers[i].length) == -1) {
                perror("munmap");
            }
        }

        // Free buffer array
        free(buffers);

        // Close device
        close(fd);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    exit(0);
}

// Function to query device capabilities
int query_device_capabilities(int fd) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    printf("Device %s supports video capture and streaming.\n", DEVICE_NAME);
    return 0;
}

// Function to set the video format
int set_video_format(int fd) {
    struct v4l2_format fmt;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    // Verify the format
    if (ioctl(fd, VIDIOC_G_FMT, &fmt) == -1) {
        perror("VIDIOC_G_FMT");
        return -1;
    }

    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT ||
        fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Error: Could not set desired format\n");
        return -1;
    }

    printf("Format set to %dx%d MJPEG\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    return 0;
}

// Function to request buffers
int request_buffers(int fd) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    n_buffers = req.count;
    buffers = calloc(req.count, sizeof(struct buffer));

    if (!buffers) {
        perror("calloc");
        return -1;
    }

    return 0;
}

// Function to mmap buffers
int mmap_buffers(int fd) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
    }

    return 0;
}

// Function to queue buffers
int queue_buffers(int fd) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }

    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buf) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    return 0;
}

// Function to write the image to a file
int write_image(const void *data, size_t size) {
    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error: Could not write all bytes to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Image saved to %s\n", OUTPUT_FILE);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Query device capabilities
    if (query_device_capabilities(fd) == -1) {
        close(fd);
        return 1;
    }

    // Set video format
    if (set_video_format(fd) == -1) {
        close(fd);
        return 1;
    }

    // Request buffers
    if (request_buffers(fd) == -1) {
        close(fd);
        return 1;
    }

    // Mmap buffers
    if (mmap_buffers(fd) == -1) {
        free(buffers);
        close(fd);
        return 1;
    }

    // Queue buffers
    if (queue_buffers(fd) == -1) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    // Dequeue a buffer
    struct v4l2_buffer buf;
    if (dequeue_buffer(fd, &buf) == -1) {
        if (ioctl(fd, VIDIOC_STREAMOFF, 0) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    // Verify bytes used
    if (buf.bytesused == 0) {
        fprintf(stderr, "Error: No data received\n");
        if (ioctl(fd, VIDIOC_STREAMOFF, 0) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    // Write the image to a file
    if (write_image(buffers[buf.index].start, buf.bytesused) == -1) {
        if (ioctl(fd, VIDIOC_STREAMOFF, 0) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        for (unsigned int i = 0; i < n_buffers; ++i) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
        close(fd);
        return 1;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, 0) == -1) {
        perror("VIDIOC_STREAMOFF");
    }

    // Unmap buffers
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("munmap");
        }
    }

    // Free buffer array
    free(buffers);

    // Close device
    close(fd);

    return 0;
}

