#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM parameters
#define PWM_PERIOD_NS 20000000 // 20 ms
#define MIN_PULSE_WIDTH_NS 1000000  // 1 ms
#define MAX_PULSE_WIDTH_NS 2000000  // 2 ms

// Define servo position range
#define MIN_POSITION 25
#define MAX_POSITION 125
#define INITIAL_POSITION 75

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pan_line;
static struct gpiod_line *tilt_line;
static struct gpiod_line *tilt_up_line;
static struct gpiod_line *tilt_down_line;
static struct gpiod_line *pan_left_line;
static struct gpiod_line *pan_right_line;

static volatile int running = 1;

// Function prototypes
int set_servo_position(struct gpiod_line *line, int position);
int read_button(struct gpiod_line *line);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Function to set the servo position using software PWM
int set_servo_position(struct gpiod_line *line, int position) {
    if (position < MIN_POSITION || position > MAX_POSITION) {
        fprintf(stderr, "Error: Position out of range (%d).\n", position);
        return -1;
    }

    // Calculate pulse width based on position
    int pulse_width_ns = MIN_PULSE_WIDTH_NS + (int)(((float)(position - MIN_POSITION) / (MAX_POSITION - MIN_POSITION)) * (MAX_PULSE_WIDTH_NS - MIN_PULSE_WIDTH_NS));

    // Calculate number of high and low cycles
    int high_cycles = pulse_width_ns * 1000 / PWM_PERIOD_NS; // Duty cycle percentage
    int low_cycles = 1000 - high_cycles;

    // Generate PWM signal
    for (int i = 0; i < 1000; i++) {
        if (i < high_cycles) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Error setting line value high");
                return -1;
            }
        } else {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Error setting line value low");
                return -1;
            }
        }
        usleep(PWM_PERIOD_NS / 1000); // Sleep for 1/1000 of the period
    }

    return 0;
}

// Function to read the button state
int read_button(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading line value");
        return -1;
    }
    return value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_BUTTON);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_BUTTON);
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT_BUTTON);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_BUTTON);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line || !pan_left_line || !pan_right_line) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    // Request GPIO lines for output (servos) and input (buttons)
    if (gpiod_line_request_output(pan_line, "pan_servo", 0) < 0 ||
        gpiod_line_request_output(tilt_line, "tilt_servo", 0) < 0 ||
        gpiod_line_request_input(tilt_up_line, "tilt_up_button") < 0 ||
        gpiod_line_request_input(tilt_down_line, "tilt_down_button") < 0 ||
        gpiod_line_request_input(pan_left_line, "pan_left_button") < 0 ||
        gpiod_line_request_input(pan_right_line, "pan_right_button") < 0) {
        perror("Error requesting GPIO line");
        goto cleanup;
    }

    // Set initial servo positions
    int pan_position = INITIAL_POSITION;
    int tilt_position = INITIAL_POSITION;

    if (set_servo_position(pan_line, pan_position) < 0 || set_servo_position(tilt_line, tilt_position) < 0) {
        fprintf(stderr, "Error setting initial servo positions.\n");
        goto cleanup;
    }

    // Main loop
    while (running) {
        // Read button states
        int tilt_up_pressed = (read_button(tilt_up_line) == 0);
        int tilt_down_pressed = (read_button(tilt_down_line) == 0);
        int pan_left_pressed = (read_button(pan_left_line) == 0);
        int pan_right_pressed = (read_button(pan_right_line) == 0);

        // Update servo positions based on button presses
        if (tilt_up_pressed) {
            tilt_position += 5;
            if (tilt_position > MAX_POSITION) {
                tilt_position = MAX_POSITION;
            }
            set_servo_position(tilt_line, tilt_position);
        }
        if (tilt_down_pressed) {
            tilt_position -= 5;
            if (tilt_position < MIN_POSITION) {
                tilt_position = MIN_POSITION;
            }
            set_servo_position(tilt_line, tilt_position);
        }
        if (pan_left_pressed) {
            pan_position -= 5;
            if (pan_position < MIN_POSITION) {
                pan_position = MIN_POSITION;
            }
            set_servo_position(pan_line, pan_position);
        }
        if (pan_right_pressed) {
            pan_position += 5;
            if (pan_position > MAX_POSITION) {
                pan_position = MAX_POSITION;
            }
            set_servo_position(pan_line, pan_position);
        }

        usleep(50000); // 50 ms delay
    }

cleanup:
    // Release GPIO lines
    if (pan_line) gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up_line) gpiod_line_release(tilt_up_line);
    if (tilt_down_line) gpiod_line_release(tilt_down_line);
    if (pan_left_line) gpiod_line_release(pan_left_line);
    if (pan_right_line) gpiod_line_release(pan_right_line);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 0;
}

