// Function to apply a 5x5 box blur
void box_blur(unsigned char *input, unsigned char *output, int width, int height, int radius) {
    int i, j, k, l;
    int r, g, b;
    int sum_r, sum_g, sum_b;
    int x, y;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            sum_r = 0;
            sum_g = 0;
            sum_b = 0;

            for (k = -radius; k <= radius; k++) {
                for (l = -radius; l <= radius; l++) {
                    x = j + l;
                    y = i + k;

                    // Clamp to image boundaries
                    if (x < 0) x = 0;
                    if (x >= width) x = width - 1;
                    if (y < 0) y = 0;
                    if (y >= height) y = height - 1;

                    r = input[(y * width + x) * 3 + 0];
                    g = input[(y * width + x) * 3 + 1];
                    b = input[(y * width + x) * 3 + 2];

                    sum_r += r;
                    sum_g += g;
                    sum_b += b;
