        close(fd);
        return 1;
    }

    // Enumerate frame rates for each resolution (example: 640x480 and 1280x720)
    if (enumerate_frame_rates(fd, 640, 480) != 0) {
        close(fd);
        return 1;
    }
    if (enumerate_frame_rates(fd, 1280, 720) != 0) {
        close(fd);
        return 1;
    }

    // Check for autofocus support
    if (check_autofocus_support(fd) < 0) {
        close(fd);
        return 1;
