#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Define servo increment/decrement step
#define SERVO_STEP 10

// Define loop delay in milliseconds
#define LOOP_DELAY_MS 50

// Global variables for servo positions
int pan_position = 1500;
int tilt_position = 1500;

// Function prototypes
void signal_handler(int signal);
void move_pan(int direction);
void move_tilt(int direction);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to move the pan servo
void move_pan(int direction) {
    pan_position += direction * SERVO_STEP;
    if (pan_position < SERVO_MIN_PULSE_WIDTH) {
        pan_position = SERVO_MIN_PULSE_WIDTH;
    } else if (pan_position > SERVO_MAX_PULSE_WIDTH) {
        pan_position = SERVO_MAX_PULSE_WIDTH;
    }
    gpioServo(PAN_SERVO_PIN, pan_position);
}

// Function to move the tilt servo
void move_tilt(int direction) {
    tilt_position += direction * SERVO_STEP;
    if (tilt_position < SERVO_MIN_PULSE_WIDTH) {
        tilt_position = SERVO_MIN_PULSE_WIDTH;
    } else if (tilt_position > SERVO_MAX_PULSE_WIDTH) {
        tilt_position = SERVO_MAX_PULSE_WIDTH;
    }
    gpioServo(TILT_SERVO_PIN, tilt_position);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable internal pull-up resistors for buttons
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set initial servo positions
    gpioServo(PAN_SERVO_PIN, pan_position);
    gpioServo(TILT_SERVO_PIN, tilt_position);

    // Print startup message
    printf("Pan-Tilt Control System\n");
    printf("Pan Servo: GPIO%d, Tilt Servo: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("UP: GPIO%d, DOWN: GPIO%d, LEFT: GPIO%d, RIGHT: GPIO%d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Initial position: Pan = %d, Tilt = %d\n", pan_position, tilt_position);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read button states
        int up_pressed = (gpioRead(UP_BUTTON_PIN) == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        // Move servos based on button presses
        if (up_pressed) {
            move_tilt(1); // Tilt up
        }
        if (down_pressed) {
            move_tilt(-1); // Tilt down
        }
        if (left_pressed) {
            move_pan(-1); // Pan left
        }
        if (right_pressed) {
            move_pan(1); // Pan right
        }

        // Delay
        gpioDelay(LOOP_DELAY_MS * 1000); // Convert ms to microseconds
    }

    return 0;
}

