#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <jansson.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define MOTION_STATUS "Motion Detected"
#define NO_MOTION_STATUS "No Motion"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
char *server_ip = NULL;
char *server_port = NULL;

// Structure to hold program state
typedef struct {
    time_t last_motion_time;
    int gpio_initialized;
    int curl_initialized;
} ProgramState;

ProgramState state = {0, 0, 0};

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_image(char *filename);
int send_data(char *filename, char *timestamp, char *status, int gpio_pin);
void signal_handler(int signal);
char* get_iso8601_timestamp();
int create_motion_captures_dir();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    state.gpio_initialized = 1;
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture an image using libcamera-still
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n --width %d --height %d --quality %d", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still: %s\n", strerror(errno));
        return 1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return 1;
    }

    return 0;
}

// Function to send data to the server using libcurl
int send_data(char *filename, char *timestamp, char *status, int gpio_pin) {
    CURL *curl;
    CURLcode res;
    json_t *root;
    json_t *data;
    char *json_string;
    long response_code = 0; // Initialize response_code

    // Create JSON payload
    root = json_object();
    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "status", json_string(status));
    json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));

    json_string = json_dumps(root, JSON_REAL_PRECISION(5));

    if (!json_string) {
        fprintf(stderr, "Error creating JSON string\n");
        json_decref(root);
        return 1;
    }

    // Initialize libcurl
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error initializing libcurl\n");
        json_decref(root);
        free(json_string);
        return 1;
    }

    // Construct the URL
    char url[256];
    snprintf(url, sizeof(url), "http://%s:%s/upload", server_ip, server_port);

    // Set the URL and other options
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback); // Set the write callback

    // Set the content type to application/json
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the request
    res = curl_easy_perform(curl);

    // Get the response code
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);

    // Check for errors
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
        printf("HTTP Response Code: %ld\n", response_code);
    }

    // Clean up
    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    json_decref(root);
    free(json_string);

    return (res != CURLE_OK) ? 1 : 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(30 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to create the motion_captures directory
int create_motion_captures_dir() {
    struct stat st = {0};

    if (stat("motion_captures", &st) == -1) {
        if (mkdir("motion_captures", 0777) == -1) {
            if (errno == EEXIST) {
                // Directory already exists, which is fine
