#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_fp;
static volatile sig_atomic_t terminate = 0;

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "[%s] %s\n", timestamp, message);
    fflush(log_fp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    log_message("Received signal, exiting...");
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        log_message("Error executing libcamera-still command.");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "libcamera-still exited with status %d", WEXITSTATUS(status));
        log_message(log_msg);
        return -1;
    }
    return 0;
}

// Function to generate a timestamped filename
int generate_filename(char *filename, size_t filename_size) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (strftime(filename, filename_size, "%Y%m%d_%H%M%S_000.jpg", t) == 0) {
        log_message("Error generating filename.");
        return -1;
    }
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char filename[64];
    if (generate_filename(filename, sizeof(filename)) != 0) {
        return;
    }

    char filepath[128];
    snprintf(filepath, sizeof(filepath), "%s/%s", IMAGE_DIR, filename);

    log_message("Motion detected, capturing image...");
    if (capture_image(filepath) == 0) {
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Image captured: %s", filepath);
        log_message(log_msg);
    } else {
        log_message("Failed to capture image.");
    }
}

int main() {
    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_message("Starting motion capture...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_message("Error opening GPIO chip.");
        fclose(log_fp);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_message("Error getting GPIO line.");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return 1;
    }

    // Request GPIO line for input with rising edge detection
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;

    if (gpiod_line_request(line, &config, 0) != 0) {
        log_message("Error requesting GPIO line.");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return 1;
    }

    log_message("Motion capture started.");

    // Main loop
    while (!terminate) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            log_message("Error waiting for GPIO event.");
            break;
        }

        if (ret > 0) {
            if (gpiod_line_event_read(line, &event) == 0) {
                handle_motion();
            } else {
                log_message("Error reading GPIO event.");
            }
        }
    }

    // Release GPIO resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    log_message("Exiting motion capture.");

    fclose(log_fp);

    return 0;
}

