#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"

// Global variables for signal handling
static int fd = -1;
static void *buffer = NULL;
static struct v4l2_buffer v4l2_buf;
static struct v4l2_requestbuffers req;
static struct v4l2_format fmt;

// Signal handler function
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);

    if (fd != -1) {
        // Stop streaming
        if (ioctl(fd, VIDIOC_STREAMOFF, &v4l2_buf.type) == -1) {
            perror("VIDIOC_STREAMOFF failed");
        }

        // Unmap the buffer
        if (buffer != NULL) {
            if (munmap(buffer, req.length) == -1) {
                perror("munmap failed");
            }
        }

        // Close the device
        if (close(fd) == -1) {
            perror("close failed");
        }
    }

    exit(EXIT_SUCCESS);
}

// Function to query device capabilities
int query_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    printf("Device capabilities: %s\n", cap.card);
    return 0;
}

// Function to set the video format
int set_format(int fd) {
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd) {
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Function to query buffer
int query_buffer(int fd) {
    memset(&v4l2_buf, 0, sizeof(v4l2_buf));
    v4l2_buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    v4l2_buf.memory = V4L2_MEMORY_MMAP;
    v4l2_buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &v4l2_buf) == -1) {
        perror("VIDIOC_QUERYBUF failed");
        return -1;
    }

    return 0;
}

// Function to mmap the buffer
int mmap_buffer(int fd) {
    buffer = mmap(NULL, v4l2_buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, v4l2_buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    return 0;
}

