#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define neutral angle (degrees)
#define NEUTRAL_ANGLE 90

// Global variables for pan and tilt angles
int pan_angle = NEUTRAL_ANGLE;
int tilt_angle = NEUTRAL_ANGLE;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int gpio, int angle);
int handle_input(char input);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set initial angles to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    return 0; // Indicate success
}

// Function to set the servo angle based on GPIO and angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180 degrees)\n");
        return 1; // Indicate failure
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(gpio, pulse_width);

    return 0; // Indicate success
}

// Function to handle user input and update pan/tilt angles
int handle_input(char input) {
    switch (input) {
        case 'w': // Up arrow
            tilt_angle += 5;
            if (tilt_angle > MAX_ANGLE) {
                tilt_angle = MAX_ANGLE;
            }
            set_servo_angle(TILT_GPIO, tilt_angle);
            break;
        case 's': // Down arrow
            tilt_angle -= 5;
            if (tilt_angle < MIN_ANGLE) {
                tilt_angle = MIN_ANGLE;
            }
            set_servo_angle(TILT_GPIO, tilt_angle);
            break;
        case 'a': // Left arrow
            pan_angle -= 5;
            if (pan_angle < MIN_ANGLE) {
                pan_angle = MIN_ANGLE;
            }
            set_servo_angle(PAN_GPIO, pan_angle);
            break;
        case 'd': // Right arrow
            pan_angle += 5;
            if (pan_angle > MAX_ANGLE) {
                pan_angle = MAX_ANGLE;
            }
            set_servo_angle(PAN_GPIO, pan_angle);
            break;
        case 'q': // Quit
            return 1; // Indicate quit
        default:
            fprintf(stderr, "Invalid input. Use w/a/s/d to move, q to quit.\n");
            break;
    }
    return 0; // Indicate continue
}

// Function to clean up GPIO and terminate pigpio
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);

    gpioTerminate();
    printf("pigpio terminated\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pan-Tilt Camera Control\n");
    printf("Use w/a/s/d to move, q to quit.\n");

    char input;
    while (1) {
        input = getchar();

        if (handle_input(input) == 1) {
            break; // Quit if 'q' is pressed
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up GPIO before exiting
    cleanup_gpio();

    return 0;
}

