#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);

// Function to handle pulses from the flow sensor
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to initialize the LCD
int lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialization sequence (adjust as needed for your LCD)
    char init_commands[] = {0x33, 0x32, 0x28, 0x0C, 0x06, 0x01};
    for (int i = 0; i < sizeof(init_commands); i++) {
        i2cWriteByte(i2c_handle, init_commands[i]);
        gpioDelay(1000); // 1ms delay
    }

    return 0;
}

// Function to clear the LCD
void lcd_clear() {
    i2cWriteByte(i2c_handle, 0x01);
    gpioDelay(2000); // 2ms delay
}

// Function to print text to the LCD at a specific row and column
void lcd_print(int row, int col, const char *text) {
    int addr = (row == 0) ? 0x80 : 0xC0; // Address for the start of each row
    addr += col;

    i2cWriteByte(i2c_handle, addr);
    i2cWriteDevice(i2c_handle, text, strlen(text));
}

// Function to update the LCD with flow rate and total volume
void update_lcd(double flow_rate, double total_volume) {
    char flow_str[20];
    char volume_str[20];

    snprintf(flow_str, sizeof(flow_str), "Flow: %.2f LPM", flow_rate);
    snprintf(volume_str, sizeof(volume_str), "Volume: %.2f L", total_volume);

    lcd_clear();
    lcd_print(0, 0, flow_str);
    lcd_print(1, 0, volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_lcd_update = time(NULL);

    // Main loop
    while (!terminate) {
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second

        double flow_rate = calculate_flow_rate(current_pulse_count);
        total_volume += flow_rate / 60.0; // Accumulate volume (LPM to L)

        printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);

        time_t current_time = time(NULL);
        if (difftime(current_time, last_lcd_update) >= 10.0) {
            update_lcd(flow_rate, total_volume);
            last_lcd_update = current_time;
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

