#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define LCD_I2C_ADDR 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_INTERVAL_MS 500

// Global variables
static volatile int anemometer_count = 0;
static int spi_handle = -1;
static int i2c_handle = -1;
static volatile int running = 1;

// Function prototypes
void anemometer_callback(int gpio, int level, uint32_t tick, void *user);
float calculate_wind_speed(int pulse_count);
int read_wind_direction();
int lcd_init(int i2c_handle);
int lcd_clear(int i2c_handle);
int lcd_write_string(int i2c_handle, const char *str);
void signal_handler(int signal);

// LCD I2C commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// Flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// PCF8574 LCD backpack defines
#define LCD_BACKLIGHT 0x08
#define En 0x04  // Enable bit
#define Rw 0x02  // Read/Write bit (not used in this example)
#define Rs 0x01  // Register select bit

// Function to send command to LCD
void lcd_send_command(int i2c_handle, unsigned char cmd) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);

    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | En | LCD_BACKLIGHT;
    data_t[2] = data_u | LCD_BACKLIGHT;
    data_t[3] = data_l | LCD_BACKLIGHT;

    i2cWriteDevice(i2c_handle, (char *)data_t, 4);
}

// Function to send data to LCD
void lcd_send_data(int i2c_handle, unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | Rs | LCD_BACKLIGHT;
    data_t[1] = data_u | Rs | En | LCD_BACKLIGHT;
    data_t[2] = data_u | Rs | LCD_BACKLIGHT;
    data_t[3] = data_l | Rs | LCD_BACKLIGHT;

    i2cWriteDevice(i2c_handle, (char *)data_t, 4);
}

// Function to initialize the LCD
int lcd_init(int i2c_handle) {
    // 4-bit initialization sequence
    gpioDelay(50); // Wait for more than 4.1ms after VCC rises to 4.5V
    lcd_send_command(i2c_handle, 0x30); // Initialization command 1
    gpioDelay(5);  // Wait for more than 4.1ms
    lcd_send_command(i2c_handle, 0x30); // Initialization command 2
    gpioDelay(1);  // Wait for more than 100us
    lcd_send_command(i2c_handle, 0x30); // Initialization command 3
    gpioDelay(10); // Wait for more than 100us
    lcd_send_command(i2c_handle, 0x20); // 4-bit mode

    lcd_send_command(i2c_handle, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(i2c_handle, LCD_DISPLAYCONTROL | LCD_DISPLAYON);
    lcd_send_command(i2c_handle, LCD_ENTRYMODESET | LCD_ENTRYLEFT);
    lcd_clear(i2c_handle);
    return 0;
}

// Function to clear the LCD
int lcd_clear(int i2c_handle) {
    lcd_send_command(i2c_handle, LCD_CLEARDISPLAY);
    gpioDelay(2); // This command requires a long execution time > 1.53 ms
    return 0;
}

// Function to write a string to the LCD
int lcd_write_string(int i2c_handle, const char *str) {
    int i = 0;
    while (str[i] != '\0') {
        lcd_send_data(i2c_handle, str[i]);
        i++;
    }
    return 0;
}

// Anemometer interrupt callback function
void anemometer_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) {
        anemometer_count++;
    }
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count) {
    return pulse_count * 0.5; // 0.5 m/s per pulse
}

// Function to read wind direction from MCP3008
int read_wind_direction() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to wind direction (0-359 degrees)
float map_adc_to_degrees(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    // Linear mapping: 0-1023 -> 0-359
    return (float)adc_value * 359.0 / 1023.0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection to LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI connection to MCP3008
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set anemometer GPIO as input and register interrupt callback
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetAlertFuncEx(ANEMOMETER_GPIO, anemometer_callback, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read wind speed
        int pulse_count = anemometer_count;
        anemometer_count = 0; // Reset counter for next sample
        float wind_speed = calculate_wind_speed(pulse_count);

        // Read wind direction
        int adc_value = read_wind_direction();
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read wind direction\n");
        } else {
            float wind_direction = map_adc_to_degrees(adc_value);

            // Display data on LCD
            char lcd_buffer[32];
            snprintf(lcd_buffer, sizeof(lcd_buffer), "Speed: %.1f m/s", wind_speed);
            lcd_clear(i2c_handle);
            lcd_write_string(i2c_handle, lcd_buffer);

            snprintf(lcd_buffer, sizeof(lcd_buffer), "Dir: %.0f deg", wind_direction);
            lcd_send_command(i2c_handle, LCD_SETDDRAMADDR | 0x40); // Move cursor to second line
            lcd_write_string(i2c_handle, lcd_buffer);

            printf("Wind Speed: %.1f m/s, Wind Direction: %.0f degrees\n", wind_speed, wind_direction);
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup
    gpioSetAlertFuncEx(ANEMOMETER_GPIO, NULL, NULL); // Disable interrupt
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

