// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void lcd_init();
void lcd_clear();
void lcd_print(int row, int col, const char *text);
void signal_handler(int signal);

// Function to handle pulses from the flow sensor
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulses) {
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Function to display flow rate on the LCD
void display_flow_rate(float flow_rate) {
    char buffer[17]; // Buffer to hold the formatted string (16 chars + null terminator)
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

    lcd_clear();
    lcd_print(0, 0, buffer);
}

// LCD initialization function
void lcd_init() {
    // Initialize LCD
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error: Could not initialize LCD. Check I2C address and wiring.\n");
        exit(EXIT_FAILURE);
    }

    // Initialization sequence (adjust as needed for your LCD)
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x38); // Function set: 8-bit, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Display control: Display on, cursor off, blink off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Entry mode set: Increment cursor, no shift
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    usleep(2000); // Wait for clear display to complete
}

// Function to clear the LCD display
void lcd_clear() {
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display command
    usleep(2000); // Wait for clear display to complete
}

// Function to print text to the LCD at a specific row and column
void lcd_print(int row, int col, const char *text) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col; // First line address
    } else {
        addr = 0xC0 + col; // Second line address
    }

    wiringPiI2CWriteReg8(lcd_fd, 0x00, addr); // Set cursor position
    for (int i = 0; text[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(lcd_fd, 0x00, text[i]); // Write character
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set up interrupt handler for rising edge detection
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Could not set alert function for GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        sleep(1);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display flow rate on LCD
        display_flow_rate(flow_rate);

        // Check for sensor absence (e.g., zero pulses for a long time)
        if (pulse_count == 0) {
            fprintf(stderr, "Warning: No pulses detected from flow sensor. Check sensor connection.\n");
            lcd_clear();
            lcd_print(0, 0, "Sensor Absent");
        }
    }

    // Clean up resources before exiting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable interrupt handler
    lcd_clear();
    gpioTerminate();

    printf("Water flow monitoring stopped.\n");

    return 0;
}

