#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_pins = 8;

// Define GPIO chip name
const char *gpiochip = "gpiochip0";

// Global variable for GPIO chip
struct gpiod_chip *chip = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_pins; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (line) {
            gpiod_line_release(line);
        }
        line = gpiod_chip_get_line(chip, col_pins[i]);
        if (line) {
            gpiod_line_release(line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to display a frame on the LED matrix
int display_frame(int frame[]) {
    for (int row = 0; row < num_pins; row++) {
        // Set row pin HIGH
        struct gpiod_line *row_line = gpiod_chip_get_line(chip, row_pins[row]);
        if (!row_line) {
            fprintf(stderr, "Error getting row line %d\n", row_pins[row]);
            return -1;
        }
        if (set_gpio_value(row_line, 1) < 0) {
            gpiod_line_release(row_line);
            return -1;
        }

        // Set column pins LOW based on the frame data
        for (int col = 0; col < num_pins; col++) {
            struct gpiod_line *col_line = gpiod_chip_get_line(chip, col_pins[col]);
            if (!col_line) {
                fprintf(stderr, "Error getting column line %d\n", col_pins[col]);
                gpiod_line_release(row_line);
                return -1;
            }
            if (set_gpio_value(col_line, (frame[row * num_pins + col] == 0) ? 0 : 1) < 0) {
                gpiod_line_release(col_line);
                gpiod_line_release(row_line);
                return -1;
            }
            gpiod_line_release(col_line);
        }

        // Delay for scan time
        usleep(800);

        // Set row pin LOW
        if (set_gpio_value(row_line, 0) < 0) {
            gpiod_line_release(row_line);
            return -1;
        }
        gpiod_line_release(row_line);
    }
    return 0;
}

// Function to generate a left-to-right wave pattern
void generate_left_to_right_wave(int frame[]) {
    static int offset = 0;
    for (int i = 0; i < num_pins * num_pins; i++) {
        frame[i] = 0;
    }
    for (int i = 0; i < num_pins; i++) {
        frame[i * num_pins + (i + offset) % num_pins] = 1;
    }
    offset = (offset + 1) % num_pins;
}

// Function to generate a right-to-left wave pattern
void generate_right_to_left_wave(int frame[]) {
    static int offset = 0;
    for (int i = 0; i < num_pins * num_pins; i++) {
        frame[i] = 0;
    }
    for (int i = 0; i < num_pins; i++) {
        frame[i * num_pins + (num_pins - 1 - ((i + offset) % num_pins))] = 1;
    }
    offset = (offset + 1) % num_pins;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(gpiochip);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines for rows and columns
    for (int i = 0; i < num_pins; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (!line) {
            fprintf(stderr, "Error getting row line %d\n", row_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(line, "led_matrix", 0) < 0) {
            fprintf(stderr, "Error requesting row line %d as output\n", row_pins[i]);
            gpiod_line_release(line);
            goto cleanup;
        }

        line = gpiod_chip_get_line(chip, col_pins[i]);
        if (!line) {
            fprintf(stderr, "Error getting column line %d\n", col_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(line, "led_matrix", 0) < 0) {
            fprintf(stderr, "Error requesting column line %d as output\n", col_pins[i]);
            gpiod_line_release(line);
            goto cleanup;
        }
    }

    // Main loop
    int frame[num_pins * num_pins];
    while (1) {
        generate_left_to_right_wave(frame);
        if (display_frame(frame) < 0) {
            goto cleanup;
        }
        usleep(50000); // Delay between frames

        generate_right_to_left_wave(frame);
        if (display_frame(frame) < 0) {
            goto cleanup;
        }
        usleep(50000); // Delay between frames
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_pins; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, row_pins[i]);
        if (line) {
            gpiod_line_release(line);
        }
        line = gpiod_chip_get_line(chip, col_pins[i]);
        if (line) {
            gpiod_line_release(line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

