#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_pins = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[8];
struct gpiod_line *col_lines[8];

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Set all row anodes LOW and column cathodes HIGH
    for (int i = 0; i < num_pins; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
        }
        if (col_lines[i]) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to clear the LED matrix
int clear_matrix()
{
    for (int i = 0; i < num_pins; i++) {
        if (set_gpio_value(col_lines[i], 1) < 0) return -1; // Set column cathode HIGH
        if (set_gpio_value(row_lines[i], 0) < 0) return -1; // Set row anode LOW
    }
    return 0;
}

// Function to display a column of the wave
int display_column(int col_index, int wave_height)
{
    // Clear the matrix first
    if (clear_matrix() < 0) return -1;

    // Set the column cathode LOW
    if (set_gpio_value(col_lines[col_index], 0) < 0) return -1;

    // Set the row anodes HIGH up to the wave height
    for (int i = 0; i < wave_height; i++) {
        if (set_gpio_value(row_lines[i], 1) < 0) return -1;
    }

    // Delay for 150ms
    usleep(150000);

    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO lines for rows and columns
    for (int i = 0; i < num_pins; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error getting row GPIO line %d: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }

        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column GPIO line %d: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }

        // Request row lines as output
        if (gpiod_line_request_output(row_lines[i], NULL, 0) < 0) {
            fprintf(stderr, "Error requesting row GPIO line %d as output: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }

        // Request column lines as output
        if (gpiod_line_request_output(col_lines[i], NULL, 1) < 0) {
            fprintf(stderr, "Error requesting column GPIO line %d as output: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    // Wave animation loop
    while (1) {
        for (int col = 0; col < num_pins; col++) {
            // Calculate wave height (sine wave approximation)
            int wave_height = (int)((num_pins / 2.0) * (1.0 + sin((double)col * 2.0 * 3.14159 / num_pins)));

            if (display_column(col, wave_height) < 0) {
                goto cleanup;
            }
        }
    }

cleanup:
    // Release GPIO lines and close chip before exiting
    signal_handler(0); // Call signal handler to clean up
    return 1;
}

