    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            retries--;
            if (retries <= 0) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

