#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x45
#define COMMAND_REG 0x18
#define MEAS_RATE_REG 0x08
#define IRQ_ENABLE_REG 0x02
#define ALS_VIS_DATA0 0x22
#define ALS_VIS_DATA1 0x23
#define PS1_DATA0 0x24
#define PS1_DATA1 0x25

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }

    // Set measurement rate
    if (i2cWriteByteData(i2c_handle, MEAS_RATE_REG, 0x07) < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE_REG: %s\n", strerror(errno));
        return -1;
    }

    // Clear IRQ
    if (i2cWriteByteData(i2c_handle, IRQ_ENABLE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to IRQ_ENABLE_REG: %s\n", strerror(errno));
        return -1;
    }

    // Set command register to start measurements
    if (i2cWriteByteData(i2c_handle, COMMAND_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to COMMAND_REG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data
int read_sensor_data(int *proximity, int *ambient_light) {
    int als_vis_low, als_vis_high, ps1_low, ps1_high;

    als_vis_low = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0: %s\n", strerror(errno));
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, ALS_VIS_DATA1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1: %s\n", strerror(errno));
        return -1;
    }

    ps1_low = i2cReadByteData(i2c_handle, PS1_DATA0);
    if (ps1_low < 0) {
        fprintf(stderr, "Error reading PS1_DATA0: %s\n", strerror(errno));
        return -1;
    }

    ps1_high = i2cReadByteData(i2c_handle, PS1_DATA1);
    if (ps1_high < 0) {
        fprintf(stderr, "Error reading PS1_DATA1: %s\n", strerror(errno));
        return -1;
    }

    *ambient_light = (als_vis_high << 8) | als_vis_low;
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

// Function to log data to a file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

