#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22

#define PART_ID_VALUE 0x45
#define HW_KEY_VALUE 0x17
#define CH_LIST_VALUE 0x77 // Enable PS1 and ALS_VIS

#define ALS_FORCE 0x06
#define PS_FORCE 0x07

#define LOG_FILE "biometric_data.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(uint16_t *proximity, uint16_t *ambient_light);
void log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART_ID register
    status = i2cWriteByteData(i2c_handle, PART_ID_REG, 0); // Dummy write to read
    if (status < 0) {
        fprintf(stderr, "Error writing to PART_ID_REG: %d\n", status);
        return -1;
    }
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID_REG: %d\n", part_id);
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect PART_ID value: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }
    printf("Si1145 PART_ID: 0x%02X\n", part_id);

    // Write HW_KEY register
    status = i2cWriteByteData(i2c_handle, HW_KEY_REG, HW_KEY_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY_REG: %d\n", status);
        return -1;
    }

    // Write CH_LIST register
    status = i2cWriteByteData(i2c_handle, CH_LIST_REG, CH_LIST_VALUE);
    if (status < 0) {
        fprintf(stderr, "Error writing to CH_LIST_REG: %d\n", status);
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(uint16_t *proximity, uint16_t *ambient_light) {
    int status;

    // Trigger ALS measurement
    status = i2cWriteByteData(i2c_handle, COMMAND_REG, ALS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND_REG (ALS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Small delay for measurement

    // Trigger PS measurement
    status = i2cWriteByteData(i2c_handle, COMMAND_REG, PS_FORCE);
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND_REG (PS_FORCE): %d\n", status);
        return -1;
    }
    gpioDelay(10); // Small delay for measurement

    // Read PS1 data (2 bytes)
    char ps1_data[2];
    status = i2cReadI2CBlockData(i2c_handle, PS1_DATA_REG, ps1_data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading PS1 data: %d\n", status);
        return -1;
    }
    *proximity = (uint16_t)((ps1_data[1] << 8) | ps1_data[0]);

    // Read ALS_VIS data (2 bytes)
    char als_vis_data[2];
    status = i2cReadI2CBlockData(i2c_handle, ALS_VIS_DATA_REG, als_vis_data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading ALS_VIS data: %d\n", status);
        return -1;
    }
    *ambient_light = (uint16_t)((als_vis_data[1] << 8) | als_vis_data[0]);

    return 0;
}

// Log data to a CSV file
void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int status;
    uint16_t proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            // Log data
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

