#include <unistd.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ID 0x92
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);
int reinitialize_sensor();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to reinitialize the sensor
int reinitialize_sensor() {
    printf("Reinitializing sensor...\n");
    i2cClose(i2c_handle);
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    if (apds9960_init() != 0) {
        fprintf(stderr, "Error reinitializing APDS9960\n");
        return -1;
    }
    return 0;
}

// Function to initialize the APDS9960 sensor
int apds9960_init() {
    // Verify sensor ID
    int id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", id);
        return -1;
    }

    // Configure ENABLE register
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure ATIME register
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Configure WTIME register
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Configure PPULSE register
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Configure CONTROL register
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Configure CONFIG2 register
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the APDS9960 sensor
int read_apds9960_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int status = i2cReadByteData(i2c_handle, APDS9960_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading status register: %d\n", status);
        return -1;
    }

    // Check if data is ready
    if (!(status & 0x01)) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read red data
    int red_l = i2cReadByteData(i2c_handle, APDS9960_CDATAL);
    int red_h = i2cReadByteData(i2c_handle, APDS9960_CDATAH);
    if (red_l < 0 || red_h < 0) {
        fprintf(stderr, "Error reading red data\n");
        return -1;
    }
    *red = (red_h << 8) | red_l;

    // Read green data
    int green_l = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    int green_h = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    if (green_l < 0 || green_h < 0) {
        fprintf(stderr, "Error reading green data\n");
        return -1;
    }
    *green = (green_h << 8) | green_l;

    // Read blue data
    int blue_l = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    int blue_h = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    if (blue_l < 0 || blue_h < 0) {
        fprintf(stderr, "Error reading blue data\n");
        return -1;
    }
    *blue = (blue_h << 8) | blue_l;

    // Read proximity data
    int prox = i2cReadByteData(i2c_handle, APDS9960_PDATAL);
    if (prox < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    *proximity = (uint8_t)prox;

    return 0;
}

// Function to log data to a CSV file
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() != 0) {
        fprintf(stderr, "Error initializing APDS9960\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    uint8_t proximity;

    // Main loop
    while (!terminate) {
        if (read_apds9960_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization\n");
            if (reinitialize_sensor() != 0) {
                fprintf(stderr, "Failed to re-initialize sensor, exiting\n");
                break;
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

