#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l0x_init();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to write a byte to a VL53L0X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from a VL53L0X register
int read_block(int handle, uint8_t reg, char *buf, int len) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, len) != len) {
        fprintf(stderr, "Error reading block from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Initialize the VL53L0X sensor
int vl53l0x_init() {
    // Check sensor presence
    if (i2cWriteDevice(i2c_handle, "\x00", 1) != 1) {
        fprintf(stderr, "VL53L0X not found at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }

    // Required initialisation sequence (from datasheet)
    if (write_register(i2c_handle, 0x88, 0x00) < 0) return -1;
    if (write_register(i2c_handle, 0x80, 0x01) < 0) return -1;
    if (write_register(i2c_handle, 0xFF, 0x01) < 0) return -1;
    if (write_register(i2c_handle, 0x00, 0x00) < 0) return -1;
    if (write_register(i2c_handle, 0x91, 0x00) < 0) return -1;
    if (write_register(i2c_handle, 0x00, 0x01) < 0) return -1;
    if (write_register(i2c_handle, 0xFF, 0x00) < 0) return -1;
    if (write_register(i2c_handle, 0x80, 0x00) < 0) return -1;

    return 0;
}

// Read the distance from the VL53L0X sensor
int read_distance(uint16_t *distance) {
    char result[14];
    uint8_t interrupt_status;

    // Start a single measurement
    if (write_register(i2c_handle, SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Poll for interrupt
    int timeout_counter = 0;
    while (1) {
        if (read_register(i2c_handle, RESULT_INTERRUPT_STATUS, &interrupt_status) < 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (interrupt_status & 0x01) {
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout_counter++;
        if (timeout_counter > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the result block
    if (read_block(i2c_handle, RESULT_RANGE_STATUS, result, 14) < 0) {
        fprintf(stderr, "Error reading result block\n");
        return -1;
    }

    // Extract the distance
    *distance = (result[10] << 8) | result[11];

    // Clear the interrupt
    if (write_register(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

// Log the distance to a file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == FALLING_EDGE) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance in interrupt handler\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (vl53l0x_init() < 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as input with pull-up
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_TRIGGER, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep for 100 ms
    }

    // Cleanup
    gpioSetISRFuncEx(GPIO_TRIGGER, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt handler
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

