#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define SAMPLE_INTERVAL_MS 200

int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int ch101_address;
    int sample_interval_ms;
    char *log_file_name;
} config_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize pigpio and I2C
int initialize(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->ch101_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(config->log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to trigger a measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, TRIGGER_REG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int *distance) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read distance: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log the data to a file and stdout
void log_data(const char *timestamp, int distance) {
    fprintf(log_file, "%s, %d\n", timestamp, distance);
    printf("%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    config_t config = {
        .i2c_bus = I2C_BUS,
        .ch101_address = CH101_ADDR,
        .sample_interval_ms = SAMPLE_INTERVAL_MS,
        .log_file_name = "distance_log.txt"
    };

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    if (initialize(&config) != 0) {
        return 1;
    }

    char timestamp[20];
    int distance;

    while (!terminate) {
        if (trigger_measurement() == 0) {
            gpioDelay(50); // Wait for measurement to complete
            if (read_distance(&distance) == 0) {
                get_timestamp(timestamp);
                log_data(timestamp, distance);
            }
        } else {
            get_timestamp(timestamp);
            fprintf(log_file, "%s, I2C Error\n", timestamp);
            printf("%s, I2C Error\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(config.sample_interval_ms);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

