#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
int log_distance(float distance);
int control_led(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t config_reg1;
    uint8_t config_reg2;
} sensor_config_t;

// Function to initialize the I2C connection
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance: %d\n", bytes_read);
        return -1;
    }

    // Convert the raw data to a distance in centimeters (example)
    int16_t raw_distance = (buf[0] << 8) | buf[1];
    *distance = (float)raw_distance / 10.0; // Example conversion

    return 0;
}

// Function to log the distance to a file
int log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to control the LED based on the distance
int control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

