#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define RETRY_COUNT 3
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient_light);
int log_data(FILE *log_file, uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient_light) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, PROXIMITY_REG);
        if (result >= 0) {
            *proximity = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading proximity data: %d, retries remaining: %d\n", result, retries - 1);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REG);
        if (result >= 0) {
            *ambient_light = (uint16_t)result;
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data: %d, retries remaining: %d\n", result, retries - 1);
            retries--;
            gpioDelay(10); // Small delay before retrying
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ambient light data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

