#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x41
#define DISTANCE_HIGH_REG 0x00
#define DISTANCE_LOW_REG 0x01
#define GPIO_LED 17
#define DEFAULT_DISTANCE_THRESHOLD 100 // mm
#define LOG_FILE "tof_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
int distance_threshold = DEFAULT_DISTANCE_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
void log_data(uint16_t distance);
void control_led(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set back to input
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the ICU-20201 sensor
int initialize_sensor() {
    int retries = 3;
    int status = 0;

    while (retries > 0) {
        i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %d. Retrying...\n", i2c_handle);
            gpioDelay(100000); // 100 ms delay
            retries--;
            continue;
        }

        // Verify WHO_AM_I register
        char who_am_i;
        status = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, &who_am_i, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register: %d. Retrying...\n", status);
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100 ms delay
            retries--;
            continue;
        }

        if (who_am_i != WHO_AM_I_VALUE) {
            fprintf(stderr, "WHO_AM_I value mismatch: 0x%02X (expected 0x%02X). Retrying...\n", who_am_i, WHO_AM_I_VALUE);
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100 ms delay
            retries--;
            continue;
        }

        printf("ICU-20201 sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize ICU-20201 sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    char buffer[2];
    int status = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buffer, 2);

    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1; // Failure
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0; // Success
}

// Function to log the distance data to a file
void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %u mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED based on the distance
void control_led(uint16_t distance) {
    if (distance < distance_threshold) {
        gpioWrite(GPIO_LED, 1); // Turn on LED
    } else {
        gpioWrite(GPIO_LED, 0); // Turn off LED
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        distance_threshold = atoi(argv[1]);
        printf("Distance threshold set to: %d mm\n", distance_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    uint16_t distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying initialization.\n");
            i2cClose(i2c_handle);
            if (initialize_sensor() != 0) {
                fprintf(stderr, "Sensor re-initialization failed. Exiting.\n");
                terminate = 1; // Exit the loop if re-initialization fails
            }
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

