#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C device address of the Omron B5L-LD50-07050 sensor
#define I2C_ADDRESS 0x50

// Define the I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define the command frame to request a distance measurement
const uint8_t command_frame[] = {0x50, 0x0A, 0x00, 0x01};

// Define the size of the response frame
#define RESPONSE_FRAME_SIZE 15

// Define the number of samples to take per cycle
#define NUM_SAMPLES 10

// Define the intrusion detection threshold (1000 mm)
#define INTRUSION_THRESHOLD 1000

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Global variable to store the log file pointer
FILE *log_file = NULL;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C device if it's open
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C device closed.\n");
    }

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    exit(0);
}

// Function to initialize the I2C interface
int init_i2c() {
    // Open the I2C device file
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to send a command frame to the sensor
int send_command(const uint8_t *command, size_t command_size) {
    ssize_t bytes_written = write(i2c_fd, command, command_size);
    if (bytes_written != command_size) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a response frame from the sensor
int read_response(uint8_t *response, size_t response_size) {
    ssize_t bytes_read = read(i2c_fd, response, response_size);
    if (bytes_read != response_size) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to validate the response frame
int validate_response(const uint8_t *response) {
    if (response[0] != 0x50) {
        fprintf(stderr, "Error: Invalid response header (0x%02X)\n", response[0]);
        return -1;
    }
    return 0;
}

// Function to extract the distance from the response frame
int extract_distance(const uint8_t *response, uint16_t *distance) {
    *distance = (response[11] << 8) | response[12];
    return 0;
}

// Function to calculate the average distance
double calculate_average_distance(uint16_t *distances, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Function to log an intrusion event
int log_intrusion(double average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C interface
    if (init_i2c() < 0) {
        return 1;
    }

    printf("I2C interface initialized successfully.\n");

    // Main loop
    while (1) {
        uint16_t distances[NUM_SAMPLES];
        double average_distance;

        // Take multiple samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            uint8_t response[RESPONSE_FRAME_SIZE];

            // Send the command frame
            if (send_command(command_frame, sizeof(command_frame)) < 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                continue; // Retry the sample
            }

            // Wait for at least 10 ms
            usleep(10000); // 10 ms

            // Read the response frame
            if (read_response(response, sizeof(response)) < 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                continue; // Retry the sample
            }

            // Validate the response frame
            if (validate_response(response) < 0) {
                fprintf(stderr, "Invalid response, retrying...\n");
                continue; // Retry the sample
            }

            // Extract the distance
            if (extract_distance(response, &distances[i]) < 0) {
                fprintf(stderr, "Error extracting distance, retrying...\n");
                continue; // Retry the sample
            }
        }

        // Calculate the average distance
        average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            if (log_intrusion(average_distance) < 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        } else {
            printf("No intrusion detected. Average distance: %.2f mm\n", average_distance);
        }

        // Wait for 100 ms before the next cycle
        usleep(100000); // 100 ms
    }

    return 0;
}

