    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C interface
    if (init_i2c() < 0) {
        return 1;
    }

    printf("I2C interface initialized successfully.\n");

    // Main loop
    while (1) {
        uint16_t distances[NUM_SAMPLES];
        double average_distance;

        // Take multiple samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            uint8_t response[RESPONSE_FRAME_SIZE];

            // Send the command frame
            if (send_command(command_frame, sizeof(command_frame)) < 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                continue; // Retry the sample
            }

            // Wait for at least 10 ms
            usleep(10000); // 10 ms

            // Read the response frame
            if (read_response(response, sizeof(response)) < 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                continue; // Retry the sample
            }

            // Validate the response frame
            if (validate_response(response) < 0) {
                fprintf(stderr, "Invalid response, retrying...\n");
                continue; // Retry the sample
            }

            // Extract the distance
            if (extract_distance(response, &distances[i]) < 0) {
                fprintf(stderr, "Error extracting distance, retrying...\n");
                continue; // Retry the sample
            }
        }

        // Calculate the average distance
        average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
            if (log_intrusion(average_distance) < 0) {
                fprintf(stderr, "Error logging intrusion.\n");
            }
        } else {
            printf("No intrusion detected. Average distance: %.2f mm\n", average_distance);
        }

        // Wait for 100 ms before the next cycle
        usleep(100000); // 100 ms
    }

    return 0;
}

