#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteI2CBlockData(handle, reg, (char *)&value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two I2C registers (little-endian)
int read_distance(int handle, uint16_t *distance) {
    uint8_t data[2];
    int result = i2cReadI2CBlockData(handle, VL53L0X_REG_RESULT_RANGE_STATUS, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }
    *distance = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

// Function to clear the interrupt
int clear_interrupt(int handle) {
    if (write_register(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }
    return 0;
}

// Function to perform a single-shot ranging measurement
int get_distance(int handle, uint16_t *distance) {
    // Start ranging
    if (write_register(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Wait for measurement to complete with timeout
    int timeout = 100; // 100 ms
    while (timeout > 0) {
        uint8_t status;
        if (read_register(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read distance
    if (read_distance(handle, distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Clear interrupt
    if (clear_interrupt(handle) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return 0;
}

