// Si1182 I2C address
#define SI1182_ADDR 0x39

// Si1182 register addresses
#define CONFIG_REG 0x18
#define IRQ_STATUS_REG 0x25
#define PROX_DATA_LSB_REG 0x2A
#define PROX_DATA_MSB_REG 0x2B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the Si1182 sensor
int init_si1182()
{
    // Enable proximity mode by writing 0x01 to the CONFIG register
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to read the proximity data from the Si1182 sensor
int read_proximity_data(int *proximity_value)
{
    int lsb, msb;

    // Check if data is ready by reading the IRQ status register
    int irq_status = i2cReadByteData(i2c_handle, IRQ_STATUS_REG);
    if (irq_status < 0) {
        fprintf(stderr, "Error reading IRQ status register\n");
        return -1;
    }

    // Check if bit 0 of the IRQ status register is set
    if ((irq_status & 0x01) == 0) {
        // Data not ready yet
        return -1;
    }

    // Read the proximity data from registers 0x2A and 0x2B
    lsb = i2cReadByteData(i2c_handle, PROX_DATA_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error reading proximity data LSB\n");
        return -1;
    }

    msb = i2cReadByteData(i2c_handle, PROX_DATA_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error reading proximity data MSB\n");
        return -1;
    }

    // Combine the LSB and MSB to form the 16-bit proximity value
    *proximity_value = (msb << 8) | lsb;

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        int proximity_value;

        // Read proximity data
        if (read_proximity_data(&proximity_value) == 0) {
            // Print the proximity value
            printf("Proximity: %d\n", proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

