#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define MM_PER_COUNT 0.125

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 500 ms
    int result;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence (optional, but good practice)
    unsigned char dummy_data[1];
    if (read(i2c_fd, dummy_data, 1) < 0) {
        fprintf(stderr, "Error: No response from MLX75030 at address 0x%02X. Check connection.\n", MLX75030_ADDR);
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 sensor found at address 0x%02X.\n", MLX75030_ADDR);

    while (program_running) {
        unsigned char data[2];
        int16_t raw_distance;
        float distance_mm;

        // Read distance data
        if (read(i2c_fd, data, 2) == 2) {
            // Convert to little-endian and calculate distance
            raw_distance = (data[1] << 8) | data[0];
            distance_mm = raw_distance * MM_PER_COUNT;

            printf("Distance: %.2f mm\n", distance_mm);
        } else {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        }

        // Sleep for 500 ms
        result = nanosleep(&sleep_time, NULL);
        if (result != 0 && errno == EINTR) {
            printf("nanosleep interrupted by signal\n");
        }
    }

    // Close I2C bus
    close(i2c_fd);
    return 0;
}

