        int16_t raw_distance;
        float distance_mm;

        // Read distance data
        if (read(i2c_fd, data, 2) == 2) {
            // Convert to little-endian and calculate distance
            raw_distance = (data[1] << 8) | data[0];
            distance_mm = raw_distance * MM_PER_COUNT;

            printf("Distance: %.2f mm\n", distance_mm);
        } else {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        }

        // Sleep for 500 ms
        result = nanosleep(&sleep_time, NULL);
        if (result != 0 && errno == EINTR) {
            printf("nanosleep interrupted by signal\n");
        }
    }

    // Close I2C bus
    close(i2c_fd);
    return 0;
}

