#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout values in microseconds
#define RISING_EDGE_TIMEOUT 200000 // 200 ms
#define FALLING_EDGE_TIMEOUT 200000 // 200 ms

// Define maximum pulse duration in microseconds
#define MAX_PULSE_DURATION 38000 // 38 ms

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin HIGH
    gpioDelay(10);             // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin LOW
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go HIGH (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < RISING_EDGE_TIMEOUT) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= RISING_EDGE_TIMEOUT) {
        fprintf(stderr, "Error: Rising edge timeout\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick(); // Record the start time

    // Wait for the echo pin to go LOW (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < FALLING_EDGE_TIMEOUT) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= FALLING_EDGE_TIMEOUT) {
        fprintf(stderr, "Error: Falling edge timeout\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick(); // Record the end time

    pulse_duration = end_tick - start_tick; // Calculate the pulse duration

    // Handle potential tick rollover
    if (end_tick < start_tick) {
        pulse_duration = (0xFFFFFFFF - start_tick) + end_tick;
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration <= 0 || pulse_duration > MAX_PULSE_DURATION) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld\n", pulse_duration);
        return -1.0; // Indicate invalid distance
    }

    return (pulse_duration * 0.0343) / 2.0; // Calculate distance in cm
}

// Function to log the distance with a timestamp
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        triggerSensor(); // Trigger the sensor
        long pulse_duration = measurePulseWidth(); // Measure the pulse width

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration); // Calculate the distance

            if (distance >= 0.0) {
                logDistance(distance); // Log the distance
            }
        }

        gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    return 0; // Exit successfully
}

