#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_PIN 17
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define DATA_FRAME_SIZE (MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE)
#define LED_ON_TIME 2 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_uart(const char *device, speed_t baud_rate);
int read_uart_data(int fd, unsigned char *buffer, size_t size);
int parse_range_profile(const unsigned char *data, int *range_profile);
float calculate_distance(int range_bin);
int detect_intrusion(const int *range_profile);
void trigger_alert(int gpio_pin);
void log_intrusion(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// UART initialization function
int initialize_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = DATA_FRAME_SIZE;  // Read at least DATA_FRAME_SIZE bytes
    tty.c_cc[VTIME] = 5;              // Timeout of 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// UART data reading function
int read_uart_data(int fd, unsigned char *buffer, size_t size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != size) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %zu\n", bytes_read, size);
        return -1; // Indicate an error
    }
    return 0;
}

// Range profile parsing function
int parse_range_profile(const unsigned char *data, int *range_profile) {
    // Check for magic word
    unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    if (memcmp(data, magic_word, MAGIC_WORD_SIZE) != 0) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }

    // Extract range profile data
    for (int i = 0; i < 64; i++) {
        range_profile[i] = (int16_t)((data[MAGIC_WORD_SIZE + (i * 2 + 1)] << 8) | data[MAGIC_WORD_SIZE + (i * 2)]);
    }

    return 0;
}

// Distance calculation function
float calculate_distance(int range_bin) {
    return range_bin * RANGE_RESOLUTION;
}

// Intrusion detection function
int detect_intrusion(const int *range_profile) {
    for (int i = 0; i < 64; i++) {
        float distance = calculate_distance(i);
        if (distance <= DISTANCE_THRESHOLD) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Alert triggering function
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(LED_ON_TIME * 1000000); // Wait for 2 seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Intrusion logging function
void log_intrusion(float distance) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", tv.tv_usec);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char uart_buffer[DATA_FRAME_SIZE];
    int range_profile[64];

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read data from UART
        if (read_uart_data(uart_fd, uart_buffer, DATA_FRAME_SIZE) == 0) {
            // Parse range profile
            if (parse_range_profile(uart_buffer, range_profile) == 0) {
                // Detect intrusion
                if (detect_intrusion(range_profile)) {
                    printf("Intrusion detected!\n");
                    trigger_alert(GPIO_PIN);
                    log_intrusion(DISTANCE_THRESHOLD); // Log the threshold distance
                }
            }
        }
    }

    // Cleanup
    close(uart_fd);
    fclose(log_file);
    gpioTerminate();

    printf("Intrusion detection system stopped.\n");

    return EXIT_SUCCESS;
}

