#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_distance(uint16_t *distance);
int log_distance(uint16_t distance);
void trigger_alert(uint16_t distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    // Read high byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read high byte: %d\n", result);
        return 1;
    }
    uint8_t high_byte = buf[0];

    // Read low byte
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_LOW_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read low byte: %d\n", result);
        return 1;
    }
    uint8_t low_byte = buf[0];

    // Combine bytes
    *distance = (high_byte << 8) | low_byte;

    return 0;
}

// Function to log distance to file
int log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Function to trigger alert based on distance
void trigger_alert(uint16_t distance) {
    if (distance < (uint16_t)(DISTANCE_THRESHOLD * 10)) { // Assuming distance is in mm
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(500);          // Wait 500ms
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    uint16_t distance;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance)) {
            fprintf(stderr, "Failed to read distance, retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;        // Skip logging and alerting on this iteration
        }

        // Log distance
        if (log_distance(distance)) {
            fprintf(stderr, "Failed to log distance\n");
        }

        // Trigger alert
        trigger_alert(distance);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

