// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0007
#define VL53L1X_REG_SYSRANGE_START 0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void print_guidance_message(uint16_t distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;
    uint8_t model_id;

    // Check if the sensor is present by reading the model ID register
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID register: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID (0x%02X)\n", model_id);
        return -1;
    }

    // Perform a software reset
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing to reset register: %d\n", status);
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to mode start register: %d\n", status);
        return -1;
    }

    // Wait for the sensor to be ready (polling SYSRANGE__START register)
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START);
        if (status < 0) {
            fprintf(stderr, "Error reading SYSRANGE__START register: %d\n", status);
            return -1;
        }
        if ((status & 0x01) == 0) {
            break; // Sensor is ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Sensor not ready after timeout\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(uint16_t *distance) {
    int status;
    uint8_t data[2];

    // Poll the RESULT__INTERRUPT_STATUS register for data-ready
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status register: %d\n", status);
            return -1;
        }
        if (status & 0x01) {
            break; // Data is ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Data not ready after timeout\n");
        return -1;
    }

    // Read the 16-bit distance from RESULT__RANGE_STATUS + 10 (register 0x078, big-endian)
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10, (char *)data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }

    *distance = (uint16_t)((data[0] << 8) | data[1]);

    // Clear the interrupt by writing 0x01 to the SYSTEM__INTERRUPT_CLEAR register
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error writing to interrupt clear register: %d\n", status);
        return -1;
    }

    return 0;
}

// Log distance to file function
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Print guidance message function
void print_guidance_message(uint16_t distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

