#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4A
#define TRIGGER_COMMAND 0x00 // Example trigger command
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int trigger_command;
    int retry_count;
    int retry_delay_ms;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int i2c_bus, int i2c_address);
int trigger_measurement(int i2c_handle, int trigger_command);
int read_distance(int i2c_handle);
void log_distance(FILE *log_file, int distance_cm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int i2c_bus, int i2c_address) {
    int handle = i2cOpen(i2c_bus, i2c_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Trigger a measurement on the MLX75030
int trigger_measurement(int i2c_handle, int trigger_command) {
    int result = i2cWriteByteData(i2c_handle, trigger_command, 0); // Assuming no data to write
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance data from the MLX75030
int read_distance(int i2c_handle) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }
    // Combine the two bytes into a single integer (assuming little-endian)
    int distance_cm = (buffer[1] << 8) | buffer[0];
    return distance_cm;
}

// Log distance data to a CSV file
void log_distance(FILE *log_file, int distance_cm) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%d\n", now, distance_cm);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sensor configuration
    sensor_config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75030_ADDR,
        .trigger_command = TRIGGER_COMMAND,
        .retry_count = RETRY_COUNT,
        .retry_delay_ms = RETRY_DELAY_MS,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement with retry logic
        int trigger_result = -1;
        for (int i = 0; i < config.retry_count; ++i) {
            trigger_result = trigger_measurement(i2c_handle, config.trigger_command);
            if (trigger_result == 0) {
                break; // Success, exit retry loop
            }
            gpioDelay(config.retry_delay_ms * 1000); // Delay in microseconds
        }
        if (trigger_result != 0) {
            fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
            continue; // Skip to the next iteration
