#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define the log file name
#define LOG_FILE "proximity_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int sensor_id;
    int last_state;
    int debounced_state;
    unsigned long last_change_time;
} sensor_t;

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce_sensor(int gpio, int current_state, unsigned long last_change_time);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce a sensor reading
int debounce_sensor(int gpio, int current_state, unsigned long last_change_time) {
    unsigned long now = gpioTick();
    if (now - last_change_time > DEBOUNCE_TIME * 1000) {
        return current_state;
    } else {
        return -1; // Indicate that the reading is still debouncing
    }
}

// Function to log an event to the log file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

