    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Initialize sensor data
    sensor_t sensor1 = {SENSOR_1_GPIO, 1, -1, -1, 0};
    sensor_t sensor2 = {SENSOR_2_GPIO, 2, -1, -1, 0};

    // Main loop
    while (program_running) {
        // Read sensor 1
        int sensor1_state = read_sensor(sensor1.gpio);
        if (sensor1_state != -1) {
            int debounced_state = debounce_sensor(sensor1.gpio, sensor1_state, sensor1.last_change_time);
            if (debounced_state != -1 && debounced_state != sensor1.debounced_state) {
                if (debounced_state == 0 && sensor1.debounced_state == 1) {
                    log_event(sensor1.sensor_id, "DETECTED");
                } else if (debounced_state == 1 && sensor1.debounced_state == 0) {
                    log_event(sensor1.sensor_id, "CLEARED");
                }
                sensor1.debounced_state = debounced_state;
                sensor1.last_change_time = gpioTick();
            }
            sensor1.last_state = sensor1_state;
        }

        // Read sensor 2
        int sensor2_state = read_sensor(sensor2.gpio);
        if (sensor2_state != -1) {
            int debounced_state = debounce_sensor(sensor2.gpio, sensor2_state, sensor2.last_change_time);
            if (debounced_state != -1 && debounced_state != sensor2.debounced_state) {
                if (debounced_state == 0 && sensor2.debounced_state == 1) {
                    log_event(sensor2.sensor_id, "DETECTED");
                } else if (debounced_state == 1 && sensor2.debounced_state == 0) {
                    log_event(sensor2.sensor_id, "CLEARED");
                }
                sensor2.debounced_state = debounced_state;
                sensor2.last_change_time = gpioTick();
            }
            sensor2.last_state = sensor2_state;
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

