#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define CSV_FILE "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t data);
int trigger_measurement(int fd);
int read_distance(int fd, uint16_t *distance);
int log_data(FILE *fp, uint16_t distance);
void signal_handler(int sig);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
  if (write(fd, &reg_addr, 1) != 1) {
    fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
    return -1;
  }
  if (read(fd, data, len) != len) {
    fprintf(stderr, "Error reading data: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t data) {
  uint8_t buf[2];
  buf[0] = reg_addr;
  buf[1] = data;
  if (write(fd, buf, 2) != 2) {
    fprintf(stderr, "Error writing data: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Trigger measurement function
int trigger_measurement(int fd) {
  return i2c_write_register(fd, MEAS_TRIGGER_REG, 0x01);
}

// Read distance function
int read_distance(int fd, uint16_t *distance) {
  uint8_t high_byte, low_byte;

  if (i2c_read_register(fd, DIST_HIGH_REG, &high_byte, 1) != 0) {
    fprintf(stderr, "Error reading high byte\n");
    return -1;
  }
  if (i2c_read_register(fd, DIST_LOW_REG, &low_byte, 1) != 0) {
    fprintf(stderr, "Error reading low byte\n");
    return -1;
  }

  *distance = (high_byte << 8) | low_byte;
  return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t distance) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[30];

  time(&rawtime);
  timeinfo = gmtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

  if (fprintf(fp, "%s,%u\n", timestamp, distance) < 0) {
    fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
    return -1;
  }
  fflush(fp); // Ensure data is written to disk
  return 0;
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

int main() {
  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
    close(i2c_fd);
    return 1;
  }

  // Open CSV file
  csv_file = fopen(CSV_FILE, "a");
  if (csv_file == NULL) {
    fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
    close(i2c_fd);
    return 1;
  }

  // Main loop
  while (!terminate) {
    uint16_t distance;
    int timeout_count = 0;

    // Trigger measurement
    if (trigger_measurement(i2c_fd) != 0) {
      fprintf(stderr, "Error triggering measurement\n");
      continue; // Skip to the next iteration
    }

    // Poll for data ready
    uint8_t status;
    do {
      if (i2c_read_register(i2c_fd, MEAS_STATUS_REG, &status, 1) != 0) {
        fprintf(stderr, "Error reading status register\n");
        continue; // Skip to the next iteration
      }
      if (status & 0x01) {
        break; // Data ready
      }
      usleep(1000); // Wait 1 ms
      timeout_count++;
      if (timeout_count > 50) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        continue; // Skip to the next iteration
      }
    } while (!(status & 0x01));

    // Read distance
    if (read_distance(i2c_fd, &distance) != 0) {
      fprintf(stderr, "Error reading distance\n");
      continue; // Skip to the next iteration
    }

    // Log data
    if (log_data(csv_file, distance) != 0) {
      fprintf(stderr, "Error logging data\n");
    }

    usleep(500000); // Wait 500 ms
  }

  // Cleanup
  close(i2c_fd);
  fclose(csv_file);

  return 0;
}

