// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement
#define DISTANCE_REG 0x00

// Define the number of retries for I2C transactions
#define MAX_RETRIES 3

// Global variable for the I2C handle
int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the distance from the MLX75030 sensor
int read_distance(int i2c_handle) {
    char buf[2];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int distance = (buf[0] << 8) | buf[1];
            return distance;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10); // Wait 10 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate an error
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read the distance from the sensor
        int distance = read_distance(i2c_handle);

        // Get the current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Log the distance and timestamp to the console
        if (distance != -1) {
            printf("Timestamp: %ld ms, Distance: %d mm\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
