#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// Register addresses
#define VL53L4CX_REG_SOFT_RESET 0x7FFF
#define VL53L4CX_REG_START_RANGING 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init();
int vl53l4cx_read_distance(uint16_t *distance);
void signal_handler(int signal);
void get_timestamp(char *timestamp);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to get timestamp with microsecond precision
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", &tm_info);
    sprintf(timestamp + 19, ".%06ld", ts.tv_nsec / 1000);
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write start ranging command.\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int vl53l4cx_read_distance(uint16_t *distance) {
    uint8_t interrupt_status;
    uint8_t distance_high, distance_low;

    // Read interrupt status
    interrupt_status = i2cReadByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS);
    if (interrupt_status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    // Check if new data is ready
    if (interrupt_status & 0x01) {
        // Read distance high byte
        distance_high = i2cReadByteData(i2c_handle, VL53L4CX_REG_DISTANCE_HIGH);
        if (distance_high < 0) {
            fprintf(stderr, "Error: Failed to read distance high byte.\n");
            return -1;
        }

        // Read distance low byte
        distance_low = i2cReadByteData(i2c_handle, VL53L4CX_REG_DISTANCE_LOW);
        if (distance_low < 0) {
            fprintf(stderr, "Error: Failed to read distance low byte.\n");
            return -1;
        }

        // Combine high and low bytes to form the distance
        *distance = (distance_high << 8) | distance_low;
        return 0; // Success
    } else {
        return -1; // No new data
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init() < 0) {
        fprintf(stderr, "Error: VL53L4CX initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    char timestamp[26];

    // Main loop
    while (!terminate) {
        if (vl53l4cx_read_distance(&distance) == 0) {
            get_timestamp(timestamp);
            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
        }
        gpioDelay(500000); // Wait 500 ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

