#include <time.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// GPIO pin for the buzzer
#define BUZZER_PIN 22

// Distance threshold in mm
#define DISTANCE_THRESHOLD 100

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Error logging function
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening error log file");
    }
}

// VL53L1X initialization function
int init_vl53l1x() {
    int status = 0;

    // Soft reset
    char data[2];
    data[0] = (SOFT_RESET >> 8) & 0xFF;
    data[1] = SOFT_RESET & 0xFF;
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_error("Failed to write SOFT_RESET register");
        status = -1;
        return status;
    }
    gpioDelay(1000); // Wait for reset

    // Set I2C address
    data[0] = (I2C_SLAVE__DEVICE_ADDRESS >> 8) & 0xFF;
    data[1] = I2C_SLAVE__DEVICE_ADDRESS & 0xFF;
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_error("Failed to write I2C_SLAVE__DEVICE_ADDRESS register");
        status = -1;
        return status;
    }

    // Start continuous ranging
    data[0] = (SYSTEM__MODE_START >> 8) & 0xFF;
    data[1] = SYSTEM__MODE_START & 0xFF;
    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_error("Failed to write SYSTEM__MODE_START register");
        status = -1;
        return status;
    }

    return status;
}

// Function to read distance from VL53L1X
int read_distance() {
    char data[2];
    char result[2];
    int distance = -1;

    // Read distance
    data[0] = (RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM >> 8) & 0xFF;
    data[1] = RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM & 0xFF;

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        log_error("Failed to write RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM register");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, result, 2) != 2) {
        log_error("Failed to read distance data");
        return -1;
    }

    distance = (result[0] << 8) | result[1];

    return distance;
}

// Function to control the buzzer
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Activate buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_error("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            log_error("Failed to read distance, re-initializing...");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to open I2C bus\n");
                log_error("Failed to open I2C bus");
                terminate = 1; // Exit loop if I2C fails repeatedly
            } else {
                if (init_vl53l1x() != 0) {
                    fprintf(stderr, "VL53L1X re-initialization failed\n");
                    log_error("VL53L1X re-initialization failed");
                    terminate = 1; // Exit loop if re-initialization fails repeatedly
                }
            }
        }

        gpioDelay(500000); // Wait 500 ms
    }

    // Clean up resources
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

