#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout
#define VALID_DISTANCE_MIN 2.0  // cm
#define VALID_DISTANCE_MAX 400.0 // cm
#define BUZZER_THRESHOLD 30.0   // cm

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void display_distance(double distance);
void control_buzzer(double distance);
void signal_handler(int signal);

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Echo started
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 2; // Echo ended
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s
}

// Function to display the distance on the console
void display_distance(double distance) {
    printf("Distance: %.2f cm\n", distance);
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse();
        echo_received = 0; // Reset echo flag
        uint32_t start_time = gpioTick();

        // Wait for echo or timeout
        while (echo_received < 2) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                printf("Sensor absent or timeout\n");
                break;
            }
            gpioDelay(100); // Small delay to avoid busy-waiting
        }

        // Calculate pulse width and distance
        if (echo_received == 2) {
            uint32_t pulse_width = end_tick - start_tick;
            if (end_tick < start_tick) {
                pulse_width = (0xFFFFFFFF - start_tick) + end_tick; // Handle tick wraparound
            }

            double distance = calculate_distance(pulse_width);

            // Validate distance
            if (distance >= VALID_DISTANCE_MIN && distance <= VALID_DISTANCE_MAX) {
                display_distance(distance);
                control_buzzer(distance);
            } else {
                printf("Invalid reading: %.2f cm\n", distance);
            }
        }

        gpioDelay(100); // Delay between readings
    }

    // Clean up (should not reach here if signal handler works)
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

