#define MAX_PULSE_WIDTH 30000 // microseconds
#define TRIGGER_PULSE_WIDTH 10 // microseconds
#define MEASUREMENT_INTERVAL 200 // milliseconds
#define TIMEOUT_DURATION 60 // milliseconds

// Global variables
