#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define OPEN_DISTANCE 50  // cm
#define CLOSE_DISTANCE 60 // cm
#define SERVO_OPEN_PULSEWIDTH 2000 // us
#define SERVO_CLOSED_PULSEWIDTH 1000 // us
#define SERVO_FREQUENCY 50 // Hz
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int open);
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, char *data) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int reg, short *data) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for word read 0x%02X\n", reg);
        return -1;
    }
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading word from VL53L1X register 0x%02X\n", reg);
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure servo motor
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, 10000); // Adjust range as needed

    // Main loop
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open
    while (!terminate) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            log_event("ERROR", -1); // Log the error
            sleep(1); // Avoid spamming the log
            continue;
        }

        if (distance < OPEN_DISTANCE && !gate_open) {
            control_servo(1); // Open the gate
            gate_open = 1;
            log_event("OPEN", distance);
        } else if (distance > CLOSE_DISTANCE && gate_open) {
            control_servo(0); // Close the gate
            gate_open = 0;
            log_event("CLOSE", distance);
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    control_servo(0); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

