int read_distance() {
    // Start a measurement
    if (vl53l1x_write_byte(VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(100); // 100ms

    // Read the distance
    short distance_mm;
    if (vl53l1x_read_word(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    // Read range status
    char range_status;
    if (vl53l1x_read_byte(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Check for valid range status (example: status 0 is valid)
    if ((range_status & 0x1F) != 0) {
        fprintf(stderr, "Invalid range status: 0x%02X\n", range_status);
        return -1;
    }

    return distance_mm / 10; // Convert mm to cm
}

void control_servo(int open) {
    if (open) {
        gpioPWM(SERVO_PIN, SERVO_OPEN_PULSEWIDTH); // Open the gate
    } else {
        gpioPWM(SERVO_PIN, SERVO_CLOSED_PULSEWIDTH); // Close the gate
    }
}

void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - %s - Distance: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

