#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_motor(uint16_t distance);
void trigger_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int i2c_write_byte(int handle, uint16_t reg, uint8_t data);
int i2c_read_byte(int handle, uint16_t reg, uint8_t *data);
int i2c_read_word(int handle, uint16_t reg, uint16_t *data);

// I2C write byte function with retry and exponential backoff
int i2c_write_byte(int handle, uint16_t reg, uint8_t data) {
    int retries = 0;
    int status;
    uint8_t buf[3];

    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    while (retries < 3) {
        status = i2cWriteDevice(handle, (char *)buf, 3);
        if (status == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%04X, data 0x%02X): %s\n", reg, data, strerror(errno));
            gpioDelay(1 << retries); // Exponential backoff
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%04X, data 0x%02X)\n", reg, data);
    return -1; // Failure
}

// I2C read byte function with retry and exponential backoff
int i2c_read_byte(int handle, uint16_t reg, uint8_t *data) {
    int retries = 0;
    int status;
    uint8_t buf[2];

    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    while (retries < 3) {
        status = i2cWriteDevice(handle, (char *)buf, 2);
        if (status == 0) {
            status = i2cReadDevice(handle, (char *)data, 1);
            if (status == 0) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (reg 0x%04X): %s\n", reg, strerror(errno));
                gpioDelay(1 << retries); // Exponential backoff
                retries++;
            }
        } else {
            fprintf(stderr, "I2C write (address) failed (reg 0x%04X): %s\n", reg, strerror(errno));
