    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO_1, 0);
    gpioWrite(LED_GPIO_2, 0);
    gpioWrite(LED_GPIO_3, 0);
    gpioWrite(LED_GPIO_4, 0);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    int result;
    uint8_t reset_value = 0x63;
    uint8_t check_value = 0x00; // Example check value, adjust as needed

    // Soft reset
    result = i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, reset_value);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Verify sensor presence (example register)
    result = i2cReadByteData(i2c_handle, MPR121_ELECTRODE_CONFIG0);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 verification failed: %s\n", strerror(errno));
        return -1;
    }
    if (result != check_value) {
        fprintf(stderr, "Error: MPR121 verification failed. Expected 0x%02X, got 0x%02X\n", check_value, result);
        return -1;
    }

    // Stop mode
    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG0, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 stop mode failed: %s\n", strerror(errno));
        return -1;
    }

    // Baseline filtering
    result = i2cWriteByteData(i2c_handle, 0x2B, 0x01); // MHDR
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 MHDR failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x2C, 0x01); // NHDR
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 NHDR failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x2D, 0x0E); // NCLR
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 NCLR failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x2E, 0x00); // FDLR
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 FDLR failed: %s\n", strerror(errno));
        return -1;
    }

    // Auto-configuration thresholds
    result = i2cWriteByteData(i2c_handle, 0x5A, 0x0B);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 1 failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x5B, 0x0B);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 2 failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x5C, 0x0B);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 3 failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x5D, 0xC8);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 4 failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x5E, 0x82);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 5 failed: %s\n", strerror(errno));
        return -1;
    }
    result = i2cWriteByteData(i2c_handle, 0x5F, 0xB4);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 auto-config threshold 6 failed: %s\n", strerror(errno));
        return -1;
    }

    // Enable all 12 electrodes in run mode
    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG0, 0x0C);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 run mode failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

