    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG0, 0x0C);
    if (result < 0) {
        fprintf(stderr, "Error: MPR121 run mode failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

