#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // Speed of sound in m/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_WIDTH 58 // Minimum valid pulse width in microseconds
#define MAX_PULSE_WIDTH 25000 // Maximum valid pulse width in microseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1); // Set TRIG pin HIGH
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for 10 microseconds
    gpioWrite(TRIG_PIN, 0); // Set TRIG pin LOW
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 0; // Reset echo received flag
    } else if (level == 0) {
        // Falling edge
        end_tick = tick;
        echo_received = 1; // Set echo received flag
    }
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // pulse_width in us, result in meters
}

// Function to log distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt handler
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set interrupt handler for echo pin
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse(); // Send trigger pulse
        gpioDelay(1000); // Wait for 1 second

        if (echo_received) {
            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > 0 && pulse_width <= MAX_PULSE_WIDTH) {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
                printf("Distance: %.2f meters\n", distance);
            } else {
                fprintf(stderr, "Invalid pulse width: %u microseconds\n", pulse_width);
            }
        } else {
            fprintf(stderr, "No echo received.\n");
        }
    }

    return 0;
}

