#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
int read_status(uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to initialize the VL53L1X sensor
int init_sensor() {
    // Enable the sensor by setting XSHUT_GPIO high
    gpioWrite(XSHUT_GPIO, 1);
    gpioDelay(100); // Wait for the sensor to power up

    // Write configuration registers
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to CONTINUOUS_MODE_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to TIMEOUT_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to START_RANGING_REG");
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }
    *distance = (uint16_t)((buffer[1] << 8) | buffer[0]); // Little-endian
    return 0;
}

// Function to read the status from the sensor
int read_status(uint8_t *status) {
    if (i2cReadByteData(i2c_handle, STATUS_REG) < 0) {
        syslog(LOG_ERR, "Failed to read status");
        return -1;
    }
    *status = i2cReadByteData(i2c_handle, STATUS_REG);
    return 0;
}

// Function to log the data to syslog
void log_data(uint16_t distance, uint8_t status) {
    char* timestamp = get_iso8601_timestamp();
    syslog(LOG_INFO, "Timestamp: %s, Distance: %d mm, Status: 0x%02X", timestamp, distance, status);
    free(timestamp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set XSHUT_GPIO as output
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    uint8_t status;
    while (!terminate) {
        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }
        gpioDelay(100); // Wait 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    syslog(LOG_INFO, "Program terminated cleanly");
    return 0;
}

