#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_RANGING 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
void control_gate(int distance);
void log_data(int distance, int gate_state, const char *error_message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the VL53L1X sensor
int init_sensor() {
    int status;
    uint8_t model_id;

    // Read Model ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", status);
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set Ranging Mode to Short
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error setting ranging mode: %d\n", status);
        return -1;
    }

    // Start Ranging
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_START_RANGING, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %d\n", status);
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    int status;
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;

    // Read Range Status
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", status);
        return -1;
    }
    range_status = (uint8_t)status;

    // Read Distance (MSB and LSB)
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (status < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", status);
        return -1;
    }
    distance_msb = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading distance LSB: %d\n", status);
        return -1;
    }
    distance_lsb = (uint8_t)status;

    *distance = (distance_msb << 8) | distance_lsb;

    return 0;
}

// Control the gate actuator
void control_gate(int distance) {
    int gate_state = (distance < DISTANCE_THRESHOLD) ? 1 : 0; // 1 for open, 0 for closed
    gpioWrite(GATE_GPIO, gate_state);
    log_data(distance, gate_state, NULL);
}

// Log data to file
void log_data(int distance, int gate_state, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm, Gate State: %s, Error: %s\n",
            timestamp, distance, gate_state ? "Open" : "Closed", error_message ? error_message : "None");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    int distance;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    init_result = init_sensor();
    if (init_result != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        log_data(0, 0, "Sensor initialization failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for gate control
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to closed state

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_gate(distance);
        } else {
            log_data(0, 0, "Error reading distance");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    gpioWrite(GATE_GPIO, 0); // Ensure gate is closed on exit
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

