#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_RANGE 180.0
#define NUM_SAMPLES 5

// Global variables
volatile sig_atomic_t terminate_flag = 0;
FILE *log_file = NULL;
double distance_buffer[NUM_SAMPLES];
int buffer_index = 0;

// Structure to hold echo pulse data
typedef struct {
    uint32_t start_tick;
    uint32_t end_tick;
    int valid;
} echo_data_t;

echo_data_t echo_data = {0, 0, 0};

// Function prototypes
void trigger_pulse();
double measure_distance();
double calculate_distance(uint32_t pulse_width);
double map_distance_to_angle(double distance);
void set_servo_angle(double angle);
void log_data(double distance, double angle);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void initialize_distance_buffer();

// Function to initialize the distance buffer with -1.0
void initialize_distance_buffer() {
    for (int i = 0; i < NUM_SAMPLES; i++) {
        distance_buffer[i] = -1.0;
    }
}

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
double measure_distance() {
    echo_data.start_tick = 0;
    echo_data.end_tick = 0;
    echo_data.valid = 0;

    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL); // Register callback function

    trigger_pulse();

    // Wait for echo or timeout
    uint32_t start_time = gpioTick();
    while (!echo_data.valid && (gpioTick() - start_time) < TIMEOUT_US && !terminate_flag) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Unregister callback function

    if (!echo_data.valid) {
        fprintf(stderr, "Error: No echo received or timeout occurred.\n");
        return -1.0; // Indicate error
    }

    uint32_t pulse_width = echo_data.end_tick - echo_data.start_tick;
    if (pulse_width > 0xFFFFFFFF / 2) {
        pulse_width = (0xFFFFFFFF - echo_data.start_tick) + echo_data.end_tick;
    }

    return calculate_distance(pulse_width);
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    double distance = (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // cm
    return distance;
}

// Function to map distance to servo angle using a logarithmic function
double map_distance_to_angle(double distance) {
    if (distance < 0) return 90.0; // Default to 90 degrees for invalid distances

    double angle = 0.0;
    if (distance >= 2.0 && distance <= 400.0) {
        angle = (log10(distance / 2.0) / log10(400.0 / 2.0)) * SERVO_RANGE;
    } else {
