    uint32_t start_time = gpioTick();
    while (!echo_data.valid && (gpioTick() - start_time) < TIMEOUT_US && !terminate_flag) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Unregister callback function

