#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz
#define TIMEOUT_US 200000       // Timeout in microseconds (200 ms)

// Global variables
volatile sig_atomic_t terminate = 0;
double last_valid_distance = 100.0; // Initialize to a reasonable default
double last_valid_frequency = 1000.0; // Initialize to a reasonable default

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double calculate_frequency(double distance);
void set_pwm_frequency(double frequency);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high, with timeout
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT_US) {
        timeout_counter++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low, with timeout
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        timeout_counter++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

// Function to calculate frequency from distance
double calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %f\n", distance);
        return -1.0; // Indicate error
    }

    double frequency = MIN_FREQUENCY * exp(distance / 50.0);
    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency < 0) {
        fprintf(stderr, "Invalid frequency: %f\n", frequency);
        return;
    }

    int period = (int)(1000000.0 / frequency); // Period in microseconds
    if (period <= 0) {
        fprintf(stderr, "Invalid period calculated, setting to max frequency\n");
        period = 1; // Set to max frequency
    }

    gpioSetPWMfrequency(PWM_PIN, (int)frequency); // Set PWM frequency
    gpioPWM(PWM_PIN, 128); // Set duty cycle to 50% (128/255)
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Set PWM duty cycle to 50% initially
    gpioPWM(PWM_PIN, 128);

    // Set PWM frequency to a default value
    gpioSetPWMfrequency(PWM_PIN, 1000); // Initial frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        double distance = measure_distance();

        if (distance > 0) {
            last_valid_distance = distance;
            double frequency = calculate_frequency(distance);

            if (frequency > 0) {
                last_valid_frequency = frequency;
                set_pwm_frequency(frequency);
            } else {
                set_pwm_frequency(last_valid_frequency); // Use last valid frequency
            }
        } else {
            set_pwm_frequency(last_valid_frequency); // Use last valid frequency
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Clean up and terminate
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();     // Terminate pigpio

    fprintf(stderr, "Theremin terminated.\n");
    return 0;
}

