// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define frequency range
#define MIN_FREQ 200
#define MAX_FREQ 2000

// Define distance range
#define MIN_DIST 5
#define MAX_DIST 50

// Define timeout value
#define TIMEOUT 100000 // 100 ms in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;
float last_valid_distance = 50.0; // Initialize to max distance

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_duration);
int mapDistanceToFrequency(float distance);
void setBuzzerFrequency(int frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        program_running = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long pulseIn(int pin, int level, int timeout) {
    long start_time = 0, end_time = 0;
    long pulse_duration = 0;

    // Wait for the pulse to start
    int count = 0;
    while (gpioRead(pin) != level) {
        if (count > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
        count++;
    }

    start_time = gpioTick();

    // Wait for the pulse to end
    count = 0;
    while (gpioRead(pin) == level) {
        if (count > timeout) {
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
        count++;
    }

    end_time = gpioTick();

    pulse_duration = end_time - start_time;
    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) return -1.0; // Indicate error
    return pulse_duration / 58.0; // Speed of sound approximation
}

// Function to map distance to frequency
int mapDistanceToFrequency(float distance) {
    int frequency = MIN_FREQ + (int)((MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST));

    // Clamp the frequency to the defined range
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    } else if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }

    return frequency;
}

// Function to set the buzzer frequency using hardware PWM
void setBuzzerFrequency(int frequency) {
    gpioHardwarePWM(BUZZER_PIN, frequency, 500000); // 50% duty cycle
}

