    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse duration
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT);

        // Calculate the distance
        float distance = calculateDistance(pulse_duration);

        // Map the distance to a frequency
        int frequency = 0;
        if (distance > 0) {
            frequency = mapDistanceToFrequency(distance);
            last_valid_distance = distance; // Update last valid distance
        } else {
            distance = last_valid_distance; // Use last valid distance
            frequency = mapDistanceToFrequency(distance);
            fprintf(stderr, "Sensor timeout or error. Using last valid distance.\n");
        }

        // Set the buzzer frequency
        setBuzzerFrequency(frequency);

        // Print the distance and frequency
        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);

        // Delay for 10 ms
        gpioDelay(10000);
    }

    // Clean up and exit
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    return 0;
}

