#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to measure distance in centimeters
float measure_distance() {
    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure echo pulse width with timeout
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > 50000) { // 50 ms timeout
            fprintf(stderr, "Timeout waiting for echo start\n");
            return -1.0; // Indicate timeout
        }
    }
    uint32_t echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > 50000) { // 50 ms timeout
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1.0; // Indicate timeout
        }
    }
    uint32_t echo_end = gpioTick();

    // Calculate pulse width in microseconds
    uint32_t pulse_width = echo_end - echo_start;

    // Calculate distance in centimeters
    float distance = (float)pulse_width / 2.0 / 29.1;

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Invalid reading\n");
        } else if (distance < 2 || distance > 400) {
            fprintf(stderr, "Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10) {
                printf("Too close!\n");
            }
        }

        gpioDelay(500); // 500 ms delay
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

