#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0 // SPI mode 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"

// ICU-20201 Register Addresses
#define REG_CONTINUOUS_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int spi_read_register(int handle, uint8_t reg, uint8_t *value);
int initialize_sensor(int handle);
int read_distance(int handle, uint16_t *distance);
void log_distance(FILE *fp, uint16_t distance);
void signal_handler(int signal);

// SPI write register function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for write operation
    tx_buf[1] = value;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// SPI read register function
int spi_read_register(int handle, uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Sensor initialization function
int initialize_sensor(int handle) {
    if (spi_write_register(handle, REG_CONTINUOUS_MODE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set continuous measurement mode\n");
        return -1;
    }

    if (spi_write_register(handle, REG_RANGE, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set range to 5m\n");
        return -1;
    }

    if (spi_write_register(handle, REG_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }

    return 0;
}

// Read distance function
int read_distance(int handle, uint16_t *distance) {
    uint8_t low_byte, high_byte;

    if (spi_read_register(handle, REG_DISTANCE_LOW, &low_byte) != 0) {
        fprintf(stderr, "Error: Failed to read distance low byte\n");
        return -1;
    }

    if (spi_read_register(handle, REG_DISTANCE_HIGH, &high_byte) != 0) {
        fprintf(stderr, "Error: Failed to read distance high byte\n");
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;
    return 0;
}

// Log distance function
void log_distance(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(spi_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (!terminate) {
        if (read_distance(spi_handle, &distance) == 0) {
            log_distance(log_file, distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

