        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

