// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_fp = NULL;

// Function prototypes
int i2c_open(const char *bus);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
