    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "timestamp,als_visible\n");
    }
    rewind(log_fp);

    // Main loop
    while (program_running) {
        // Read ALS visible light
        uint16_t als_visible = read_als_visible(i2c_fd);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp. Skipping log.\n");
            sleep(5);
            continue;
        }

        // Log data
        if (log_data(timestamp, als_visible) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

