#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_PART_ID_REG 0x00
#define SI1120_RESET_REG 0x30
#define SI1120_ALS_DATA_LOW 0x22
#define SI1120_ALS_DATA_HIGH 0x23
#define SI1120_PS1_DATA_LOW 0x18
#define SI1120_PS1_DATA_HIGH 0x19
#define SI1120_PART_ID 0x41
#define SI1120_RESET_VALUE 0x01
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_als(uint16_t *als_data);
int si1120_read_ps1(uint16_t *ps1_data);
int log_data(uint16_t als_data, uint16_t ps1_data);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1120 sensor
int si1120_init() {
    int retries = 0;
    int status;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, SI1120_RESET_REG, SI1120_RESET_VALUE);
        if (status == 0) break;
        fprintf(stderr, "Error resetting Si1120 (attempt %d): %d\n", retries + 1, status);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to reset Si1120 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(10000); // Wait 10ms after reset

    // Verify the part ID
    retries = 0;
    uint8_t part_id;
    while (retries < MAX_RETRIES) {
        part_id = i2cReadByteData(i2c_handle, SI1120_PART_ID_REG);
        if (part_id >= 0) break; // i2cReadByteData returns negative on error
        fprintf(stderr, "Error reading part ID (attempt %d): %d\n", retries + 1, part_id);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read part ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 initialized successfully.\n");
    return 0;
}

// Read ALS data from the Si1120
int si1120_read_als(uint16_t *als_data) {
    int retries = 0;
    int status;
    uint8_t als_low, als_high;

    while (retries < MAX_RETRIES) {
        als_low = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_LOW);
        if (als_low >= 0) break; // i2cReadByteData returns negative on error
        fprintf(stderr, "Error reading ALS low byte (attempt %d): %d\n", retries + 1, als_low);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        als_high = i2cReadByteData(i2c_handle, SI1120_ALS_DATA_HIGH);
        if (als_high >= 0) break; // i2cReadByteData returns negative on error
        fprintf(stderr, "Error reading ALS high byte (attempt %d): %d\n", retries + 1, als_high);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ALS high byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    *als_data = (uint16_t)((als_high << 8) | als_low);
    return 0;
}

// Read proximity data from the Si1120
int si1120_read_ps1(uint16_t *ps1_data) {
    int retries = 0;
    int status;
    uint8_t ps1_low, ps1_high;

    while (retries < MAX_RETRIES) {
        ps1_low = i2cReadByteData(i2c_handle, SI1120_PS1_DATA_LOW);
        if (ps1_low >= 0) break; // i2cReadByteData returns negative on error
        fprintf(stderr, "Error reading PS1 low byte (attempt %d): %d\n", retries + 1, ps1_low);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS1 low byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        ps1_high = i2cReadByteData(i2c_handle, SI1120_PS1_DATA_HIGH);
        if (ps1_high >= 0) break; // i2cReadByteData returns negative on error
        fprintf(stderr, "Error reading PS1 high byte (attempt %d): %d\n", retries + 1, ps1_high);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read PS1 high byte after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    *ps1_data = (uint16_t)((ps1_high << 8) | ps1_low);
    return 0;
}

// Log data to file
int log_data(uint16_t als_data, uint16_t ps1_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, PS1: %u\n", timestamp, als_data, ps1_data);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    uint16_t als_data, ps1_data;

    // Main loop
    while (!terminate) {
        // Read ALS and proximity data
        if (si1120_read_als(&als_data) == 0 && si1120_read_ps1(&ps1_data) == 0) {
            // Log the data
            log_data(als_data, ps1_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

