#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_DATA_REG 0x22
#define PROX_DATA_REG 0x24
#define LUX_SCALE 0.1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_sensor(int fd);
int read_sensor_data(int fd, float *lux, uint16_t *proximity);
void log_data(FILE *fp, float lux, uint16_t proximity);
void print_data(float lux, uint16_t proximity);
void signal_handler(int sig);
char* get_timestamp(char* timestamp_str);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, data, len) != len) {
    perror("Failed to read data");
    return -1;
  }
  return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = data;
  if (write(fd, buf, 2) != 2) {
    perror("Failed to write data");
    return -1;
  }
  return 0;
}

// Sensor initialization function
int init_sensor(int fd) {
  uint8_t part_id;

  // Verify Part ID
  if (i2c_read_reg(fd, PART_ID_REG, &part_id, 1) != 0) {
    fprintf(stderr, "Error reading Part ID\n");
    return -1;
  }

  if (part_id != 0x82) {
    fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
    return -1;
  }

  // Configure Measurement Rate
  if (i2c_write_reg(fd, MEAS_RATE_REG, 0x07) != 0) {
    fprintf(stderr, "Error writing Measurement Rate\n");
    return -1;
  }

  return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, float *lux, uint16_t *proximity) {
  uint8_t als_data[2];
  uint8_t prox_data[2];

  // Read Ambient Light Data
  if (i2c_read_reg(fd, ALS_DATA_REG, als_data, 2) != 0) {
    fprintf(stderr, "Error reading Ambient Light Data\n");
    return -1;
  }
  uint16_t raw_als = (als_data[1] << 8) | als_data[0];
  *lux = (float)raw_als * LUX_SCALE;

  // Read Proximity Data
  if (i2c_read_reg(fd, PROX_DATA_REG, prox_data, 2) != 0) {
    fprintf(stderr, "Error reading Proximity Data\n");
    return -1;
  }
  *proximity = (prox_data[1] << 8) | prox_data[0];

  return 0;
}

// Function to log data to file
void log_data(FILE *fp, float lux, uint16_t proximity) {
  char timestamp_str[30];
  get_timestamp(timestamp_str);
  fprintf(fp, "%s,%.2f,%u\n", timestamp_str, lux, proximity);
  fflush(fp); // Ensure data is written to disk immediately
}

