void print_data(float lux, uint16_t proximity) {
  char timestamp_str[30];
  get_timestamp(timestamp_str);
  printf("%s,%.2f,%u\n", timestamp_str, lux, proximity);
}

// Signal handler function
void signal_handler(int sig) {
  terminate = 1;
  printf("Received signal %d, terminating...\n", sig);
}

// Function to get timestamp
char* get_timestamp(char* timestamp_str) {
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  time_t t = ts.tv_sec;
  struct tm* tm_info = localtime(&t);

  strftime(timestamp_str, 30, "%Y-%m-%d %H:%M:%S", tm_info);
  sprintf(timestamp_str + strlen(timestamp_str), ".%03ld", ts.tv_nsec / 1000000);
  return timestamp_str;
}

int main() {
  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize sensor
  if (init_sensor(i2c_fd) != 0) {
    fprintf(stderr, "Sensor initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("biometric_log.txt", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  float lux;
  uint16_t proximity;

  // Main loop
  while (!terminate) {
    // Read sensor data
    if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
      // Log data
      log_data(log_file, lux, proximity);

      // Print data
      print_data(lux, proximity);
    } else {
      fprintf(stderr, "Failed to read sensor data\n");
    }

    // Wait 100ms
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100 milliseconds
    nanosleep(&ts, NULL);
  }

  // Close resources
  close(i2c_fd);
  fclose(log_file);

  return 0;
}

