#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

// Si1145 Registers
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_INT_CFG 0x1A
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80
#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity(uint16_t *proximity);
int log_data(uint16_t proximity);
void signal_handler(int signal);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_register(int handle, uint8_t reg, uint8_t *value);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to write a byte to a register with retries
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
            log_data(0); // Log the error
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }
    fprintf(stderr, "Failed to write to register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read a byte from a register with retries
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
            log_data(0); // Log the error
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }
    fprintf(stderr, "Failed to read from register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    if (write_register(i2c_handle, REG_HW_KEY, 0x03) != 0) return -1;
    if (write_register(i2c_handle, REG_MEAS_RATE, 0x02) != 0) return -1;
    if (write_register(i2c_handle, REG_INT_CFG, 0x00) != 0) return -1;
    if (write_register(i2c_handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) != 0) return -1;
    if (write_register(i2c_handle, REG_ALS_VIS_ADC_GAIN, 0x00) != 0) return -1;
    if (write_register(i2c_handle, REG_PS_ADC_COUNTER, 0x49) != 0) return -1;
    if (write_register(i2c_handle, REG_PS_LED21, 0x03) != 0) return -1;
    if (write_register(i2c_handle, REG_PS_LED3, 0x0F) != 0) return -1;
    if (write_register(i2c_handle, REG_PS_ADC_MISC, 0x03) != 0) return -1;
    if (write_register(i2c_handle, REG_PS_ADC_GAIN, 0x07) != 0) return -1;
    if (write_register(i2c_handle, REG_COMMAND, 0x03) != 0) return -1;

    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity(uint16_t *proximity) {
    uint8_t low_byte, high_byte;

    if (read_register(i2c_handle, REG_PS1_DATA0, &low_byte) != 0) return -1;
    if (read_register(i2c_handle, REG_PS1_DATA1, &high_byte) != 0) return -1;

    *proximity = ((uint16_t)high_byte << 8) | low_byte;
    return 0;
}

// Function to log the proximity data to a file
int log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t proximity;

    // Main loop
    while (!terminate) {
        if (read_proximity(&proximity) == 0) {
            log_data(proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
            log_data(0); // Log the error
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

