#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm
#define TRIGGER_PULSE_DURATION 10 // us

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_active = 0; // Flag to indicate if echo is active

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin high\n");
        gpioTerminate();
        exit(1);
    }
    gpioDelay(TRIGGER_PULSE_DURATION);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low\n");
        gpioTerminate();
        exit(1);
    }
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        rising_tick = tick;
        echo_active = 1; // Set flag to indicate echo is active
    } else if (level == 0) { // Falling edge
        if (echo_active) { // Only process if rising edge was detected
            falling_tick = tick;
            uint32_t diff = falling_tick - rising_tick;
            double distance = (double)diff * SPEED_OF_SOUND / 2.0;

            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) != 0) {
                    fprintf(stderr, "Error: Failed to set buzzer pin high\n");
                    gpioTerminate();
                    exit(1);
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to set buzzer pin low\n");
                    gpioTerminate();
                    exit(1);
                }
            }
            echo_active = 0; // Reset flag
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set echo pin as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(1000000); // 1 second delay
    }

    return 0;
}

