#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants for distance calculation
#define SOUND_SPEED 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000      // Timeout for echo pulse in microseconds

// Constants for servo control
#define SERVO_MIN_PULSE_WIDTH 500  // Minimum pulse width (0 degrees)
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum pulse width (180 degrees)
#define SERVO_CENTER_PULSE_WIDTH 1500 // Center pulse width (90 degrees)

// Constants for distance range
#define MIN_DISTANCE 20.0  // Minimum distance in cm
#define MAX_DISTANCE 200.0 // Maximum distance in cm

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the ultrasonic sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SOUND_SPEED / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set the servo angle
void setServoAngle(float distance) {
    // Map distance to servo pulse width
    float pulse_width = 0.0;

    if (distance <= MIN_DISTANCE) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    } else if (distance >= MAX_DISTANCE) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else {
        // Linear mapping
        pulse_width = SERVO_MAX_PULSE_WIDTH - (distance - MIN_DISTANCE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / (MAX_DISTANCE - MIN_DISTANCE);
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Get the distance
        float distance = getDistance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set the servo angle
        setServoAngle(distance);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait for 100 ms
        gpioDelay(100);
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

