#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define SERVO_CLOSED 1000
#define SERVO_OPEN 2000
#define DISTANCE_CLOSE_THRESHOLD 200 // mm
#define DISTANCE_OPEN_THRESHOLD 250  // mm
#define TIMING_BUDGET 50 // ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_servo(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0088
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x0004
#define VL53L1X_REG_PERF_TIMING_BUDGET_US 0x008E

// Helper function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a word (2 bytes) from a VL53L1X register
int read_register_word(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for word read 0x%04X\n", reg);
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading word from register 0x%04X\n", reg);
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM range and frequency for servo control
    gpioSetPWMrange(SERVO_GPIO, 20000); // 20 ms period (50 Hz)
    gpioSetPWMfrequency(SERVO_GPIO, 50);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    uint16_t distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Main loop
    while (!terminate) {
