    // Write to the CONFIG register (0x03) to select internal temperature sensor and disable heater
    result = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }

    // Wait for 10 milliseconds
    gpioDelay(10000);

    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    int raw_temp, raw_humid;
    int result;

    // Read temperature data
    result = i2cWriteByte(i2c_handle, TEMP_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing to temperature register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait for conversion
    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temp);
        return -1;
    }

    // Read humidity data
    result = i2cWriteByte(i2c_handle, HUMID_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing to humidity register: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait for conversion
    raw_humid = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humid < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", raw_humid);
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = (175.72 * raw_temp) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humid) / 65536.0 - 6.0;

    return 0;
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si7005() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_si7005() != 0) {
                    fprintf(stderr, "Sensor re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        // Wait for 2 seconds
        gpioDelay(2000000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

