// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_HIGH_REP 0x2C06
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sts30(float *temperature);
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data (optional)
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read temperature from STS30
int read_sts30(float *temperature) {
    char cmd[2] = {(MEASURE_HIGH_REP >> 8) & 0xFF, MEASURE_HIGH_REP & 0xFF};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for high repeatability)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // Convert data
    uint16_t temp_raw = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    return 0;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written immediately
    } else {
        log_error("Log file is not open");
    }
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s, %s\n", timestamp, message);
        fflush(error_log_file);
    } else {
        perror("Error log file is not open");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_sts30(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

