int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the sensor for continuous measurement
int configure_sensor() {
    char command[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait at least 1 ms
    return 0;
}

// Read data from the sensor
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_SIZE);
    if (bytes_read != DATA_FRAME_SIZE) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Process raw sensor data
SensorData process_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t scale_factor_pressure = (data[6] << 8) | data[7];
    int16_t scale_factor_temperature = (data[6] << 8) | data[7]; // Same as pressure scale factor

    // Convert raw data to physical units (Pa and °C)
    sensor_data.pressure = (float)raw_pressure / (float)scale_factor_pressure;
    sensor_data.temperature = (float)raw_temperature / (float)scale_factor_temperature;

    return sensor_data;
}

// Log data to CSV file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Get current timestamp in ISO 8601 format
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    uint8_t data[DATA_FRAME_SIZE];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 3) && validate_crc(data + 3, 3) && validate_crc(data + 6, 3)) {
                // Process sensor data
                sensor_data = process_sensor_data(data);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1); // Poll every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

