#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define LOG_FILE "sht40_log.txt"
#define SLEEP_DURATION_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int read_sht40(int fd, float *temperature, float *humidity) {
    unsigned char data[6];
    unsigned char cmd = MEASUREMENT_COMMAND;

    // Send measurement command
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write measurement command");
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    usleep(10000); // 10 ms

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    float temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            // Log data
            log_data(log_fp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION_SEC);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

