// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_CMD_1 0x21
#define TRIGGER_CMD_2 0x96
#define SAMPLE_INTERVAL_MS 100
#define NUM_RETRIES 3
#define BACKOFF_DELAY_MS 10

// Global variables
static volatile sig_atomic_t terminate = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sdp31(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SDP31 with retry logic
int read_sdp31(sensor_data_t *data) {
    char buf[2];
    char read_buf[6];
    int retries = 0;
    int result;

    buf[0] = TRIGGER_CMD_1;
    buf[1] = TRIGGER_CMD_2;

    while (retries < NUM_RETRIES) {
        result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result == 0) {
            gpioDelay(1); // Wait at least 1 ms
            break;
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }

    if (retries == NUM_RETRIES) {
        fprintf(stderr, "I2C write failed after %d retries\n", NUM_RETRIES);
        return -1;
    }

    retries = 0;
    while (retries < NUM_RETRIES) {
        result = i2cReadDevice(i2c_handle, read_buf, 6);
        if (result == 6) {
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }

    if (retries == NUM_RETRIES) {
        fprintf(stderr, "I2C read failed after %d retries\n", NUM_RETRIES);
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (read_buf[0] << 8) | read_buf[1];
    int16_t raw_temperature = (read_buf[3] << 8) | read_buf[4];

    data->pressure_pa = (float)raw_pressure / 60.0;
    data->temperature_c = (float)raw_temperature / 200.0;

    return 0;
}

// Function to log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    fflush(log_file);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

