int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint8_t command, uint16_t *raw_data) {
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(i2c_handle, command) != 0) {
            fprintf(stderr, "I2C write failed (command 0x%02X): %s\n", command, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(20000); // Wait for measurement (20ms)

