#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// CRC-8 lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t address, uint16_t command);
int i2c_read(int fd, uint8_t address, uint8_t *data, int length);
uint8_t crc8(const uint8_t *data, int length);
int validate_crc(const uint8_t *data, int length);
int trigger_measurement(int fd, uint8_t address);
int read_sensor_data(int fd, uint8_t address, uint8_t *data);
float convert_pressure(int32_t raw_pressure, int32_t scale_factor);
float convert_temperature(int32_t raw_temperature);
int log_data(const char *filename, float pressure, float temperature);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t address, uint16_t command) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t address, uint8_t *data, int length) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int length) {
    uint8_t crc = crc8(data, length - 1);
    return (crc == data[length - 1]);
}

// Trigger measurement function
int trigger_measurement(int fd, uint8_t address) {
    return i2c_write(fd, address, MEASUREMENT_COMMAND);
}

// Read sensor data function
int read_sensor_data(int fd, uint8_t address, uint8_t *data) {
    return i2c_read(fd, address, data, DATA_LENGTH);
}

// Pressure conversion function
float convert_pressure(int32_t raw_pressure, int32_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Temperature conversion function
float convert_temperature(int32_t raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Log data function
int log_data(const char *filename, float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(log_file);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Trigger measurement
    if (trigger_measurement(i2c_fd, SDP800_ADDRESS) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Wait for measurement to complete
    usleep(45000); // 45 ms

    uint8_t data[DATA_LENGTH];
    int32_t raw_pressure, raw_temperature, scale_factor;
    float pressure, temperature;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, SDP800_ADDRESS, data) < 0) {
            fprintf(stderr, "Error reading sensor data. Retrying in 100ms.\n");
            usleep(100000); // 100 ms
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 3)) {
            fprintf(stderr, "Pressure CRC validation failed. Retrying in 100ms.\n");
            usleep(100000); // 100 ms
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 3)) {
            fprintf(stderr, "Temperature CRC validation failed. Retrying in 100ms.\n");
            usleep(100000); // 100 ms
            continue;
        }

        // Validate CRC for scale factor
        if (!validate_crc(data + 6, 3)) {
            fprintf(stderr, "Scale factor CRC validation failed. Retrying in 100ms.\n");
            usleep(100000); // 100 ms
            continue;
        }

        // Convert raw data
        raw_pressure = (int32_t)((data[0] << 8) | data[1]);
        raw_temperature = (int32_t)((data[3] << 8) | data[4]);
        scale_factor = (int32_t)((data[6] << 8) | data[7]);

        pressure = convert_pressure(raw_pressure, scale_factor);
        temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(LOG_FILE, pressure, temperature) < 0) {
            fprintf(stderr, "Error logging data. Retrying in 100ms.\n");
        }

        // Wait before next measurement
        usleep(100000); // 100 ms
    }

    // Close I2C bus and log file (should not reach here if signal handler works)
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

