#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REP 0xFD
#define DATA_LENGTH 6
#define LOG_FILE "sht40_log.txt"
#define SLEEP_SECONDS 5

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t stop_flag = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT40
int read_sht40(int fd, float *temperature, float *humidity) {
    unsigned char data[DATA_LENGTH];
    unsigned char cmd = MEASURE_HIGH_REP;

    // Send measurement command
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement (at least 8.5 ms)
    usleep(10000); // 10 ms

    // Read 6 bytes of data
    if (read(fd, data, DATA_LENGTH) != DATA_LENGTH) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        stop_flag = 1;
    }
}

int main() {
    float temperature, humidity;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(log_fp, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading SHT40, continuing...\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    return 0;
}

