#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SCALE_FACTOR_PRESSURE 240.0f
#define SCALE_FACTOR_TEMPERATURE 200.0f
#define TEMPERATURE_OFFSET -45.0f
#define LOG_FILE "airflow_data.txt"

// Global variables for cleanup
static int i2c_fd = -1;
static FILE *log_file = NULL;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int fd, float *pressure, float *temperature) {
    uint8_t cmd[2] = {(CONTINUOUS_MEASUREMENT_CMD >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_CMD & 0xFF};
    uint8_t data[6];

    // Send continuous measurement command
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for at least 1 ms
    usleep(1000);

    // Read 6 bytes of data
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC for pressure
    uint8_t crc_pressure = crc8(data, 2);
    if (crc_pressure != data[2]) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temperature = crc8(data + 3, 2);
    if (crc_temperature != data[5]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    *temperature = ((float)raw_temperature / SCALE_FACTOR_TEMPERATURE) + TEMPERATURE_OFFSET;

    return 0;
}

// Function to log data to a file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    float pressure, temperature;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sdp800(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(log_file, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1); // Read data every 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    fclose(log_file);
    return 0;
}

