// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    char buf[2];
    int raw_temperature, raw_humidity;
    int retries = RETRY_COUNT;

    // Read temperature
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, 0xE3) == 0) {
            gpioDelay(10); // Wait 10ms
            if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
                raw_temperature = (buf[0] << 8) | buf[1];
                break;
            } else {
                fprintf(stderr, "Error reading temperature, retrying...\n");
            }
        } else {
            fprintf(stderr, "Error writing temperature command, retrying...\n");
        }
        retries--;
        gpioDelay(100); // Wait before retrying
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    // Read humidity
    while (retries > 0) {
        if (i2cWriteByte(i2c_handle, 0xE5) == 0) {
            gpioDelay(10); // Wait 10ms
            if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
                raw_humidity = (buf[0] << 8) | buf[1];
                break;
            } else {
