#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_DATA_READY 0xE4B8

// CRC polynomial and initialization value
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int verify_crc(uint8_t data[], int len);
int read_scd40_data(int handle, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 verification function
int verify_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(int handle, sensor_data_t *data) {
    uint8_t read_ready_cmd[2] = {(CMD_DATA_READY >> 8) & 0xFF, CMD_DATA_READY & 0xFF};
    uint8_t read_measurement_cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    uint8_t data_ready[2];
    uint8_t measurement_data[9];

    // Check data ready flag
    if (i2cWriteDevice(handle, read_ready_cmd, 2) != 2) {
        fprintf(stderr, "Failed to send data ready command\n");
        return -1;
    }
    gpioDelay(10); // Small delay after sending the command
    if (i2cReadDevice(handle, (char *)data_ready, 2) != 2) {
        fprintf(stderr, "Failed to read data ready response\n");
        return -1;
    }

    uint16_t data_ready_value = (data_ready[0] << 8) | data_ready[1];

    if (data_ready_value != 1) {
        fprintf(stderr, "Data not ready yet\n");
        return -1; // Data not ready
    }

    // Read measurement data
    if (i2cWriteDevice(handle, read_measurement_cmd, 2) != 2) {
        fprintf(stderr, "Failed to send read measurement command\n");
        return -1;
    }
    gpioDelay(10); // Small delay after sending the command
    if (i2cReadDevice(handle, (char *)measurement_data, 9) != 9) {
        fprintf(stderr, "Failed to read measurement data\n");
        return -1;
    }

    // Verify CRC for CO2
    if (!verify_crc(measurement_data, 3)) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // Verify CRC for Temperature
    if (!verify_crc(measurement_data + 3, 3)) {
        fprintf(stderr, "CRC check failed for Temperature\n");
        return -1;
    }

    // Verify CRC for Humidity
    if (!verify_crc(measurement_data + 6, 3)) {
        fprintf(stderr, "CRC check failed for Humidity\n");
        return -1;
    }

    // Extract raw values
    uint16_t raw_co2 = (measurement_data[0] << 8) | measurement_data[1];
    uint16_t raw_temperature = (measurement_data[3] << 8) | measurement_data[4];
    uint16_t raw_humidity = (measurement_data[6] << 8) | measurement_data[7];

    // Convert to physical values
    data->co2 = raw_co2;
    data->temperature = -45 + 175 * (float)raw_temperature / 65535.0;
    data->humidity = 100 * (float)raw_humidity / 65535.0;

    return 0;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            data.co2, data.temperature, data.humidity);
    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second after starting periodic measurement

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(i2c_handle, &sensor_data) == 0) {
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

