int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // I2C bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn off the LED
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return 1;
    }
    gpioDelay(1); // Small delay after write
    return 0;
}

// Get data ready status
int get_data_ready_status() {
    char buf[2];
    buf[0] = (GET_DATA_READY_STATUS >> 8) & 0xFF;
    buf[1] = GET_DATA_READY_STATUS & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready status command: %d\n", result);
        return 1;
    }
    gpioDelay(1); // Small delay after write

    char read_buf[3];
    result = i2cReadDevice(i2c_handle, read_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready status: %d\n", result);
        return 1;
    }

    uint16_t status = (read_buf[0] << 8) | read_buf[1];
    uint8_t crc = read_buf[2];

    uint8_t calculated_crc = crc8((uint8_t *)read_buf, 2);

    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed for data ready status\n");
        return 1;
    }

    if ((status & 0x0001) == 0) {
        return 1; // Data not ready
    }

    return 0; // Data ready
}

// Read measurement
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    char buf[2];
    buf[0] = (READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return 1;
    }
    gpioDelay(1); // Small delay after write

    char read_buf[9];
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return 1;
    }

    *co2 = (read_buf[0] << 8) | read_buf[1];
    *temperature = (read_buf[3] << 8) | read_buf[4];
    *humidity = (read_buf[6] << 8) | read_buf[7];

    uint8_t co2_crc = read_buf[2];
    uint8_t temperature_crc = read_buf[5];
    uint8_t humidity_crc = read_buf[8];

    uint8_t calculated_co2_crc = crc8((uint8_t *)read_buf, 2);
    uint8_t calculated_temperature_crc = crc8((uint8_t *)read_buf + 3, 2);
    uint8_t calculated_humidity_crc = crc8((uint8_t *)read_buf + 6, 2);

    if (calculated_co2_crc != co2_crc) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return 1;
    }

    if (calculated_temperature_crc != temperature_crc) {
        fprintf(stderr, "CRC check failed for temperature\n");
        return 1;
    }

    if (calculated_humidity_crc != humidity_crc) {
        fprintf(stderr, "CRC check failed for humidity\n");
        return 1;
    }

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write stop periodic measurement command: %d\n", result);
        return 1;
    }
    gpioDelay(1); // Small delay after write
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Add data to circular buffer
void add_to_buffer(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print buffer contents
void print_buffer() {
    printf("CO2 (ppm), Temperature (C), Humidity (%%RH)\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("%d, %d, %d\n", circular_buffer[index].co2, circular_buffer[index].temperature, circular_buffer[index].humidity);
    }
    printf("\n");
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program.\n", signal);
    terminate = 1;
}

