        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Measure temperature
double measure_temperature() {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    double TH, TL, temperature;

    // Measure high time
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for high signal\n");
            return -1000.0; // Indicate error
        }
    }
    high_tick = gpioTick();

    // Measure low time
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - high_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for low signal\n");
            return -1000.0; // Indicate error
        }
    }
    end_tick = gpioTick();

    TH = (double)(high_tick - start_tick);
    TL = (double)(end_tick - start_tick);

    if (TL == 0.0) {
        fprintf(stderr, "Division by zero error: TL is zero\n");
        return -1000.0; // Indicate error
    }

    temperature = 4215.0 - (2143.0 * TH / TL);

