#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define SIMULATION_PERIOD 3600 // seconds (1 hour)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int write_i2c_command(int handle, uint16_t command);
int read_i2c_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int validate_crc(uint8_t data[], int nbrOfBytes);
int read_sensor_data(int handle, uint8_t *data);
SensorData process_sensor_data(uint8_t *data);
SensorData simulate_environmental_variation(SensorData data, time_t current_time);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to write a command to the I2C device
int write_i2c_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc_calculated = calculate_crc(data, nbrOfBytes);
    if (crc_calculated != data[nbrOfBytes]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int handle, uint8_t *data) {
    for (int i = 0; i < RETRY_COUNT; i++) {
        if (write_i2c_command(handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write measurement command, retry %d\n", i + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }
        gpioDelay(15); // Wait 15 ms for measurement

        if (read_i2c_data(handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read sensor data, retry %d\n", i + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        // Validate CRC for temperature and humidity
        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "CRC validation failed, retry %d\n", i + 1);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to process sensor data
SensorData process_sensor_data(uint8_t *data) {
    SensorData sensor_data;
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    // Convert raw values to temperature and humidity
    sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to simulate environmental variation
SensorData simulate_environmental_variation(SensorData data, time_t current_time) {
    float time_fraction = (float)(current_time % SIMULATION_PERIOD) / SIMULATION_PERIOD;
    float temperature_variation = 2.0 * sin(2 * M_PI * time_fraction);
    float humidity_variation = 5.0 * sin(2 * M_PI * time_fraction);

    data.temperature += temperature_variation;
    data.humidity += humidity_variation;

    return data;
}

// Function to log data to file
int log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data_raw[6];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data_raw) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(sensor_data_raw);

            // Simulate environmental variation
            sensor_data = simulate_environmental_variation(sensor_data, time(NULL));

            // Log data
            log_data(sensor_data);
        } else {
            // Log NaN values if read fails
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

