#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CSV_FILE "environment.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c();
int send_measurement_command(int handle);
int read_sensor_data(int handle, uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to the sensor
int send_measurement_command(int handle) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadDevice(handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    if (crc_calculated != data[len - 1]) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, expected 0x%02X\n", crc_calculated, data[len - 1]);
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
int convert_data(const uint8_t *data, float *temperature, float *humidity) {
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Log data to CSV file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command(i2c_handle) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Wait for measurement (at least 15ms)
        gpioDelay(15000); // 15ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Validate CRC checksums
        if (validate_crc(sensor_data, 3) != 0 || validate_crc(sensor_data + 3, 3) != 0) {
            fprintf(stderr, "CRC validation failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Convert data
        if (convert_data(sensor_data, &temperature, &humidity) != 0) {
            fprintf(stderr, "Error converting data, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Log data
        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

