#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define PAIRED_READ_CMD 0xE0
#define RESET_CMD 0xFE
#define CSV_FILE "environment.log"
#define POLLING_INTERVAL_SEC 5

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t addr, uint8_t cmd);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int read_temperature(int fd, float *temperature);
int read_humidity(int fd, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int sig);
void cleanup(void);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t cmd) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device (expected %d, got %zd): %s\n", len, bytes_read, strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read temperature function
int read_temperature(int fd, float *temperature) {
    uint8_t data[3];
    int retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        if (i2c_write(fd, SI7021_ADDR, TEMP_CMD) < 0) {
            fprintf(stderr, "Error writing temperature command.\n");
            return -1;
        }

        usleep(20000); // Wait for measurement (at least 20ms)

        if (i2c_read(fd, SI7021_ADDR, data, 3) == 0) {
            uint8_t crc = crc8(data, 2);
            if (crc == data[2]) {
                uint16_t raw = (data[0] << 8) | data[1];
                *temperature = 175.72 * raw / 65536.0 - 46.85;
                return 0;
            } else {
                fprintf(stderr, "Temperature CRC check failed.\n");
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading temperature data. Retry %d\n", retries + 1);
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1;
}

// Read humidity function
int read_humidity(int fd, float *humidity) {
    uint8_t data[3];
    int retries = 0;
    int delay_ms = 10;

    while (retries < 10) {
        if (i2c_write(fd, SI7021_ADDR, HUMID_CMD) < 0) {
            fprintf(stderr, "Error writing humidity command.\n");
            return -1;
        }

        usleep(20000); // Wait for measurement (at least 20ms)

        if (i2c_read(fd, SI7021_ADDR, data, 3) == 0) {
            uint8_t crc = crc8(data, 2);
            if (crc == data[2]) {
                uint16_t raw = (data[0] << 8) | data[1];
                *humidity = 125.0 * raw / 65536.0 - 6.0;
                return 0;
            } else {
                fprintf(stderr, "Humidity CRC check failed.\n");
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading humidity data. Retry %d\n", retries + 1);
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Failed to read humidity after multiple retries.\n");
    return -1;
}

// Log data function
int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    }
    rewind(log_file);

    float temperature, humidity;

    while (!terminate) {
        // Read temperature and humidity
        if (read_temperature(i2c_fd, &temperature) == 0 && read_humidity(i2c_fd, &humidity) == 0) {
            // Log data
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // Log error
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Error reading sensor data. Resetting sensor.\n");

            // Reset sensor
            if (i2c_write(i2c_fd, SI7021_ADDR, RESET_CMD) < 0) {
                fprintf(stderr, "Error resetting sensor.\n");
            }
            usleep(100000); // Wait for reset to complete
        }

        sleep(POLLING_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

