#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SAMPLE_INTERVAL_MS 1000
#define DATA_FILE "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function prototypes
int init_pigpio();
int open_i2c();
int write_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *buffer, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int16_t convert_pressure(uint8_t msb, uint8_t lsb);
int16_t convert_temperature(uint8_t msb, uint8_t lsb);
float process_pressure(int16_t raw_pressure, uint32_t scale_factor);
float process_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *buffer, int count) {
    int result = i2cReadDevice(handle, (char *)buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Convert pressure data
int16_t convert_pressure(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Convert temperature data
int16_t convert_temperature(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Process pressure data
float process_pressure(int16_t raw_pressure, uint32_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor - 1000.0f;
}

// Process temperature data
float process_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0f - 45.0f;
}

// Log data to file
int log_data(float pressure, float temperature) {
    if (data_file == NULL) {
        data_file = fopen(DATA_FILE, "ab");
        if (data_file == NULL) {
            fprintf(stderr, "Failed to open data file\n");
            return -1;
        }
    }

    size_t bytes_written = fwrite(&pressure, sizeof(float), 1, data_file);
    bytes_written += fwrite(&temperature, sizeof(float), 1, data_file);

    if (bytes_written != 2) {
        fprintf(stderr, "Failed to write data to file\n");
        return -1;
    }

    fflush(data_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        uint32_t scale_factor;

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract raw values
        int16_t raw_pressure = convert_pressure(data[0], data[1]);
        int16_t raw_temperature = convert_temperature(data[3], data[4]);
        scale_factor = ((uint32_t)data[5] << 16) | ((uint32_t)data[6] << 8) | (uint32_t)data[7];

        // Validate CRC
        if (!validate_crc(data, 2, data[2]) || !validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Skip to the next sample
        }

        // Process data
        float pressure = process_pressure(raw_pressure, scale_factor);
        float temperature = process_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    if (data_file != NULL) {
        fclose(data_file);
    }

    return 0;
}

