int16_t convert_pressure(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Convert temperature data
int16_t convert_temperature(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

// Process pressure data
float process_pressure(int16_t raw_pressure, uint32_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor - 1000.0f;
}

// Process temperature data
float process_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0f - 45.0f;
}

