        if (data_file == NULL) {
            fprintf(stderr, "Failed to open data file\n");
            return -1;
        }
    }

    size_t bytes_written = fwrite(&pressure, sizeof(float), 1, data_file);
    bytes_written += fwrite(&temperature, sizeof(float), 1, data_file);

    if (bytes_written != 2) {
        fprintf(stderr, "Failed to write data to file\n");
        return -1;
    }

    fflush(data_file); // Ensure data is written to disk
    return 0;
}

