    if (open_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
