        uint8_t data[9];
        uint32_t scale_factor;

        // Read data from sensor
        if (read_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract raw values
        int16_t raw_pressure = convert_pressure(data[0], data[1]);
        int16_t raw_temperature = convert_temperature(data[3], data[4]);
        scale_factor = ((uint32_t)data[5] << 16) | ((uint32_t)data[6] << 8) | (uint32_t)data[7];

        // Validate CRC
        if (!validate_crc(data, 2, data[2]) || !validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Skip to the next sample
        }

        // Process data
        float pressure = process_pressure(raw_pressure, scale_factor);
        float temperature = process_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    if (data_file != NULL) {
        fclose(data_file);
    }

    return 0;
}

