#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle);
float convert_to_flow_rate(int raw_reading);
void set_fan_speed(float flow_rate);
void log_data(float pressure_pa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit word
    int raw_reading = (buffer[0] << 8) | buffer[1];

    // Mask off the status bits and shift right by 2
    raw_reading = (raw_reading & 0x3FFF) >> 2;

    return raw_reading;
}

// Function to convert raw reading to flow rate
float convert_to_flow_rate(int raw_reading) {
    // Linear transfer function: 1638 counts = 0 SLPM, 14745 counts = 10 SLPM
    float flow_rate = (float)(raw_reading - 1638) * 10.0 / (14745 - 1638);
    return flow_rate;
}

// Function to set fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    // Scale the flow rate linearly between 0% and 100%
    int duty_cycle = (int)(flow_rate * 100.0);

    // Ensure duty cycle is within the valid range (0-100)
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 100) {
        duty_cycle = 100;
    }

    // Set the PWM duty cycle
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float pressure_pa) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_pa);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int raw_reading = read_sensor_data(i2c_handle);
        if (raw_reading == -1) {
            // Handle I2C read error, but continue running
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next attempt
            continue;
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(raw_reading);

        // Set fan speed
        set_fan_speed(flow_rate);

        // Log data
        log_data(flow_rate * 1000.0); // Log pressure in Pa (SLPM * 1000)

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

