#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
static volatile sig_atomic_t terminate = 0;
static int i2c_handle;
static FILE *log_file;
static char *server_ip;
static int server_port;

// Function prototypes
int init_i2c();
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint8_t value);
int32_t read_pressure(int handle);
int16_t read_temperature(int handle);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
int send_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read a single register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a single register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read pressure data
int32_t read_pressure(int handle) {
    int32_t pressure = 0;
    int xl, l, h;

    xl = read_register(handle, PRESS_OUT_XL);
    l = read_register(handle, PRESS_OUT_L);
    h = read_register(handle, PRESS_OUT_H);

    if (xl < 0 || l < 0 || h < 0) {
        return -1; // Indicate error
    }

    pressure = (int32_t)((xl << 16) | (l << 8) | h);
    pressure = pressure >> 8; // Align to 24 bits

    return pressure;
}

// Read temperature data
int16_t read_temperature(int handle) {
    int16_t temperature = 0;
    int l, h;

    l = read_register(handle, TEMP_OUT_L);
    h = read_register(handle, TEMP_OUT_H);

    if (l < 0 || h < 0) {
        return -1; // Indicate error
    }

    temperature = (int16_t)((h << 8) | l);

    return temperature;
}

// Convert pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tstruct;
    char buf[80];
    localtime_r(&now, &tstruct);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tstruct);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", buf, pressure, temperature);
    fflush(log_file);
    return 0;
}

// Send data to server
int send_data(float pressure, float temperature) {
    int sockfd;
    struct sockaddr_in servaddr;
    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);

    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    snprintf(message, sizeof(message), "Pressure: %.2f hPa, Temperature: %.2f °C", pressure, temperature);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Check WHO_AM_I register
    int who_am_i = read_register(i2c_handle, WHO_AM_I);
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X\n", who_am_i);
        cleanup();
        return 1;
    }

    // Configure CTRL_REG1
    if (write_register(i2c_handle, CTRL_REG1, 0xB0) != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int32_t raw_pressure = read_pressure(i2c_handle);
        int16_t raw_temperature = read_temperature(i2c_handle);

        if (raw_pressure >= 0 && raw_temperature >= 0) {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);

            log_data(pressure, temperature);
            send_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    cleanup();
    return 0;
}

