#define CMD_SET_MEASUREMENT_INTERVAL 0x21B1
#define CMD_START_CONTINUOUS_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_GET_DATA_READY 0x0202

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Function prototypes
int initialize_sensor();
int set_measurement_interval(int interval);
int start_continuous_measurement();
int read_data_ready();
int read_measurement(float *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float co2, float temperature, float humidity);
void ventilation_control(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the SCD30 sensor
int initialize_sensor() {
    if (set_measurement_interval(2) != 0) {
        fprintf(stderr, "Error setting measurement interval.\n");
        return -1;
    }

    if (start_continuous_measurement() != 0) {
        fprintf(stderr, "Error starting continuous measurement.\n");
        return -1;
    }

    return 0;
}

// Set the measurement interval
int set_measurement_interval(int interval) {
    uint8_t cmd[2] = {CMD_SET_MEASUREMENT_INTERVAL >> 8, CMD_SET_MEASUREMENT_INTERVAL & 0xFF};
    uint8_t data[3] = {interval >> 8, interval & 0xFF, crc8(data, 2)};
    char buf[5] = {(char)cmd[0], (char)cmd[1], (char)data[0], (char)data[1], (char)data[2]};

    if (i2cWriteDevice(i2c_handle, buf, 5) != 5) {
        fprintf(stderr, "Error writing measurement interval command.\n");
        return -1;
    }
    return 0;
}

// Start continuous measurement
int start_continuous_measurement() {
    uint8_t cmd[2] = {CMD_START_CONTINUOUS_MEASUREMENT >> 8, CMD_START_CONTINUOUS_MEASUREMENT & 0xFF};
    char buf[2] = {(char)cmd[0], (char)cmd[1]};

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing start measurement command.\n");
        return -1;
    }
    return 0;
}

// Read the data ready flag
int read_data_ready() {
    uint8_t cmd[2] = {CMD_GET_DATA_READY >> 8, CMD_GET_DATA_READY & 0xFF};
    char buf[2] = {(char)cmd[0], (char)cmd[1]};
    char response[3];

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing data ready command.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, response, 3) != 3) {
        fprintf(stderr, "Error reading data ready response.\n");
        return -1;
    }

    uint16_t data_ready = (response[0] << 8) | response[1];
    return data_ready;
}

// Read measurement data
int read_measurement(float *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {CMD_READ_MEASUREMENT >> 8, CMD_READ_MEASUREMENT & 0xFF};
    char buf[2] = {(char)cmd[0], (char)cmd[1]};
    char response[18];

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing read measurement command.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, response, 18) != 18) {
        fprintf(stderr, "Error reading measurement data.\n");
        return -1;
    }

    // Extract CO2
    uint32_t co2_raw = (response[0] << 24) | (response[1] << 16) | (response[2] << 8) | response[3];
    uint8_t co2_crc = response[4];
    if (crc8((uint8_t *)&response[0], 4) != co2_crc) {
        fprintf(stderr, "CO2 CRC check failed.\n");
        return -1;
    }
    *co2 = *(float *)&response[0];

    // Extract Temperature
    uint32_t temperature_raw = (response[6] << 24) | (response[7] << 16) | (response[8] << 8) | response[9];
    uint8_t temperature_crc = response[10];
    if (crc8((uint8_t *)&response[6], 4) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed.\n");
        return -1;
    }
    *temperature = *(float *)&response[6];

    // Extract Humidity
    uint32_t humidity_raw = (response[12] << 24) | (response[13] << 16) | (response[14] << 8) | response[15];
    uint8_t humidity_crc = response[16];
    if (crc8((uint8_t *)&response[12], 4) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed.\n");
        return -1;
    }
    *humidity = *(float *)&response[12];

    return 0;
}

// Log data to file
void log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Ventilation control logic
void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 >= 800 && co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction (SIGINT)");
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction (SIGTERM)");
        cleanup();
        return 1;
    }

    float co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (read_data_ready() == 1) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity);

                // Ventilation control
                ventilation_control(co2);
            } else {
                fprintf(stderr, "Error reading measurement data.\n");
            }
        } else {
            // Data not ready, wait a bit
            gpioDelay(100); // 100 ms
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

