#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
int verify_crc(uint8_t data[], int nbrOfBytes, uint8_t crc);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
void log_data(float pressure_pa, float temperature_c);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start measurement function
int start_measurement() {
    char cmd[2] = {0x36, 0x2F};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(sensor_data_t *data) {
    char buffer[9];
    int result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    // CRC verification
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};
    uint8_t scale_factor_data[2] = {buffer[6], buffer[7]};

    if (!verify_crc(pressure_data, 2, buffer[2])) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    if (!verify_crc(temperature_data, 2, buffer[5])) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (!verify_crc(scale_factor_data, 2, buffer[8])) {
        fprintf(stderr, "Scale factor CRC check failed\n");
        return -1;
    }

    return 0;
}

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 verification function
int verify_crc(uint8_t data[], int nbrOfBytes, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, nbrOfBytes);
    return (calculated_crc == crc);
}

// Pressure conversion function
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Data logging function
void log_data(float pressure_pa, float temperature_c) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f C\n", timestamp, pressure_pa, temperature_c);
}

// Cleanup function
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int sample_interval = SAMPLE_INTERVAL_MS;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default: %d ms\n", SAMPLE_INTERVAL_MS);
            sample_interval = SAMPLE_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start measurement
    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    float pressure_pa, temperature_c;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            pressure_pa = convert_pressure(sensor_data.raw_pressure, sensor_data.scale_factor);
            temperature_c = (float)sensor_data.raw_temperature / 200.0; // Temperature conversion
            log_data(pressure_pa, temperature_c);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(sample_interval * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

