#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C device address of the HDC1000 sensor
#define HDC1000_ADDR 0x40

// Define the I2C device file path
#define I2C_DEVICE "/dev/i2c-1"

// Define the configuration register pointer
#define CONFIG_REG 0x02

// Define the temperature register pointer
#define TEMP_REG 0x00

// Define the humidity register pointer
#define HUMID_REG 0x01

// Define the resolution setting (14-bit)
#define RESOLUTION 0x0000

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    // Open the I2C device file
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to configure the HDC1000 sensor
int config_hdc1000() {
    unsigned char buf[3];

    // Set the configuration register pointer
    buf[0] = CONFIG_REG;

    // Set the configuration value (14-bit resolution, temperature and humidity measurement)
    buf[1] = (RESOLUTION >> 8) & 0xFF;
    buf[2] = RESOLUTION & 0xFF;

    // Write the configuration value to the sensor
    if (write(i2c_fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    unsigned char buf[4];
    unsigned short raw_temperature, raw_humidity;

    // Set the temperature register pointer
    if (write(i2c_fd, TEMP_REG, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the conversion to complete (at least 20ms)
    usleep(20000);

    // Read 4 bytes of data (2 bytes temperature, 2 bytes humidity)
    if (read(i2c_fd, buf, 4) != 4) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Extract the raw temperature and humidity values
    raw_temperature = (buf[0] << 8) | buf[1];
    raw_humidity = (buf[2] << 8) | buf[3];

    // Convert the raw values to temperature and humidity
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    float temperature, humidity;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure the HDC1000 sensor
    if (config_hdc1000() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity data
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Print the temperature and humidity values
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

