#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the register to read from (0x00 for pressure)
#define PRESSURE_REGISTER 0x00

// Define the number of bytes to read (2 bytes for pressure)
#define BYTES_TO_READ 2

// Global variable for the I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle, uint16_t *pressure) {
    char buffer[BYTES_TO_READ];
    int result;

    // Write the register address to be read
    result = i2cWriteByte(i2c_handle, PRESSURE_REGISTER);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Read the pressure data
    result = i2cReadDevice(i2c_handle, buffer, BYTES_TO_READ);
    if (result != BYTES_TO_READ) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *pressure = (buffer[0] << 8) | buffer[1];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t pressure;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Read the pressure
        if (read_pressure(i2c_handle, &pressure) == 0) {
            // Get the current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Format the timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print the timestamp and pressure value
            printf("%s Pressure: %u\n", timestamp, pressure);
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // This point should not be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

