#define CALIB_DATA_CMD 0x50
#define CALIB_DATA_LEN 8

// Measurement command
#define MEASURE_CMD 0x40
#define MEASURE_DELAY_MS 7
#define MEASURE_DATA_LEN 6

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int16_t c0, c1, c00, c10, c01, c11, c20, c21;

// Function prototypes
int read_calibration_data(int i2c_handle, int16_t *coefficients);
int trigger_measurement(int i2c_handle);
int read_measurement_data(int i2c_handle, uint8_t *data);
double calculate_temperature(uint8_t *data, int16_t *coefficients);
double calculate_pressure(uint8_t *data, int16_t *coefficients);
void log_data(double temperature, double pressure);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

// Function to read calibration data from the sensor
int read_calibration_data(int i2c_handle, int16_t *coefficients) {
    char buf[2];
    buf[0] = CALIB_DATA_CMD;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "%s - Error writing calibration command\n", iso8601_timestamp());
        return -1;
    }

    char data[CALIB_DATA_LEN];
    if (i2cReadDevice(i2c_handle, data, CALIB_DATA_LEN) != CALIB_DATA_LEN) {
        fprintf(stderr, "%s - Error reading calibration data\n", iso8601_timestamp());
        return -1;
    }

    // Check for all 0xFF bytes (sensor absent)
    int all_ff = 1;
    for (int i = 0; i < CALIB_DATA_LEN; i++) {
        if (data[i] != 0xFF) {
            all_ff = 0;
            break;
        }
    }
    if (all_ff) {
        fprintf(stderr, "%s - Sensor absent or I2C error\n", iso8601_timestamp());
        return -1;
    }

    // Extract calibration coefficients (example, adjust based on datasheet)
    coefficients[0] = (int16_t)((data[0] << 8) | data[1]);
    coefficients[1] = (int16_t)((data[2] << 8) | data[3]);
    coefficients[2] = (int16_t)((data[4] << 8) | data[5]);
    coefficients[3] = (int16_t)((data[6] << 8) | data[7]);

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement(int i2c_handle) {
    char buf[2];
    buf[0] = MEASURE_CMD;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "%s - Error writing measurement command\n", iso8601_timestamp());
        return -1;
    }
    gpioDelay(MEASURE_DELAY_MS * 1000); // Delay in microseconds
    return 0;
}

// Function to read measurement data from the sensor
int read_measurement_data(int i2c_handle, uint8_t *data) {
    if (i2cReadDevice(i2c_handle, (char *)data, MEASURE_DATA_LEN) != MEASURE_DATA_LEN) {
        fprintf(stderr, "%s - Error reading measurement data\n", iso8601_timestamp());
        return -1;
    }
    return 0;
}

// Function to calculate temperature (example, adjust based on datasheet)
double calculate_temperature(uint8_t *data, int16_t *coefficients) {
    // Example calculation (replace with actual formula from datasheet)
    int32_t raw_temperature = (data[0] << 8) | data[1];
    double temperature = (double)raw_temperature / 100.0; // Example scaling
    return temperature;
}

// Function to calculate pressure (example, adjust based on datasheet)
double calculate_pressure(uint8_t *data, int16_t *coefficients) {
    // Example calculation (replace with actual formula from datasheet)
    int32_t raw_pressure = (data[2] << 24) | (data[3] << 16) | (data[4] << 8) | data[5];
    double pressure = (double)raw_pressure / 100.0; // Example scaling
    return pressure;
}

// Function to log data to stdout
void log_data(double temperature, double pressure) {
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", iso8601_timestamp(), temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s - pigpio initialisation failed\n", iso8601_timestamp());
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "%s - I2C open failed\n", iso8601_timestamp());
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    int16_t coefficients[4];
    if (read_calibration_data(i2c_handle, coefficients) != 0) {
        fprintf(stderr, "%s - Failed to read calibration data\n", iso8601_timestamp());
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint8_t measurement_data[MEASURE_DATA_LEN];
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "%s - Failed to trigger measurement\n", iso8601_timestamp());
            continue; // Try again
        }

        // Read measurement data
        if (read_measurement_data(i2c_handle, measurement_data) != 0) {
            fprintf(stderr, "%s - Failed to read measurement data\n", iso8601_timestamp());
            continue; // Try again
        }

        // Calculate temperature and pressure
        double temperature = calculate_temperature(measurement_data, coefficients);
        double pressure = calculate_pressure(measurement_data, coefficients);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

