#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND_1 0x36
#define MEASUREMENT_COMMAND_2 0x2F
#define DATA_LENGTH 3
#define PRESSURE_SCALE_FACTOR 60.0
#define LOG_FILE "airflow_log.csv"
#define SLEEP_DURATION_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int verify_crc(const uint8_t *data, size_t length);
float convert_to_pressure(const uint8_t *data);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char command[2] = {MEASUREMENT_COMMAND_1, MEASUREMENT_COMMAND_2};
    if (i2cWriteDevice(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(8000); // Wait 8 ms

    if (i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH) != DATA_LENGTH) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(const uint8_t *data, size_t length) {
    uint8_t calculated_crc = crc8(data, length - 1);
    if (calculated_crc != data[length - 1]) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, data[length - 1]);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure
float convert_to_pressure(const uint8_t *data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Log data to CSV file
int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Check if the file is newly created and write the header
    struct stat st;
    if (stat(LOG_FILE, &st) == -1) {
        fprintf(fp, "Timestamp,Pressure (Pa)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[DATA_LENGTH];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data, DATA_LENGTH) == 0) {
                // Convert to pressure
                float pressure = convert_to_pressure(sensor_data);

                // Log data
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "CRC verification failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SLEEP_DURATION_US); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

