        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    uint16_t raw_pressure;
    float pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            log_pressure(pressure_kPa);
            check_pressure_range(pressure_kPa);
        } else {
            // Retry I2C initialization
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break; // Exit loop if re-initialization fails
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

