#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
int validate_status(unsigned char status);
SensorData convert_data(unsigned char *data);
char* get_iso8601_timestamp();
int log_data(SensorData data, char *timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a measurement on the HIH6130
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read 4 bytes of data from the HIH6130
int read_sensor_data(unsigned char *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate the status bits of the sensor data
int validate_status(unsigned char status) {
    if ((status & 0x80) != 0) {
        fprintf(stderr, "Sensor in command mode\n");
        return -1;
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "Sensor in sleep mode\n");
        return -1;
    }
    return 0;
}

// Convert raw data to temperature and humidity
SensorData convert_data(unsigned char *data) {
    SensorData sensor_data;
    unsigned int raw_humidity = ((unsigned int)data[0] << 8) | data[1];
    unsigned int raw_temperature = ((unsigned int)data[2] << 6) | (data[3] >> 2);

    sensor_data.humidity = (float)raw_humidity * 100.0 / 16383.0;
    sensor_data.temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;

    return sensor_data;
}

// Get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log the sensor data to a file
int log_data(SensorData data, char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Check if the file size exceeds the limit
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(LOG_FILE, "w"); // Truncate the file
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file for truncation: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Environmental data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        unsigned char data[4];
        SensorData sensor_data;
        char *timestamp;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Wait for measurement to complete (at least 40ms)
        gpioDelay(50); // Wait 50ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor data read failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Validate status bits
        if (validate_status(data[0]) != 0) {
            fprintf(stderr, "Sensor status invalid. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert data
        sensor_data = convert_data(data);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(sensor_data, timestamp) != 0) {
            fprintf(stderr, "Data logging failed.\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental data logger stopped.\n");
    return 0;
}

