    int raw_value;
    float pressure;

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sent_data(&sent_data) == 0) {
            // Combine data nibbles into raw value
            raw_value = (sent_data.data[0] << 8) | (sent_data.data[1] << 4) | sent_data.data[2];

            // Calculate checksum
            int calculated_checksum = calculate_checksum(sent_data.status, sent_data.data[0], sent_data.data[1], sent_data.data[2]);

            // Validate checksum
            if (calculated_checksum == sent_data.checksum) {
                // Convert to pressure
                pressure = convert_to_pressure(raw_value, scale, offset);

                // Log pressure
                log_pressure(pressure);
            } else {
                log_error("Checksum mismatch.");
            }
        } else {
            log_error("Failed to read SENT data.");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

