#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x0F
#define TEMPERATURE_REG 0x00
#define DEVICE_ID_VALUE 0x0117
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the TMP117 device ID
int verify_device_id() {
    int device_id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Error: Incorrect device ID. Expected 0x%04X, got 0x%04X\n", DEVICE_ID_VALUE, device_id);
        return -1;
    }

    printf("Device ID verified: 0x%04X\n", device_id);
    return 0;
}

// Read the temperature from the TMP117
float read_temperature() {
    int raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temperature);
        return -1000.0; // Indicate an error
    }

    // Convert raw temperature to Celsius
    float temperature = (float)((int16_t)raw_temperature) * 0.0078125;
    return temperature;
}

// Write the temperature to the binary file
int write_temperature_to_file(float temperature) {
    // Convert float to little-endian bytes
    uint32_t temp_bytes = *((uint32_t*)&temperature);

    size_t bytes_written = fwrite(&temp_bytes, sizeof(uint32_t), 1, fp);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        printf("I2C connection closed.\n");
    }
    if (fp != NULL) {
        fclose(fp);
        printf("File closed.\n");
    }
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open the file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping write.\n");
        }

        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

