#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define DATA_LENGTH 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SLEEP_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
SensorData convert_data(const uint8_t *data);
int log_data(const SensorData *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(const uint8_t *data) {
    SensorData sensor_data;
    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    sensor_data.humidity = -6.0 + 125.0 * (raw_hum / 65535.0);
    if (sensor_data.humidity < 0.0) sensor_data.humidity = 0.0;
    if (sensor_data.humidity > 100.0) sensor_data.humidity = 100.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(const SensorData *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, data->temperature, data->humidity);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

