    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    // Send measurement command
    if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return 1;
    }

    // Wait for conversion (at least 8.5 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (bytes_read != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d bytes read\n", bytes_read);
        return 1;
    }

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    uint8_t sensor_data[DATA_LENGTH];
    SensorData converted_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data)) {
            fprintf(stderr, "Error reading sensor data, retrying in %d seconds...\n", SLEEP_INTERVAL);
            gpioDelay(SLEEP_INTERVAL * 1000000); // Sleep for SLEEP_INTERVAL seconds
            continue;
        }

        // Validate CRC
        if (!validate_crc(sensor_data, 3) || !validate_crc(sensor_data + 3, 3)) {
            fprintf(stderr, "CRC validation failed, retrying in %d seconds...\n", SLEEP_INTERVAL);
            gpioDelay(SLEEP_INTERVAL * 1000000); // Sleep for SLEEP_INTERVAL seconds
            continue;
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (log_data(&converted_data)) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", SLEEP_INTERVAL);
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

