#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
float read_temperature();
void store_temperature(float temperature);
void save_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert big-endian data to temperature
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Store temperature in the circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Save the temperature buffer to a file
void save_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }

    size_t bytes_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (bytes_written != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write all data to log file: %s\n", strerror(errno));
    }

    fclose(fp);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    save_buffer_to_file(); // Save buffer on exit
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            store_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        save_buffer_to_file(); // Save buffer after each sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

