#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 measurement command (normal power, clock stretching disabled)
#define SHTC3_MEASURE_CMD 0x7866

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Function prototypes
int init_i2c();
int read_shtc3(float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from SHTC3 sensor
int read_shtc3(float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    uint8_t cmd[2] = {(SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 12.4 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int16_t raw_temperature = (data[0] << 8) | data[1];
    int16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    // Validate temperature and humidity ranges
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Temperature or humidity out of range\n");
        return -1;
    }

    return 0;
