#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x00
#define TEMP_REG 0x01
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int reg, uint16_t *raw_value);
float convert_to_gauss(uint16_t raw_value);
float convert_to_celsius(uint16_t raw_value);
int log_data(float mag_gauss, float temp_celsius);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from a specific register
int read_sensor_data(int reg, uint16_t *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading sensor data from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw magnetic field value to Gauss
float convert_to_gauss(uint16_t raw_value) {
    return (float)raw_value * 0.1;
}

// Function to convert raw temperature value to Celsius
float convert_to_celsius(uint16_t raw_value) {
    return (float)raw_value * 0.01 - 25.0;
}

// Function to log data to a CSV file
int log_data(float mag_gauss, float temp_celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Check if the file is newly created and write the header
    struct stat st;
    if (stat(LOG_FILE, &st) == -1) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mag_gauss, temp_celsius);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t raw_mag, raw_temp;
    float mag_gauss, temp_celsius;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(MAG_REG, &raw_mag) == 0 && read_sensor_data(TEMP_REG, &raw_temp) == 0) {
            // Convert raw values to Gauss and Celsius
            mag_gauss = convert_to_gauss(raw_mag);
            temp_celsius = convert_to_celsius(raw_temp);

            // Log the data
            log_data(mag_gauss, temp_celsius);
        } else {
            // Log NaN values if sensor read fails
            log_data(NAN, NAN);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

