#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.log"

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
    int checksum;
} DHT11Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening error log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to read DHT11 data
int read_dht11(DHT11Data *data) {
    int bit_count = 0;
    int byte_index = 0;
    unsigned char data_bytes[5] = {0, 0, 0, 0, 0};
    unsigned int start_time, end_time, pulse_duration;

    // 1. Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18); // Minimum 18ms
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(20); // Added delay to allow the sensor to respond

    // 2. Switch to input mode
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // 3. Wait for sensor response (80us low, 80us high)
    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > 100) { // Timeout after 100us
            log_error("DHT11: Sensor response timeout (initial high).");
            return -1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_time > 100) { // Timeout after 100us
            log_error("DHT11: Sensor response timeout (initial low).");
            return -1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > 100) { // Timeout after 100us
            log_error("DHT11: Sensor response timeout (initial high).");
            return -1; // Timeout
        }
    }

    // 4. Read 40 bits of data
    for (int i = 0; i < 40; i++) {
        // Wait for the start of the bit (low pulse)
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - start_time > 100) { // Timeout after 100us
                log_error("DHT11: Data bit timeout (low pulse).");
                return -1; // Timeout
            }
        }

        // Measure the high pulse duration
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - start_time > 100) { // Timeout after 100us
                log_error("DHT11: Data bit timeout (high pulse).");
                return -1; // Timeout
            }
        }
        end_time = gpioTick();
        pulse_duration = end_time - start_time;

        // Determine bit value based on pulse duration
        if (pulse_duration > 40) { // Considered as '1' if duration > 40us
            data_bytes[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // 5. Validate checksum
    if ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) != data_bytes[4]) {
        log_error("DHT11: Checksum failure.");
        return -2; // Checksum failure
    }

    // 6. Store data
    data->humidity = data_bytes[0];
    data->temperature = data_bytes[2];
    data->checksum = data_bytes[4];

    return 0; // Success
}

// Function to log data to a file
void log_data(int humidity, int temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Humidity: %d%%, Temperature: %d°C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            humidity, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT11Data dht11_data;

    // Main loop
    while (!terminate) {
        int result = read_dht11(&dht11_data);

        if (result == 0) {
            log_data(dht11_data.humidity, dht11_data.temperature);
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "DHT11 read failed with error code: %d", result);
            log_error(error_message);
        }

        gpioDelay(2000); // Sample every 2 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

