#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65

// Register addresses
#define DEVICE_ID_REG 0x00
#define RED_DATA_REG 0x64
#define GREEN_DATA_REG 0x66
#define BLUE_DATA_REG 0x68

// I2C bus
#define I2C_BUS 1

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
void log_data(FILE *fp, float cct);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result;

    // Read red data
    result = i2cReadI2CBlockData(i2c_handle, RED_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading red data: %d\n", result);
        return -1;
    }
    *red = (uint16_t)((buf[1] << 8) | buf[0]);

    // Read green data
    result = i2cReadI2CBlockData(i2c_handle, GREEN_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading green data: %d\n", result);
        return -1;
    }
    *green = (uint16_t)((buf[1] << 8) | buf[0]);

    // Read blue data
    result = i2cReadI2CBlockData(i2c_handle, BLUE_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading blue data: %d\n", result);
        return -1;
    }
    *blue = (uint16_t)((buf[1] << 8) | buf[0]);

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;

    float X = -0.26666 * r + -0.63333 * g + 1.9 * b;
    float Y = 1.1 * r + -1.1 * g + -0.0 * b;
    float Z = -0.33333 * r + 0.33333 * g + 0.66666 * b;

    float xc = X / (X + Y + Z);
    float yc = Y / (X + Y + Z);

    float n = (xc - 0.3320) / (0.1858 - yc);

    float cct = 449.0 * n * n + 3525.0 * n + 6823.3;

    return cct;
}

// Function to log data to CSV file
void log_data(FILE *fp, float cct) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, cct);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = init_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = init_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify device ID for both sensors
    char device_id;
    int result = i2cReadI2CBlockData(i2c_handle1, DEVICE_ID_REG, &device_id, 1);
    if (result != 1 || device_id != 0x2A) {
        fprintf(stderr, "Sensor 1 device ID verification failed: 0x%02X\n", device_id);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    result = i2cReadI2CBlockData(i2c_handle2, DEVICE_ID_REG, &device_id, 1);
    if (result != 1 || device_id != 0x2A) {
        fprintf(stderr, "Sensor 2 device ID verification failed: 0x%02X\n", device_id);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        sensor_data_t sensor1_data, sensor2_data;
        float cct1, cct2, avg_cct;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data.red, &sensor1_data.green, &sensor1_data.blue) == 0) {
            cct1 = calculate_cct(sensor1_data.red, sensor1_data.green, sensor1_data.blue);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &sensor2_data.red, &sensor2_data.green, &sensor2_data.blue) == 0) {
            cct2 = calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Calculate average CCT, handling errors
        if (cct1 >= 0.0 && cct2 >= 0.0) {
            avg_cct = (cct1 + cct2) / 2.0;
            log_data(log_file, avg_cct);
        } else {
            fprintf(stderr, "Error: Could not read data from one or more sensors. Skipping log entry.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

