#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(int i2c_handle);
float convert_temperature(int raw_temp);
void update_circular_buffer(float temperature);
float calculate_average_temperature();
void control_fan(float average_temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from LM75B
int read_temperature(int i2c_handle) {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return raw_temp;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int raw_temp) {
    // Extract the 9-bit temperature value (ignoring the 0th bit)
    int temp_value = (raw_temp >> 7) & 0x1FF; // Shift right by 7 bits and mask to get 9 bits

    // Check if the temperature is negative (MSB is set)
    if (temp_value & 0x100) {
        // Convert to signed 9-bit integer
        temp_value |= 0xFE00; // Sign extend to 16 bits
    }

    // Convert to Celsius (0.5 degree resolution)
    return (float)temp_value * 0.5;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average temperature
float calculate_average_temperature() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off the fan
    gpioWrite(FAN_GPIO, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        int raw_temp = read_temperature(i2c_handle);
        if (raw_temp >= 0) {
            // Convert temperature
            float temperature = convert_temperature(raw_temp);

            // Update circular buffer
            update_circular_buffer(temperature);

            // Calculate average temperature
            float average_temperature = calculate_average_temperature();

            // Control fan
            control_fan(average_temperature);

            printf("Temperature: %.2f °C, Average Temperature: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping this cycle.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

