#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define LOG_FILE "airflow.log"
#define PRESSURE_THRESHOLD 5.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_command(int handle, uint16_t command);
int i2c_read_data(int handle, char *buffer, int count);
uint8_t crc8(const char *data, int len);
int validate_crc(const char *data, int len);
int read_sensor_data(int handle, float *pressure, float *temperature);
int log_data(const char *filename, float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == (uint8_t)data[len - 1]);
}

// I2C write command function
int i2c_write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// I2C read data function
int i2c_read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data function
int read_sensor_data(int handle, float *pressure, float *temperature) {
    char buffer[9];
    int16_t raw_pressure, raw_temperature;
    uint16_t status;

    // Send continuous measurement command
    if (i2c_write_command(handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        fprintf(stderr, "Failed to send measurement command.\n");
        return -1;
    }

    // Wait for the first measurement (45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data
    if (i2c_read_data(handle, buffer, 9) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    // Validate CRC for pressure
    if (!validate_crc(buffer, 3)) {
        fprintf(stderr, "Pressure CRC validation failed.\n");
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(buffer + 3, 3)) {
        fprintf(stderr, "Temperature CRC validation failed.\n");
        return -1;
    }

    // Validate CRC for status
    if (!validate_crc(buffer + 6, 3)) {
        fprintf(stderr, "Status CRC validation failed.\n");
        return -1;
    }

    // Extract raw values
    raw_pressure = (buffer[0] << 8) | buffer[1];
    raw_temperature = (buffer[3] << 8) | buffer[4];
    status = (buffer[6] << 8) | buffer[7];

    // Convert to physical values
    *pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    *temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE;

    return 0;
}

// Log data function
int log_data(const char *filename, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_data(LOG_FILE, pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "Warning: Differential pressure exceeds threshold (%.2f Pa > %.2f Pa)\n", pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 1 second.\n");
        }

        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

