#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_REG 0x00
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_SCALE 0.0625

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
int control_led(int gpio_pin, int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from STTS2004
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB, right-shift by 4 bits
    int16_t raw_temp = ((int16_t)buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 4;

    // Convert to Celsius
    *temperature = raw_temp * TEMP_SCALE;

    return 0;
}

// Function to control the LED
int control_led(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    float temperature;
    int led_state = 0; // 0 = off, 1 = on

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
