#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define DATA_LENGTH 9
#define SCALE_FACTOR_OFFSET 6
#define SCALE_FACTOR_SIZE 2
#define PRESSURE_SIZE 2
#define TEMPERATURE_SIZE 2
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int length);
uint8_t calculate_crc(uint8_t data[], int length);
int validate_crc(uint8_t data[], int length, uint8_t crc);
int parse_sensor_data(uint8_t data[], sensor_data_t *sensor_data);
int log_data(sensor_data_t sensor_data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint8_t data[], int length, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, length);
    return (calculated_crc == crc);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_sensor_data(int handle, uint8_t *data, int length) {
    int result = i2cReadDevice(handle, (char *)data, length);
    if (result != length) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Parse sensor data
int parse_sensor_data(uint8_t data[], sensor_data_t *sensor_data) {
    // Extract raw pressure and temperature
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Extract scale factor
    int16_t scale_factor = (data[6] << 8) | data[7];

    // Validate CRC for pressure
    if (!validate_crc(data, PRESSURE_SIZE, data[2])) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(data + 3, TEMPERATURE_SIZE, data[5])) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }

    // Convert raw data to physical units
    sensor_data->differential_pressure = (float)raw_pressure / scale_factor;
    sensor_data->temperature = (float)raw_temperature / 200.0;

    return 0;
}

// Log data to file
int log_data(sensor_data_t sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa, %.2f °C\n", timestamp, sensor_data.differential_pressure, sensor_data.temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    uint8_t sensor_data[DATA_LENGTH];
    sensor_data_t parsed_data;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data, DATA_LENGTH) == 0) {
            // Parse sensor data
            if (parse_sensor_data(sensor_data, &parsed_data) == 0) {
                // Log data
                log_data(parsed_data);
            } else {
                fprintf(stderr, "Error parsing sensor data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 45 ms
        gpioDelay(45000); // Delay in microseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

