#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY 0xF5
#define MEASURE_TEMPERATURE 0xF3
#define READ_PREVIOUS_TEMP 0xE0
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert data
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Validate sensor presence (read firmware revision)
    char cmd = 0x84; // Firmware Revision command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for firmware check\n");
        i2cClose(i2c_handle);
        return 1;
    }
    gpioDelay(10); // Small delay after write

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading firmware revision from I2C device\n");
        i2cClose(i2c_handle);
        return 1;
    }

    // Basic check: firmware revision should be non-zero
    if (buffer[0] == 0 && buffer[1] == 0) {
        fprintf(stderr, "Sensor not responding or invalid firmware revision\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd;
    char buffer[2];
    int retries;

    // Measure Humidity
    cmd = MEASURE_HUMIDITY;
    for (retries = 0; retries < RETRY_COUNT; retries++) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) == 0) {
            gpioDelay(20); // Wait 20ms
