    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Configure HDC1080
    if (configure_hdc1080() != 0) {
        cleanup();
        return 1;
    }

    printf("HDC1080 sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_temp, raw_humidity;
        int retry = 0;

        // Trigger measurement and read data with retries
        while (retry < RETRY_COUNT) {
            if (trigger_measurement() == 0) {
                gpioDelay(20); // Wait for conversion
                if (read_sensor_data(&raw_temp, &raw_humidity) == 0) {
                    // Convert and log data
                    sensor_data_t data = convert_data(raw_temp, raw_humidity);
                    if (log_data(data) == 0) {
                        printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "Failed to log data, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Failed to read sensor data, retrying...\n");
                }
            } else {
                fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            }
            retry++;
            gpioDelay(100); // Wait before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

