#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// STS40 I2C address
#define STS40_ADDR 0x44

// STS40 single-shot high repeatability command
#define STS40_MEASURE_CMD_1 0x2C
#define STS40_MEASURE_CMD_2 0xE0

// CRC8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C file descriptor and log file pointer
int i2c_fd = -1;
FILE *log_file = NULL;

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
float read_temperature() {
    uint8_t cmd[2] = {STS40_MEASURE_CMD_1, STS40_MEASURE_CMD_2};
    uint8_t data[3];
    int ret;

    // Send measurement command
    ret = write(i2c_fd, cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Wait for conversion (at least 10 ms)
    usleep(10000);

    // Read 3 bytes of data
    ret = read(i2c_fd, data, 3);
    if (ret != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Validate CRC8 checksum
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC8 checksum mismatch: calculated 0x%02X, received 0x%02X\n", crc, data[2]);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_ticks = (data[0] << 8) | data[1];
    float temperature = -45.0 + 175.0 * (float)raw_ticks / 65535.0;

    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging.\n");
        }

        sleep(5);
    }

    return 0;
}

