// I2C write function
int i2c_write(int handle, uint16_t data) {
    char buf[2];
    buf[0] = (data >> 8) & 0xFF;
    buf[1] = data & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
