int i2c_read(int handle, char *buf, int count) {
    int result = i2cReadDevice(handle, buf, count);
    if (result != count) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Read SDP810 sensor data
int read_sdp810(int handle, float *pressure, float *temperature) {
    char buf[9];
    int16_t raw_pressure, raw_temperature;
    uint16_t scale_factor;

    // Send continuous measurement command
    if (i2c_write(handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
