    raw_temperature = (buf[3] << 8) | buf[4];
    scale_factor = (buf[6] << 8) | buf[7];

    // CRC validation
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC error\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Scale factor CRC error\n");
        return -1;
    }

