#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define START_MEASUREMENT_CMD 0x21B1
#define READ_MEASUREMENT_CMD 0xE000
#define STOP_MEASUREMENT_CMD 0x3F86
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static volatile sig_atomic_t running = 1;
static int i2c_handle;
static circular_buffer_t buffer;
static pthread_t logging_thread;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int read_sensor_data(int handle, float *co2, float *temperature, float *humidity);
void init_circular_buffer(circular_buffer_t *buffer);
int add_to_circular_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_circular_buffer(circular_buffer_t *buffer, sensor_data_t *data);
void *logging_thread_func(void *arg);
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        log_error("Failed to send command");
        return -1;
    }

    return 0;
}

// Function to read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        log_error("Failed to read data");
        return -1;
    }

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to read sensor data from the SCD40
int read_sensor_data(int handle, float *co2, float *temperature, float *humidity) {
    uint8_t data[9];

    if (send_command(handle, READ_MEASUREMENT_CMD) != 0) {
        return -1;
    }

    gpioDelay(1); // Wait for data to be ready

    if (read_data(handle, data, 9) != 0) {
        return -1;
    }

    // Validate CRC for each value
    if (!validate_crc(data, 2, data[2])) {
        log_error("CO2 CRC validation failed");
        return -1;
    }
    if (!validate_crc(data + 3, 2, data[5])) {
        log_error("Temperature CRC validation failed");
        return -1;
    }
    if (!validate_crc(data + 6, 2, data[8])) {
        log_error("Humidity CRC validation failed");
        return -1;
    }

    // Convert raw data to physical values
    uint16_t raw_co2 = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t raw_humidity = (data[6] << 8) | data[7];

    *co2 = (float)raw_co2;
    *temperature = -45 + 175 * (float)raw_temperature / 65535;
    *humidity = 100 * (float)raw_humidity / 65535;

    return 0;
}

// Function to initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Function to add data to the circular buffer
int add_to_circular_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Function to get data from the circular buffer
int get_from_circular_buffer(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Function for the logging thread
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer.mutex);
        int count = buffer.count;
        sensor_data_t data[BUFFER_SIZE];
        for (int i = 0; i < count; i++) {
            sensor_data_t temp_data;
            get_from_circular_buffer(&buffer, &temp_data);
            data[i] = temp_data;
        }
        pthread_mutex_unlock(&buffer.mutex);

        // Create the log directory if it doesn't exist
        struct stat st = {0};
        if (stat(LOG_DIR, &st) == -1) {
            if (mkdir(LOG_DIR, 0777) == -1) {
                log_error("Failed to create log directory");
                continue; // Skip logging this iteration
            }
        }

        // Generate timestamped filename
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char filename[256];
        strftime(filename, sizeof(filename), LOG_DIR "scd40_data_%Y%m%d_%H%M%S.csv", tstruct);

        // Open the CSV file for writing
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            log_error("Failed to open CSV file for writing");
            continue; // Skip logging this iteration
        }

        // Write the header row
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

        // Write the data to the CSV file
        for (int i = 0; i < count; i++) {
            struct tm *tstruct_data = localtime(&data[i].timestamp);
            char timestamp_str[64];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tstruct_data);
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp_str, data[i].co2, data[i].temperature, data[i].humidity);
        }

        // Close the CSV file
        fclose(fp);
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t now = time(NULL);
