#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x63
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define HIGH_ACCURACY_COMMAND 0x4011
#define HIGH_PRESSURE_THRESHOLD 95000.0 // Pa
#define HIGH_ALTITUDE_THRESHOLD 90000.0 // Pa
#define LOG_FILE "sensor_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration coefficients
static uint16_t c0, c1, c00, c10;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
uint8_t calculate_crc(uint8_t *data, int len);
int verify_crc(uint8_t *data, int len, uint8_t crc);
int convert_data(uint8_t *data, float *pressure, float *temperature);
int control_led(struct gpiod_line *line, float pressure);
void signal_handler(int sig);
int log_data(float pressure, float temperature);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, data, len) != len) {
    perror("Failed to read data");
    return -1;
  }
  return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
  uint8_t buf[len + 1];
  buf[0] = reg;
  memcpy(buf + 1, data, len);
  if (write(fd, buf, len + 1) != len + 1) {
    perror("Failed to write data");
    return -1;
  }
  return 0;
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
  uint8_t data[8];
  if (i2c_read_bytes(fd, 0x66, data, 8) != 0) {
    fprintf(stderr, "Failed to read calibration coefficients\n");
    return -1;
  }

  c0 = (data[0] << 8) | data[1];
  c1 = (data[2] << 8) | data[3];
  c00 = (data[4] << 8) | data[5];
  c10 = (data[6] << 8) | data[7];

  return 0;
}

// Trigger a measurement
int trigger_measurement(int fd) {
  uint8_t data[2];
  data[0] = (HIGH_ACCURACY_COMMAND >> 8) & 0xFF;
  data[1] = HIGH_ACCURACY_COMMAND & 0xFF;
  if (i2c_write_bytes(fd, 0x00, data, 2) != 0) {
    fprintf(stderr, "Failed to trigger measurement\n");
    return -1;
  }
  return 0;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *data) {
  if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
    fprintf(stderr, "Failed to read sensor data\n");
    return -1;
  }
  return 0;
}

// Calculate CRC
uint8_t calculate_crc(uint8_t *data, int len) {
  uint8_t crc = 0xFF;
  for (int i = 0; i < len; i++) {
    crc ^= data[i];
    for (int j = 0; j < 8; j++) {
      if (crc & 0x80) {
        crc = (crc << 1) ^ 0x31;
      } else {
        crc <<= 1;
      }
    }
  }
  return crc;
}

// Verify CRC
int verify_crc(uint8_t *data, int len, uint8_t crc) {
  uint8_t calculated_crc = calculate_crc(data, len);
  return (calculated_crc == crc);
}

// Convert raw data to pressure and temperature
int convert_data(uint8_t *data, float *pressure, float *temperature) {
  int32_t raw_pressure = (data[0] << 8) | data[1];
  int32_t raw_temperature = (data[3] << 8) | data[4];

  // Placeholder conversion formulas (replace with actual formulas from datasheet)
  *pressure = (float)raw_pressure; // Replace with actual conversion
  *temperature = (float)raw_temperature; // Replace with actual conversion

  return 0;
}

// Control the LED based on pressure
int control_led(struct gpiod_line *line, float pressure) {
  if (pressure < HIGH_PRESSURE_THRESHOLD) {
    // Blink at 5 Hz
    for (int i = 0; i < 5; i++) {
      if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO value");
        return -1;
      }
      usleep(100000); // 100 ms
      if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO value");
        return -1;
      }
      usleep(100000); // 100 ms
    }
  } else {
    // Blink at 1 Hz
    if (gpiod_line_set_value(line, 1) < 0) {
      perror("Failed to set GPIO value");
      return -1;
    }
    usleep(500000); // 500 ms
    if (gpiod_line_set_value(line, 0) < 0) {
      perror("Failed to set GPIO value");
      return -1;
    }
    usleep(500000); // 500 ms
  }
  return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, exiting...\n");
  terminate = 1;
}

// Log data to file
int log_data(float pressure, float temperature) {
  FILE *fp = fopen(LOG_FILE, "a");
  if (fp == NULL) {
    perror("Failed to open log file");
    return -1;
  }

  time_t t = time(NULL);
  struct tm tm = *localtime(&t);
  fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Pressure: %.2f Pa, Temperature: %.2f C\n",
          tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
          pressure, temperature);

  fclose(fp);
  return 0;
}

int main() {
  // Install signal handler
  signal(SIGINT, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Read calibration coefficients
  if (read_calibration_coefficients(i2c_fd) != 0) {
    close(i2c_fd);
    return 1;
  }

  // Open GPIO chip
  gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
  if (!gpio_chip) {
    perror("Failed to open GPIO chip");
    close(i2c_fd);
    return 1;
  }

  // Get GPIO line
  gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
  if (!gpio_line) {
    perror("Failed to get GPIO line");
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    return 1;
  }

  // Request GPIO line for output
  if (gpiod_line_request_output(gpio_line, "pressure_monitor", 0) < 0) {
    perror("Failed to request GPIO line for output");
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
