#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mlx90614(int handle, uint8_t reg, uint16_t *value);
float convert_to_celsius(uint16_t raw_temp);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);

// Function to read data from the MLX90614 sensor with retries
int read_mlx90614(int handle, uint8_t reg, uint16_t *value) {
    int result, i;
    char buf[2];

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (result == 2) {
            *value = (buf[1] << 8) | buf[0];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "I2C read failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return raw_temp * 0.02 - 273.15;
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control the cooling fan with hysteresis
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint16_t raw_ambient_temp, raw_object_temp;
    float ambient_temp, object_temp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ambient temperature
        if (read_mlx90614(i2c_handle, AMBIENT_TEMP_REG, &raw_ambient_temp) == 0) {
            ambient_temp = convert_to_celsius(raw_ambient_temp);
        } else {
            ambient_temp = -999.0; // Indicate error
        }

        // Read object temperature
        if (read_mlx90614(i2c_handle, OBJECT_TEMP_REG, &raw_object_temp) == 0) {
            object_temp = convert_to_celsius(raw_object_temp);
        } else {
            object_temp = -999.0; // Indicate error
        }

        // Log temperature data
        if (ambient_temp != -999.0 && object_temp != -999.0) {
            log_temperature(ambient_temp, object_temp);
        } else {
            fprintf(stderr, "Error: Invalid temperature reading, skipping log entry.\n");
        }

        // Control the fan
        control_fan(object_temp);

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
    fclose(log_file);

    return 0;
}

