#include <time.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Global variables for I2C handle and socket file descriptor
int i2c_handle = -1;
int server_fd = -1;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
int handle_client(int client_fd);
void signal_handler(int signum);
int setup_server_socket(int port);

// Function to read data from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(10000); // Wait 10 ms

        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_T = (buf[0] << 8) | buf[1];
        unsigned int raw_RH = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * ((float)raw_T / 65535.0);
        *humidity = -6.0 + 125.0 * ((float)raw_RH / 65535.0);

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

