    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_temperature(i2c_handle, &temperature);
        if (result == 0) {
            if (log_temperature(CSV_FILE, temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping log.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

