#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG_REG 0x0E
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Set CONFIG register (0x0F) to disable heater and set resolution to 14-bit
    char config_data[2] = {0x0F, 0x00}; // Heater disabled, 14-bit resolution
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement() {
    char trigger_data[2] = {MEASUREMENT_CONFIG_REG, 0x01}; // Trigger measurement
    int result = i2cWriteDevice(i2c_handle, trigger_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read raw temperature and humidity data from the sensor
int read_raw_data(unsigned short *temperature, unsigned short *humidity) {
    char data[4];
    int result = i2cReadDevice(i2c_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    *humidity = (data[2] << 8) | data[3];

    return 0;
}

// Function to convert raw data to temperature and humidity values
void convert_data(unsigned short raw_temperature, unsigned short raw_humidity, float *temperature, float *humidity) {
    *temperature = (float)raw_temperature / 65536.0 * 165.0 - 40.0;
    *humidity = (float)raw_humidity / 65536.0 * 100.0;
}

// Function to log temperature and humidity values to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HDC2010 sensor
    if (init_hdc2010() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Wait for measurement to complete (polling with timeout)
        int timeout = 500; // 500 ms timeout
        while (timeout > 0) {
            char config_data[1] = {MEASUREMENT_CONFIG_REG};
            char result_data[1];
            int result = i2cWriteDevice(i2c_handle, config_data, 1);
            if (result != 0) {
                fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register for polling: %d\n", result);
                break;
            }
            result = i2cReadDevice(i2c_handle, result_data, 1);
            if (result != 1) {
                fprintf(stderr, "Error reading MEASUREMENT_CONFIG register for polling: %d\n", result);
                break;
            }

            if ((result_data[0] & 0x01) == 0) {
                break; // Measurement complete
            }
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for measurement to complete\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read raw data
        unsigned short raw_temperature, raw_humidity;
        if (read_raw_data(&raw_temperature, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        float temperature, humidity;
        convert_data(raw_temperature, raw_humidity, &temperature, &humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

