            }
            result = i2cReadDevice(i2c_handle, result_data, 1);
            if (result != 1) {
                fprintf(stderr, "Error reading MEASUREMENT_CONFIG register for polling: %d\n", result);
                break;
            }

            if ((result_data[0] & 0x01) == 0) {
                break; // Measurement complete
            }
            gpioDelay(1); // Wait 1 ms
            timeout--;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout waiting for measurement to complete\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read raw data
        unsigned short raw_temperature, raw_humidity;
        if (read_raw_data(&raw_temperature, &raw_humidity) != 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        float temperature, humidity;
        convert_data(raw_temperature, raw_humidity, &temperature, &humidity);

        // Log data
        log_data(temperature, humidity);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

