#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define MEASUREMENT_DELAY_MS 45
#define LOGGING_INTERVAL_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        char command[2] = {(CONTINUOUS_MEASUREMENT_COMMAND >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_COMMAND & 0xFF};
        int write_result = i2cWriteDevice(i2c_handle, command, 2);
        if (write_result != 0) {
            fprintf(stderr, "I2C write failed: %d\n", write_result);
            break; // Exit loop on error
        }

        // Wait for measurement to complete
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

        // Read 6 bytes of data
        char data[6];
        int read_result = i2cReadDevice(i2c_handle, data, 6);
        if (read_result != 6) {
            fprintf(stderr, "I2C read failed: %d\n", read_result);
            break; // Exit loop on error
        }

        // Extract pressure and temperature values
        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temperature = (data[3] << 8) | data[4];

        // CRC check for pressure
        unsigned char pressure_data[2] = {data[0], data[1]};
        unsigned char pressure_crc = crc8(pressure_data, 2);
        if (pressure_crc != data[2]) {
            fprintf(stderr, "Pressure CRC check failed\n");
            continue; // Skip to next iteration
        }

        // CRC check for temperature
        unsigned char temperature_data[2] = {data[3], data[4]};
        unsigned char temperature_crc = crc8(temperature_data, 2);
        if (temperature_crc != data[5]) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue; // Skip to next iteration
        }

        // Log raw values
        printf("Raw Pressure: %d, Raw Temperature: %d\n", raw_pressure, raw_temperature);

        // Wait before next reading
        gpioDelay(LOGGING_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

