#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <gpiod.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define RELAY_GPIO 17
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_LENGTH 100
#define MAX_LINE_LENGTH 100

// Global variables
static int spi_handle_0 = -1;
static int spi_handle_1 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// PID parameters
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;
double integral = 0.0;
double previous_error = 0.0;

// Target temperature profile
double target_temperatures[MAX_PROFILE_LENGTH];
int profile_length = 0;
int current_profile_index = 0;

// Function prototypes
int spi_read_max6675(int spi_channel, double *temperature);
int gpio_set_relay_duty_cycle(int gpio_pin, double duty_cycle);
int log_data(FILE *fp, double temp1, double temp2, double duty_cycle);
int load_profile(const char *filename);
double calculate_pid(double setpoint, double actual_temperature);
void signal_handler(int sig);
int initialize();
void cleanup();

// Function to read temperature from MAX6675 via SPI
int spi_read_max6675(int spi_channel, double *temperature) {
    int handle;
    unsigned char buffer[2];
    int status;

    if (spi_channel == SPI_CHANNEL_0) {
        handle = spi_handle_0;
    } else if (spi_channel == SPI_CHANNEL_1) {
        handle = spi_handle_1;
    } else {
        fprintf(stderr, "Error: Invalid SPI channel: %d\n", spi_channel);
        return -1;
    }

    status = spiXfer(handle, buffer, buffer, 2);
    if (status != 2) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %s\n", spi_channel, strerror(errno));
        return -1;
    }

    // Check for open circuit fault
    if (buffer[1] & 0x04) {
        fprintf(stderr, "Error: MAX6675 open circuit fault (channel %d)\n", spi_channel);
        return -1;
    }

    // Extract temperature data
    int raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to set the solid-state relay duty cycle using PWM
int gpio_set_relay_duty_cycle(int gpio_pin, double duty_cycle) {
    if (duty_cycle < 0.0 || duty_cycle > 1.0) {
        fprintf(stderr, "Error: Invalid duty cycle: %f\n", duty_cycle);
        return -1;
    }

    int pulse_width = (int)(duty_cycle * 1000000.0 / PWM_FREQUENCY); // Calculate pulse width in microseconds
    gpioPWM(gpio_pin, pulse_width); // Set PWM duty cycle

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, double temp1, double temp2, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temp1, temp2, duty_cycle);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Function to load the target temperature profile from a file
int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open profile file: %s\n", filename);
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < MAX_PROFILE_LENGTH) {
        double time_seconds, target_temp_celsius;
        if (sscanf(line, "%lf,%lf", &time_seconds, &target_temp_celsius) == 2) {
            target_temperatures[i] = target_temp_celsius;
            i++;
        } else {
            fprintf(stderr, "Warning: Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    profile_length = i;

    if (profile_length == 0) {
        fprintf(stderr, "Error: Profile file is empty or contains no valid data.\n");
        return -1;
    }

    return 0;
}

// Function to calculate the PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    // Anti-windup
    if (integral > 100) integral = 100;
    if (integral < -100) integral = -100;

    double derivative = error - previous_error;

    double output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Clamp the output to the range 0.0 to 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(RELAY_GPIO, 1000000); // Set PWM range to 1000000 for finer control

    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name failed: %s\n", strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Error: gpiod_chip_get_line failed: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output failed: %s\n", strerror(errno));
        return -1;
    }

    // Open SPI devices
    spi_handle_0 = spiOpen(SPI_CHANNEL_0, 1000000, 0); // SPI0 CE0, 1MHz, mode 0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error: spiOpen (CE0) failed: %s\n", strerror(errno));
        return -1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, 1000000, 0); // SPI0 CE1, 1MHz, mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error: spiOpen (CE1) failed: %s\n", strerror(errno));
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", LOG_FILE);
        return -1;
    }

    // Load temperature profile
    if (load_profile(PROFILE_FILE) != 0) {
        fprintf(stderr, "Error: Failed to load temperature profile.\n");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI devices
    if (spi_handle_0 >= 0) spiClose(spi_handle_0);
    if (spi_handle_1 >= 0) spiClose(spi_handle_1);

    // Release GPIO resources
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    double temperature1, temperature2, duty_cycle;
    double setpoint;

    // Main loop
    while (!terminate) {
        // Read temperatures from thermocouples
        if (spi_read_max6675(SPI_CHANNEL_0, &temperature1) != 0) {
            fprintf(stderr, "Error reading temperature from channel 0, using previous value.\n");
        }
        if (spi_read_max6675(SPI_CHANNEL_1, &temperature2) != 0) {
            fprintf(stderr, "Error reading temperature from channel 1, using previous value.\n");
        }

        // Determine the current setpoint from the profile
        if (current_profile_index < profile_length) {
            setpoint = target_temperatures[current_profile_index];
        } else {
            setpoint = target_temperatures[profile_length - 1]; // Hold at the last temperature
        }

        // Calculate the average temperature
        double average_temperature = (temperature1 + temperature2) / 2.0;

        // Calculate PID output
        duty_cycle = calculate_pid(setpoint, average_temperature);

        // Set relay duty cycle
        if (gpio_set_relay_duty_cycle(RELAY_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error setting relay duty cycle.\n");
        }

        // Log data
        if (log_data(log_file, temperature1, temperature2, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Move to the next setpoint if the current one is reached (within a tolerance)
        if (current_profile_index < profile_length - 1 && fabs(average_temperature - setpoint) < 1.0) {
            current_profile_index++;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

