// CRC-8 calculation (simplified for demonstration)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07; // Example polynomial
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from a DS18B20 sensor
float read_temperature(const char *sensor_id) {
