    crc_data[0] = 0xAA; // Example CRC data
    crc_data[1] = 0xBB;

    if (crc8(crc_data, 2) != 0) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return NAN;
    }

    // Extract temperature from line2 (example, adjust based on actual format)
    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in sensor %s\n", sensor_id);
        return NAN;
    }

    long temperature_milli_celsius = strtol(temp_str + 2, NULL, 10);
    return (float)temperature_milli_celsius / 1000.0;
}

// Function to calculate the average temperature
float calculate_average_temperature(float temperatures[], int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (!isnan(temperatures[i])) {
            sum += temperatures[i];
            valid_count++;
        }
    }
    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return NAN; // Return NaN if no valid readings
    }
