#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_trigger_measurement();
int aht20_read_data(uint8_t *data);
float calculate_humidity(const uint8_t *data);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// AHT20 initialization function
int aht20_init() {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    int result, retries = 3;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)init_cmd, sizeof(init_cmd));
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 initialization failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "AHT20 initialization failed after multiple retries.\n");
    return -1; // Failure
}

// AHT20 trigger measurement function
int aht20_trigger_measurement() {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    int result, retries = 3;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)trigger_cmd, sizeof(trigger_cmd));
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 trigger measurement failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "AHT20 trigger measurement failed after multiple retries.\n");
    return -1; // Failure
}

// AHT20 read data function
int aht20_read_data(uint8_t *data) {
    int result, retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "AHT20 read data failed (attempt %d): %d\n", 4 - retries, result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }
    fprintf(stderr, "AHT20 read data failed after multiple retries.\n");
    return -1; // Failure
}

// Humidity calculation function
float calculate_humidity(const uint8_t *data) {
    // Check status bit (bit 7 of the first byte)
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 sensor is busy or not calibrated.\n");
        return -1.0; // Indicate error
    }

    uint32_t humidity_data = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = ((float)humidity_data / 0x100000) * 100;
    return humidity;
}

// Dehumidifier control function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

// Data logging function
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set dehumidifier GPIO as output
    gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT);
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Initially turn off the dehumidifier

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float humidity;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (aht20_trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger AHT20 measurement\n");
        } else {
            gpioDelay(80000); // Wait 80 ms

            // Read data
            if (aht20_read_data(data) == 0) {
                // Calculate humidity
                humidity = calculate_humidity(data);

                if (humidity >= 0) { // Check for valid humidity reading
                    // Log data
                    log_data(humidity);

                    // Control dehumidifier
                    control_dehumidifier(humidity);
                } else {
                    fprintf(stderr, "Failed to calculate humidity\n");
                }
            } else {
                fprintf(stderr, "Failed to read AHT20 data\n");
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000000); // Wait for the next measurement interval
    }

    // Cleanup
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

