#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080        // Replace with your server port
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int socket_fd = -1;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int address);
int i2c_write_byte(int fd, unsigned char data);
int i2c_read_bytes(int fd, unsigned char *data, int len);
unsigned char calculate_crc(const unsigned char *data, int len);
int read_humidity(int fd, float *humidity);
int read_temperature(int fd, float *temperature);
int post_humidity(float humidity);
void signal_handler(int sig);
void cleanup();

// I2C functions
int i2c_open(const char *bus) {
  int fd = open(bus, O_RDWR);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open I2C bus %s: %s", bus, strerror(errno));
    return -1;
  }
  return fd;
}

int i2c_set_slave_address(int fd, int address) {
  if (ioctl(fd, I2C_SLAVE, address) < 0) {
    syslog(LOG_ERR, "Failed to set I2C slave address 0x%02x: %s", address, strerror(errno));
    return -1;
  }
  return 0;
}

int i2c_write_byte(int fd, unsigned char data) {
  if (write(fd, &data, 1) != 1) {
    syslog(LOG_ERR, "Failed to write byte 0x%02x: %s", data, strerror(errno));
    return -1;
  }
  return 0;
}

int i2c_read_bytes(int fd, unsigned char *data, int len) {
  if (read(fd, data, len) != len) {
    syslog(LOG_ERR, "Failed to read %d bytes: %s", len, strerror(errno));
    return -1;
  }
  return 0;
}

// CRC calculation
unsigned char calculate_crc(const unsigned char *data, int len) {
  unsigned int polynomial = 0x988000; // x^8 + x^5 + x^4 + x^0
  unsigned int crc = 0;
  unsigned char byte;

  for (int i = 0; i < len; i++) {
    byte = data[i];
    crc ^= (byte << 8);
    for (int j = 0; j < 8; j++) {
      if (crc & 0x800000) {
        crc = (crc << 1) ^ polynomial;
      } else {
        crc <<= 1;
      }
    }
  }
  return (unsigned char)(crc >> 16);
}

// Sensor reading functions
int read_humidity(int fd, float *humidity) {
  unsigned char data[3];
  int retries = RETRY_COUNT;

  while (retries > 0) {
    if (i2c_write_byte(fd, TRIGGER_HUMID_MEASURE) < 0) {
      syslog(LOG_ERR, "Failed to trigger humidity measurement");
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }
    usleep(50000); // Wait for measurement (datasheet says 25ms max)

    if (i2c_read_bytes(fd, data, 3) < 0) {
      syslog(LOG_ERR, "Failed to read humidity data");
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    unsigned char crc = calculate_crc(data, 2);
    if (crc != data[2]) {
      syslog(LOG_ERR, "CRC mismatch for humidity data: calculated 0x%02x, received 0x%02x", crc, data[2]);
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    unsigned int raw_humidity = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;
    return 0; // Success
  }

  syslog(LOG_ERR, "Failed to read humidity after multiple retries");
  return -1; // Failure
}

int read_temperature(int fd, float *temperature) {
  unsigned char data[3];
  int retries = RETRY_COUNT;

  while (retries > 0) {
    if (i2c_write_byte(fd, TRIGGER_TEMP_MEASURE) < 0) {
      syslog(LOG_ERR, "Failed to trigger temperature measurement");
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }
    usleep(50000); // Wait for measurement (datasheet says 25ms max)

    if (i2c_read_bytes(fd, data, 3) < 0) {
      syslog(LOG_ERR, "Failed to read temperature data");
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    unsigned char crc = calculate_crc(data, 2);
    if (crc != data[2]) {
      syslog(LOG_ERR, "CRC mismatch for temperature data: calculated 0x%02x, received 0x%02x", crc, data[2]);
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    unsigned int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -46.85 + 175.72 * (raw_temperature / 65536.0);
    return 0; // Success
  }

  syslog(LOG_ERR, "Failed to read temperature after multiple retries");
  return -1; // Failure
}

// HTTP POST function
int post_humidity(float humidity) {
  struct sockaddr_in server_addr;
  char json_data[100];
  char message[200];
  int retries = RETRY_COUNT;

  snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

  while (retries > 0) {
    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
      syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
      syslog(LOG_ERR, "Invalid address/ Address not supported: %s", SERVER_IP);
      close(socket_fd);
      socket_fd = -1;
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    // Connect to server
    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
      syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
      close(socket_fd);
      socket_fd = -1;
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    // Prepare HTTP POST message
    snprintf(message, sizeof(message), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %ld\r\n\r\n%s", API_ENDPOINT, SERVER_IP, strlen(json_data), json_data);

    // Send data
    if (send(socket_fd, message, strlen(message), 0) < 0) {
      syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
      close(socket_fd);
      socket_fd = -1;
      retries--;
      sleep(RETRY_DELAY);
      continue;
    }

    // Receive response (basic check)
    char buffer[1024];
    ssize_t bytes_received = recv(socket_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
      buffer[bytes_received] = '\0';
      syslog(LOG_INFO, "Received response: %s", buffer);
      if (strstr(buffer, "200 OK") != NULL) {
        syslog(LOG_INFO, "Humidity data posted successfully");
        close(socket_fd);
        socket_fd = -1;
        return 0; // Success
      } else {
        syslog(LOG_ERR, "HTTP request failed: %s", buffer);
      }
    } else {
      syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
    }

    close(socket_fd);
    socket_fd = -1;
    retries--;
    sleep(RETRY_DELAY);
  }

  syslog(LOG_ERR, "Failed to post humidity data after multiple retries");
  return -1; // Failure
}

// Signal handler
void signal_handler(int sig) {
  syslog(LOG_INFO, "Signal received: %d. Terminating...", sig);
  terminate = 1;
}

// Cleanup function
void cleanup() {
  syslog(LOG_INFO, "Cleaning up...");
  if (i2c_fd != -1) {
    close(i2c_fd);
    i2c_fd = -1;
  }
  if (socket_fd != -1) {
    close(socket_fd);
    socket_fd = -1;
  }
  closelog();
  exit(0);
}

int main() {
  // Initialize syslog
  openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

  // Set signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = i2c_open(I2C_BUS);
  if (i2c_fd < 0) {
    syslog(LOG_ERR, "Failed to open I2C bus. Exiting.");
    cleanup();
    return 1;
  }

  // Set I2C slave address
  if (i2c_set_slave_address(i2c_fd, HTU21D_ADDR) < 0) {
    syslog(LOG_ERR, "Failed to set I2C slave address. Exiting.");
    cleanup();
    return 1;
  }

  float humidity, temperature;

  while (!terminate) {
    // Read humidity
    if (read_humidity(i2c_fd, &humidity) == 0) {
      syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

      // Read temperature
      if (read_temperature(i2c_fd, &temperature) == 0) {
        syslog(LOG_INFO, "Temperature: %.2f°C", temperature);

        // Post humidity data
        if (post_humidity(humidity) != 0) {
          syslog(LOG_ERR, "Failed to post humidity data");
        }
      } else {
        syslog(LOG_ERR, "Failed to read temperature");
      }
    } else {
      syslog(LOG_ERR, "Failed to read humidity");
    }

    sleep(60); // Wait 60 seconds
  }

  cleanup();
  return 0;
}

