#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define AHT20_ADDR 0x38
#define AHT20_INIT_CMD1 0xBE
#define AHT20_INIT_CMD2 0x08
#define AHT20_INIT_CMD3 0x00
#define AHT20_MEASURE_CMD1 0xAC
#define AHT20_MEASURE_CMD2 0x33
#define AHT20_MEASURE_CMD3 0x00
#define PIR_GPIO_CHIP "gpiochip4"
#define PIR_GPIO_LINE 17
#define I2C_DEVICE "/dev/i2c-1"
#define CSV_FILE_PATH "/home/pi/temperature_log.csv"
#define MAX_RETRIES 3
#define RETRY_BACKOFF_MS 10

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int init_gpio(const char *chip, int line);
int init_aht20(int fd);
float read_temperature(int fd);
float read_humidity(int fd);
int read_motion(struct gpiod_line *line);
int log_data(FILE *fp, float temperature, float humidity, int motion);
void signal_handler(int sig);
void cleanup(void);

// I2C helper functions
int i2c_write(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len);
int i2c_read(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len);

// Function to initialize I2C
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Function to initialize GPIO
int init_gpio(const char *chip, int line) {
    struct gpiod_chip *chip_p = gpiod_chip_open_by_name(chip);
    if (!chip_p) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_p = gpiod_chip_get_line(chip_p, line);
    if (!line_p) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_p);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line_p, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip_p);
        gpiod_line_release(line_p);
        return -1;
    }

    return 0;
}

// Function to initialize AHT20 sensor
int init_aht20(int fd) {
    unsigned char init_cmd[] = {AHT20_INIT_CMD1, AHT20_INIT_CMD2, AHT20_INIT_CMD3};
    if (i2c_write(fd, AHT20_ADDR, 0, init_cmd, sizeof(init_cmd)) < 0) {
        fprintf(stderr, "Error initializing AHT20 sensor\n");
        return -1;
    }
    usleep(10000); // Wait for initialization to complete
    return 0;
}

// Function to read temperature from TMP117 sensor
float read_temperature(int fd) {
    unsigned char data[2];
    if (i2c_read(fd, TMP117_ADDR, TMP117_TEMP_REG, data, sizeof(data)) < 0) {
        fprintf(stderr, "Error reading temperature from TMP117 sensor\n");
        return -1000.0; // Indicate error
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Function to read humidity from AHT20 sensor
float read_humidity(int fd) {
    unsigned char measure_cmd[] = {AHT20_MEASURE_CMD1, AHT20_MEASURE_CMD2, AHT20_MEASURE_CMD3};
    unsigned char data[7];

    if (i2c_write(fd, AHT20_ADDR, 0, measure_cmd, sizeof(measure_cmd)) < 0) {
        fprintf(stderr, "Error sending measurement command to AHT20 sensor\n");
        return -1.0; // Indicate error
    }

    usleep(80000); // Wait for measurement to complete

    if (i2c_read(fd, AHT20_ADDR, 0, data, sizeof(data)) < 0) {
        fprintf(stderr, "Error reading data from AHT20 sensor\n");
        return -1.0; // Indicate error
    }

    // Check for busy bit
    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 sensor busy\n");
        return -1.0; // Indicate error
    }

    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = ((float)raw_humidity / 0x100000) * 100;
    return humidity;
}

