    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// I2C write function with retries
int i2c_write(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff
            continue;
        }

        unsigned char buf[len + 1];
        buf[0] = reg;
        memcpy(buf + 1, data, len);

        if (write(fd, buf, len + 1) == len + 1) {
            return 0; // Success
        } else {
            perror("Error writing to I2C device");
            retries++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff
        }
    }
    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read function with retries
int i2c_read(int fd, unsigned char addr, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            perror("Error setting I2C slave address");
            retries++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff
            continue;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Error writing register address");
            retries++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff
            continue;
        }

        if (read(fd, data, len) == len) {
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff
        }
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize AHT20 sensor
    if (init_aht20(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor. Continuing without humidity data.\n");
    }

    // Initialize GPIO
    if (init_gpio(PIR_GPIO_CHIP, PIR_GPIO_LINE) < 0) {
        fprintf(stderr, "Failed to initialize GPIO. Continuing without motion data.\n");
    } else {
        gpio_chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
        pir_line = gpiod_chip_get_line(gpio_chip, PIR_GPIO_LINE);
    }

    // Open log file
    log_file = fopen(CSV_FILE_PATH, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_fd);
        float humidity = read_humidity(i2c_fd);
        int motion = 0;
        if (pir_line) {
            motion = read_motion(pir_line);
        }

        if (temperature > -999.0) {
            log_data(log_file, temperature, humidity, motion);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log entry.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

