#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *rain_sensor_line;
struct gpiod_line *motor_ena_line;
struct gpiod_line *motor_in1_line;
struct gpiod_line *motor_in2_line;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    log_event("Signal received, stopping motor and releasing GPIO lines.");
    stop_motor();

    if (rain_sensor_line) {
        gpiod_line_release(rain_sensor_line);
    }
    if (motor_ena_line) {
        gpiod_line_release(motor_ena_line);
    }
    if (motor_in1_line) {
        gpiod_line_release(motor_in1_line);
    }
    if (motor_in2_line) {
        gpiod_line_release(motor_in2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int value = gpiod_line_get_value(rain_sensor_line);
    if (value < 0) {
        log_event("Error reading rain sensor value.");
        return -1; // Indicate an error
    }
    return value;
}

// Function to close the window by activating the motor
void close_window() {
    log_event("Closing window.");

    // Set motor direction to forward
    if (gpiod_line_set_value(motor_in1_line, 1) < 0) {
        log_event("Error setting motor IN1 high.");
        return;
    }
    if (gpiod_line_set_value(motor_in2_line, 0) < 0) {
        log_event("Error setting motor IN2 low.");
        return;
    }

    // Enable the motor
    if (gpiod_line_set_value(motor_ena_line, 1) < 0) {
        log_event("Error setting motor ENA high.");
        return;
    }

    // Run the motor for 5 seconds
    sleep(5);

    // Stop the motor
    stop_motor();
}

// Function to stop the motor
void stop_motor() {
    log_event("Stopping motor.");

    // Disable the motor
    if (gpiod_line_set_value(motor_ena_line, 0) < 0) {
        log_event("Error setting motor ENA low.");
    }

    // Set IN1 and IN2 to low to ensure motor is stopped
    if (gpiod_line_set_value(motor_in1_line, 0) < 0) {
        log_event("Error setting motor IN1 low.");
    }
    if (gpiod_line_set_value(motor_in2_line, 0) < 0) {
        log_event("Error setting motor IN2 low.");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        log_event("Error opening GPIO chip.");
        return 1;
    }

    // Get the GPIO lines
    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_sensor_line || !motor_ena_line || !motor_in1_line || !motor_in2_line) {
        log_event("Error getting GPIO line.");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for input/output
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        log_event("Error requesting rain sensor line for input.");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        log_event("Error requesting motor ENA line for output.");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        log_event("Error requesting motor IN1 line for output.");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        log_event("Error requesting motor IN2 line for output.");
        gpiod_chip_close(chip);
        return 1;
    }

    log_event("Rain sensor and motor control initialized.");

    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            log_event("Rain detected!");
            close_window();
        } else if (rain_detected < 0) {
            log_event("Error reading rain sensor, retrying...");
        }

        sleep(2);
    }

    return 0;
}

