#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               user, nice, system, idle, iowait, irq, softirq) != 7) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
float calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle, unsigned long long prev_iowait, unsigned long long prev_irq, unsigned long long prev_softirq,
                         unsigned long long curr_user, unsigned long long curr_nice, unsigned long long curr_system, unsigned long long curr_idle, unsigned long long curr_iowait, unsigned long long curr_irq, unsigned long long curr_softirq)
{
    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long curr_idle_all = curr_idle + curr_iowait;

    unsigned long long prev_non_idle = prev_user + prev_nice + prev_system + prev_irq + prev_softirq;
    unsigned long long curr_non_idle = curr_user + curr_nice + curr_system + curr_irq + curr_softirq;

    unsigned long long prev_total = prev_idle_all + prev_non_idle;
    unsigned long long curr_total = curr_idle_all + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle_all - prev_idle_all;

    float cpu_usage = (float)(totald - idled) / totald;

    return cpu_usage * 100.0;
}

// Function to map CPU load to RGB color values
void map_cpu_load_to_rgb(float cpu_load, int *red, int *green, int *blue)
{
    if (cpu_load <= 50.0) {
        // Green to Yellow
        *red = (int)(cpu_load / 50.0 * 255.0);
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = (int)((100.0 - cpu_load) / 50.0 * 255.0);
        *blue = 0;
    }
}

// Function to set RGB LED color using hardware PWM
void set_rgb_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq;
    unsigned long long curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq;

    // Read initial CPU stats
    if (read_cpu_stats(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read current CPU stats
        if (read_cpu_stats(&curr_user, &curr_nice, &curr_system, &curr_idle, &curr_iowait, &curr_irq, &curr_softirq) != 0) {
            fprintf(stderr, "Error reading CPU stats, exiting...\n");
            break;
        }

        // Calculate CPU load
        float cpu_load = calculate_cpu_load(prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq,
                                            curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq);

        // Map CPU load to RGB color
        int red, green, blue;
        map_cpu_load_to_rgb(cpu_load, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_led_color(red, green, blue);

        // Update previous CPU stats
        prev_user = curr_user;
        prev_nice = curr_nice;
        prev_system = curr_system;
        prev_idle = curr_idle;
        prev_iowait = curr_iowait;
        prev_irq = curr_irq;
        prev_softirq = curr_softirq;

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Turn off RGB LED
    set_rgb_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

