#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_DATA 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

// UDP server address and port
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000

// Global variables for I2C handle and UDP socket
int i2c_handle = -1;
int udp_socket = -1;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Function prototypes
int init_i2c();
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib, int32_t *t_fine);
double compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, int32_t t_fine);
int send_udp_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from BMP280
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib) {
    char data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    char data[6];

    // Set forced mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) != 0) { // Oversampling x1, forced mode
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10 ms delay

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_DATA, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using Bosch formulas
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib, int32_t *t_fine) {
    double var1 = (raw_temperature / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temperature / 131072.0 - calib.dig_T1 / 8192.0) * (raw_temperature / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    double T = (*t_fine) / 5120.0;
    return T;
}

// Compensate pressure using Bosch formulas
double compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, int32_t t_fine) {
    double var1 = (t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (calib.dig_P4 * 65536.0);
    var1 = (calib.dig_P3 * var1 * var1 / 524288.0 + calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * calib.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    double p = 1048576.0 - raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + calib.dig_P7) / 16.0;

    return p;
}

// Send data over UDP
int send_udp_data(double temperature, double pressure) {
    char json_string[100];
    snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP data\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    bmp280_calib_data calib;
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) == 0) {
            int32_t t_fine;
            double temperature = compensate_temperature(raw_temperature, calib, &t_fine);
            double pressure = compensate_pressure(raw_pressure, calib, t_fine);

            if (send_udp_data(temperature, pressure) != 0) {
                fprintf(stderr, "Failed to send UDP data, retrying in 5 seconds...\n");
            } else {
                printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
            }
        } else {
            fprintf(stderr, "Failed to read raw data, retrying in 5 seconds...\n");
        }

        sleep(5);
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    close(udp_socket);
    gpioTerminate();

    return 0;
}

