#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(int spi_handle, float *temperature);
int calculate_pwm_duty(float temperature);
void add_to_buffer(time_t timestamp, float temperature, int pwm_duty);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    unsigned char data[4];
    int result = spiXfer(spi_handle, data, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Check for fault bit
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: ");
        if (data[0] & 0x01) fprintf(stderr, "OC ");
        if (data[0] & 0x02) fprintf(stderr, "SCG ");
        if (data[0] & 0x04) fprintf(stderr, "SCV ");
        fprintf(stderr, "\n");
        return -1; // Indicate error
    }

    // Extract thermocouple temperature (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0; // Indicate success
}

// Function to calculate PWM duty cycle based on temperature
int calculate_pwm_duty(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 50.0);
    } else if (temperature < 60.0) {
        duty_cycle = (int)((temperature - 40.0) / (60.0 - 40.0) * 150.0 + 50.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to add a log entry to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int pwm_duty) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, PWM Duty: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].pwm_duty);
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    int pwm_duty;
    time_t current_time;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate PWM duty cycle
            pwm_duty = calculate_pwm_duty(temperature);

