#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS = 3)
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 2

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile int logging_enabled = 0;
static int ac1, ac2, ac3, b1, b2, mb, mc, md;
static unsigned int ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature);
float calculate_pressure(int raw_pressure, int raw_temperature);
void log_data(float temperature, float pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int read_16(int reg, int *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the BMP180
int read_u16(int reg, unsigned int *value)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_16(BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_u16(BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_16(BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_16(BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS = 3)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate the compensated temperature
float calculate_temperature(int raw_temperature)
{
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate the compensated pressure
float calculate_pressure(int raw_pressure, int raw_temperature)
{
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x1_pressure = ((long)ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x1_pressure + x2_pressure + 32768)) >> 15;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long pressure;
    if (b7 < 0x80000000)
    {
        pressure = (b7 * 2) / b4;
    }
    else
    {
        pressure = (b7 / b4) * 2;
    }

    x1 = (pressure >> 8) * (pressure >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * pressure) >> 16;
    pressure = pressure + ((x1 + x2 + 3791) >> 4);

    return pressure / 100.0f; // Return pressure in Pa
}

// Function to log data to a file
void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    logging_enabled = !logging_enabled;
    printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT); // Set back to input
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable interrupt

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Data logging is initially disabled. Press the button connected to GPIO2 to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            float temperature, pressure;

            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, raw_temperature);
                log_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(1000000); // 1-second interval
    }

    return 0;
}

