        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Data logging is initially disabled. Press the button connected to GPIO2 to toggle logging.\n");

    // Main loop
    while (1) {
        if (logging_enabled) {
            int raw_temperature, raw_pressure;
            float temperature, pressure;

            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, raw_temperature);
                log_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(1000000); // 1-second interval
    }

    return 0;
}

