#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// MAX31865 Configuration Values
#define MAX31865_CONFIG_3WIRE 0xC2 // 3-wire, VBIAS on, auto conversion, fault detection

// Global variables
static int spi_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int max31865_init(void);
int read_rtd_value(uint16_t *rtd_value);
int read_fault_status(uint8_t *fault_status);
float calculate_temperature(uint16_t rtd_value);
int log_data(float temperature);
void signal_handler(int sig);
void cleanup(void);

// Helper function to write to a MAX31865 register
int write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer transfer[1];

    tx_buf[0] = reg | 0x80; // Set MSB for write operation
    tx_buf[1] = value;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 2;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI write failed");
        return -1;
    }

    return 0;
}

// Helper function to read from a MAX31865 register
int read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer transfer[1];

    tx_buf[0] = reg & 0x7F; // Clear MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 2;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI read failed");
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

int main(void) {
    uint16_t rtd_value;
    uint8_t fault_status;
    float temperature;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read RTD value
        if (read_rtd_value(&rtd_value) < 0) {
            fprintf(stderr, "Failed to read RTD value.\n");
            continue; // Continue to the next iteration
        }

        // Read fault status
        if (read_fault_status(&fault_status) < 0) {
            fprintf(stderr, "Failed to read fault status.\n");
            continue; // Continue to the next iteration
        }

        // Check for faults
        if (fault_status != 0) {
            fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
            fprintf(log_fp, "Fault detected: 0x%02X\n", fault_status);
            fflush(log_fp);
            continue; // Continue to the next iteration
        }

        // Calculate temperature
        temperature = calculate_temperature(rtd_value);

        // Log data
        if (log_data(temperature) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "rtd_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int max31865_init(void) {
    // Initialize MAX31865 configuration register
    if (write_register(MAX31865_CONFIG_REG, MAX31865_CONFIG_3WIRE) < 0) {
        fprintf(stderr, "Failed to write to configuration register.\n");
        return -1;
    }

    return 0;
}

int read_rtd_value(uint16_t *rtd_value) {
    uint8_t msb, lsb;

    // Read RTD MSB
    if (read_register(MAX31865_RTD_MSB_REG, &msb) < 0) {
        fprintf(stderr, "Failed to read RTD MSB.\n");
        return -1;
    }

    // Read RTD LSB
    if (read_register(MAX31865_RTD_LSB_REG, &lsb) < 0) {
        fprintf(stderr, "Failed to read RTD LSB.\n");
        return -1;
    }

    *rtd_value = ((uint16_t)msb << 8) | lsb;
    *rtd_value = *rtd_value >> 1; // Remove fault bit

    return 0;
}

int read_fault_status(uint8_t *fault_status) {
    if (read_register(MAX31865_FAULT_REG, fault_status) < 0) {
        fprintf(stderr, "Failed to read fault status.\n");
        return -1;
    }
    return 0;
}

float calculate_temperature(uint16_t rtd_value) {
    // Callendar-Van Dusen equation (simplified for PT100)
    float rtd_resistance = (float)rtd_value * 430.0 / 32768.0; // 430 is the ratio of the reference resistor to the PT100
    float temperature = (rtd_resistance - 100.0) / 0.385; // Simplified linear approximation

    return temperature;
}

int log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    fflush(log_fp);

    return 0;
}

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

