#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA_PRESS_MSB 0xF7
#define BME280_REG_DATA_PRESS_LSB 0xF8
#define BME280_REG_DATA_PRESS_XLSB 0xF9
#define BME280_REG_DATA_TEMP_MSB 0xFA
#define BME280_REG_DATA_TEMP_LSB 0xFB
#define BME280_REG_DATA_TEMP_XLSB 0xFC
#define BME280_REG_DATA_HUM_MSB 0xFD
#define BME280_REG_DATA_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data);
int bme280_init(int fd);
int bme280_read_data(int fd, int32_t *temperature, int32_t *pressure, int32_t *humidity);
double compensate_temperature(int32_t adc_T, struct bme280_calib_data calib);
double compensate_pressure(int32_t adc_P, struct bme280_calib_data calib, double t_fine);
double compensate_humidity(int32_t adc_H, struct bme280_calib_data calib, double t_fine);
int log_data(FILE *fp, double temperature, double humidity, double pressure);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// BME280 initialization function
int bme280_init(int fd) {
    uint8_t chip_id;

    // Check the chip ID
    if (i2c_read_bytes(fd, BME280_REG_CHIPID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error reading chip ID\n");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data (00-25)\n");
        return -1;
    }

    uint8_t calib_data_26[7];
    if (i2c_read_bytes(fd, BME280_REG_CALIB_26, calib_data_26, 7) != 0) {
        fprintf(stderr, "Error reading calibration data (26-31)\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)calib_data[1] << 8 | calib_data[0];
    calib.dig_T2 = (int16_t)calib_data[3] << 8 | calib_data[2];
    calib.dig_T3 = (int16_t)calib_data[5] << 8 | calib_data[4];
    calib.dig_P1 = (uint16_t)calib_data[7] << 8 | calib_data[6];
