#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_START 0xAA

// Oversampling setting (OSS = 0)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 20 samples/second)
#define BUFFER_SIZE 1200

// Structure to hold pressure reading and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

// Global variables
int i2c_handle;
PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
float calibration_data[11];
int running = 1;

// Function prototypes
int read_calibration_data(int i2c_handle, float *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
float calculate_pressure(int raw_temperature, int raw_pressure, float *calibration_data);
float calculate_rolling_average(float *buffer, int buffer_size);
void alert_callback(int gpio, int level, uint32_t tick, void *user_data);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, float *calibration_data) {
    for (int i = 0; i < 11; i++) {
        int msb = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 2 * i);
        int lsb = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 2 * i + 1);

        if (msb < 0 || lsb < 0) {
            fprintf(stderr, "Error reading calibration data: %d\n", i);
            return -1;
        }

        calibration_data[i] = (float)((msb << 8) | lsb);
    }
    return 0;
}

// Function to read raw temperature value from BMP180
int read_raw_temperature(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (minimum)

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to read raw pressure value from BMP180
int read_raw_pressure(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
