#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Conversion commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE (0x34 + (BMP180_OSS << 6))

// Global variables
