int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

