// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Conversion commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE (0x34 + (BMP180_OSS << 6))

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp);
void log_data(double temperature, double pressure);
void signal_handler(int signal);
void timer_callback();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    // Basic validation: check if AC1 is within a reasonable range
    if (ac1 < -32768 || ac1 > 32767) {
        fprintf(stderr, "Error: Invalid AC1 value: %d\n", ac1);
        return -1;
    }

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (minimum)

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) != 0) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp) {
    long x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    unsigned long x1_pressure = ((long)ac3 * b6) >> 13;
    unsigned long x2_pressure = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x1_pressure + x2_pressure + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long pressure;
    if (b7 < 0x80000000)
    {
        pressure = (b7 * 2) / b4;
    }
    else
    {
        pressure = (b7 / b4) * 2;
    }
    x1 = (pressure >> 8) * (pressure >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * pressure) >> 16;
    pressure = pressure + ((x1 + x2 + 3791) >> 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt (every 500ms)
    gpioSetTimerFunc(0, 500, timer_callback);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up resources
    gpioSetTimerFunc(0, 0, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

