#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP280 Registers
#define BMP280_REG_ID         0xD0
#define BMP280_REG_CALIB_00   0x88
#define BMP280_REG_DATA       0xF7
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_STATUS     0xF3

// BMP280 Chip ID
#define BMP280_CHIP_ID        0x58

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP_X1 0x20
#define BMP280_OVERSAMPLING_PRES_X1 0x04
#define BMP280_MODE_FORCED          0x01

// I2C Addresses
#define BMP280_I2C_ADDR_1 0x76
#define BMP280_I2C_ADDR_2 0x77

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static int bmp280_address = -1;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
};

// Function prototypes
int bmp280_init(int i2c_address);
int bmp280_read_calibration_data(int fd, struct bmp280_calib_data *calib);
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data *calib);
double bmp280_compensate_pressure(int32_t raw_pressure, struct bmp280_calib_data *calib, double t_fine);
int log_data(double temperature, double pressure);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Initialize BMP280 sensor
int bmp280_init(int i2c_address) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-1");
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Check chip ID
    char reg = BMP280_REG_ID;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    char chip_id;
    if (read(fd, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x58)\n", chip_id);
        close(fd);
        return -1;
    }

    // Set oversampling and mode
    char ctrl_meas = (BMP280_OVERSAMPLING_TEMP_X1 << 5) | (BMP280_OVERSAMPLING_PRES_X1 << 2) | BMP280_MODE_FORCED;
    reg = BMP280_REG_CTRL_MEAS;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (write(fd, &ctrl_meas, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration data from BMP280
int bmp280_read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    char reg = BMP280_REG_CALIB_00;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char data[24];
    if (read(fd, data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    char reg = BMP280_REG_DATA;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char data[6];
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data *calib) {
    double var1, var2, T;
    double adc_T = (double)raw_temperature;
    double dig_T1 = (double)calib->dig_T1;
    double dig_T2 = (double)calib->dig_T2;
    double dig_T3 = (double)calib->dig_T3;

    var1 = (adc_T / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    var2 = ((adc_T / 131072.0 - dig_T1 / 8192.0) * (adc_T / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure
double bmp280_compensate_pressure(int32_t raw_pressure, struct bmp280_calib_data *calib, double t_fine) {
    double var1, var2, p;
    double adc_P = (double)raw_pressure;
    double dig_P1 = (double)calib->dig_P1;
    double dig_P2 = (double)calib->dig_P2;
    double dig_P3 = (double)calib->dig_P3;
    double dig_P4 = (double)calib->dig_P4;
    double dig_P5 = (double)calib->dig_P5;
    double dig_P6 = (double)calib->dig_P6;
    double dig_P7 = (double)calib->dig_P7;
    double dig_P8 = (double)calib->dig_P8;
    double dig_P9 = (double)calib->dig_P9;

    var1 = (t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (dig_P4 * 65536.0);
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
