// BMP280 Registers
#define BMP280_REG_ID         0xD0
#define BMP280_REG_CALIB_00   0x88
#define BMP280_REG_DATA       0xF7
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_STATUS     0xF3

// BMP280 Chip ID
#define BMP280_CHIP_ID        0x58

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP_X1 0x20
#define BMP280_OVERSAMPLING_PRES_X1 0x04
#define BMP280_MODE_FORCED          0x01

// I2C Addresses
#define BMP280_I2C_ADDR_1 0x76
#define BMP280_I2C_ADDR_2 0x77

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static int bmp280_address = -1;
static volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
