// Initialize BMP280 sensor
int bmp280_init(int i2c_address) {
    int fd;
    char filename[20];

    snprintf(filename, 19, "/dev/i2c-1");
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Check chip ID
    char reg = BMP280_REG_ID;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    char chip_id;
    if (read(fd, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x58)\n", chip_id);
        close(fd);
        return -1;
    }

    // Set oversampling and mode
    char ctrl_meas = (BMP280_OVERSAMPLING_TEMP_X1 << 5) | (BMP280_OVERSAMPLING_PRES_X1 << 2) | BMP280_MODE_FORCED;
    reg = BMP280_REG_CTRL_MEAS;
    if (write(fd, &reg, 1) != 1) {
