}

// Read raw temperature and pressure data from BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    char reg = BMP280_REG_DATA;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char data[6];
    if (read(fd, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data *calib) {
    double var1, var2, T;
