#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 5

// Global variables
static int i2c_handle;
static pthread_mutex_t buffer_mutex;
static volatile int running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static circular_buffer_t temp_buffer;

// Function prototypes
void *sensor_thread(void *arg);
float read_temperature();
void add_to_buffer(float temp);
float calculate_average();
void control_led(float average_temp);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *cb);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add temperature reading to circular buffer
void add_to_buffer(float temp) {
    pthread_mutex_lock(&buffer_mutex);
    temp_buffer.buffer[temp_buffer.head] = temp;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Calculate running average of temperature readings
float calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    if (temp_buffer.count == 0) {
        pthread_mutex_unlock(&buffer_mutex);
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < temp_buffer.count; i++) {
        sum += temp_buffer.buffer[i];
    }
    float average = sum / temp_buffer.count;
    pthread_mutex_unlock(&buffer_mutex);
    return average;
}

// Control LED based on temperature
void control_led(float average_temp) {
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Read temperature from LM75 sensor
float read_temperature() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Convert raw temperature to Celsius
            int16_t temp = (int16_t)raw_temp;
            float celsius = (float)(temp >> 5) / 256.0;
            return celsius;
        } else {
