#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <jansson.h>
#include <math.h>

// Constants
#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define CONFIG_FILE "config.json"
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define MAX_TEMP 80.0
#define MAX_RTD_RESISTANCE 1000.0 // Maximum expected RTD resistance

// Global variables
static volatile int running = 1;
static int spi_fd;
static double target_temperature = DEFAULT_TARGET_TEMP;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int initialize_gpio();
int read_config();
double read_temperature();
double rtd_to_resistance(int rtd_code);
double resistance_to_temperature(double resistance);
double pid_control(double current_temperature);
void set_pwm_duty_cycle(double duty_cycle);
void handle_signals(int signal);
void log_error(const char *message);

// Callendar-Van Dusen coefficients (example values, adjust as needed)
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775

int main() {
    if (initialize_pigpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (initialize_gpio() != 0) {
        wiringPiSPIClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    if (read_config() != 0) {
        wiringPiSPIClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signals);
    signal(SIGTERM, handle_signals);

    while (running) {
        double temperature = read_temperature();
        if (temperature < -273.0) { // Error code from read_temperature
            log_error("Failed to read temperature. Shutting down.");
            break;
        }

        double duty_cycle = pid_control(temperature);
        set_pwm_duty_cycle(duty_cycle);

        gpioDelay(100); // 100 ms
    }

    // Cleanup
    set_pwm_duty_cycle(0.0);
    wiringPiSPIClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

int initialize_spi() {
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }

    // Initialize MAX31865 (enable VBIAS, auto conversion, clear faults)
    unsigned char config_data[2];
    config_data[0] = 0x80; // Configuration register address
    config_data[1] = 0xC1; // Enable VBIAS, auto conversion, clear faults

    wiringPiSPIDataRW(SPI_CHANNEL, config_data, 2);

    return 0;
}

int initialize_gpio() {
    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_HEATER, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_HEATER, PWM_RANGE);
    return 0;
}

int read_config() {
    json_t *root;
    json_error_t error;

    root = json_load_file(CONFIG_FILE, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        // Use default values
        target_temperature = DEFAULT_TARGET_TEMP;
        kp = DEFAULT_KP;
        ki = DEFAULT_KI;
        kd = DEFAULT_KD;
        return 0; // Non-critical error, continue with defaults
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    json_t *kp_json = json_object_get(root, "kp");
    json_t *ki_json = json_object_get(root, "ki");
    json_t *kd_json = json_object_get(root, "kd");

    if (json_is_real(target_temp_json)) {
        target_temperature = json_real_value(target_temp_json);
    } else {
        fprintf(stderr, "Error: Invalid target_temperature in config file. Using default.\n");
        target_temperature = DEFAULT_TARGET_TEMP;
    }

    if (json_is_real(kp_json)) {
        kp = json_real_value(kp_json);
    } else {
        fprintf(stderr, "Error: Invalid kp in config file. Using default.\n");
        kp = DEFAULT_KP;
    }

    if (json_is_real(ki_json)) {
        ki = json_real_value(ki_json);
    } else {
        fprintf(stderr, "Error: Invalid ki in config file. Using default.\n");
        ki = DEFAULT_KI;
    }

    if (json_is_real(kd_json)) {
        kd = json_real_value(kd_json);
    } else {
        fprintf(stderr, "Error: Invalid kd in config file. Using default.\n");
        kd = DEFAULT_KD;
    }

    json_decref(root);
    return 0;
}

double read_temperature() {
    unsigned char data[3];
    int rtd_code;
    double resistance;
    double temperature;

    // Read RTD MSB (0x01) and LSB (0x02)
    data[0] = 0x01; // RTD MSB register address (auto-increment)
    wiringPiSPIDataRW(SPI_CHANNEL, data, 3);

    // Check for fault bit (D0 of MSB)
    if (data[1] & 0x01) {
        log_error("RTD Fault detected!");
        return -274.0; // Indicate error
    }

    // Combine MSB and LSB to get the 15-bit RTD code
    rtd_code = ((data[1] << 8) | data[2]) >> 1; // Shift right by 1 to get 15 bits

    resistance = rtd_to_resistance(rtd_code);
    if (resistance < 0) {
        log_error("Invalid RTD resistance. Check sensor connection.");
        return -274.0; // Indicate error
    }

    temperature = resistance_to_temperature(resistance);
    return temperature;
}

double rtd_to_resistance(int rtd_code) {
    double resistance = ((double)rtd_code / 32768.0) * 430.0;
    return resistance;
}

double resistance_to_temperature(double resistance) {
    // Callendar-Van Dusen equation (simplified for positive temperatures)
    // R = R0 * (1 + A*t + B*t^2)
    // t = (R/R0 - 1) / (A + B*t)
    // This is a simplified approximation.  A more accurate solution would require
    // solving the quadratic equation.

    if (resistance <= 0.0) {
        return -274.0; // Indicate error
    }

    double t = (resistance / R0 - 1.0) / (A + B * (resistance / R0 - 1.0) / (A + B * (resistance / R0 - 1.0)));

    return t;
}

double pid_control(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;

    double output = kp * error + ki * integral + kd * derivative;

    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

void set_pwm_duty_cycle(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * PWM_RANGE / 100.0);
    gpioPWM(GPIO_HEATER, pwm_value);
}

void handle_signals(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

