#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdbool.h>

// BMP180 I2C address
#define BMP180_I2C_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 //oss = 0
#define BMP180_CMD_PRESSURE1 0x74 //oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 //oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 //oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd);
int bmp180_read_raw_pressure(int fd, uint8_t oss);
float bmp180_calculate_temperature(int32_t ut);
float bmp180_calculate_pressure(int32_t up, int32_t ut, uint8_t oss);
void log_breach(float temperature, float pressure);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    int retries = 3;
    int result;

    while (retries > 0) {
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

