int bmp180_read_calibration_data(int fd) {
    uint8_t data[22];
    if (i2c_read_reg(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Read raw temperature value from BMP180
int bmp180_read_raw_temperature(int fd) {
    uint8_t data[2];
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Failed to write temperature conversion command.\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms (minimum)

    if (i2c_read_reg(fd, BMP180_REG_MSB, data, 2) != 0) {
        fprintf(stderr, "Failed to read raw temperature data.\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Read raw pressure value from BMP180
int bmp180_read_raw_pressure(int fd, uint8_t oss) {
    uint8_t data[3];
    uint8_t cmd;

    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE0; break;
        case 1: cmd = BMP180_CMD_PRESSURE1; break;
        case 2: cmd = BMP180_CMD_PRESSURE2; break;
        case 3: cmd = BMP180_CMD_PRESSURE3; break;
        default: cmd = BMP180_CMD_PRESSURE0; break; // Default to oss = 0
    }

    if (i2c_write_reg(fd, BMP180_REG_CONTROL, cmd) != 0) {
        fprintf(stderr, "Failed to write pressure conversion command.\n");
        return -1;
    }

    usleep((2 + (3 << oss)) * 1000); // Wait for conversion

    if (i2c_read_reg(fd, BMP180_REG_MSB, data, 3) != 0) {
