        fprintf(stderr, "Failed to read BMP180 calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read raw temperature and pressure
        int32_t ut = bmp180_read_raw_temperature(i2c_fd);
        int32_t up = bmp180_read_raw_pressure(i2c_fd, 3); // Use oss = 3 for highest accuracy

        if (ut == -1 || up == -1) {
            fprintf(stderr, "Failed to read temperature or pressure. Retrying.\n");
            usleep(100000); // 100ms delay before retry
            continue;
        }

        // Calculate temperature and pressure
        float temperature = bmp180_calculate_temperature(ut);
        float pressure = bmp180_calculate_pressure(up, ut, 3);

        // Check for breaches
