int read_i2c_word(int reg, int *value) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading I2C word from register 0x%X\n", reg);
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    if (read_i2c_word(BMP180_REG_CAL_START, &ac1) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_START + 2, &ac2) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_START + 4, &ac3) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_START + 6, &ac4) != 0) return -1;
    if (read_i2c_word(BMP180_REG_CAL_START + 8, &ac5) != 0) return -1;
