#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// GPIO pin for logging toggle
#define LOGGING_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile unsigned long last_interrupt_time = 0;
static int ac1, ac2, ac3, b1, b2, mb, mc, md, ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int oss, int *raw_pressure);
double calculate_pressure(int raw_temp, int raw_pressure, int oss);
void log_data(double pressure);
void toggle_logging(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    unsigned char data[22];
    if (i2cReadDevice(i2c_handle, (char *)data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temp) {
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    unsigned char data[2];
    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int oss, int *raw_pressure) {
    char buf[1];
    unsigned char data[3];

    switch (oss) {
        case 0:
            buf[0] = BMP180_CMD_PRESSURE0;
            break;
        case 1:
            buf[0] = BMP180_CMD_PRESSURE1;
            break;
        case 2:
            buf[0] = BMP180_CMD_PRESSURE2;
            break;
        case 3:
            buf[0] = BMP180_CMD_PRESSURE3;
            break;
        default:
            fprintf(stderr, "Invalid OSS value\n");
            return -1;
    }

    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(2 + (3 << oss)) ; // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
    return 0;
}

// Function to calculate pressure using BMP180 formulas
double calculate_pressure(int raw_temp, int raw_pressure, int oss) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    x1 = ((long)raw_temp - ac6) * ac5 / pow(2, 15);
    x2 = ((long)mc * pow(2, 11)) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 / pow(2, 12))) / pow(2, 11);
    x2 = ac2 * b6 / pow(2, 11);
    x3 = x1 + x2;
    b3 = (((ac1 * 4 + x3) << oss) + 2) / 4;

    x1 = ac3 * b6 / pow(2, 13);
    x2 = (b1 * (b6 * b6 / pow(2, 12))) / pow(2, 16);
    x3 = ((x1 + x2) + 2) / pow(2, 2);
    b4 = ac4 * (unsigned long)(x3 + 32768) / pow(2, 15);

    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    if (b7 < 0x80000000)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    p = p + (x1 + x2 + 3791) / pow(2, 4);

    return (double)p;
}

// Function to log data to file
void log_data(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

// Function to toggle logging based on GPIO interrupt
void toggle_logging(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_time;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(LOGGING_PIN, PI_INPUT);
    gpioSetPullUpDown(LOGGING_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge detection
    gpioSetISRFuncEx(LOGGING_PIN, FALLING_EDGE, 0, toggle_logging, NULL);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_temp, raw_pressure;
    double pressure;
    int oss = 3; // Oversampling setting

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(oss, &raw_pressure) == 0) {
                // Calculate pressure
                pressure = calculate_pressure(raw_temp, raw_pressure, oss);

                // Log data
                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

