#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_MODE 0

// Define PI controller parameters
#define Kp 1.0
#define Ki 0.1
#define MAX_DUTY_CYCLE 0.8

// Define log file name
#define LOG_FILE "heater_log.csv"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double target_temperature = 25.0;
static double integral = 0.0;

// Function prototypes
double read_temperature();
double calculate_pwm(double current_temperature);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 3-18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 3;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_pwm(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;

    // Anti-windup
    if (integral > 100) integral = 100;
    if (integral < -100) integral = -100;

    double duty_cycle = Kp * error + Ki * integral;

    // Limit duty cycle to 0-100%
    if (duty_cycle > 100) duty_cycle = 100;
    if (duty_cycle < 0) duty_cycle = 0;

    // Apply maximum duty cycle limit
    if (duty_cycle > MAX_DUTY_CYCLE * 100) {
        duty_cycle = MAX_DUTY_CYCLE * 100;
    }

    return duty_cycle;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    gpioPWM(HEATER_PIN, (int)(duty_cycle * 2.55)); // pigpio PWM range is 0-255
}

// Function to log data to CSV file
void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set heater pin as output
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),PWM Duty Cycle (%)\n");
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off heater
    set_heater_pwm(0.0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        printf("Target temperature set to %.2f°C\n", target_temperature);
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature < -999) {
            set_heater_pwm(0.0);
            fprintf(stderr, "Error reading temperature, turning off heater\n");
        } else {
            double duty_cycle = calculate_pwm(temperature);
            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle);
            printf("Temperature: %.2f°C, Duty Cycle: %.2f%%\n", temperature, duty_cycle);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

