#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error during file read: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temperature = read_cpu_temp();

        if (temperature == -1) {
            // Error reading temperature, skip this cycle
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        int red, green, blue;

        if (temperature < TEMP_BLUE) {
            // Blue
            red = 0;
            green = 0;
            blue = 255;
        } else if (temperature < TEMP_GREEN) {
            // Green
            red = 0;
            green = 255;
            blue = 0;
        } else {
            // Red
            red = 255;
            green = 0;
            blue = 0;
        }

        set_led_color(red, green, blue);

        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temperature, red, green, blue);

        gpioDelay(500000); // 0.5 seconds
    }

    // Cleanup before exiting
    set_led_color(255, 255, 255); // Turn off LED (common anode)
    gpioTerminate();

    return 0;
}

