#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read DHT22 data
int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum;
    unsigned int pulse_lengths[81];

