#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS = 3)
#define BMP180_OSS 3

// Conversion command for pressure measurement
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE (0x34 + (BMP180_OSS << 6))

// GPIO pin for the push-button
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static FILE *log_file = NULL;

// BMP180 calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int *raw_temp);
int read_raw_pressure(int *raw_pressure);
double calculate_temperature(int raw_temp);
double calculate_pressure(int raw_pressure, int raw_temp);
void toggle_logging(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void log_data(double pressure);

// Helper function to read a 16-bit value from the BMP180
int16_t read_16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%X\n", reg);
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Helper function to read an unsigned 16-bit value from the BMP180
uint16_t read_u16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%X\n", reg);
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0)
    {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up the push-button interrupt
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, toggle_logging, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1)
    {
        if (logging_enabled)
        {
            int raw_temp, raw_pressure;
            double temperature, pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0)
            {
                fprintf(stderr, "Error reading temperature or pressure\n");
                continue; // Skip to the next iteration
            }

            // Calculate compensated temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, raw_temp);

            // Log the data
            log_data(pressure);
        }
        else
        {
            printf("Logging is disabled. Press the button to enable.\n");
        }

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    return 0;
}

// Initialize I2C communication
int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_16(BMP180_REG_CAL_AC1);
    ac2 = read_16(BMP180_REG_CAL_AC2);
    ac3 = read_16(BMP180_REG_CAL_AC3);
    ac4 = read_u16(BMP180_REG_CAL_AC4);
    ac5 = read_u16(BMP180_REG_CAL_AC5);
    ac6 = read_u16(BMP180_REG_CAL_AC6);
    b1 = read_16(BMP180_REG_CAL_B1);
    b2 = read_16(BMP180_REG_CAL_B2);
    mb = read_16(BMP180_REG_CAL_MB);
    mc = read_16(BMP180_REG_CAL_MC);
    md = read_16(BMP180_REG_CAL_MD);

    // Basic validation: check if any calibration value is zero (very unlikely)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == 0 || b2 == 0 || mb == 0 || mc == 0 || md == 0)
    {
        fprintf(stderr, "Error: Invalid calibration data. Sensor may be faulty.\n");
        return 1;
    }

    return 0;
}

// Read raw temperature value from the BMP180
int read_raw_temperature(int *raw_temp)
{
    char buf[1];
    buf[0] = BMP180_CMD_TEMP;

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature conversion command\n");
        return 1;
    }

    gpioDelay(5000); // Wait 5ms for conversion

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return 1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure value from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = BMP180_CMD_PRESSURE;

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure conversion command\n");
        return 1;
    }

    gpioDelay(26000); // Wait 26ms for conversion (OSS = 3)

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate compensated temperature in degrees Celsius
double calculate_temperature(int raw_temp)
{
    long x1, x2, b5;
    double temperature;

    x1 = (((long)raw_temp - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;
    temperature = ((b5 + 8) >> 4) / 10.0;

    return temperature;
}

// Calculate compensated pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temp)
{
    long x1, x2, x3, b3, b6, p;
    unsigned long b4, b7;
    double pressure;

    long ut = raw_temp;
    long up = raw_pressure;

    x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Toggle data logging on/off
void toggle_logging(int gpio, int level, uint32_t tick)
{
    if (tick - last_interrupt_tick > DEBOUNCE_TIME)
    {
        logging_enabled = !logging_enabled;
        if (logging_enabled)
        {
            log_file = fopen("pressure_log.txt", "a");
            if (log_file == NULL)
            {
                fprintf(stderr, "Error opening log file\n");
                logging_enabled = 0; // Disable logging if file can't be opened
            }
        }
        else
        {
            if (log_file != NULL)
            {
                fclose(log_file);
                log_file = NULL;
            }
        }
        last_interrupt_tick = tick;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Exiting...\n");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file if it's open
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    exit(0);
}

// Log data to file
void log_data(double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

