#define MAX_RETRIES 3
#define RETRY_DELAY 2 // seconds
#define READ_INTERVAL 10 // seconds

// Structure to hold DHT22 data
typedef struct {
    float humidity;
    float temperature;
    int error;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *server_url = DEFAULT_URL;

// Function prototypes
DHT22Data read_dht22();
int post_humidity(float humidity, const char *url);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
