    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to read data from DHT22 sensor
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    unsigned int data_buffer[5] = {0, 0, 0, 0, 0};
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1000); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // 1us
        timeout++;
    }
    if (timeout >= 100) {
        data.error = -1; // Timeout error
        log_message(LOG_ERR, "DHT22: Timeout waiting for start signal (low).");
        return data;
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
        gpioDelay(1); // 1us
        timeout++;
    }
    if (timeout >= 100) {
        data.error = -1; // Timeout error
        log_message(LOG_ERR, "DHT22: Timeout waiting for start signal (high).");
        return data;
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // 1us
        timeout++;
    }
    if (timeout >= 100) {
        data.error = -1; // Timeout error
        log_message(LOG_ERR, "DHT22: Timeout waiting for start signal (low).");
        return data;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // 1us
            timeout++;
        }
        if (timeout >= 100) {
            data.error = -1; // Timeout error
            log_message(LOG_ERR, "DHT22: Timeout waiting for bit start (low).");
            return data;
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // 1us
            timeout++;
        }
        if (timeout >= 100) {
            data.error = -1; // Timeout error
            log_message(LOG_ERR, "DHT22: Timeout waiting for bit end (high).");
            return data;
        }
        long end = gpioTick();

        if ((end - start) > 40) {
            data_buffer[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    // Validate checksum
    if (((data_buffer[0] + data_buffer[1] + data_buffer[2] + data_buffer[3]) & 0xFF) != data_buffer[4]) {
        data.error = -1;
        log_message(LOG_ERR, "DHT22: Checksum failure.");
        return data;
    }

    // Convert data to humidity and temperature
    data.humidity = (float)(((data_buffer[0] << 8) | data_buffer[1])) / 10.0;
    data.temperature = (float)(((data_buffer[2] << 8) | data_buffer[3])) / 10.0;
    if (data.temperature > 125) {
        data.temperature = data.temperature - 256;
    }

    return data;
}

// Function to post humidity data to the server
int post_humidity(float humidity, const char *url) {
    CURL *curl;
    CURLcode res;
    char json_data[50];
    long http_code = 0;

    // Create JSON payload
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        log_message(LOG_ERR, "libcurl: curl_easy_init() failed");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        log_message(LOG_ERR, curl_easy_strerror(res));
    } else {
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            log_message(LOG_INFO, "HTTP POST successful");
        } else {
            log_message(LOG_ERR, "HTTP POST failed with code: %ld", http_code);
            res = CURLE_HTTP_RETURNED_ERROR; // Indicate HTTP error
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    if (res != CURLE_OK) {
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    int dht22_retries = 0;
    int http_retries = 0;
    DHT22Data dht22_data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio: Initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Starting DHT22 humidity sensor and HTTP POST service");

    while (running) {
        dht22_retries = 0;
        http_retries = 0;
        dht22_data.error = -1; // Initialize error

        // Read DHT22 sensor with retries
        while (dht22_data.error != 0 && dht22_retries < MAX_RETRIES) {
            dht22_data = read_dht22();
            if (dht22_data.error != 0) {
                log_message(LOG_WARNING, "DHT22 read failed, retrying...");
                sleep(RETRY_DELAY);
                dht22_retries++;
            }
        }

        if (dht22_data.error == 0) {
            // Post humidity data with retries
            while (http_retries < MAX_RETRIES) {
                if (post_humidity(dht22_data.humidity, server_url) == 0) {
                    break; // Success, exit retry loop
                } else {
                    log_message(LOG_WARNING, "HTTP POST failed, retrying...");
                    sleep(RETRY_DELAY);
                    http_retries++;
                }
            }

            if (http_retries == MAX_RETRIES) {
                log_message(LOG_ERR, "HTTP POST failed after multiple retries");
            }
        } else {
            log_message(LOG_ERR, "DHT22 read failed after multiple retries");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup
    gpioTerminate();
    curl_global_cleanup();
    closelog();

    return 0;
}

