#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define constants
#define PWM_FREQUENCY 1000  // 1 kHz
#define SPI_FREQUENCY 500000 // 500 kHz
#define TARGET_TEMPERATURE 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID variables
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize();
void cleanup();
float read_temperature();
void control_heater(float temperature);
void log_data(float temperature, int duty_cycle, float pid_output);
void handle_fault(uint8_t fault_code);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Configure PWM
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 100); // Duty cycle range 0-100

    // Open SPI channel
    spi_handle = spiOpen(0, SPI_FREQUENCY, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

// Read temperature from MAX31855
float read_temperature() {
    char buffer[4];
    int result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(log_file, "%ld, SPI read error: %d\n", time(NULL), result);
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    // Extract temperature data
    int16_t internal_temperature = ((buffer[2] << 8) | buffer[3]) >> 4;
    float temperature = internal_temperature * 0.0625;

    // Check for fault bits
    uint8_t fault_code = buffer[3] & 0x07;
    if (fault_code) {
        handle_fault(fault_code);
        return -1000.0; // Indicate error
    }

    return temperature;
}

// Handle MAX31855 faults
void handle_fault(uint8_t fault_code) {
    fprintf(log_file, "%ld, Thermocouple fault: 0x%02X\n", time(NULL), fault_code);
    fflush(log_file);
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    integral = 0.0;          // Reset PID integral
    previous_error = 0.0;    // Reset PID previous error
}

// Control heater using PID algorithm
void control_heater(float temperature) {
    float error = TARGET_TEMPERATURE - temperature;

    // PID calculations
    float proportional = Kp * error;
    integral += Ki * error;
    float derivative = Kd * (error - previous_error);
    float pid_output = proportional + integral + derivative;

    // Limit PID output to 0-100
    if (pid_output < 0) pid_output = 0;
    if (pid_output > 100) pid_output = 100;

    // Set PWM duty cycle
    gpioPWM(HEATER_PIN, (int)pid_output);

    // Failsafe: Disable heater if temperature is out of range
    if (temperature > 100.0 || temperature < 0.0) {
        fprintf(log_file, "%ld, Temperature out of range: %.2f, disabling heater\n", time(NULL), temperature);
        fflush(log_file);
        gpioPWM(HEATER_PIN, 0); // Turn off heater
    }

    log_data(temperature, (int)pid_output, pid_output);
    previous_error = error;
}

// Log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    fprintf(log_file, "%ld, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n", time(NULL), temperature, duty_cycle, pid_output);
    fflush(log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            control_heater(temperature);
        } else {
            fprintf(log_file, "%ld, Failed to read temperature\n", time(NULL));
            fflush(log_file);
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

