#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char temp_str[10];
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fgets(temp_str, sizeof(temp_str), fp) == NULL) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);

    // Convert millidegrees Celsius to degrees Celsius
    temp_celsius = (float)atoi(temp_str) / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        // Linear interpolation
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle using pigpio
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle * 2.55) != 0) { // pigpio duty cycle is 0-255
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    int duty_cycle;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed.\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Temperature: %.2f C, Duty Cycle: %d %%\n", temperature, duty_cycle);
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan...\n");
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

