int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    int duty_cycle;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed.\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Temperature: %.2f C, Duty Cycle: %d %%\n", temperature, duty_cycle);
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan...\n");
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

