// Define continuous measurement command
#define MEASURE_CMD 0x3608

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables for I2C handles and log file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(unsigned char data[], int len);
void log_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 lookup table
unsigned char crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to calculate CRC-8 checksum
int validate_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
        crc = (crc << 4) ^ crc8_table[crc >> 4];
    }
    return (crc == 0x00);
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    unsigned char data[3];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        gpioDelay(1000); // Wait for measurement (adjust as needed)

        result = i2cReadDevice(i2c_handle, (char *)data, 3);
        if (result != 3) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        if (validate_crc(data, 3)) {
            int raw_value = (data[0] << 8) | data[1];
            *flow_rate = raw_value * 0.01;
            return 0; // Success
        } else {
            fprintf(stderr, "CRC validation failed\n");
            retries--;
        }
    }

