    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

