#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
volatile int encoder_count = 0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
void handle_encoder_interrupt(int gpio, int level, uint32_t tick, void *user_data);
float calculate_angle(int encoder_count);
int log_data(float angle);
void signal_handler(int signal);
void cleanup();

// Structure to hold previous encoder state
typedef struct {
    int a_state;
    int b_state;
} EncoderState;

EncoderState previous_state = {0, 0};

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    // Set up interrupts for both rising and falling edges
    gpioSetISRFuncEx(ENCODER_A, EITHER_EDGE, 0, handle_encoder_interrupt, NULL);
    gpioSetISRFuncEx(ENCODER_B, EITHER_EDGE, 0, handle_encoder_interrupt, NULL);

    return 0;
}

// Interrupt handler function for the rotary encoder
void handle_encoder_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    int a_state = gpioRead(ENCODER_A);
    int b_state = gpioRead(ENCODER_B);

    // Quadrature decoding logic
    if (gpio == ENCODER_A) {
        if (a_state != previous_state.a_state) {
            if (a_state == b_state) {
                encoder_count++; // Clockwise
            } else {
                encoder_count--; // Counter-clockwise
            }
        }
    } else if (gpio == ENCODER_B) {
        if (b_state != previous_state.b_state) {
            if (a_state == b_state) {
                encoder_count--; // Counter-clockwise
            } else {
                encoder_count++; // Clockwise
            }
        }
    }

    previous_state.a_state = a_state;
    previous_state.b_state = b_state;
}

// Function to calculate the angular position in degrees
float calculate_angle(int encoder_count) {
    float angle = (float)(encoder_count % PULSES_PER_REVOLUTION) * 360.0 / PULSES_PER_REVOLUTION;
    if (angle < 0) {
        angle += 360.0;
    }
    return angle;
}

// Function to log the data to a file
int log_data(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angle);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler function for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float angle = calculate_angle(encoder_count);
        if (log_data(angle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }
        gpioDelay(10); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

