#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define FLOW_SCALE_FACTOR 1000.0
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_flow_rate(int i2c_handle, int *raw_flow);
float convert_to_flow_rate(int raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, size_t len);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the sensor
int initialize_sensor(int i2c_handle) {
    char command[2] = {0x36, 0x08};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the flow rate from the sensor
int read_flow_rate(int i2c_handle, int *raw_flow) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    // Extract raw flow value and CRC
    int16_t raw_flow_temp = (buffer[0] << 8) | buffer[1];
    uint8_t crc = buffer[2];

    // Validate CRC
    uint8_t calculated_crc = crc8((uint8_t *)buffer, 2);
    if (calculated_crc != crc) {
        fprintf(stderr, "CRC check failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, crc);
        return -1;
    }

    *raw_flow = raw_flow_temp;
    return 0;
}

// Convert raw flow value to uL/min
float convert_to_flow_rate(int raw_flow) {
    return (float)raw_flow / FLOW_SCALE_FACTOR;
}

// Log the flow rate to a CSV file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", FLOW_LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_flow_rate(i2c_handle, &raw_flow) == 0) {
            flow_rate = convert_to_flow_rate(raw_flow);
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error reading flow rate, retrying...\n");
        }

        gpioDelay(1000); // Wait 1000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

