#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TAMPER_THRESHOLD_SEC 5
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nSignal received, exiting gracefully...\n");
}

// Function to open the GPIO chip
static struct gpiod_chip *open_gpio_chip(const char *chipname)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", chipname, strerror(errno));
        return NULL;
    }
    return chip;
}

// Function to get the GPIO line
static struct gpiod_line *get_gpio_line(struct gpiod_chip *chip, int offset)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", offset, strerror(errno));
        return NULL;
    }
    return line;
}

// Function to request the GPIO line for input
static int request_gpio_line_input(struct gpiod_line *line, const char *consumer)
{
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the GPIO line value
static int read_gpio_line(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to print the intrusion alert
static void print_intrusion_alert(void)
{
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("INTRUSION ALERT: %s\n", buf);
}

int main(void)
{
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000L};
    struct timespec tamper_threshold = {TAMPER_THRESHOLD_SEC, 0};
    struct timespec start_time, current_time, elapsed_time;
    int touched = 0;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = open_gpio_chip(GPIO_CHIP);
    if (!chip) {
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = get_gpio_line(chip, GPIO_PIN);
    if (!line) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line for input
    if (request_gpio_line_input(line, "ttp223_tamper") < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring GPIO %d on %s... (Press Ctrl+C to exit)\n", GPIO_PIN, GPIO_CHIP);

    // Main loop
    while (!terminate) {
        int value = read_gpio_line(line);
        if (value < 0) {
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value == 1) {
            if (!touched) {
                // Start the timer
                if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                    fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
                    gpiod_line_release(line);
                    gpiod_chip_close(chip);
                    return EXIT_FAILURE;
                }
                touched = 1;
            } else {
                // Check if the tamper threshold has been exceeded
                if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                    fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                    gpiod_line_release(line);
                    gpiod_chip_close(chip);
                    return EXIT_FAILURE;
                }

                elapsed_time.tv_sec = current_time.tv_sec - start_time.tv_sec;
                elapsed_time.tv_nsec = current_time.tv_nsec - start_time.tv_nsec;
                if (elapsed_time.tv_nsec < 0) {
                    elapsed_time.tv_sec--;
                    elapsed_time.tv_nsec += 1000000000;
                }

                if (elapsed_time.tv_sec >= tamper_threshold.tv_sec) {
                    print_intrusion_alert();
                    touched = 0; // Reset the timer after printing the alert
                }
            }
        } else {
            // Reset the timer if the sensor is released
            touched = 0;
        }

        // Wait for the next poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

