#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S32_LE
#define PERIOD_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *fp = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int init_alsa() {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

int main() {
    int err;
    int16_t *buffer = NULL;
    int buffer_size = PERIOD_SIZE * 4; // 4 bytes per 24-bit sample
    int16_t *pcm_buffer = NULL;
    int pcm_buffer_size = PERIOD_SIZE * 2; // 2 bytes per 16-bit sample

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_alsa() < 0) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    buffer = (int16_t *) malloc(buffer_size);
    if (!buffer) {
        perror("Error allocating buffer");
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    pcm_buffer = (int16_t *) malloc(pcm_buffer_size);
    if (!pcm_buffer) {
        perror("Error allocating PCM buffer");
        free(buffer);
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("Error opening file");
        free(buffer);
        free(pcm_buffer);
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE);
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        } else if (err != PERIOD_SIZE) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        }

        // Extract 24-bit data and right-shift to 16-bit PCM
        for (int i = 0; i < PERIOD_SIZE; i++) {
            int32_t sample = ((int32_t *)buffer)[i];
            pcm_buffer[i] = (int16_t)(sample >> 8); // Right-shift 8 bits
        }

        if (fwrite(pcm_buffer, sizeof(int16_t), PERIOD_SIZE, fp) != PERIOD_SIZE) {
            perror("Error writing to file");
            break;
        }

        // Set GPIO low for left channel
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            perror("Error setting GPIO low");
            break;
        }
        usleep(1); // Small delay

        // Set GPIO high for right channel
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            perror("Error setting GPIO high");
            break;
        }
        usleep(1); // Small delay
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (fp) {
        fclose(fp);
    }
    if (buffer) {
        free(buffer);
    }
    if (pcm_buffer) {
        free(pcm_buffer);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return EXIT_SUCCESS;
}

