    fprintf(stderr, "Cleaning up...\n");
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (fp) {
        fclose(fp);
    }
    if (buffer) {
        free(buffer);
    }
    if (pcm_buffer) {
        free(pcm_buffer);
    }
    if (gpio_line) {
