#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected, double flame_duration);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int flame_detected;
    double flame_start_time;
} ProgramState;

ProgramState state = {0, 0.0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("System started");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!state.flame_detected) {
                state.flame_detected = 1;
                state.flame_start_time = time_time();
                log_event("Flame detected");
            }
        } else if (sensor_value == 1) { // No flame detected (HIGH signal)
            if (state.flame_detected) {
                state.flame_detected = 0;
                double flame_duration = time_time() - state.flame_start_time;
                control_fan(0, 0.0); // Turn off fan
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Flame ended, duration: %.2f seconds", flame_duration);
                log_event(log_message);
            }
        } else {
            fprintf(stderr, "Error reading sensor value.\n");
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioPWM(FAN_PIN, 0); // Initially turn off the fan

    return 0;
}

// Read flame sensor with timeout
int read_flame_sensor() {
    int start_time = time_time();
    int timeout = 1; // Timeout after 1 second

    while (time_time() - start_time < timeout) {
        int value = gpioRead(FLAME_SENSOR_PIN);
        if (value == 0 || value == 1) {
            return value;
        }
        gpioDelay(1000); // Check every 1 ms
    }

    fprintf(stderr, "Error: Flame sensor not responding.\n");
    log_event("Error: Flame sensor not responding.");
    return -1; // Indicate error
}

// Control fan speed based on flame duration
void control_fan(int flame_detected, double flame_duration) {
    if (flame_detected) {
        // Exponential duty cycle mapping
        double duty_cycle = 80.0 * (1.0 - exp(-flame_duration / 5.0)); // Adjust 5.0 for desired curve
        if (duty_cycle > 80.0) duty_cycle = 80.0;
        gpioPWM(FAN_PIN, (int)duty_cycle);
    } else {
        gpioPWM(FAN_PIN, 0); // Turn off fan
    }
}

// Log events to file
void log_event(const char *event) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Turn off fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Reset pin mode
    gpioSetMode(FAN_PIN, PI_INPUT); // Reset pin mode
    gpioTerminate();

    if (log_file != NULL) {
        log_event("System shutdown");
        fclose(log_file);
    }
}

