// Configuration structure
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    float frame_period;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Configuration parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define LOG_FILE_NAME "radar_data.log"
#define MAGIC_NUMBER 0x52444144 // "RADA"

// Function prototypes
int initialize_spi();
int initialize_gpio();
int initialize_logging();
void trigger_radar();
void data_ready_callback(int gpio, int level, uint32_t tick, void *user_data);
int read_radar_data(uint8_t *data, int data_len);
int log_data(uint8_t *data, int data_len, int frame_number);
void signal_handler(int signal);
void cleanup();

// Configuration data
radar_config_t config = {
    .start_frequency = 77.0,
    .end_frequency = 79.0,
    .num_chirps = 64,
    .num_samples = 256,
    .frame_period = 0.1 // 100 ms
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        fprintf(stderr, "Logging initialization failed\n");
        cleanup();
        return 1;
    }

    int frame_number = 0;
    uint8_t *data = (uint8_t *)malloc(32768 * sizeof(uint8_t));
    if (data == NULL) {
        fprintf(stderr, "Failed to allocate memory for radar data\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the radar
        trigger_radar();

        // Wait for data ready interrupt (handled by callback)

        // Read radar data
        if (read_radar_data(data, 32768) == 0) {
            // Log the data
            if (log_data(data, 32768, frame_number) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            frame_number++;
        } else {
            fprintf(stderr, "Failed to read radar data\n");
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    // Cleanup and exit
    free(data);
    cleanup();
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_DOWN); // Optional pull-down resistor

    // Set interrupt callback for data ready GPIO
    if (gpioSetISRFuncEx(DATA_READY_GPIO, RISING_EDGE, 0, data_ready_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return 1;
    }

    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE_NAME, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write log file header
    uint32_t magic = MAGIC_NUMBER;
    time_t timestamp = time(NULL);
    radar_config_t config_data = config;

    if (fwrite(&magic, sizeof(uint32_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number to log file\n");
        fclose(log_file);
        return 1;
    }
    if (fwrite(&timestamp, sizeof(time_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        fclose(log_file);
        return 1;
    }
    if (fwrite(&config_data, sizeof(radar_config_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write configuration data to log file\n");
        fclose(log_file);
        return 1;
    }

    return 0;
}

// Trigger the radar
void trigger_radar() {
    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_GPIO, 0);
}

// Data ready callback function
void data_ready_callback(int gpio, int level, uint32_t tick, void *user_data) {
    // This function is called when the data ready GPIO goes high
    // It indicates that the radar has finished transmitting a frame
    // and is ready to receive the data.
    // In this implementation, the main loop handles the data reading and logging.
    // This callback is just a placeholder to indicate that data is ready.
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
}

// Read radar data via SPI
int read_radar_data(uint8_t *data, int data_len) {
    char tx_buf[data_len];
    memset(tx_buf, 0, data_len); // Fill with dummy data for full-duplex

    int result = spiXfer(spi_handle, tx_buf, (char *)data, data_len);
    if (result != data_len) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Log data to file
int log_data(uint8_t *data, int data_len, int frame_number) {
    time_t timestamp = time(NULL);

    if (fwrite(&timestamp, sizeof(time_t), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        return 1;
    }
    if (fwrite(&frame_number, sizeof(int), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write frame number to log file\n");
        return 1;
    }
    if (fwrite(data, sizeof(uint8_t), data_len, log_file) != data_len) {
        fprintf(stderr, "Failed to write data to log file\n");
        return 1;
    }

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

