#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_CONT_MODE 0xCB01 // Continuous conversion mode, 100ms conversion time, auto range
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_sensor();
int read_sensor_data(uint16_t *raw_data);
double calculate_lux(uint16_t raw_data);
int log_data(double lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int config_sensor() {
    uint16_t config_value = CONFIG_CONT_MODE;
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the OPT3001 sensor
int read_sensor_data(uint16_t *raw_data) {
    char buf[1];
    buf[0] = RESULT_REG;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to result register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    *raw_data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Calculate lux value from raw data
double calculate_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return LUX_SCALE * pow(2, exponent) * mantissa;
}

// Log data to file
int log_data(double lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (config_sensor() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    double lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_data) == 0) {
            // Calculate lux
            lux = calculate_lux(raw_data);

            // Log data
            log_data(lux);

            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit the loop if re-initialization fails
            }
            if (config_sensor() != 0) {
                fprintf(stderr, "Failed to reconfigure sensor. Exiting.\n");
                terminate = 1;
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

