#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a GPIO pin as input with pull-down resistor
int initialize_gpio(int gpio_pin)
{
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", gpio_pin);
        return -1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down resistor on GPIO %d\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio(int gpio_pin)
{
    return gpioRead(gpio_pin);
}

// Function to log the sensor data with timestamp
void log_data(int channel_states[])
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long milliseconds = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    printf("[%ld ms] ", milliseconds);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, channel_states[i]);
    }
    printf("\n");
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    for (int i = 0; i < num_channels; i++) {
        if (initialize_gpio(gpio_pins[i]) != 0) {
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (!terminate) {
        int channel_states[num_channels];
        for (int i = 0; i < num_channels; i++) {
            channel_states[i] = read_gpio(gpio_pins[i]);
        }

        log_data(channel_states);

        gpioDelay(100000); // Delay for 100 milliseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    return 0;
}

