        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read sensor states and log them
    while (program_running) {
        // Read the state of sensor 1
        int sensor_1_state = gpioRead(SENSOR_1_GPIO);
        if (sensor_1_state < 0) {
