#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result;
    int gpio_read_result;
    int previous_state = -1; // Initialize to an invalid state
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO 4 as input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the state of the tilt sensor
        gpio_read_result = gpioRead(TILT_SENSOR_GPIO);

        if (gpio_read_result == 0) {
            // Tilted (LOW)
            if (previous_state != 0) {
                // State changed from Not Tilted to Tilted
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s: Tilted\n", timestamp);
                fflush(stdout);
                previous_state = 0;
            }
        } else if (gpio_read_result == 1) {
            // Not Tilted (HIGH)
            if (previous_state != 1) {
                // State changed from Tilted to Not Tilted
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s: Not Tilted\n", timestamp);
                fflush(stdout);
                previous_state = 1;
            }
        } else {
            fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_SENSOR_GPIO, gpio_read_result);
            fflush(stderr);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Tilt sensor monitoring stopped.\n");

    return 0;
}

