                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s: Not Tilted\n", timestamp);
                fflush(stdout);
                previous_state = 1;
            }
        } else {
            fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_SENSOR_GPIO, gpio_read_result);
            fflush(stderr);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Tilt sensor monitoring stopped.\n");

    return 0;
}

