#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37

// I2C bus
#define I2C_BUS 1

// GPIO pin for alarm
#define ALARM_GPIO 17

// Flow rate scale factor
#define FLOW_SCALE_FACTOR 0.036

// Log file name
#define LOG_FILE "flow_log.txt"

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
    float flow_rate;
} sensor_t;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
sensor_t sensor1, sensor2;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize a sensor
int init_sensor(sensor_t *sensor) {
    char buf[2];
    buf[0] = 0x08; // Command register
    buf[1] = 0x36; // Start measurement command

    int result = i2cWriteDevice(sensor->handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor at address 0x%02X: %d\n", sensor->address, result);
        return -1;
    }
    gpioDelay(100); // Wait 100ms
    return 0;
}

// Function to read flow rate from a sensor
float read_flow_rate(sensor_t *sensor) {
    char buf[9];
    int result = i2cReadDevice(sensor->handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from sensor at address 0x%02X: %d\n", sensor->address, result);
        return -1.0;
    }

    // Validate CRC for flow data
    uint8_t crc_flow = crc8((uint8_t *)buf, 2);
    if (crc_flow != buf[2]) {
        fprintf(stderr, "CRC error for flow data from sensor at address 0x%02X\n", sensor->address);
        return -1.0;
    }

    // Validate CRC for temperature data
    uint8_t crc_temp = crc8((uint8_t *)buf + 3, 2);
    if (crc_temp != buf[5]) {
        fprintf(stderr, "CRC error for temperature data from sensor at address 0x%02X\n", sensor->address);
        return -1.0;
    }

    // Extract raw flow value
    int16_t raw_flow = (buf[0] << 8) | buf[1];

    // Convert to ml/min
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Function to log flow data
void log_flow_data(float avg_flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow_rate);
    fflush(log_file);
}

// Function to control the alarm
void control_alarm(float avg_flow_rate) {
    if (avg_flow_rate < 0.5) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    sensor1.address = SENSOR1_ADDR;
    sensor2.address = SENSOR2_ADDR;

    sensor1.handle = i2cOpen(I2C_BUS, sensor1.address, 0);
    if (sensor1.handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", sensor1.handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    sensor2.handle = i2cOpen(I2C_BUS, sensor2.address, 0);
    if (sensor2.handle < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", sensor2.handle);
        i2cClose(sensor1.handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(&sensor1) != 0) {
        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_sensor(&sensor2) != 0) {
        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float flow1 = read_flow_rate(&sensor1);
        float flow2 = read_flow_rate(&sensor2);

        float avg_flow_rate = 0.0;
        int valid_readings = 0;

        if (flow1 >= 0) {
            avg_flow_rate += flow1;
            valid_readings++;
        }
        if (flow2 >= 0) {
            avg_flow_rate += flow2;
            valid_readings++;
        }

        if (valid_readings > 0) {
            avg_flow_rate /= valid_readings;
            log_flow_data(avg_flow_rate);
            control_alarm(avg_flow_rate);
        } else {
            fprintf(stderr, "No valid flow rate readings\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(sensor1.handle);
    i2cClose(sensor2.handle);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

