        i2cClose(sensor1.handle);
        i2cClose(sensor2.handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        float flow1 = read_flow_rate(&sensor1);
        float flow2 = read_flow_rate(&sensor2);

        float avg_flow_rate = 0.0;
        int valid_readings = 0;

