        return 1; // Exit if initialization fails
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            time_t current_time = time(NULL);
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected!\n");
        }

        gpioDelay(50); // Poll every 50 ms
    }

    return 0; // This line will not be reached due to the infinite loop
}

