#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define D7S_ADDRESS 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB 0x2A
#define ACCEL_X_MSB 0x2B
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Y_MSB 0x2D
#define ACCEL_Z_LSB 0x2E
#define ACCEL_Z_MSB 0x2F
#define SCALE_FACTOR 0.0009765625f
#define CSV_FILE "fan_health.csv"

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int initialize_sensor(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  if (write(fd, &reg, 1) != 1) {
    fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
    return -1;
  }
  if (read(fd, value, 1) != 1) {
    fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
    return -1;
  }
  if (read(fd, data, len) != len) {
    fprintf(stderr, "Error reading block from I2C device: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Sensor initialization function
int initialize_sensor(int fd) {
  // Set mode to active
  if (i2c_write_reg(fd, MODE_CONTROL_REG, 0x10) != 0) {
    fprintf(stderr, "Error setting mode to active\n");
    return -1;
  }

  // Wait for operating status to be active
  time_t start_time = time(NULL);
  uint8_t status;
  while (time(NULL) - start_time < 1) {
    if (i2c_read_reg(fd, OPERATING_STATUS_REG, &status) == 0) {
      if (status & 0x01) {
        return 0; // Sensor is active
      }
    }
    usleep(100000); // Check every 100ms
  }

  fprintf(stderr, "Error: Sensor did not become active within 1 second\n");
  return -1;
}

// Read acceleration data function
int read_acceleration(int fd, float *x, float *y, float *z) {
  uint8_t data[6];
  if (i2c_read_block(fd, ACCEL_X_LSB, data, 6) != 0) {
    fprintf(stderr, "Error reading acceleration data\n");
    return -1;
  }

  // Combine LSB and MSB, convert to signed 16-bit, and scale to g
  int16_t raw_x = (int16_t)((data[1] << 8) | data[0]);
  int16_t raw_y = (int16_t)((data[3] << 8) | data[2]);
  int16_t raw_z = (int16_t)((data[5] << 8) | data[4]);

  *x = (float)raw_x * SCALE_FACTOR;
  *y = (float)raw_y * SCALE_FACTOR;
  *z = (float)raw_z * SCALE_FACTOR;

  return 0;
}

// Log data to CSV file function
int log_data(FILE *fp, float x, float y, float z) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[30];

  time(&rawtime);
  timeinfo = gmtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

  fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
  fflush(fp); // Ensure data is written to file immediately
  return 0;
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

int main() {
  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C device
  i2c_fd = open(I2C_DEVICE, O_RDWR);
  if (i2c_fd < 0) {
    fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDRESS) < 0) {
    fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
    close(i2c_fd);
    return 1;
  }

  // Initialize sensor
  if (initialize_sensor(i2c_fd) != 0) {
    close(i2c_fd);
    return 1;
  }

  // Open CSV file
  csv_file = fopen(CSV_FILE, "a");
  if (csv_file == NULL) {
    fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
    close(i2c_fd);
    return 1;
  }

  // Write header if the file is newly created
  fseek(csv_file, 0, SEEK_END);
  long file_size = ftell(csv_file);
  if (file_size == 0) {
    fprintf(csv_file, "timestamp,x,y,z\n");
  }
  rewind(csv_file);

  float x, y, z;

  // Main loop
  while (!terminate) {
    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
      log_data(csv_file, x, y, z);
    } else {
      fprintf(stderr, "Error reading acceleration data, retrying...\n");
    }
    usleep(500000); // 500ms
  }

  // Close I2C device and CSV file
  close(i2c_fd);
  fclose(csv_file);

  return 0;
}

