#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set sensor pins as inputs
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_1_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_2_PIN as input\n");
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR_1_PIN);
    int sensor2_value = gpioRead(SENSOR_2_PIN);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1; // Indicate error
    }

    return (sensor1_value | sensor2_value); // Return OR of sensor values
}

// Function to control the LED
void control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to LED_PIN\n");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_sensors();

        if (sensor_value == -1) {
            // Error reading sensors, but continue running
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Control LED based on sensor values
        if (sensor_value == 0) { // Either sensor detects an obstacle
            control_led(1); // Turn LED ON
        } else {
            control_led(0); // Turn LED OFF
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

