#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD 2 // seconds
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value with validation
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading on GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check for stall condition
int check_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log stall event
int log_stall_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Check for duplicate log entry
    char last_timestamp[64];
    if (ftell(fp) > 0) {
        fseek(fp, -strlen(timestamp) - 1, SEEK_END); // Move pointer to the beginning of the last line
        if (fgets(last_timestamp, sizeof(last_timestamp), fp) != NULL) {
            if (strcmp(last_timestamp, timestamp) == 0) {
                fclose(fp);
                return 0; // Duplicate entry, do not log
            }
        }
    }

    fprintf(fp, "%s Stall detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set pull-up resistors (optional, depending on sensor module)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int stall_count = 0;

    printf("Monitoring conveyor belt... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, skip this iteration
            gpioDelay(100); // Small delay to avoid busy-waiting
            continue;
        }

        // Check for stall condition
        if (check_stall(sensor1_value, sensor2_value)) {
            stall_count++;
            if (stall_count >= STALL_THRESHOLD * 10) { // 10ms loop
                if (log_stall_event() == 0) {
                    printf("Stall logged.\n");
                } else {
                    fprintf(stderr, "Error: Failed to log stall event.\n");
                }
                stall_count = 0; // Reset stall count after logging
            }
        } else {
            stall_count = 0; // Reset stall count if no stall
        }

        gpioDelay(10); // 10ms delay
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

