#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define DEVICE_ID_REGISTER 0x00
#define DEVICE_ID_VALUE 0x8D
#define CONFIGURATION_REGISTER 0x09
#define CONFIGURATION_VALUE 0x37 // Continuous mode, all axes enabled, 50mT range
#define X_AXIS_REGISTER 0x01
#define Y_AXIS_REGISTER 0x03
#define Z_AXIS_REGISTER 0x05
#define LSB_SCALE_FACTOR 0.001525 // 50mT range: 50 / 32768

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Initialize the sensor
int initialize_sensor() {
    int status;

    // Verify device ID
    char device_id;
    status = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REGISTER, &device_id, 1);
    if (status != 1) {
        fprintf(stderr, "Error reading device ID: %d\n", status);
        return -1;
    }

    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", device_id, DEVICE_ID_VALUE);
        return -1;
    }

    // Configure sensor
    status = i2cWriteI2CBlockData(i2c_handle, CONFIGURATION_REGISTER, (char*)&CONFIGURATION_VALUE, 1);
    if (status != 1) {
        fprintf(stderr, "Error writing configuration: %d\n", status);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, X_AXIS_REGISTER, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)raw_x * LSB_SCALE_FACTOR;
    *y = (float)raw_y * LSB_SCALE_FACTOR;
    *z = (float)raw_z * LSB_SCALE_FACTOR;

    return 0;
}

// Log data to CSV file
void log_data(float x, float y, float z) {
    char *timestamp = get_iso8601_timestamp();
    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

