#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

static volatile int running = 1;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to the log file
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    char *timestamp = get_timestamp();
    fprintf(fp, "%s %s\n", timestamp, message);
    free(timestamp); // Free the allocated memory
    fclose(fp);
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        char error_message[100];
        sprintf(error_message, "Error reading sensor: %d", value);
        log_message(error_message);
        return -1; // Indicate an error
    }
    return value;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    log_message("Daemon shutting down...");
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    log_message("Daemon started successfully");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            char *timestamp = get_timestamp();
            char alert_message[100];
            sprintf(alert_message, "ALERT: Water detected");
            printf("%s %s\n", timestamp, alert_message);
            log_message(alert_message);
            free(timestamp);
        } else if (sensor_value < 0) {
            // Sensor read error, attempt re-initialization after 60 seconds
            log_message("Attempting to re-initialize pigpio in 60 seconds...");
            gpioTerminate();
            sleep(60);
            if (gpioInitialise() < 0) {
                log_message("pigpio re-initialisation failed");
                fprintf(stderr, "pigpio re-initialisation failed\n");
                running = 0; // Exit the loop if re-initialization fails
            } else {
                gpioSetMode(GPIO_PIN, PI_INPUT);
                log_message("pigpio re-initialised successfully");
            }
        }

        sleep(2);
    }

    gpioTerminate();
    return 0;
}

