        } else if (sensor_value < 0) {
            // Sensor read error, attempt re-initialization after 60 seconds
            log_message("Attempting to re-initialize pigpio in 60 seconds...");
            gpioTerminate();
            sleep(60);
            if (gpioInitialise() < 0) {
                log_message("pigpio re-initialisation failed");
                fprintf(stderr, "pigpio re-initialisation failed\n");
                running = 0; // Exit the loop if re-initialization fails
            } else {
