// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to calculate RPM
float calculate_rpm(int pulses) {
    return (float)pulses * 60.0;
}

// Function to log RPM to file and stdout
void log_rpm(float rpm) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file);
    }
    printf("%s %.2f\n", timestamp, rpm);
}

