#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of states in the quadrature state machine
#define NUM_STATES 4

// Define the quadrature state machine states
typedef enum {
    STATE_00 = 0,
    STATE_01 = 1,
    STATE_11 = 2,
    STATE_10 = 3
} QuadratureState;

// Structure to hold the shared state
typedef struct {
    QuadratureState currentState;
    pthread_mutex_t mutex;
    FILE *logFile;
    volatile sig_atomic_t terminate;
} SharedState;

// Global pointer to the shared state
SharedState *sharedState = NULL;

// Function prototypes
void signalHandler(int signal);
void logRotation(const char *direction);
void sensorAInterruptHandler(int gpio, int level, uint32_t tick, void *user);
void sensorBInterruptHandler(int gpio, int level, uint32_t tick, void *user);
void initializeSharedState(SharedState *state);
void cleanupSharedState(SharedState *state);

// Function to initialize the shared state
void initializeSharedState(SharedState *state) {
    state->currentState = STATE_00;
    if (pthread_mutex_init(&state->mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        exit(EXIT_FAILURE);
    }
    state->logFile = fopen(LOG_FILE, "a");
    if (state->logFile == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    state->terminate = 0;
}

// Function to cleanup the shared state
void cleanupSharedState(SharedState *state) {
    if (state->logFile != NULL) {
        fflush(state->logFile);
        fclose(state->logFile);
    }
    pthread_mutex_destroy(&state->mutex);
}

// Signal handler function
void signalHandler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    if (sharedState != NULL) {
        sharedState->terminate = 1;
    }
}

// Function to log a rotation event
void logRotation(const char *direction) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&sharedState->mutex);
    fprintf(sharedState->logFile, "%s %s\n", timestamp, direction);
    fflush(sharedState->logFile);
    pthread_mutex_unlock(&sharedState->mutex);
}

// Interrupt handler for Sensor A
void sensorAInterruptHandler(int gpio, int level, uint32_t tick, void *user) {
    int sensorBValue = gpioRead(SENSOR_B_PIN);
    QuadratureState nextState;

    pthread_mutex_lock(&sharedState->mutex);
    switch (sharedState->currentState) {
        case STATE_00:
            nextState = (sensorBValue == 0) ? STATE_01 : STATE_10;
            break;
        case STATE_01:
            nextState = (sensorBValue == 0) ? STATE_11 : STATE_00;
            break;
        case STATE_11:
            nextState = (sensorBValue == 0) ? STATE_10 : STATE_01;
            break;
        case STATE_10:
            nextState = (sensorBValue == 0) ? STATE_00 : STATE_11;
            break;
        default:
            fprintf(stderr, "Invalid current state: %d\n", sharedState->currentState);
            pthread_mutex_unlock(&sharedState->mutex);
            return;
    }

    if (nextState == STATE_01 || nextState == STATE_11) {
        logRotation("CW");
    } else {
        logRotation("CCW");
    }

    sharedState->currentState = nextState;
    pthread_mutex_unlock(&sharedState->mutex);
}

// Interrupt handler for Sensor B
void sensorBInterruptHandler(int gpio, int level, uint32_t tick, void *user) {
    int sensorAValue = gpioRead(SENSOR_A_PIN);
    QuadratureState nextState;

    pthread_mutex_lock(&sharedState->mutex);
    switch (sharedState->currentState) {
        case STATE_00:
            nextState = (sensorAValue == 0) ? STATE_10 : STATE_01;
            break;
        case STATE_01:
            nextState = (sensorAValue == 0) ? STATE_00 : STATE_11;
            break;
        case STATE_11:
            nextState = (sensorAValue == 0) ? STATE_10 : STATE_01;
            break;
        case STATE_10:
            nextState = (sensorAValue == 0) ? STATE_01 : STATE_11;
            break;
        default:
            fprintf(stderr, "Invalid current state: %d\n", sharedState->currentState);
            pthread_mutex_unlock(&sharedState->mutex);
            return;
    }

    if (nextState == STATE_01 || nextState == STATE_11) {
        logRotation("CW");
    } else {
        logRotation("CCW");
    }

    sharedState->currentState = nextState;
    pthread_mutex_unlock(&sharedState->mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Allocate memory for the shared state
    sharedState = (SharedState *)malloc(sizeof(SharedState));
    if (sharedState == NULL) {
        perror("Failed to allocate memory for shared state");
        gpioTerminate();
        return 1;
    }

    // Initialize the shared state
    initializeSharedState(sharedState);

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Set interrupt handlers
    gpioSetAlertFuncEx(SENSOR_A_PIN, sensorAInterruptHandler, NULL);
    gpioSetAlertFuncEx(SENSOR_B_PIN, sensorBInterruptHandler, NULL);

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (!sharedState->terminate) {
        // Sleep for a short interval to avoid busy-waiting
        gpioDelay(100); // Sleep for 100 milliseconds
    }

    // Cleanup and exit
    gpioSetAlertFuncEx(SENSOR_A_PIN, NULL, NULL); // Disable interrupts
    gpioSetAlertFuncEx(SENSOR_B_PIN, NULL, NULL); // Disable interrupts
    cleanupSharedState(sharedState);
    free(sharedState);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

