#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down gracefully...", signal);
    program_running = 0;
}

int main() {
    // Initialize syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read touch sensor value
        int touch_value = gpioRead(TOUCH_SENSOR_PIN);

        // Log touch event
        if (touch_value == 1) {
            syslog(LOG_INFO, "Touch detected");
        } else {
            syslog(LOG_INFO, "No touch detected");
        }

        // Control LED based on touch sensor value
        gpioWrite(LED_PIN, touch_value);

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Cleanup
    syslog(LOG_INFO, "Turning off LED");
    gpioWrite(LED_PIN, 0); // Turn off LED

    syslog(LOG_INFO, "Terminating pigpio");
    gpioTerminate(); // Terminate pigpio

    syslog(LOG_INFO, "Exiting program");
    closelog(); // Close syslog

    return 0;
}

