#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio(void);
void cleanup_gpio(void);
void touch_callback(int gpio, int level, unsigned int tick, void *user_data);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initialize LED to OFF

    // Set touch sensor pin as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set up interrupt on rising edge for touch sensor
    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for touch sensor\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Touch sensor callback function
void touch_callback(int gpio, int level, unsigned int tick, void *user_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    unsigned long current_time = (unsigned long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

    // Debounce the touch sensor
    if (level == 1) { // Rising edge
        if (current_time - last_touch_time > DEBOUNCE_TIME) {
            // Toggle the LED
            int current_led_state = gpioRead(LED_PIN);
            gpioWrite(LED_PIN, !current_led_state);
            last_touch_time = current_time;
        }
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

