#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define buffer size
#define BUFFER_SIZE 100

// Structure for log entry
typedef struct {
    int gpio_pin;
    time_t timestamp;
    int new_state;
} log_entry_t;

// Global variables
log_entry_t log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
void log_event(int gpio_pin, int new_state);
void print_log_buffer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read sensor value from GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Control LED state
int control_led(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio_pin);
        return 1;
    }
    return 0;
}

// Log event to buffer
void log_event(int gpio_pin, int new_state) {
    time_t now = time(NULL);
    log_buffer[buffer_index].gpio_pin = gpio_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].new_state = new_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Print log buffer contents
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        printf("Index: %d, GPIO: %d, Timestamp: %ld, State: %d\n", index, log_buffer[index].gpio_pin, log_buffer[index].timestamp, log_buffer[index].new_state);
    }
    printf("Overflow Count: %d\n", overflow_count);
    printf("--- End of Log Buffer ---\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor 1
        int sensor_1_value = read_sensor(SENSOR_1_PIN);
        if (sensor_1_value >= 0) {
            control_led(LED_1_PIN, sensor_1_value);
            log_event(SENSOR_1_PIN, sensor_1_value);
        }

        // Read sensor 2
        int sensor_2_value = read_sensor(SENSOR_2_PIN);
        if (sensor_2_value >= 0) {
            control_led(LED_2_PIN, sensor_2_value);
            log_event(SENSOR_2_PIN, sensor_2_value);
        }

        gpioDelay(50); // Debounce delay
    }

    // Cleanup
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);
    gpioTerminate();

    // Print log buffer
    print_log_buffer();

    return 0;
}

