#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 2.0

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
volatile int running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int gpio;
    int last_state;
    unsigned long last_tick;
} sensor_t;

sensor_t sensor1, sensor2;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
void close_resources();
void sensor_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_rpm(unsigned long time_diff_us);
int log_data(unsigned long timestamp, int sensor1_state, int sensor2_state);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    sensor1.gpio = SENSOR1_GPIO;
    sensor1.last_state = gpioRead(SENSOR1_GPIO);
    sensor1.last_tick = gpioTick();

    sensor2.gpio = SENSOR2_GPIO;
    sensor2.last_state = gpioRead(SENSOR2_GPIO);
    sensor2.last_tick = gpioTick();

    return 0;
}

// Open the log file
int open_log_file() {
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Close resources (GPIO and log file)
void close_resources() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Callback function for sensor state changes
void sensor_callback(int gpio, int level, unsigned int tick, void *user_data) {
    sensor_t *sensor = (sensor_t *)user_data;
    unsigned long current_tick = gpioTick();
    unsigned long time_diff_us = current_tick - sensor->last_tick;

    if (time_diff_us > DEBOUNCE_TIME * 1000) {
        int current_state = gpioRead(gpio);
        if (current_state != sensor->last_state) {
            sensor->last_state = current_state;
            sensor->last_tick = current_tick;

            // Log the data
            log_data(current_tick, gpioRead(SENSOR1_GPIO), gpioRead(SENSOR2_GPIO));
        }
    }
}

// Calculate RPM
double calculate_rpm(unsigned long time_diff_us) {
    if (time_diff_us == 0) return 0.0; // Avoid division by zero
    double time_diff_seconds = (double)time_diff_us / 1000000.0;
    return (60.0 / time_diff_seconds) / PULSES_PER_REVOLUTION;
}

// Log data to the CSV file
int log_data(unsigned long timestamp, int sensor1_state, int sensor2_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%lu,%d,%d\n", timestamp, sensor1_state, sensor2_state);
