int open_log_file() {
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Close resources (GPIO and log file)
void close_resources() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Callback function for sensor state changes
void sensor_callback(int gpio, int level, unsigned int tick, void *user_data) {
    sensor_t *sensor = (sensor_t *)user_data;
    unsigned long current_tick = gpioTick();
    unsigned long time_diff_us = current_tick - sensor->last_tick;

    if (time_diff_us > DEBOUNCE_TIME * 1000) {
        int current_state = gpioRead(gpio);
        if (current_state != sensor->last_state) {
            sensor->last_state = current_state;
            sensor->last_tick = current_tick;

            // Log the data
