#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_REG 0x02
#define SPO2_REG 0x04
#define PART_ID_VALUE 0x82

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle);
int read_sensor_data(int handle, int *heart_rate, int *spo2);
int log_data(FILE *fp, int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Verify sensor presence
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART_ID value: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }
    printf("Sensor verified (PART_ID: 0x%02X)\n", part_id);
    return 0;
}

// Configure sensor for continuous measurement
int configure_sensor(int handle) {
    int status = i2cWriteByteData(handle, CONFIG_REG, 0x03); // Example configuration
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %d\n", status);
        return -1;
    }
    printf("Sensor configured for continuous measurement\n");
    return 0;
}

// Read heart rate and SpO2 data
int read_sensor_data(int handle, int *heart_rate, int *spo2) {
    int hr = i2cReadByteData(handle, HR_REG);
    if (hr < 0) {
        fprintf(stderr, "Failed to read HR register: %d\n", hr);
        return -1;
    }

    int spo2_val = i2cReadByteData(handle, SPO2_REG);
    if (spo2_val < 0) {
        fprintf(stderr, "Failed to read SPO2 register: %d\n", spo2_val);
        return -1;
    }

    *heart_rate = hr;
    *spo2 = spo2_val;
    return 0;
}

// Log data to file
int log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int heart_rate, spo2;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

