#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_DURATION 2000 // milliseconds
#define POLL_INTERVAL 100   // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int check_threshold(int sensor_value);
void activate_alarm(int gpio_pin);
void deactivate_alarm(int gpio_pin);
void log_event(const char *event_type, int sensor_number);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to check if threshold is exceeded
int check_threshold(int sensor_value) {
    return (sensor_value == 1) ? 1 : 0;
}

// Function to activate the alarm
void activate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
    log_event("ALARM", 0);   // Log alarm activation
}

// Function to deactivate the alarm
void deactivate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
    log_event("ALARM DEACTIVATED", 0); // Log alarm deactivation
}

// Function to log events
void log_event(const char *event_type, int sensor_number) {
    char *timestamp = get_iso8601_timestamp();
    if (log_file != NULL) {
        if (sensor_number > 0) {
            fprintf(log_file, "%s - %s - Sensor %d\n", timestamp, event_type, sensor_number);
        } else {
            fprintf(log_file, "%s - %s\n", timestamp, event_type);
        }
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
    free(timestamp);
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors (optional, as sensors are active high)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Initialize alarm to LOW
    deactivate_alarm(ALARM_PIN);

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for alarm timing
    int alarm_active = 0;
    unsigned long alarm_start_time = 0;

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensor, exit loop
            program_running = 0;
            continue;
        }

        int threshold_exceeded_1 = check_threshold(sensor1_value);
        int threshold_exceeded_2 = check_threshold(sensor2_value);

        if (threshold_exceeded_1 || threshold_exceeded_2) {
            if (!alarm_active) {
                // First time threshold exceeded
                alarm_active = 1;
                alarm_start_time = gpioTick();
                if (threshold_exceeded_1) {
                    log_event("TILT START", 1);
                } else {
                    log_event("TILT START", 2);
                }
            } else {
                // Check if alarm duration has been reached
                if (gpioTick() - alarm_start_time >= ALARM_DURATION * 1000) {
                    activate_alarm(ALARM_PIN);
                    alarm_active = 2; // Indicate alarm is active
                }
            }
        } else {
            // Sensors are back to normal
            if (alarm_active == 1) {
                // Threshold exceeded but alarm not activated yet
                if (threshold_exceeded_1) {
                    log_event("TILT END", 1);
                } else {
                    log_event("TILT END", 2);
                }
            } else if (alarm_active == 2) {
                // Alarm is active, check if both sensors are back to normal
                if (!threshold_exceeded_1 && !threshold_exceeded_2) {
                    deactivate_alarm(ALARM_PIN);
                    alarm_active = 0;
                }
            }
        }

        gpioDelay(POLL_INTERVAL); // Delay for 100ms
    }

    // Clean up
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

