    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors (optional, as sensors are active high)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Initialize alarm to LOW
    deactivate_alarm(ALARM_PIN);

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for alarm timing
    int alarm_active = 0;
    unsigned long alarm_start_time = 0;

    // Main loop
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value < 0 || sensor2_value < 0) {
            // Error reading sensor, exit loop
            program_running = 0;
            continue;
        }

        int threshold_exceeded_1 = check_threshold(sensor1_value);
        int threshold_exceeded_2 = check_threshold(sensor2_value);

        if (threshold_exceeded_1 || threshold_exceeded_2) {
            if (!alarm_active) {
                // First time threshold exceeded
                alarm_active = 1;
                alarm_start_time = gpioTick();
                if (threshold_exceeded_1) {
                    log_event("TILT START", 1);
                } else {
                    log_event("TILT START", 2);
                }
            } else {
                // Check if alarm duration has been reached
                if (gpioTick() - alarm_start_time >= ALARM_DURATION * 1000) {
                    activate_alarm(ALARM_PIN);
                    alarm_active = 2; // Indicate alarm is active
                }
            }
        } else {
            // Sensors are back to normal
            if (alarm_active == 1) {
                // Threshold exceeded but alarm not activated yet
                if (threshold_exceeded_1) {
                    log_event("TILT END", 1);
                } else {
                    log_event("TILT END", 2);
                }
            } else if (alarm_active == 2) {
                // Alarm is active, check if both sensors are back to normal
                if (!threshold_exceeded_1 && !threshold_exceeded_2) {
                    deactivate_alarm(ALARM_PIN);
                    alarm_active = 0;
                }
            }
        }

        gpioDelay(POLL_INTERVAL); // Delay for 100ms
    }

    // Clean up
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

