#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define ACCEL_Y_REG 0x2A
#define ACCEL_Z_REG 0x2C
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define LOG_FILE "seismic_events.log"
#define NUM_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the sensor
int init_sensor() {
    int retries = NUM_RETRIES;
    while (retries > 0) {
        // Verify sensor presence by reading CTRL1 register
        int ctrl1_value = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (ctrl1_value >= 0) {
            printf("Sensor found, CTRL1 value: 0x%X\n", ctrl1_value);

            // Clear power-down bit in CTRL1 register (set to 0x00)
            if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) == 0) {
                printf("Sensor initialized successfully.\n");
                return 0; // Success
            } else {
                fprintf(stderr, "Error writing to CTRL1 register: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading CTRL1 register: %s\n", strerror(errno));
        }
        retries--;
        gpioDelay(100); // Wait before retrying
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = NUM_RETRIES;
    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG, buffer, 6) == 6) {
            // Convert little-endian data to int16_t
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
            retries--;
            gpioDelay(100); // Wait before retrying
        }
    }
    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Calculate the Euclidean vibration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log the event to a file
void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s, %.2f\n", buf, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("Event logged: %s, Magnitude: %.2f\n", buf, magnitude);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate vibration magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check if threshold is exceeded
            if (magnitude > VIBRATION_THRESHOLD) {
                printf("Vibration threshold exceeded: %.2f\n", magnitude);

                // Log the event
                log_event(magnitude);

                // Turn on LED
                gpioWrite(LED_GPIO, 1);
                gpioDelay(1000); // 1 second

                // Turn off LED
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

