// Define GPIO pins
#define SENSOR_1 4
#define SENSOR_2 17
#define SENSOR_3 27
#define SENSOR_4 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating program...\n", signal);
    program_running = 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to set LED state
void set_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1);
        int sensor2_value = read_sensor(SENSOR_2);
        int sensor3_value = read_sensor(SENSOR_3);
        int sensor4_value = read_sensor(SENSOR_4);

        // Check if any sensor detects an object
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0) {
            // Turn on the LED
            set_led(LED_PIN, 1);
        } else {
            // Turn off the LED
            set_led(LED_PIN, 0);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

