#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/file.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/var/log/flame_events.log"

// Sensor configuration
const int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char *sensor_ids[NUM_SENSORS] = {"sensor1", "sensor2", "sensor3", "sensor4", "sensor5"};

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_SENSORS];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce_sensor(struct gpiod_line *line, int initial_value);
void log_event(const char *sensor_id, int gpio_pin);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_USER | LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        syslog(LOG_USER | LOG_ERR, "Error reading sensor value: %s", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce sensor
int debounce_sensor(struct gpiod_line *line, int initial_value) {
    int current_value = read_sensor(line);
    if (current_value < 0) {
        return -1; // Propagate error
    }

    if (current_value == initial_value) {
        return initial_value;
    }

    struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 50ms
    nanosleep(&delay, NULL);

    int debounced_value = read_sensor(line);
    if (debounced_value < 0) {
        return -1; // Propagate error
    }

    return debounced_value;
}

// Function to log event
void log_event(const char *sensor_id, int gpio_pin) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        syslog(LOG_USER | LOG_ERR, "Error opening log file: %s", strerror(errno));
        return;
    }

    if (flock(log_fd, LOCK_EX) == -1) {
        syslog(LOG_USER | LOG_ERR, "Error acquiring lock on log file: %s", strerror(errno));
        close(log_fd);
        return;
    }

    FILE *log_file = fdopen(log_fd, "a");
    if (log_file == NULL) {
        syslog(LOG_USER | LOG_ERR, "Error opening log file stream: %s", strerror(errno));
        flock(log_fd, LOCK_UN);
        close(log_fd);
        return;
    }

    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(log_file);

    if (flock(log_fd, LOCK_UN) == -1) {
        syslog(LOG_USER | LOG_ERR, "Error releasing lock on log file: %s", strerror(errno));
    }

    fclose(log_file);
}

// Function to setup GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_USER | LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_USER | LOG_ERR, "Error getting GPIO line %d: %s", sensor_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "flame_monitor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            syslog(LOG_USER | LOG_ERR, "Error requesting GPIO line %d: %s", sensor_pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_USER | LOG_INFO, "Starting flame monitor...");

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_USER | LOG_ERR, "Error setting up signal handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (setup_gpio() != 0) {
        syslog(LOG_USER | LOG_ERR, "GPIO setup failed, exiting.");
        closelog();
        return 1;
    }

    int previous_values[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        previous_values[i] = read_sensor(lines[i]);
        if (previous_values[i] < 0) {
            syslog(LOG_USER | LOG_ERR, "Failed to read initial sensor value, exiting.");
            cleanup_gpio();
            closelog();
            return 1;
        }
    }

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_value = debounce_sensor(lines[i], previous_values[i]);
            if (current_value < 0) {
                syslog(LOG_USER | LOG_ERR, "Debounce failed for sensor %s (GPIO %d), continuing.", sensor_ids[i], sensor_pins[i]);
                continue;
            }

            if (current_value == 0 && previous_values[i] == 1) {
                log_event(sensor_ids[i], sensor_pins[i]);
            }

            previous_values[i] = current_value;
        }

        struct timespec sleep_time = {1, 0}; // 1 second
        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio();
    syslog(LOG_USER | LOG_INFO, "Flame monitor terminated.");
    closelog();
    return 0;
}

