#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the touch sensor channels
const int touch_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(touch_pins) / sizeof(touch_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to read the touch sensor channels
int read_touch_sensors(int *sensor_states)
{
    for (int i = 0; i < num_channels; i++)
    {
        int value = gpioRead(touch_pins[i]);
        if (value < 0)
        {
            fprintf(stderr, "Error reading GPIO pin %d: %s\n", touch_pins[i], strerror(errno));
            return -1; // Indicate an error
        }
        sensor_states[i] = value;
    }
    return 0; // Indicate success
}

// Function to log touch events
void log_touch_event(int channel, int state)
{
    char timestamp[21];
    get_iso8601_timestamp(timestamp);
    printf("%s - Channel %d (GPIO %d): %s\n", timestamp, channel, touch_pins[channel], state ? "Touched" : "Released");
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    for (int i = 0; i < num_channels; i++)
    {
        gpioSetMode(touch_pins[i], PI_INPUT);
    }

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Array to store the previous sensor states
    int previous_sensor_states[num_channels] = {0};

    // Main loop
    while (!terminate)
    {
        int current_sensor_states[num_channels];

        // Read the touch sensor channels
        if (read_touch_sensors(current_sensor_states) != 0)
        {
            fprintf(stderr, "Error reading touch sensors, exiting...\n");
            break; // Exit the loop on error
        }

        // Check for state changes and log events
        for (int i = 0; i < num_channels; i++)
        {
            if (current_sensor_states[i] != previous_sensor_states[i])
            {
                log_touch_event(i, current_sensor_states[i]);
                previous_sensor_states[i] = current_sensor_states[i];
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 milliseconds = 50000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

