#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_REG 0x04
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int veml7700_init(int i2c_handle);
float read_lux(int i2c_handle);
int set_led_brightness(int gpio, int brightness);
int log_data(FILE *log_file, float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VEML7700 initialization function
int veml7700_init(int i2c_handle) {
    uint8_t config_data[2] = {0x00, 0x00}; // ALS gain 1/8, ALS integration time 100ms
    int result = i2cWriteDevice(i2c_handle, (char *)config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read lux value from VEML7700
float read_lux(int i2c_handle) {
    uint8_t als_data[2];
    int result = i2cReadDevice(i2c_handle, (char *)als_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VEML7700 ALS register: %d\n", result);
        return -1.0;
    }

    uint16_t raw_value = (als_data[1] << 8) | als_data[0];
    return (float)raw_value * 0.0576;
}

// Function to set LED brightness using PWM
int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }
    gpioPWM(gpio, brightness);
    return 0;
}

// Function to log data to file
int log_data(FILE *log_file, float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VEML7700 sensor
    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux(i2c_handle);
        int brightness = 0;
        int error_code = 0;

        if (lux < 0) {
            error_code = -1; // I2C read error
            lux = 0.0; // Set lux to 0 to avoid further errors
        } else {
            // Adaptive brightness logic
            if (lux < 100) {
                brightness = 100;
            } else if (lux < 500) {
                brightness = 75;
            } else if (lux < 1000) {
                brightness = 50;
            } else {
                brightness = 25;
            }
        }

        if (set_led_brightness(PWM_GPIO, brightness) != 0) {
            error_code = -2; // PWM error
        }

        log_data(log_file, lux, brightness, error_code);

        sleep(1);
    }

    // Cleanup
    set_led_brightness(PWM_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

