#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define LED_PIN 17
#define TOUCH_SENSOR_START_PIN 2
#define NUM_TOUCH_SENSORS 8

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int touch_states[NUM_TOUCH_SENSORS];
static int last_touch_states[NUM_TOUCH_SENSORS];
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
int log_touch_event(int channel);
void process_touch_sensors();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    running = 0;
    gpioWrite(LED_PIN, 0); // Turn off LED
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially off

    // Set touch sensor pins as inputs with pull-down resistors
    for (int i = 0; i < NUM_TOUCH_SENSORS; i++) {
        int pin = TOUCH_SENSOR_START_PIN + i;
        gpioSetMode(pin, PI_INPUT);
        gpioSetPullUpDown(pin, PI_PUD_DOWN);
        touch_states[i] = 0; // Initialize touch states
        last_touch_states[i] = 0;
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Log touch event to file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
