#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define LUX_SCALE 0.01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_opt3001();
int read_opt3001(float *lux_value);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure for OPT3001 data
typedef struct {
    uint16_t exponent;
    uint16_t mantissa;
} opt3001_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the OPT3001 sensor
int config_opt3001() {
    uint16_t config_word = ((CONFIG_WORD >> 8) & 0xFF) | ((CONFIG_WORD << 8) & 0xFF00); // Byte swap
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_word);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for conversion
    return 0;
}

// Function to read data from the OPT3001 sensor
int read_opt3001(float *lux_value) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    uint16_t raw_data = ((result >> 8) & 0xFF) | ((result << 8) & 0xFF00); // Byte swap

    opt3001_data_t data;
    data.exponent = (raw_data >> 12) & 0x0F;
    data.mantissa = raw_data & 0x0FFF;

    *lux_value = data.mantissa * LUX_SCALE * (1 << data.exponent);
    return 0;
}

// Function to log data to a file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk
    printf("%s, %.2f\n", timestamp, lux_value);
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float lux_value;
    // Main loop
    while (!terminate) {
        if (read_opt3001(&lux_value) == 0) {
            log_data(lux_value);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

