#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure static allocation

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1; // Failure
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to release GPIO resources
void release_gpio() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    int value, prev_value = -1; // Initialize to an invalid value
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 50ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        release_gpio();
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input with pull-down bias
    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line for input: %s\n", strerror(errno));
        release_gpio();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        release_gpio();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        if (value != prev_value) {
            if (value == 1) {
                log_message("Touch Detected");
            } else {
                log_message("Touch Released");
            }
            prev_value = value;
            nanosleep(&debounce_delay, NULL); // Debounce
        }
        usleep(1000); // Small delay to reduce CPU usage
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    release_gpio();
    if (log_file) {
        fclose(log_file);
    }

    fprintf(stderr, "Exiting.\n");
    return EXIT_SUCCESS;
}

