#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define START_MEASUREMENT_COMMAND_1 0x36
#define START_MEASUREMENT_COMMAND_2 0x08
#define FLOW_RATE_CONVERSION_FACTOR 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int start_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
float convert_to_flow_rate(int16_t raw_flow);
int log_data(float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start continuous measurement
int start_measurement() {
    char command[2] = {START_MEASUREMENT_COMMAND_1, START_MEASUREMENT_COMMAND_2};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    gpioDelay(2); // Wait at least 2 ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    if (calculated_crc != data[len - 1]) {
        fprintf(stderr, "CRC validation failed: calculated 0x%02X, received 0x%02X\n", calculated_crc, data[len - 1]);
        return -1;
    }
    return 0;
}

// Function to convert raw flow to ml/min
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_CONVERSION_FACTOR;
}

// Function to log data to file
int log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        // Check if the file is newly created (empty)
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        }
        fseek(log_file, 0, SEEK_END); // Append mode
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Start measurement
    if (start_measurement() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[3];
    sensor_data_t parsed_data;
    float flow_rate;
    char status[16];

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 3) == 0) {
                // Parse data
                parsed_data.raw_flow = (int16_t)((sensor_data[0] << 8) | sensor_data[1]);
                parsed_data.crc = sensor_data[2];

                // Convert to flow rate
                flow_rate = convert_to_flow_rate(parsed_data.raw_flow);

                // Validate flow rate
                if (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) {
                    strcpy(status, "OK");
                } else {
                    strcpy(status, "INVALID");
                }
            } else {
                strcpy(status, "ERROR");
                flow_rate = 0.0; // Set a default value in case of error
            }
        } else {
            strcpy(status, "ERROR");
            flow_rate = 0.0; // Set a default value in case of error
        }

        // Log data
        if (log_data(flow_rate, status) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Attempt recovery on error
        if (strcmp(status, "ERROR") == 0) {
            fprintf(stderr, "Attempting I2C recovery...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Wait 100ms before re-initializing
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C recovery failed\n");
            } else {
                if (start_measurement() != 0) {
                    fprintf(stderr, "Measurement restart failed\n");
                }
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

