#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <stdbool.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to read the sensor value from a given GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a CSV file
void log_data(const char *timestamp, int left, int middle, int right) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO lines for the sensors
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        // Release already acquired lines
        if(left_line) gpiod_line_release(left_line);
        if(middle_line) gpiod_line_release(middle_line);
        if(right_line) gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as inputs
    if (gpiod_line_request_input(left_line, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_line, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_line, "right_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        // Release already acquired lines
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        // Release GPIO lines and close chip before exiting
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            goto next_iteration;
        }

        // Read the sensor values
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        // Check for errors during sensor reading
        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            free(timestamp);
            goto next_iteration;
        }

        // Log the data
        log_data(timestamp, left_value, middle_value, right_value);

        // Free the timestamp memory
        free(timestamp);

next_iteration:
        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

