static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals (SIGINT, SIGTERM)
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp as a string
static char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log the flame event to a file
static int log_flame_event(const char *timestamp)
{
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: Flame detected!\n", timestamp) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to handle the flame detection event
static void handle_flame_event(void *data)
{
    (void)data; // Suppress unused parameter warning
    char *timestamp = get_timestamp();

    printf("%s: Flame detected!\n", timestamp);

    if (log_flame_event(timestamp) != 0) {
        fprintf(stderr, "Error logging flame event.\n");
    }
}

int main()
{
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line request
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;

    // Request the line for event monitoring
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to monitor for flame events
    while (!terminate) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == -EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("gpiod_line_event_wait");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        handle_flame_event(NULL);
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

