#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIOCHIP "gpiochip4"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *touch_line = NULL;
struct gpiod_line *led_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int init_gpio(void);
int read_touch_sensor(void);
int toggle_led(int current_state);
int log_event(int led_state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get GPIO line for touch sensor
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line for touch sensor as input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(touch_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request GPIO line for LED as output
    memset(&config, 0, sizeof(config));
    config.consumer = "led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read touch sensor value
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        return -1;
    }
    return value;
}

// Toggle LED state
int toggle_led(int current_state) {
    int new_state = !current_state;
    if (gpiod_line_set_value(led_line, new_state) < 0) {
        fprintf(stderr, "Error setting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }
    return new_state;
}

// Log event to file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, LED State: %d\n", timestamp, led_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }
    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup(0); // Clean up before exiting
        return 1;
    }

    int led_state = 0; // Initial LED state

    printf("Touch sensor and LED control started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read touch sensor
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // If touch is detected (rising edge)
        if (touch_value == 1) {
            // Toggle LED
            led_state = toggle_led(led_state);
            if (led_state < 0) {
                fprintf(stderr, "Error toggling LED. Retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            // Log event
            if (log_event(led_state) < 0) {
                fprintf(stderr, "Error logging event. Retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            // Debounce delay (adjust as needed)
            usleep(200000); // 200ms
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    return 0;
}

