            if (log_event(led_state) < 0) {
                fprintf(stderr, "Error logging event. Retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            // Debounce delay (adjust as needed)
            usleep(200000); // 200ms
        }

        // Small delay to prevent busy-waiting
        usleep(10000); // 10ms
    }

    return 0;
}

