#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log touch event with timestamp
void log_touch_event() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Log file not open\n");
    }
    free(timestamp);
}

// Function to toggle the LED
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0; // Initialize to no touch
    unsigned int last_touch_time = 0; // Initialize last touch time

    // Main loop
    while (running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            unsigned int current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_MS * 1000) { // Debounce
                toggle_led();
                log_touch_event();
                last_touch_time = current_time;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

