#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define sensor GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);
int initialize_gpio(void);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates current_states, previous_states;

// Function to read sensor state
int read_sensor(int pin) {
    int state = gpioRead(pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on pin %d: %d\n", pin, state);
        return -1; // Indicate error
    }
    return state;
}

// Function to log events to file
void log_event(int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor %d: %s\n", buf, sensor_id, state ? "Removed" : "Present");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes and pull-up resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR1_PIN);
        return -1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR2_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR2_PIN);
        return -1;
    }

    if (gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR3_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR3_PIN);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read initial sensor states
    current_states.sensor1_state = read_sensor(SENSOR1_PIN);
    current_states.sensor2_state = read_sensor(SENSOR2_PIN);
    current_states.sensor3_state = read_sensor(SENSOR3_PIN);

    if (current_states.sensor1_state == -1 || current_states.sensor2_state == -1 || current_states.sensor3_state == -1) {
        fprintf(stderr, "Error reading initial sensor states. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    previous_states = current_states; // Initialize previous states

    // Main loop
    while (program_running) {
        // Read sensor states
        current_states.sensor1_state = read_sensor(SENSOR1_PIN);
        current_states.sensor2_state = read_sensor(SENSOR2_PIN);
        current_states.sensor3_state = read_sensor(SENSOR3_PIN);

        // Log state changes
        if (current_states.sensor1_state != previous_states.sensor1_state && current_states.sensor1_state != -1) {
            log_event(1, current_states.sensor1_state);
        }
        if (current_states.sensor2_state != previous_states.sensor2_state && current_states.sensor2_state != -1) {
            log_event(2, current_states.sensor2_state);
        }
        if (current_states.sensor3_state != previous_states.sensor3_state && current_states.sensor3_state != -1) {
            log_event(3, current_states.sensor3_state);
        }

        // Update previous states
        previous_states = current_states;

