#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define BPM_SCALE_FACTOR 0.5
#define MOVING_AVG_SIZE 5
#define BPM_MIN 30.0
#define BPM_MAX 220.0
#define LOG_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int led_current;
    int averaging;
    int enable;
} sensor_config_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus(int bus, int addr);
int verify_sensor(int handle);
int configure_sensor(int handle, sensor_config_t config);
int read_heart_rate(int handle);
double convert_to_bpm(int raw_value);
double apply_moving_average(double new_value, double *history, int history_size, int *index);
int log_heart_rate(double bpm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Verify sensor presence and ID
int verify_sensor(int handle) {
    int part_id = i2cReadByteData(handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    int hw_rev = i2cReadByteData(handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    printf("Sensor verified (PART_ID: 0x%02X, HW_REV: 0x%02X)\n", part_id, hw_rev);
    return 0;
}

// Configure the sensor
int configure_sensor(int handle, sensor_config_t config) {
    int result;

    result = i2cWriteByteData(handle, LED_CURRENT_REG, config.led_current);
    if (result < 0) {
        fprintf(stderr, "Error writing LED_CURRENT register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(handle, AVERAGING_REG, config.averaging);
    if (result < 0) {
        fprintf(stderr, "Error writing AVERAGING register: %d\n", result);
        return -1;
    }

    result = i2cWriteByteData(handle, ENABLE_REG, config.enable);
    if (result < 0) {
        fprintf(stderr, "Error writing ENABLE register: %d\n", result);
        return -1;
    }

    printf("Sensor configured\n");
    return 0;
}

// Read heart rate data from the sensor
int read_heart_rate(int handle) {
    int raw_value = i2cReadWordData(handle, HEART_RATE_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading heart rate register: %d\n", raw_value);
        return -1;
    }
    return raw_value;
}

// Convert raw value to BPM
double convert_to_bpm(int raw_value) {
    return raw_value * BPM_SCALE_FACTOR;
}

// Apply moving average filter
double apply_moving_average(double new_value, double *history, int history_size, int *index) {
    static double sum = 0.0;
    sum -= history[*index];
    sum += new_value;
    history[*index] = new_value;
    *index = (*index + 1) % history_size;
    return sum / history_size;
}

// Log heart rate data to file
int log_heart_rate(double bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately

    printf("%s,%.2f\n", timestamp, bpm);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI1182_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    sensor_config_t config = { .led_current = 0x3F, .averaging = 0x04, .enable = 0x01 };
    if (configure_sensor(i2c_handle, config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Moving average filter variables
    double bpm_history[MOVING_AVG_SIZE] = {0.0};
    int history_index = 0;

    // Main loop
    while (!terminate) {
        // Read heart rate
        int raw_value = read_heart_rate(i2c_handle);
        if (raw_value >= 0) {
            // Convert to BPM
            double bpm = convert_to_bpm(raw_value);

            // Apply moving average filter
            double filtered_bpm = apply_moving_average(bpm, bpm_history, MOVING_AVG_SIZE, &history_index);

            // Validate BPM range
            if (filtered_bpm >= BPM_MIN && filtered_bpm <= BPM_MAX) {
                // Log heart rate
                log_heart_rate(filtered_bpm);
            } else {
                fprintf(stderr, "BPM out of range: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

