#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define OUTPUT_PINS {17, 18, 19, 20, 21, 22, 23, 24}

// Define constants
#define NUM_CHANNELS 8
#define STABILIZATION_DELAY_MS 200
#define POLLING_INTERVAL_MS 10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_lines[NUM_CHANNELS];
static struct gpiod_line *output_lines[NUM_CHANNELS];
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int read_sensor_data(int *sensor_values);
int update_counter(int *sensor_values, int *counter);
int update_outputs(int counter);
int log_event(int channel, int counter);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i, ret;
    const int sensor_pins[] = SENSOR_PINS;
    const int output_pins[] = OUTPUT_PINS;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request sensor lines for input
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            perror("Error getting sensor line");
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        ret = gpiod_line_request(sensor_lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting sensor line");
            goto cleanup;
        }
    }

    // Request output lines for output
    for (i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines[i]) {
            perror("Error getting output line");
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        ret = gpiod_line_request(output_lines[i], &config, 0);
        if (ret < 0) {
            perror("Error requesting output line");
            goto cleanup;
        }
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY_MS * 1000);

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Read sensor data
int read_sensor_data(int *sensor_values) {
    int i, ret;

    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_get_value(sensor_lines[i]);
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor line %d: %s\n", i + 1, strerror(errno));
            sensor_values[i] = 0; // Set to 0 to avoid affecting the counter
        } else {
            sensor_values[i] = ret;
        }
    }
    return 0;
}

// Update counter based on sensor data
int update_counter(int *sensor_values, int *counter) {
    static int previous_sensor_values[NUM_CHANNELS] = {0};
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_values[i] == 1 && previous_sensor_values[i] == 0) {
            // Rising edge detected
            *counter = (*counter + 1) % 256;
            printf("Touch on channel %d | Counter: %d\n", i + 1, *counter);
            log_event(i + 1, *counter);
        }
        previous_sensor_values[i] = sensor_values[i];
    }
    return 0;
}

// Update output pins
int update_outputs(int counter) {
    int i, ret;

    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_set_value(output_lines[i], (counter >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting output line %d: %s\n", i + 17, strerror(errno));
        }
    }
    return 0;
}

// Log event to file
int log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk
    } else {
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    int i;

    // Release output lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
        }
    }

    // Release sensor lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int sensor_values[NUM_CHANNELS] = {0};
    int counter = 0;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout.\n");
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_values) != 0) {
            fprintf(stderr, "Error reading sensor data. Continuing.\n");
        }

        // Update counter
        update_counter(sensor_values, &counter);

        // Update outputs
        update_outputs(counter);

        // Wait for the next polling interval
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    return 0;
}

