#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Define the CSV file name
#define CSV_FILE "tracking_log.csv"

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int pin;
} gpio_line_t;

// Global variables
static volatile sig_atomic_t keep_running = 1;
static FILE *csv_file = NULL;
static gpio_line_t sensor_lines[4];

// Function prototypes
int initialize_gpio(gpio_line_t *sensor_lines);
int read_sensor_data(int sensor_index);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void cleanup_gpio(gpio_line_t *sensor_lines);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_line_t *sensor_lines) {
    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (int i = 0; i < 4; i++) {
        sensor_lines[i].pin = pins[i];
        sensor_lines[i].chip = gpiod_chip_open_by_name(CHIP_NAME);
        if (!sensor_lines[i].chip) {
            fprintf(stderr, "Error opening chip %s for pin %d: %s\n", CHIP_NAME, pins[i], strerror(errno));
            return -1;
        }

        sensor_lines[i].line = gpiod_chip_get_line(sensor_lines[i].chip, pins[i]);
        if (!sensor_lines[i].line) {
            fprintf(stderr, "Error getting line %d: %s\n", pins[i], strerror(errno));
            gpiod_chip_close(sensor_lines[i].chip);
            return -1;
        }

        int ret = gpiod_line_request_input(sensor_lines[i].line, "ir_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting input for line %d: %s\n", pins[i], strerror(errno));
            gpiod_chip_close(sensor_lines[i].chip);
            return -1;
        }
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int sensor_index) {
    int value = gpiod_line_get_value(sensor_lines[sensor_index].line);
    if (value < 0) {
        fprintf(stderr, "Error reading value from sensor %d: %s\n", sensor_lines[sensor_index].pin, strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(gpio_line_t *sensor_lines) {
    for (int i = 0; i < 4; i++) {
        if (sensor_lines[i].line) {
            gpiod_line_release(sensor_lines[i].line);
        }
        if (sensor_lines[i].chip) {
            gpiod_chip_close(sensor_lines[i].chip);
        }
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio(sensor_lines) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup_gpio(sensor_lines);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(csv_file);
    }

    // Main loop
    while (keep_running) {
        int sensor1_value = read_sensor_data(0);
        int sensor2_value = read_sensor_data(1);
        int sensor3_value = read_sensor_data(2);
        int sensor4_value = read_sensor_data(3);

        if (sensor1_value >= 0 && sensor2_value >= 0 && sensor3_value >= 0 && sensor4_value >= 0) {
            log_data(csv_file, sensor1_value, sensor2_value, sensor3_value, sensor4_value);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup and exit
    fclose(csv_file);
    cleanup_gpio(sensor_lines);
    fprintf(stderr, "Program finished.\n");
    return 0;
}

