#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"

static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor state and last event time
typedef struct {
    int last_state;
    struct timespec last_event_time;
} sensor_state_t;

sensor_state_t sensor17_state = {1, {0, 0}};
sensor_state_t sensor18_state = {1, {0, 0}};

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log tilt event
void log_tilt_event(int sensor_number) {
    char* timestamp = get_timestamp();
    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fflush(log_file); // Ensure immediate write to file
}

// Function to read sensor value with error handling
int read_sensor(struct gpiod_line *line, int sensor_number) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", sensor_number, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to check for tilt event with debouncing
int check_tilt_event(struct gpiod_line *line, int sensor_number, sensor_state_t *sensor_state) {
    int current_value = read_sensor(line, sensor_number);
    if (current_value < 0) return 0; // Error reading sensor, no event

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (current_value == 0 && sensor_state->last_state == 1) {
        // Falling edge detected
        double time_diff = (now.tv_sec - sensor_state->last_event_time.tv_sec) + 
                           (now.tv_nsec - sensor_state->last_event_time.tv_nsec) / 1e9;

        if (time_diff * 1000 >= 50) { // Debounce window: 50ms
            log_tilt_event(sensor_number);
            sensor_state->last_event_time = now;
            sensor_state->last_state = 0;
            return 1; // Event occurred
        }
    } else if (current_value == 1 && sensor_state->last_state == 0) {
        // Rising edge detected
        sensor_state->last_state = 1;
    }

    return 0; // No event
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);

    if (!line17 || !line18) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs with pull-up
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "tilt_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(line17, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(line18, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 18: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        return 1;
    }

    // Main loop
    while (!terminate) {
        check_tilt_event(line17, 1, &sensor17_state);
        check_tilt_event(line18, 2, &sensor18_state);
        usleep(100000); // 100ms
    }

    // Cleanup
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

