#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_chip *chip = NULL;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int set_led(struct gpiod_line *line, int value);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Turn off the LED
        if (led_line) {
            set_led(led_line, 0);
        }

        // Release GPIO lines
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }
        if (led_line) {
            gpiod_line_release(led_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        // Close log file
        if (log_file) {
            fclose(log_file);
        }

        exit(0);
    }
}

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to set LED state
int set_led(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting LED value");
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int ret = fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state);
    if (ret < 0) {
        perror("Error writing to log file");
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!sensor1_line || !sensor2_line || !led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "sensor_input";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "led_output";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(sensor1_line, &input_config, 0) < 0 ||
        gpiod_line_request(sensor2_line, &input_config, 0) < 0 ||
        gpiod_line_request(led_line, &output_config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break;
        }

        int led_state = 0;
        if (sensor1_value == 0 && sensor2_value == 0) {
            if (set_led(led_line, 1) == 0) {
                led_state = 1;
            }
        } else {
            if (set_led(led_line, 0) == 0) {
                led_state = 0;
            }
        }

        if (log_data(log_file, sensor1_value, sensor2_value, led_state) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup (in case of error in the main loop)
    signal_handler(SIGINT);

    return 0;
}

