#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling period (microseconds)
#define SAMPLING_PERIOD 125

// Define LED on time (milliseconds)
#define LED_ON_TIME 100

// Global flag for signal handling
volatile sig_atomic_t terminate_flag = 0;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate_flag = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate_flag) {
        // Read microphone input
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", MIC_PIN);
            break; // Exit loop on error
        }

        // Check for peak detection (HIGH signal)
        if (mic_value == 1) {
            // Get current timestamp
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Failed to get current time\n");
                break; // Exit loop on error
            }

            // Print timestamp to stdout
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Turn LED ON
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }

            // Delay for LED on time
            gpioDelay(LED_ON_TIME * 1000); // Convert milliseconds to microseconds

            // Turn LED OFF
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD);
    }

    // Clean up and terminate
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

