        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate_flag) {
        // Read microphone input
        int mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read GPIO%d\n", MIC_PIN);
            break; // Exit loop on error
        }

        // Check for peak detection (HIGH signal)
        if (mic_value == 1) {
            // Get current timestamp
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                fprintf(stderr, "Failed to get current time\n");
                break; // Exit loop on error
            }

            // Print timestamp to stdout
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Turn LED ON
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }

            // Delay for LED on time
            gpioDelay(LED_ON_TIME * 1000); // Convert milliseconds to microseconds

            // Turn LED OFF
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
                break; // Exit loop on error
            }
        }

        // Delay for sampling period
        gpioDelay(SAMPLING_PERIOD);
    }

    // Clean up and terminate
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

