void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (center_line) {
        gpiod_line_release(center_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for the sensors
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !center_line || !right_line) {
        perror("Error getting GPIO line");
        // Release already acquired lines
        if (left_line) gpiod_line_release(left_line);
        if (center_line) gpiod_line_release(center_line);
        if (right_line) gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs with pull-up enabled
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "tracing_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(left_line, &config, 0) < 0) {
        perror("Error requesting left GPIO line");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request(center_line, &config, 0) < 0) {
        perror("Error requesting center GPIO line");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
