    while (1) {
        int left_value = gpiod_line_get_value(left_line);
        int center_value = gpiod_line_get_value(center_line);
        int right_value = gpiod_line_get_value(right_line);

        if (left_value < 0 || center_value < 0 || right_value < 0) {
            perror("Error reading GPIO line value");
            // Attempt to recover by re-requesting the line
            struct gpiod_line_request_config recover_config;
            memset(&recover_config, 0, sizeof(recover_config));
            recover_config.consumer = "tracing_sensor";
            recover_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
            recover_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

            if (left_value < 0) {
                gpiod_line_release(left_line);
                left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
                if (left_line && gpiod_line_request(left_line, &recover_config, 0) < 0) {
                    perror("Error re-requesting left GPIO line");
                    // Handle fatal error if recovery fails
                    signal_handler(SIGTERM);
                }
            }
            if (center_value < 0) {
                gpiod_line_release(center_line);
                center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
                if (center_line && gpiod_line_request(center_line, &recover_config, 0) < 0) {
                    perror("Error re-requesting center GPIO line");
                    // Handle fatal error if recovery fails
                    signal_handler(SIGTERM);
                }
            }
            if (right_value < 0) {
                gpiod_line_release(right_line);
                right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
                if (right_line && gpiod_line_request(right_line, &recover_config, 0) < 0) {
                    perror("Error re-requesting right GPIO line");
                    // Handle fatal error if recovery fails
                    signal_handler(SIGTERM);
                }
            }

            // Retry reading after recovery attempt
            continue;
        }

        // Log sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 100 milliseconds
        usleep(100000);
    }

    return 0;
}

