#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// I2C bus and address
#define I2C_BUS 1
#define SI1175_ADDR 0x49

// Register addresses
#define ALS_VIS_DATA_LSB 0x24
#define ALS_VIS_DATA_MSB 0x25

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a register from the Si1175
int read_register(int fd, uint8_t reg_addr, uint8_t *data) {
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint8_t lsb, msb;
        uint16_t als_value;

        // Read LSB
        if (read_register(i2c_fd, ALS_VIS_DATA_LSB, &lsb) < 0) {
            fprintf(stderr, "Error reading LSB, exiting...\n");
            close(i2c_fd);
            return 1;
        }

        // Read MSB
        if (read_register(i2c_fd, ALS_VIS_DATA_MSB, &msb) < 0) {
            fprintf(stderr, "Error reading MSB, exiting...\n");
            close(i2c_fd);
            return 1;
        }

        // Combine LSB and MSB into 16-bit value
        als_value = (msb << 8) | lsb;

        // Log the raw sensor value
        printf("ALS Visible: %u\n", als_value);

        // Wait 100ms
        usleep(100000);
    }

    // This point should not be reached due to the infinite loop
    close(i2c_fd);
    return 0;
}

