#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

// Define GPIO pins for TP1-TP8
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = 8;

// Global variables for chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8];

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines as inputs
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", gpio_pins[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

        printf("[%2.3fs] ", timestamp);

        for (int i = 0; i < num_channels; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d: %s\n", gpio_pins[i], strerror(errno));
                // Attempt to continue, but log the error
            } else {
                printf("CH%d=%d ", i + 1, value);
            }
        }
        printf("\n");

        // Wait 200ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

