#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// PWM frequency
#define PWM_FREQUENCY 1000

// Fade duration in seconds
#define FADE_DURATION 5

// Number of fade steps
#define FADE_STEPS 50

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function prototypes
int initialize_gpio();
RGBColor generate_random_hue();
RGBColor hsv_to_rgb(float hue, float saturation, float value);
void set_led_color(RGBColor color);
void fade_to_color(RGBColor target_color);
void signal_handler(int signal);
void cleanup();

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        return 1;
    }
    unsigned int seed;
    fread(&seed, sizeof(seed), 1, urandom);
    fclose(urandom);
    srand(seed);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        closelog();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop: randomly generate hues and fade to the corresponding colors
    while (program_running) {
        RGBColor target_color = generate_random_hue();
        fade_to_color(target_color);
        sleep(FADE_DURATION);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Initializes the pigpio library and configures the GPIO pins.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d to output mode", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d to output mode", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d to output mode", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency for GPIO%d", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Generates a random hue value between 0 and 360.
RGBColor generate_random_hue() {
    float hue = (float)(rand() % 360);
    return hsv_to_rgb(hue, 1.0, 1.0);
}

// Converts an HSV color to an RGB color.
RGBColor hsv_to_rgb(float hue, float saturation, float value) {
    RGBColor rgb;
    float c = value * saturation;
    float x = c * (1 - abs(fmod(hue / 60.0, 2) - 1));
    float m = value - c;

    float r, g, b;

    if (hue < 60) {
        r = c; g = x; b = 0;
    } else if (hue < 120) {
        r = x; g = c; b = 0;
    } else if (hue < 180) {
        r = 0; g = c; b = x;
    } else if (hue < 240) {
        r = 0; g = x; b = c;
    } else if (hue < 300) {
        r = x; g = 0; b = c;
    } else {
        r = c; g = 0; b = x;
    }

    rgb.red = (int)((r + m) * 255);
    rgb.green = (int)((g + m) * 255);
    rgb.blue = (int)((b + m) * 255);

    // Clamp values to [0, 255]
    rgb.red = (rgb.red < 0) ? 0 : (rgb.red > 255) ? 255 : rgb.red;
    rgb.green = (rgb.green < 0) ? 0 : (rgb.green > 255) ? 255 : rgb.green;
    rgb.blue = (rgb.blue < 0) ? 0 : (rgb.blue > 255) ? 255 : rgb.blue;

    return rgb;
}

// Sets the RGB LED color using hardware PWM.
void set_led_color(RGBColor color) {
    gpioPWM(RED_PIN, 255 - color.red);
    gpioPWM(GREEN_PIN, 255 - color.green);
    gpioPWM(BLUE_PIN, 255 - color.blue);
}

// Fades the LED color to the target color over FADE_DURATION seconds.
void fade_to_color(RGBColor target_color) {
    RGBColor current_color;
    current_color.red = 255 - gpioGetPWMdutycycle(RED_PIN);
    current_color.green = 255 - gpioGetPWMdutycycle(GREEN_PIN);
    current_color.blue = 255 - gpioGetPWMdutycycle(BLUE_PIN);

    float red_diff = (float)(target_color.red - current_color.red) / FADE_STEPS;
    float green_diff = (float)(target_color.green - current_color.green) / FADE_STEPS;
    float blue_diff = (float)(target_color.blue - current_color.blue) / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        current_color.red += red_diff;
        current_color.green += green_diff;
        current_color.blue += blue_diff;

        // Clamp values to [0, 255]
        current_color.red = (current_color.red < 0) ? 0 : (current_color.red > 255) ? 255 : current_color.red;
        current_color.green = (current_color.green < 0) ? 0 : (current_color.green > 255) ? 255 : current_color.green;
        current_color.blue = (current_color.blue < 0) ? 0 : (current_color.blue > 255) ? 255 : current_color.blue;

        set_led_color(current_color);
        usleep(FADE_DURATION * 1000000 / FADE_STEPS); // Delay for each step
    }
}

// Signal handler for graceful shutdown.
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Cleans up GPIO resources and terminates the pigpio library.
void cleanup() {
    // Turn off the LED
    set_led_color((RGBColor){0, 0, 0});

    // Terminate pigpio
    gpioTerminate();

    syslog(LOG_INFO, "Cleanup complete");
}

