#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_CONTROL         0x0F
#define TCS34725_ID              0x12
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// GPIO Pin
#define LED_GPIO_PIN            17

// I2C Bus
#define I2C_BUS                 "/dev/i2c-1"

// Calibration Parameters
#define RED_GAIN                1.0
#define RED_OFFSET              0
#define GREEN_GAIN              1.0
#define GREEN_OFFSET            0
#define BLUE_GAIN               1.0
#define BLUE_OFFSET             0
#define CLEAR_GAIN              1.0
#define CLEAR_OFFSET            0

// Red Threshold
#define RED_THRESHOLD           200

// Global Variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_red, float *calibrated_green, float *calibrated_blue, float *calibrated_clear);
void led_control(int value);
void signal_handler(int sig);

// Signal Handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting...\n", sig);
}

// TCS34725 Initialization
int tcs34725_init(int fd) {
    uint8_t buf[2];
    int ret;

    // Enable Power-On (PON)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x01; // PON
    ret = write(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device (PON): %s\n", strerror(errno));
        return -1;
    }
    usleep(3); // Wait for power-on

    // Enable RGBC (AEN)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x03; // PON | AEN
    ret = write(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device (AEN): %s\n", strerror(errno));
        return -1;
    }

    // Set Integration Time (ATIME = 0x00 for 154ms)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device (ATIME): %s\n", strerror(errno));
        return -1;
    }

    // Set Gain (CONTROL = 0x00 for 1x gain)
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CONTROL;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device (CONTROL): %s\n", strerror(errno));
        return -1;
    }

    // Verify Sensor ID
    uint8_t id;
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ID;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device (ID read): %s\n", strerror(errno));
        return -1;
    }
    ret = read(fd, &id, 1);
    if (ret != 1) {
        fprintf(stderr, "Error reading from I2C device (ID read): %s\n", strerror(errno));
        return -1;
    }

    if (id != 0x44) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", id);
        return -1;
    }

    printf("TCS34725 initialized successfully.\n");
    return 0;
}

// TCS34725 Data Reading
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[1];
    uint8_t data[8];
