    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device (data read): %s\n", strerror(errno));
        return -1;
    }
    ret = read(fd, data, 8);
    if (ret != 8) {
        fprintf(stderr, "Error reading from I2C device (data read): %s\n", strerror(errno));
        return -1;
