#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define WS2812B_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x10
#define NUM_LEDS 10
#define MAX_LUX 1000.0

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_bh1750();
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(BH1750_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
float read_bh1750() {
    int retries = 3;
    while (retries > 0) {
        if (wiringPiI2CWrite(i2c_fd, BH1750_CMD) == -1) {
            fprintf(stderr, "Error: Failed to write to BH1750, retrying...\n");
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        gpioDelay(180000); // 180ms delay

        int msb = wiringPiI2CReadReg8(i2c_fd, 0x00);
        int lsb = wiringPiI2CReadReg8(i2c_fd, 0x01);

        if (msb == -1 || lsb == -1) {
            fprintf(stderr, "Error: Failed to read from BH1750, retrying...\n");
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        unsigned int raw_value = (msb << 8) | lsb;
        float lux = (float)raw_value / 1.2;
        return lux;
    }

    fprintf(stderr, "Error: Failed to read BH1750 after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to LED brightness (0-255)
int map_lux_to_brightness(float lux) {
    if (lux < 0) return 0; // Handle error case
    if (lux > MAX_LUX) lux = MAX_LUX;

    float normalized_lux = lux / MAX_LUX;
    float brightness_float = 255.0 * sqrt(normalized_lux); // Logarithmic mapping
    int brightness = (int)brightness_float;
    return brightness;
}

// Set LED strip brightness using pigpio
void set_led_brightness(int brightness) {
    gpioPWM(WS2812B_GPIO, brightness);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for WS2812B
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(WS2812B_GPIO, 255);

    // Set PWM frequency (adjust as needed for WS2812B)
    gpioSetPWMfrequency(WS2812B_GPIO, 800000); // 800 kHz

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("WS2812B LED strip control with BH1750 light sensor.\n");
    printf("Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read light level
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error: Failed to read light level, using previous value.\n");
            // Consider using a default brightness or previous reading here
            continue;
        }

        // Map lux to brightness
        int brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Clean up
    set_led_brightness(0); // Turn off LEDs
    gpioTerminate();
    return 0;
}

