#include <errno.h>
#include <string.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define NUM_LEDS 10 // Example number of LEDs

// Global variables for file descriptors
int i2c_fd = -1;
int spi_fd = -1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t data);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
float read_bh1750_lux(int fd);
int map_lux_to_brightness(float lux);
int send_apa102_frame(int fd, int brightness, int num_leds);
void signal_handler(int sig);

// I2C read function
int i2c_read_bytes(int fd, uint8_t *data, int len) {
  if (read(fd, data, len) != len) {
    fprintf(stderr, "I2C read error: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t data) {
  if (write(fd, &data, 1) != 1) {
    fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
  struct spi_ioc_transfer transfer = {
    .tx_buf = (unsigned long)tx_buf,
    .rx_buf = (unsigned long)rx_buf,
    .len = len,
    .speed_hz = 1000000, // 1 MHz
    .bits_per_word = 8,
  };

  if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
    fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
    return -1;
  }
  return 0;
}

// Function to read lux value from BH1750
float read_bh1750_lux(int fd) {
  uint8_t data[2];
  uint16_t raw_value;

  // Set BH1750 to One-Time High-Resolution Mode
  if (i2c_write_byte(fd, 0x20) < 0) {
    fprintf(stderr, "Failed to set BH1750 mode.\n");
    return -1.0f;
  }

  // Wait for conversion (at least 120ms)
  usleep(150000); // 150ms

  // Read 2 bytes of data
  if (i2c_read_bytes(fd, data, 2) < 0) {
    fprintf(stderr, "Failed to read BH1750 data.\n");
    return -1.0f;
  }

  // Combine the bytes to form the raw value
  raw_value = (data[0] << 8) | data[1];

  // Convert raw value to lux
  return (float)raw_value / 1.2;
}

// Function to map lux value to APA102 brightness
int map_lux_to_brightness(float lux) {
  int brightness;

  // Clamp lux value to the defined range
  if (lux < 10.0f) {
    lux = 10.0f;
  } else if (lux > 300.0f) {
    lux = 300.0f;
  }

  // Map lux value to brightness (0-31)
  brightness = (int)(((lux - 10.0f) / (300.0f - 10.0f)) * 31.0f);

  return brightness;
}

// Function to send APA102 frame
int send_apa102_frame(int fd, int brightness, int num_leds) {
  uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
  uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
  uint8_t led_frame[4];
  int i;

  // Send start frame
  if (spi_transfer(fd, (uint8_t*)start_frame, NULL, 4) < 0) {
    fprintf(stderr, "Failed to send start frame.\n");
    return -1;
  }

  // Send LED frames
  for (i = 0; i < num_leds; i++) {
    led_frame[0] = 0xE0 | (brightness & 0x1F); // Global brightness
    led_frame[1] = 0x00; // Blue
    led_frame[2] = 0x00; // Green
    led_frame[3] = 0x00; // Red

    if (spi_transfer(fd, led_frame, NULL, 4) < 0) {
      fprintf(stderr, "Failed to send LED frame %d.\n", i);
      return -1;
    }
  }

  // Send end frame
  if (spi_transfer(fd, (uint8_t*)end_frame, NULL, 4) < 0) {
    fprintf(stderr, "Failed to send end frame.\n");
    return -1;
  }

  return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
  fprintf(stderr, "Caught signal %d, shutting down...\n", sig);

  // Turn off LEDs (send all zeros)
  if (spi_fd != -1) {
    uint8_t zero_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t led_frame[4] = {0x00, 0x00, 0x00, 0x00};
    int i;

    // Send start frame
    spi_transfer(spi_fd, (uint8_t*)zero_frame, NULL, 4);

    // Send LED frames with zero brightness
    for (i = 0; i < NUM_LEDS; i++) {
      spi_transfer(spi_fd, led_frame, NULL, 4);
    }

    // Send end frame
    spi_transfer(spi_fd, (uint8_t*)zero_frame, NULL, 4);
  }

  // Close file descriptors
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (spi_fd != -1) {
    close(spi_fd);
  }

  exit(0);
}

int main() {
