#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD 0x21
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10 // Example number of LEDs

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float calculate_average_lux(int lux1, int lux2, int lux3);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int spi_handle, int brightness);
void fade_brightness(int spi_handle, int target_brightness, int current_brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) return -1; // Invalid handle

    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CMD) != 0) {
        fprintf(stderr, "Error writing to BH1750: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(180); // Wait for conversion

    int lux = i2cReadWordData(i2c_handle, 0x00);
    if (lux < 0) {
        fprintf(stderr, "Error reading from BH1750: %d\n", i2c_handle);
        return -1;
    }

    // BH1750 returns big-endian, convert to little-endian
    lux = ((lux & 0xFF00) >> 8) | ((lux & 0x00FF) << 8);

    return lux;
}

// Function to calculate the average lux value
float calculate_average_lux(int lux1, int lux2, int lux3) {
    float sum = 0.0;
    int count = 0;

    if (lux1 >= 0) { sum += lux1; count++; }
    if (lux2 >= 0) { sum += lux2; count++; }
    if (lux3 >= 0) { sum += lux3; count++; }

    if (count == 0) return 0.0; // Avoid division by zero
    return sum / count;
}

// Function to map lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Use a logarithmic mapping for better perceptual brightness
    float brightness_float = 31.0 * (1.0 - (log10(average_lux + 1) / log10(10000))); // Assuming max lux is 10000
    if (brightness_float < 0) brightness_float = 0;
    if (brightness_float > 31) brightness_float = 31;
    return (int)brightness_float;
}

// Function to set the brightness of the APA102 LED strip
void set_apa102_brightness(int spi_handle, int brightness) {
    if (spi_handle < 0) return; // Invalid handle

    // APA102 start frame (32 bytes of 0x00)
    char start_frame[32] = {0x00};
    spiWrite(spi_handle, start_frame, 32);

    // LED data frames (brightness, blue, green, red)
    char led_data[4];
    led_data[0] = 0xE0 | brightness; // Global brightness
    led_data[1] = 0x00; // Blue
    led_data[2] = 0x00; // Green
    led_data[3] = 0x00; // Red

    for (int i = 0; i < NUM_LEDS; i++) {
        spiWrite(spi_handle, led_data, 4);
    }

    // APA102 end frame (at least (NUM_LEDS / 2) bytes of 0xFF, rounded up to multiple of 4)
    int end_frame_size = ((NUM_LEDS + 1) / 2) + ((NUM_LEDS + 1) / 2) % 2; // Calculate size
    char end_frame[end_frame_size];
    for (int i = 0; i < end_frame_size; i++) {
        end_frame[i] = 0xFF;
    }
    spiWrite(spi_handle, end_frame, end_frame_size);
}

// Function to fade the brightness of the APA102 LED strip
void fade_brightness(int spi_handle, int target_brightness, int current_brightness) {
    if (spi_handle < 0) return; // Invalid handle

    int step = (target_brightness > current_brightness) ? 1 : -1;
    for (int i = current_brightness; i != target_brightness; i += step) {
        set_apa102_brightness(spi_handle, i);
        gpioDelay(5); // Adjust delay for desired fade speed
    }
    set_apa102_brightness(spi_handle, target_brightness); // Ensure final brightness is set
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_low = i2cOpen(1, BH1750_ADDR_LOW, 0);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", BH1750_ADDR_LOW, i2c_handle_low);
        i2c_handle_low = -1; // Mark as invalid
    }

    i2c_handle_high = i2cOpen(1, BH1750_ADDR_HIGH, 0);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", BH1750_ADDR_HIGH, i2c_handle_high);
        i2c_handle_high = -1; // Mark as invalid
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI_MODE0
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int current_brightness = 0; // Initial brightness

    // Main loop
    while (!terminate) {
        // Read lux values from sensors
        int lux1 = (i2c_handle_low >= 0) ? read_bh1750(i2c_handle_low) : -1;
        int lux2 = (i2c_handle_high >= 0) ? read_bh1750(i2c_handle_high) : -1;
        int lux3 = -1; // No third sensor in this example

        // Calculate average lux
        float average_lux = calculate_average_lux(lux1, lux2, lux3);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux);

        // Fade to target brightness
        fade_brightness(spi_handle, target_brightness, current_brightness);

        current_brightness = target_brightness; // Update current brightness

        // Delay
        gpioDelay(100);
    }

    // Cleanup
    set_apa102_brightness(spi_handle, 0); // Turn off LEDs
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

