#include <math.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_ADDR 0x10
#define GPIO_PIN 18
#define NUM_LEDS 1 // Assuming a single LED for simplicity
#define MAX_LUX 120000.0
#define GAMMA 2.2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int configure_veml7700();
int read_veml7700(uint16_t *raw_value);
float calculate_lux(uint16_t raw_value);
uint8_t map_lux_to_brightness(float lux);
void set_led_brightness(uint8_t brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x10, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO initialization function
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// VEML7700 configuration function
int configure_veml7700() {
    // Configuration register 0x00: Integration time = 100ms, Gain = 1/8
    uint16_t config_value = 0x0000; // Default settings
    char buf[3];
    buf[0] = 0x00; // Configuration register address
    buf[1] = config_value & 0xFF;       // LSB
    buf[2] = (config_value >> 8) & 0xFF; // MSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// VEML7700 data reading function
int read_veml7700(uint16_t *raw_value) {
    char reg_addr = 0x04; // ALS data register
    char buf[2];

    int result = i2cWriteDevice(i2c_handle, &reg_addr, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VEML7700 register address: %s\n", strerror(errno));
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from VEML7700: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (buf[1] << 8) | buf[0]; // Combine MSB and LSB
    return 0;
}

// Lux calculation function
float calculate_lux(uint16_t raw_value) {
    return raw_value * 0.0288;
}

// Brightness mapping function
uint8_t map_lux_to_brightness(float lux) {
    float brightness = 255.0 * powf(lux / MAX_LUX, 1.0 / GAMMA);
    if (brightness > 255.0) brightness = 255.0;
    if (brightness < 0.0) brightness = 0.0;
    return (uint8_t)brightness;
}

// LED control function (bit-banging)
void set_led_brightness(uint8_t brightness) {
    // WS2812B timing: 0.4us high, 0.85us low for 0, 0.8us high, 0.45us low for 1
    // Total period: 1.25us
    // Scale to 800kHz (1.25us period)

    // Example: Simple on/off control based on brightness threshold
    if (brightness > 128) {
        gpioWrite(GPIO_PIN, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_PIN, 0); // Turn LED off
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    printf("Initialization complete. Running...\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_value;
        float lux;
        uint8_t brightness;

        // Read VEML7700 data
        if (read_veml7700(&raw_value) == 0) {
            // Calculate lux
            lux = calculate_lux(raw_value);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print values
            printf("Raw: %u, Lux: %.2f, Brightness: %u\n", raw_value, lux, brightness);
        } else {
            fprintf(stderr, "Error reading VEML7700 data\n");
        }

        gpioDelay(200); // 200ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

