#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define FLAME_DETECTED 0 // KY-026 is active low
#define FLAME_NOT_DETECTED 1
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int self_test();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Perform self-test
    if (self_test() != 0) {
        fprintf(stderr, "Self-test failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    int flame_detected = 0;
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == FLAME_DETECTED && !flame_detected) {
            log_event("Flame detected");
            activate_buzzer();
            activate_led();
            flame_detected = 1;
        } else if (sensor_value == FLAME_NOT_DETECTED && flame_detected) {
            // Debounce: Check if flame is still gone for at least one sample
            if (read_flame_sensor() == FLAME_NOT_DETECTED) {
                log_event("Flame gone");
                deactivate_buzzer();
                deactivate_led();
                flame_detected = 0;
            }
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Self-test function
int self_test() {
    printf("Starting self-test...\n");

    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        activate_led();
        gpioDelay(500); // 500 ms
        deactivate_led();
        gpioDelay(500); // 500 ms
    }

    // Check flame sensor for 500 ms
    int sensor_fault = 1;
    for (int i = 0; i < 5; i++) {
        if (read_flame_sensor() == FLAME_NOT_DETECTED) {
            sensor_fault = 0;
            break;
        }
        gpioDelay(100); // 100 ms
    }

    if (sensor_fault) {
        fprintf(stderr, "Flame sensor fault detected during self-test.\n");
        // Blink LED rapidly
        for (int i = 0; i < 5; i++) {
            activate_led();
            gpioDelay(100); // 100 ms
            deactivate_led();
            gpioDelay(100); // 100 ms
        }

        // Buzzer short-short-long-short pattern
        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            gpioDelay(200); // 200 ms
            deactivate_buzzer();
            gpioDelay(200); // 200 ms
            activate_buzzer();
            gpioDelay(600); // 600 ms
            deactivate_buzzer();
            gpioDelay(200); // 200 ms
        }

        return 1; // Self-test failed
    }

    printf("Self-test passed.\n");
    return 0; // Self-test passed
}

// Read flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0);
}

// Activate LED
void activate_led() {
    gpioWrite(LED_PIN, 1);
}

// Deactivate LED
void deactivate_led() {
    gpioWrite(LED_PIN, 0);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_buzzer();
    deactivate_led();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

