#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define BUFFER_SIZE 60
#define LUX_TO_RATE_SCALE 4.5
#define LUX_TO_RATE_OFFSET 0.5
#define MIN_RATE 0.5
#define MAX_RATE 5.0

// Global variables
static int i2c_fd = -1;
static int gpio_exported = 0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *bus, int addr);
int bh1750_init(int fd);
int bh1750_read_raw(int fd);
float raw_to_lux(int raw);
void gpio_init(int pin);
void gpio_set_value(int pin, int value);
void gpio_unexport(int pin);
float calculate_average(float buffer[], int size);
void signal_handler(int sig);

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 initialization function
int bh1750_init(int fd) {
    unsigned char mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// BH1750 read raw value function
int bh1750_read_raw(int fd) {
    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Raw to lux conversion function
float raw_to_lux(int raw) {
    return (float)raw / 1.2;
}

// GPIO initialization function
void gpio_init(int pin) {
    char buffer[64];
    int fd;

    // Export GPIO pin
    snprintf(buffer, sizeof(buffer), GPIO_PATH "/export");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO export");
        exit(EXIT_FAILURE);
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to GPIO export");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
    gpio_exported = 1;

    // Set GPIO direction to output
    snprintf(buffer, sizeof(buffer), GPIO_PATH "/gpio%d/direction", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction");
        exit(EXIT_FAILURE);
    }
    if (write(fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
}

// GPIO set value function
void gpio_set_value(int pin, int value) {
    char buffer[64];
    int fd;

    snprintf(buffer, sizeof(buffer), GPIO_PATH "/gpio%d/value", pin);
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value");
        return;
    }
    snprintf(buffer, sizeof(buffer), "%d", value);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to GPIO value");
    }
    close(fd);
}

// GPIO unexport function
void gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    snprintf(buffer, sizeof(buffer), GPIO_PATH "/unexport");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO unexport");
        return;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Error writing to GPIO unexport");
    }
    close(fd);
}

// Calculate average function
float calculate_average(float buffer[], int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int main() {
    float lux_buffer[BUFFER_SIZE] = {0.0}; // Initialize buffer to 0
    int buffer_index = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;  // 1 second
    sleep_time.tv_nsec = 0; // 0 nanoseconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize BH1750
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_init(GPIO_PIN);

    printf("Starting light sensor and LED control. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read raw value from BH1750
        int raw_value = bh1750_read_raw(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading raw value, retrying.\n");
            nanosleep(&sleep_time, NULL); // Wait before retrying
            continue;
        }

        // Convert raw value to lux
        float lux = raw_to_lux(raw_value);

        // Update circular buffer
        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate average lux
        float avg_lux = calculate_average(lux_buffer, BUFFER_SIZE);

        // Calculate blink rate
        float rate = LUX_TO_RATE_OFFSET + (avg_lux / 1000.0) * LUX_TO_RATE_SCALE;
        if (rate < MIN_RATE) {
            rate = MIN_RATE;
        } else if (rate > MAX_RATE) {
            rate = MAX_RATE;
        }

        // Calculate sleep time for half period
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = (long)((1.0 / (2.0 * rate)) * 1000000000.0);

        // Turn LED on
        gpio_set_value(GPIO_PIN, 1);
        nanosleep(&sleep_time, NULL);

        // Turn LED off
        gpio_set_value(GPIO_PIN, 0);
        nanosleep(&sleep_time, NULL);

        printf("Raw: %d, Lux: %.2f, Avg Lux: %.2f, Rate: %.2f Hz\n", raw_value, lux, avg_lux, rate);
    }

    // Cleanup
    close(i2c_fd);
    if (gpio_exported) {
        gpio_unexport(GPIO_PIN);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

