#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define the digit '5' pattern (common cathode)
const unsigned char digit_5 = 0b01010100; // a=1, b=0, c=1, d=1, e=0, f=1, g=0, dp=0

// Global variables for GPIO lines and chip
struct gpiod_line *data_line = NULL;
struct gpiod_line *clock_line = NULL;
struct gpiod_line *latch_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to shift out data to the 74HC595
int shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        // Set data pin
        int ret = gpiod_line_set_value(data_line, (data >> i) & 0x01);
        if (ret < 0) {
            perror("Error setting data line value");
            return -1;
        }

        // Clock pulse
        ret = gpiod_line_set_value(clock_line, 1);
        if (ret < 0) {
            perror("Error setting clock line value");
            return -1;
        }
        usleep(1); // Small delay for clock stability
        ret = gpiod_line_set_value(clock_line, 0);
        if (ret < 0) {
            perror("Error setting clock line value");
            return -1;
        }
        usleep(1); // Small delay for clock stability
    }
    return 0;
}

// Function to latch the data to the output
int latch_data() {
    int ret = gpiod_line_set_value(latch_line, 1);
    if (ret < 0) {
        perror("Error setting latch line value");
        return -1;
    }
    usleep(1); // Small delay for latch stability
    ret = gpiod_line_set_value(latch_line, 0);
    if (ret < 0) {
        perror("Error setting latch line value");
        return -1;
    }
    usleep(1); // Small delay for latch stability
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO lines as outputs
    if (gpiod_line_request_output(data_line, "seven_segment", 0) < 0) {
        perror("Error requesting data line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(clock_line, "seven_segment", 0) < 0) {
        perror("Error requesting clock line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "seven_segment", 0) < 0) {
        perror("Error requesting latch line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Display '5'
        if (shift_out(digit_5) < 0) {
            fprintf(stderr, "Error shifting out data, exiting.\n");
            break;
        }
        if (latch_data() < 0) {
            fprintf(stderr, "Error latching data, exiting.\n");
            break;
        }
        usleep(500000); // 500ms

        // Turn off display
        if (shift_out(0x00) < 0) {
            fprintf(stderr, "Error shifting out data, exiting.\n");
            break;
        }
        if (latch_data() < 0) {
            fprintf(stderr, "Error latching data, exiting.\n");
            break;
        }
        usleep(500000); // 500ms
    }

    // Cleanup (should not reach here under normal operation due to signal handler)
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);

    return 0;
}

