    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request LED line as output, initially low
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return 1;
    }

    // Get line for button
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return 1;
    }

    // Request button line as input with pull-up and falling edge event detection
    ret = gpiod_line_request(button_line, "blink_button", GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("Error requesting button line as input with event detection");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return 1;
    }

    // Set initial LED state to off
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Error setting initial LED state");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return 1;
    }

