            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Error setting LED value");
                break;
            }

            printf("Button pressed. Stopping blinking.\n");
            keep_running = 0;
        }
    }

    // Release resources
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

