#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the LED state
int set_led_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to read the button state
int read_button_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading button value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for button
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set LED line as output
    int ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d as output: %s\n", LED_PIN, strerror(-ret));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set button line as input with pull-down resistor
    ret = gpiod_line_request_input(button_line, "button");
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %d as input: %s\n", BUTTON_PIN, strerror(-ret));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int button_state = read_button_state(button_line);
        if (button_state < 0) {
            // Error reading button state, exit
            break;
        }

        if (button_state == 1) {
            // Button is pressed, blink LED
            if (set_led_state(led_line, 1) < 0) {
                break;
            }
            usleep(500000); // 500 ms
            if (set_led_state(led_line, 0) < 0) {
                break;
            }
            usleep(500000); // 500 ms
        } else {
            // Button is released, turn LED off
            if (set_led_state(led_line, 0) < 0) {
                break;
            }
            usleep(10000); // Small delay to avoid busy-waiting
        }
    }

    // Cleanup and exit
    signal_handler(0); // Call signal handler to release resources
    return 1;
}

