#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for RGB LED
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define chip number
#define CHIP_NUMBER 0

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the duty cycle of a GPIO line using software PWM
void set_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    if (!line) return; // Check if line is valid

    // Calculate on and off times in nanoseconds
    long on_time_ns = (long)((double)duty_cycle / 100.0 * 10000000); // 10ms period
    long off_time_ns = 10000000 - on_time_ns;

    // Set GPIO high for on_time_ns
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO high");
        return;
    }
    struct timespec on_time = {0, on_time_ns};
    clock_nanosleep(CLOCK_MONOTONIC, 0, &on_time, NULL);

    // Set GPIO low for off_time_ns
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO low");
        return;
    }
    struct timespec off_time = {0, off_time_ns};
    clock_nanosleep(CLOCK_MONOTONIC, 0, &off_time, NULL);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_number(CHIP_NUMBER);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random RGB values (0-100)
        int red_duty_cycle = rand() % 101;
        int green_duty_cycle = rand() % 101;
        int blue_duty_cycle = rand() % 101;

        // Set duty cycles for each color
        set_duty_cycle(red_line, red_duty_cycle);
        set_duty_cycle(green_line, green_duty_cycle);
        set_duty_cycle(blue_line, blue_duty_cycle);

        // Wait 100ms
        struct timespec sleep_time = {0, 100000000}; // 100ms
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
    }

    return 0;
}

