    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Generate random RGB values (0-100)
        int red_duty_cycle = rand() % 101;
        int green_duty_cycle = rand() % 101;
        int blue_duty_cycle = rand() % 101;

        // Set duty cycles for each color
        set_duty_cycle(red_line, red_duty_cycle);
        set_duty_cycle(green_line, green_duty_cycle);
        set_duty_cycle(blue_line, blue_duty_cycle);

        // Wait 100ms
        struct timespec sleep_time = {0, 100000000}; // 100ms
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
    }

    return 0;
}

