#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

// GPIO pin for impact indication
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double g_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int config_sensor();
accelerometer_data_t read_accelerometer();
double calculate_g_force(accelerometer_data_t data);
void impact_detected(accelerometer_data_t data);
void signal_handler(int signal);
void log_data(accelerometer_data_t data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the LSM303DLHC sensor
int config_sensor() {
    // CTRL_REG1_A = 0x27 (Enable all axes, 100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // CTRL_REG4_A = 0x00 (2G full-scale, sensitivity 16384 LSB/G)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer() {
    accelerometer_data_t data;
    char buffer[6];

    // Read 6 bytes starting from OUT_X_L_A (0x28) with auto-increment
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = data.y = data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculate the total G-force magnitude
double calculate_g_force(accelerometer_data_t data) {
    double x_g = (double)data.x / 16384.0;
    double y_g = (double)data.y / 16384.0;
    double z_g = (double)data.z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Handle impact detection
void impact_detected(accelerometer_data_t data) {
    // Pulse GPIO17 HIGH for 50 ms
    gpioWrite(IMPACT_PIN, 1);
    gpioDelay(50); // 50 ms
    gpioWrite(IMPACT_PIN, 0);

    log_data(data);
}

// Log data to file
void log_data(accelerometer_data_t data) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d, %d, %d\n", s, data.x, data.y, data.z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        g_threshold = atof(argv[1]);
        if (g_threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %.2f G\n", DEFAULT_THRESHOLD);
            g_threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);
    gpioWrite(IMPACT_PIN, 0); // Ensure it starts LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (config_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Threshold: %.2f G\n", g_threshold);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer();
        double g_force = calculate_g_force(data);

        if (g_force > g_threshold) {
            impact_detected(data);
        }

        gpioDelay(100); // 10 Hz polling rate (100 ms delay)
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

