#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_als_data(uint16_t *als_value);
int read_rgb_data(uint16_t *red_value, uint16_t *green_value, uint16_t *blue_value);
void log_data(uint16_t als_value, uint16_t red_value, uint16_t green_value, uint16_t blue_value);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);
void cleanup();

// Function to write a byte to an I2C register with retry
int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %d. Retrying...\n", reg, value, result);
        gpioDelay(100); // Wait 100 ms
        retries--;
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1; // Failure
}

// Function to read a byte from an I2C register with retry
int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
        gpioDelay(100); // Wait 100 ms
        retries--;
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Failure
}

// Function to read a 16-bit value from two I2C registers with retry
int i2c_read_16bit(int handle, uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t lsb, msb;
    int result;

    result = i2c_read_reg(handle, lsb_reg, &lsb);
    if (result != 0) return -1;

    result = i2c_read_reg(handle, msb_reg, &msb);
    if (result != 0) return -1;

    *value = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t als_value, red_value, green_value, blue_value;
    while (!terminate) {
        // Read sensor data
        if (read_als_data(&als_value) != 0) {
            fprintf(stderr, "Failed to read ALS data\n");
        }
        if (read_rgb_data(&red_value, &green_value, &blue_value) != 0) {
            fprintf(stderr, "Failed to read RGB data\n");
        }

        // Log the data
        log_data(als_value, red_value, green_value, blue_value);

        // Set LED brightness
        set_led_brightness(als_value);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize the ADPD188BI sensor
int initialize_sensor() {
    // Set MODE register to 0x01 for normal operation
    if (i2c_write_reg(i2c_handle, MODE_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to set MODE register\n");
        return -1;
    }
    return 0;
}

// Function to read ALS data from the sensor
int read_als_data(uint16_t *als_value) {
    return i2c_read_16bit(i2c_handle, ALS_LSB_REG, ALS_MSB_REG, als_value);
}

// Function to read RGB data from the sensor
int read_rgb_data(uint16_t *red_value, uint16_t *green_value, uint16_t *blue_value) {
    if (i2c_read_16bit(i2c_handle, RED_REG, RED_REG + 1, red_value) != 0) return -1;
    if (i2c_read_16bit(i2c_handle, GREEN_REG, GREEN_REG + 1, green_value) != 0) return -1;
    if (i2c_read_16bit(i2c_handle, BLUE_REG, BLUE_REG + 1, blue_value) != 0) return -1;
    return 0;
}

// Function to log the sensor data to a CSV file
void log_data(uint16_t als_value, uint16_t red_value, uint16_t green_value, uint16_t blue_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als_value, red_value, green_value, blue_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to set the LED brightness using hardware PWM
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);

    // Ensure duty cycle is within the valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    // Stop PWM
    gpioPWM(LED_GPIO, 0);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

