// Constants
#define I2C_BUS 1
#define FXOS8700CQ_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define ACCEL_DATA_LENGTH 6
#define SENSITIVITY 4096.0f
#define GRAVITY 9.81f
#define IMPACT_THRESHOLD 19.62f
#define SAMPLE_INTERVAL_MS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xC7, got 0x%X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed.\n");

    // Place sensor in standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00));
        return -1;
    }

    // Configure accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00));
        return -1;
    }

    // Activate sensor (active mode, 200 Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %d\n", i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01));
        return -1;
    }

    printf("FXOS8700CQ initialized successfully.\n");
    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buffer[ACCEL_DATA_LENGTH];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, ACCEL_DATA_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Convert raw data to g values
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    *x = (float)raw_x / SENSITIVITY * GRAVITY;
    *y = (float)raw_y / SENSITIVITY * GRAVITY;
    *z = (float)raw_z / SENSITIVITY * GRAVITY;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact data to a file
void log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);

    printf("Impact detected and logged: %s, x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", timestamp, x, y, z, magnitude);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

