#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)
#define CALIBRATION_SAMPLES 100
#define DPS_PER_LSB 0.00875f
#define ALERT_THRESHOLD 50.0f

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_gyro(int fd);
int calibrate_gyro(int fd, float *x_offset, float *y_offset, float *z_offset);
gyro_data_t read_gyro_data(int fd, float x_offset, float y_offset, float z_offset);
char* format_iso8601_timestamp(char *buf, size_t buf_size);
int log_data(FILE *fp, const char *timestamp, float x, float y, float z);
void signal_handler(int sig);

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize gyroscope function
int init_gyro(int fd) {
    uint8_t who_am_i;

    // Check WHO_AM_I register
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    // Configure CTRL_REG1
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Calibrate gyroscope function
int calibrate_gyro(int fd, float *x_offset, float *y_offset, float *z_offset) {
    int16_t x_raw, y_raw, z_raw;
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    uint8_t data[6];
    struct timespec sleep_time = {0, 10000000}; // 10 ms

    printf("Calibrating gyroscope...\n");

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (i2c_read_block(fd, OUT_X_L, data, 6) != 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }

        x_raw = (int16_t)((data[1] << 8) | data[0]);
        y_raw = (int16_t)((data[3] << 8) | data[2]);
        z_raw = (int16_t)((data[5] << 8) | data[4]);

        x_sum += x_raw;
        y_sum += y_raw;
        z_sum += z_raw;

        nanosleep(&sleep_time, NULL);
    }

    *x_offset = (float)x_sum / CALIBRATION_SAMPLES * DPS_PER_LSB;
    *y_offset = (float)y_sum / CALIBRATION_SAMPLES * DPS_PER_LSB;
    *z_offset = (float)z_sum / CALIBRATION_SAMPLES * DPS_PER_LSB;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f dps\n", *x_offset, *y_offset, *z_offset);

    return 0;
}

// Read gyroscope data function
gyro_data_t read_gyro_data(int fd, float x_offset, float y_offset, float z_offset) {
    uint8_t data[6];
    int16_t x_raw, y_raw, z_raw;
    gyro_data_t gyro_data;

    if (i2c_read_block(fd, OUT_X_L, data, 6) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        gyro_data.x = 0.0f;
        gyro_data.y = 0.0f;
        gyro_data.z = 0.0f;
        return gyro_data;
    }

    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    gyro_data.x = (float)x_raw * DPS_PER_LSB - x_offset;
    gyro_data.y = (float)y_raw * DPS_PER_LSB - y_offset;
    gyro_data.z = (float)z_raw * DPS_PER_LSB - z_offset;

    return gyro_data;
}

// Format ISO 8601 timestamp function
char* format_iso8601_timestamp(char *buf, size_t buf_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buf;
}

// Log data function
int log_data(FILE *fp, const char *timestamp, float x, float y, float z) {
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

int main() {
    float x_offset = 0.0f, y_offset = 0.0f, z_offset = 0.0f;
    gyro_data_t gyro_data;
    char timestamp[32];
    struct timespec sleep_time = {0, SAMPLE_PERIOD_NS};
    struct timespec remaining_time;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro(i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    if (calibrate_gyro(i2c_fd, &x_offset, &y_offset, &z_offset) != 0) {
        fprintf(stderr, "Gyroscope calibration failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    printf("Starting data acquisition...\n");
    while (!terminate) {
        // Read gyroscope data
        gyro_data = read_gyro_data(i2c_fd, x_offset, y_offset, z_offset);

        // Format timestamp
        format_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, gyro_data.x, gyro_data.y, gyro_data.z) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Check for alert condition
        if (fabs(gyro_data.x) > ALERT_THRESHOLD || fabs(gyro_data.y) > ALERT_THRESHOLD || fabs(gyro_data.z) > ALERT_THRESHOLD) {
            fprintf(stderr, "WARNING: Gyro rate exceeded threshold! X=%.2f, Y=%.2f, Z=%.2f dps\n", gyro_data.x, gyro_data.y, gyro_data.z);
            fprintf(log_file, "%s,ALERT,X=%.2f,Y=%.2f,Z=%.2f\n", timestamp, gyro_data.x, gyro_data.y, gyro_data.z);
        }

        // Sleep for the remaining time to achieve the desired sampling rate
        nanosleep(&sleep_time, &remaining_time);
        sleep_time = remaining_time;
    }

    // Close I2C bus and log file
    printf("Closing I2C bus and log file...\n");
    close(i2c_fd);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

