#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_DATAX0 0x32
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31

// GPIO pin for LED
#define LED_PIN 17

// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// I2C handle
int i2c_handle;

// Log file pointer
FILE *log_file;

// Function prototypes
int init_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
void log_data(int16_t x, int16_t y, int16_t z);
void control_led(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int adxl345_address;
    int led_gpio;
    float accel_threshold;
} config_t;

config_t config = {
    .i2c_bus = 1,
    .adxl345_address = ADXL345_ADDR,
    .led_gpio = LED_PIN,
    .accel_threshold = ACCEL_THRESHOLD
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    int16_t x, y, z;

    // Main loop
    while (1) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Log data
            log_data(x, y, z);

            // Control LED
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Delay for 100 ms (10 Hz)
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Open I2C device
    i2c_handle = i2cOpen(config.i2c_bus, config.adxl345_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Verify DEVID register
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Failed to read DEVID register: %d\n", devid);
        i2cClose(i2c_handle);
        return 1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID value: 0x%X\n", devid);
        i2cClose(i2c_handle);
        return 1;
    }

    // Set data format: full resolution, ±2g range
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    // Set power control: measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read acceleration data from ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    // Read 6 bytes of data starting from DATAX0
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Failed to read acceleration data: %d\n", bytes_read);
        return 1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Log acceleration data to file
void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Convert raw values to g units (assuming full resolution and ±2g range)
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    // Log data to file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_g, y_g, z_g);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on acceleration threshold
void control_led(int16_t x, int16_t y, int16_t z) {
    // Convert raw values to g units (assuming full resolution and ±2g range)
    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    // Check if absolute acceleration exceeds threshold
    if (fabs(x_g) > config.accel_threshold || fabs(y_g) > config.accel_threshold || fabs(z_g) > config.accel_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C device
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

