    float x_g = (float)x / 256.0;
    float y_g = (float)y / 256.0;
    float z_g = (float)z / 256.0;

    // Check if absolute acceleration exceeds threshold
    if (fabs(x_g) > config.accel_threshold || fabs(y_g) > config.accel_threshold || fabs(z_g) > config.accel_threshold) {
        gpioWrite(config.led_gpio, 1); // Turn LED on
    } else {
        gpioWrite(config.led_gpio, 0); // Turn LED off
    }
}

