    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off LED
    gpioWrite(config.led_gpio, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

