        // Calculate heading
        heading = calculate_heading(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z);

        // Log data
        if (log_data(heading, sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, sensor_data.mag_x, sensor_data.mag_y, sensor_data.mag_z) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Initialize accelerometer
int init_accelerometer(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer(int handle) {
    if (i2cWriteByteData(handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer MR_REG_M: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to g
    *x = (float)((int16_t)(buffer[1] << 8 | buffer[0])) * ACCEL_SCALE;
    *y = (float)((int16_t)(buffer[3] << 8 | buffer[2])) * ACCEL_SCALE;
    *z = (float)((int16_t)(buffer[5] << 8 | buffer[4])) * ACCEL_SCALE;

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    *x = (float)((int16_t)(buffer[0] << 8 | buffer[1])) * MAG_SCALE;
    *y = (float)((int16_t)(buffer[2] << 8 | buffer[3])) * MAG_SCALE;
    *z = (float)((int16_t)(buffer[4] << 8 | buffer[5])) * MAG_SCALE;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

