#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Define register addresses
#define CONTROL_REG 0x00
#define DATA_REG 0x01

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 10

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1_data;
    int16_t sensor2_data;
    int16_t tdoa;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int16_t read_sensor_data(int i2c_handle);
int16_t calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize a sensor
int initialize_sensor(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, CONTROL_REG, 0x80) != 0) {
        fprintf(stderr, "Error writing to control register: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from a sensor
int16_t read_sensor_data(int i2c_handle) {
    int16_t data = i2cReadWordData(i2c_handle, DATA_REG);
    if (data < 0) {
        fprintf(stderr, "Error reading data from sensor: %d\n", i2c_handle);
        return 0; // Return 0 on error
    }
    return data;
}

// Function to calculate TDOA
int16_t calculate_tdoa(int16_t sensor1_data, int16_t sensor2_data) {
    return sensor1_data - sensor2_data;
}

