// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// Sensitivities
#define GYRO_SENSITIVITY 0.005f
#define ACCEL_SENSITIVITY 0.00025f

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0b11000000000 // CPOL=1, CPHA=1, aux SPI off

// Global Variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint16_t *data);
int spi_write_register(int handle, uint8_t reg, uint16_t data);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int handle, uint8_t reg, uint16_t *data) {
    char tx[2];
    char rx[2];

    tx[0] = (reg << 1) & 0xFE; // MSB = 0 for read
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

// Function to write a register to the ADIS16488A
int spi_write_register(int handle, uint8_t reg, uint16_t data) {
    char tx[2];
    char rx[2];

    tx[0] = (reg << 1) | 0x01; // MSB = 1 for write
    tx[1] = data & 0xFF; //LSB

    if (spiXfer(handle, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(handle, X_GYRO, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(handle, Y_GYRO, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(handle, Z_GYRO, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(handle, X_ACCEL, &raw_accel_x) != 0) return -1;
    if (spi_read_register(handle, Y_ACCEL, &raw_accel_y) != 0) return -1;
    if (spi_read_register(handle, Z_ACCEL, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)((int16_t)raw_gyro_x) * GYRO_SENSITIVITY;
    *gyro_y = (float)((int16_t)raw_gyro_y) * GYRO_SENSITIVITY;
    *gyro_z = (float)((int16_t)raw_gyro_z) * GYRO_SENSITIVITY;
    *accel_x = (float)((int16_t)raw_accel_x) * ACCEL_SENSITIVITY;
    *accel_y = (float)((int16_t)raw_accel_y) * ACCEL_SENSITIVITY;
    *accel_z = (float)((int16_t)raw_accel_z) * ACCEL_SENSITIVITY;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp_ms, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Cleanup function to close SPI and file
void cleanup() {
    running = 0;
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    // Register cleanup function
    atexit(cleanup);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    // Main loop
    while (running) {
        if (read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            if (log_data(fp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading IMU data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

