#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.02f
#define ACCL_SCALE 0.00025f

// SPI Configuration
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int chip_select, int mode, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int adis16448_read_register(int fd, uint8_t reg_addr, uint16_t *data);
void adis16448_read_data(int fd, float *gyro_x, float *gyro_y, float *gyro_z, float *accl_x, float *accl_y, float *accl_z);
void signal_handler(int sig);
int gpio_init(const char *chipname, int pin);
void gpio_set_value(int value);
void gpio_close(void);
void spi_close(int fd);

// SPI Initialization
int spi_init(int bus, int chip_select, int mode, int speed) {
    char spi_device[20];
    int fd;

    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", bus, chip_select);
    fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
