void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Construct the transmit buffer (read command)
    tx_buf[0] = (reg_addr << 1) | 0x01; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte

    // Perform the SPI transfer
    status = spiXfer(handle, tx_buf, rx_buf, 2);
    if (status != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", status);
        return 0; // Return 0 on error
    }

    // Combine the received bytes into a 16-bit value
    return (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t x_gyro_raw = read_register(spi_handle, X_GYRO_OUT);
        int16_t y_gyro_raw = read_register(spi_handle, Y_GYRO_OUT);
        int16_t z_gyro_raw = read_register(spi_handle, Z_GYRO_OUT);

        // Read accelerometer data
        int16_t x_accl_raw = read_register(spi_handle, X_ACCL_OUT);
        int16_t y_accl_raw = read_register(spi_handle, Y_ACCL_OUT);
        int16_t z_accl_raw = read_register(spi_handle, Z_ACCL_OUT);

        // Scale the data
        float x_gyro = x_gyro_raw * GYRO_SCALE;
        float y_gyro = y_gyro_raw * GYRO_SCALE;
        float z_gyro = z_gyro_raw * GYRO_SCALE;

        float x_accl = x_accl_raw * ACCL_SCALE;
        float y_accl = y_accl_raw * ACCL_SCALE;
        float z_accl = z_accl_raw * ACCL_SCALE;

