#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// LED GPIO pin
#define LED_PIN 17

// Impact threshold (g)
#define IMPACT_THRESHOLD 2.5

// Scale factor (LSB/g)
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the ADXL345 accelerometer
int adxl345_init() {
    // Verify device ID
    char devid;
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DEVID, &devid, 1) != 1) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format: full resolution, +-2g range
    char data_format = 0x0B; // Full resolution, +-2g
    if (i2cWriteI2CBlockData(i2c_handle, 0x31, &data_format, 1) != 1) {
        fprintf(stderr, "Error writing data format register\n");
        return -1;
    }

    // Enable measurement mode
    char power_ctl = 0x08; // Measurement mode
    if (i2cWriteI2CBlockData(i2c_handle, ADXL345_REG_POWER_CTL, &power_ctl, 1) != 1) {
        fprintf(stderr, "Error writing power control register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate the magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / SCALE_FACTOR;
    double y_g = (double)y / SCALE_FACTOR;
    double z_g = (double)z / SCALE_FACTOR;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to a file
void log_impact(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);

                // Turn on LED
                gpioWrite(LED_PIN, 1);

                // Log impact
                log_impact(x, y, z, magnitude);

                // Turn off LED after 500ms
                gpioDelay(500);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        // Delay for 10ms
        gpioDelay(10);
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

