#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Registers
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

// Scaling factors
#define ACCEL_SCALE 16384.0f // Sensitivity at +/- 2g
#define GYRO_SCALE 131.0f    // Sensitivity at +/- 250 dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the ICM-20602 IMU
int init_imu() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up IMU. %s\n", strerror(errno));
        return -1;
    }

    // Set accelerometer range to +/- 2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range. %s\n", strerror(errno));
        return -1;
    }

    // Set gyroscope range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data from the ICM-20602
int read_sensor_data(sensor_data_t *data) {
    char buf[12];

    // Read accelerometer and gyroscope data in one burst
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12) < 0) {
        fprintf(stderr, "Error: Could not read sensor data. %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope data
    data->gyro_x = (int16_t)((buf[6] << 8) | buf[7]);
    data->gyro_y = (int16_t)((buf[8] << 8) | buf[9]);
    data->gyro_z = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Convert timestamp to milliseconds
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    // Log data to CSV file
    fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d\n",
            timestamp_ms,
            data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register. %s\n", strerror(errno));
        i2cClose(i2c_handle);
