#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.0f
#define LED_ON_TIME_MS 500
#define SAMPLE_PERIOD_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mma8451q_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_impact(const char *timestamp);
int control_led(struct gpiod_line *line, int on);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// MMA8451Q initialization function
int mma8451q_init(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Set to active mode, 800 Hz ODR
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = i2c_read_reg(fd, OUT_X_MSB);
    x_lsb = i2c_read_reg(fd, OUT_X_MSB + 1);
    y_msb = i2c_read_reg(fd, OUT_X_MSB + 2);
    y_lsb = i2c_read_reg(fd, OUT_X_MSB + 3);
    z_msb = i2c_read_reg(fd, OUT_X_MSB + 4);
    z_lsb = i2c_read_reg(fd, OUT_X_MSB + 5);

    if (x_msb == -1 || x_lsb == -1 || y_msb == -1 || y_lsb == -1 || z_msb == -1 || z_lsb == -1) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb) >> 4;
    *y = (int16_t)((y_msb << 8) | y_lsb) >> 4;
    *z = (int16_t)((z_msb << 8) | z_lsb) >> 4;

    return 0;
}

// Calculate magnitude function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 1024.0f;
    float y_g = (float)y / 1024.0f;
    float z_g = (float)z / 1024.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact function
int log_impact(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Control LED function
int control_led(struct gpiod_line *line, int on) {
    if (gpiod_line_set_value(line, on) < 0) {
        perror("Failed to set LED value");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize MMA8451Q
    if (mma8451q_init(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451Q initialization failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "impact_detector", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    int16_t x, y, z;
    float magnitude;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log impact
                if (log_impact(timestamp) == 0) {
                    printf("Impact detected at %s, magnitude: %.2f g\n", timestamp, magnitude);
                } else {
                    fprintf(stderr, "Failed to log impact\n");
                }

                // Control LED
                if (control_led(gpio_line, 1) == 0) {
                    usleep(LED_ON_TIME_MS * 1000); // Turn on for 500ms
                    control_led(gpio_line, 0); // Turn off
                } else {
                    fprintf(stderr, "Failed to control LED\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000); // Wait 100ms
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

