// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C file descriptor if it's open
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C device closed.\n");
    }

    // Close the CSV file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        printf("CSV file closed.\n");
    }

    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    int16_t value;

    // Write the register address to the I2C device
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Read two bytes from the I2C device
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    value = (int16_t)((buf[1] << 8) | buf[0]);

    return value;
}

// Function to log the magnetic field data to a CSV file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
