    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    // Main loop to read and log magnetic field data
    while (1) {
        int16_t x, y, z;

        // Read the X, Y, and Z magnetic field data from the sensor
        x = read_i2c_word(i2c_fd, TMAG5273_REG_X);
        y = read_i2c_word(i2c_fd, TMAG5273_REG_Y);
        z = read_i2c_word(i2c_fd, TMAG5273_REG_Z);

        // Check for errors during I2C read operations
        if (x == -1 || y == -1 || z == -1) {
            fprintf(stderr, "Error reading magnetic field data. Skipping logging.\n");
        } else {
            // Log the magnetic field data to the CSV file
            log_data(log_file, x, y, z);
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

