#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define THRESH_FF_REG 0x0A
#define TIME_FF_REG 0x20
#define INT_ENABLE_REG 0x2E
#define INT_MAP_REG 0x2F
#define POWER_CTL_REG 0x2D
#define INT_SOURCE_REG 0x30
#define DATAX0_REG 0x32
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0xE5

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int adxl345_init(int fd);
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z);
int gpio_setup(const char *chipname, int pin);
int gpio_wait_interrupt(struct gpiod_line *line);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Error: Could not set I2C slave address");
    return -1;
  }

  if (write(fd, &reg, 1) != 1) {
    perror("Error: Could not write register address");
    return -1;
  }

  if (read(fd, value, 1) != 1) {
    perror("Error: Could not read register value");
    return -1;
  }

  return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;

  if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Error: Could not set I2C slave address");
    return -1;
  }

  if (write(fd, buf, 2) != 2) {
    perror("Error: Could not write register value");
    return -1;
  }

  return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
  uint8_t device_id;

  // Verify device ID
  if (i2c_read_reg(fd, DEVICE_ID_REG, &device_id) < 0) {
    fprintf(stderr, "Error: Could not read device ID\n");
    return -1;
  }

  if (device_id != DEVICE_ID_VALUE) {
    fprintf(stderr, "Error: Incorrect device ID: 0x%02X (expected 0xE5)\n", device_id);
    return -1;
  }

  // Set THRESH_FF
  if (i2c_write_reg(fd, THRESH_FF_REG, 0x30) < 0) {
    fprintf(stderr, "Error: Could not write THRESH_FF\n");
    return -1;
  }

  // Set TIME_FF
  if (i2c_write_reg(fd, TIME_FF_REG, 0x10) < 0) {
    fprintf(stderr, "Error: Could not write TIME_FF\n");
    return -1;
  }

  // Enable freefall interrupt
  if (i2c_write_reg(fd, INT_ENABLE_REG, 0x04) < 0) {
    fprintf(stderr, "Error: Could not write INT_ENABLE\n");
    return -1;
  }

  // Map interrupt to INT1
  if (i2c_write_reg(fd, INT_MAP_REG, 0x00) < 0) {
    fprintf(stderr, "Error: Could not write INT_MAP\n");
    return -1;
  }

  // Enter measurement mode
  if (i2c_write_reg(fd, POWER_CTL_REG, 0x08) < 0) {
    fprintf(stderr, "Error: Could not write POWER_CTL\n");
    return -1;
  }

  return 0;
}

// ADXL345 read data function
int adxl345_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t data[6];

  if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Error: Could not set I2C slave address");
    return -1;
  }

  if (write(fd, DATAX0_REG, 1) != 1) {
    perror("Error: Could not write register address");
    return -1;
  }

  if (read(fd, data, 6) != 6) {
    perror("Error: Could not read data");
    return -1;
  }

  *x = (int16_t)((data[1] << 8) | data[0]);
  *y = (int16_t)((data[3] << 8) | data[2]);
  *z = (int16_t)((data[5] << 8) | data[4]);

  return 0;
}

// GPIO setup function
int gpio_setup(const char *chipname, int pin) {
  struct gpiod_line_request_config config;
  struct timespec timeout;

  gpio_chip = gpiod_chip_open_by_name(chipname);
  if (!gpio_chip) {
    perror("Error: Could not open GPIO chip");
    return -1;
  }

  gpio_line = gpiod_chip_get_line(gpio_chip, pin);
  if (!gpio_line) {
    perror("Error: Could not get GPIO line");
    gpiod_chip_close(gpio_chip);
    return -1;
  }

  memset(&config, 0, sizeof(config));
  config.consumer = "freefall_detector";
  config.request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE;
  config.flags = 0;

  if (gpiod_line_request(gpio_line, &config, 0) < 0) {
    perror("Error: Could not request GPIO line");
    gpiod_chip_close(gpio_chip);
    return -1;
  }

  timeout.tv_sec = 1; // 1 second timeout
  timeout.tv_nsec = 0;

  return 0;
}

// GPIO wait for interrupt function
int gpio_wait_interrupt(struct gpiod_line *line) {
  struct gpiod_line_event event;

  if (gpiod_line_event_wait(line, NULL) < 0) {
    perror("Error: Could not wait for GPIO event");
    return -1;
  }

  if (gpiod_line_event_read(line, &event) < 0) {
    perror("Error: Could not read GPIO event");
    return -1;
  }

  return 0;
}

// Log data function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[30];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
  snprintf(timestamp + strlen(timestamp), 4, ".%03ld", (long)time(NULL) % 1000);

  fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
  fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Caught signal %d, cleaning up...\n", sig);
  terminate = 1;
}

int main() {
  int16_t x, y, z;
  uint8_t int_source;

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Error: Could not open I2C bus");
    return 1;
  }

  // Initialize ADXL345
  if (adxl345_init(i2c_fd) < 0) {
    fprintf(stderr, "Error: ADXL345 initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Setup GPIO
  if (gpio_setup(GPIO_CHIP, GPIO_PIN) < 0) {
    fprintf(stderr, "Error: GPIO setup failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("freefall_log.csv", "a");
  if (!log_file) {
    perror("Error: Could not open log file");
    close(i2c_fd);
    gpiod_chip_close(gpio_chip);
    return 1;
  }

  // Write header if the file is newly created
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);
  }

  // Main loop
  while (!terminate) {
    if (gpio_wait_interrupt(gpio_line) == 0) {
      // Read INT_SOURCE
      if (i2c_read_reg(i2c_fd, INT_SOURCE_REG, &int_source) < 0) {
        fprintf(stderr, "Error: Could not read INT_SOURCE\n");
        continue; // Continue to the next iteration
      }

      // Check if freefall interrupt is set
      if (int_source & 0x04) {
        // Read accelerometer data
        if (adxl345_read_data(i2c_fd, &x, &y, &z) == 0) {
          // Log data
          log_data(log_file, x, y, z);
        } else {
          fprintf(stderr, "Error: Could not read accelerometer data\n");
        }
      }
    }
  }

  // Cleanup
  close(i2c_fd);
  gpiod_line_release(gpio_line);
  gpiod_chip_close(gpio_chip);
  fclose(log_file);

  return 0;
}

