#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define LSM6DSR_WHO_AM_I 0x0F
#define LSM6DSR_CTRL1_XL 0x10
#define LSM6DSR_CTRL2_G 0x11
#define LSM6DSR_OUTX_L_G 0x22
#define LSM6DSR_OUTX_L_XL 0x28

// Accelerometer and gyroscope ranges
#define ACCEL_RANGE 2.0f  // +-2g
#define GYRO_RANGE 250.0f // +-250 dps

// Accelerometer and gyroscope ODR
#define ODR 104 // Hz

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // g
#define IMPACT_THRESHOLD 2.5f   // g
#define FALL_WINDOW 1.0f        // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data, float acceleration_magnitude);
void fall_detection(sensor_data_t data, float acceleration_magnitude);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, LSM6DSR_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x69, got 0x%x\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    int status = i2cWriteByteData(i2c_handle, LSM6DSR_CTRL1_XL, 0x80); // 01000000
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register: %d\n", status);
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    status = i2cWriteByteData(i2c_handle, LSM6DSR_CTRL2_G, 0x80); // 01000000
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer and gyroscope data
    int status = i2cReadI2CBlockData(i2c_handle, LSM6DSR_OUTX_L_G, buffer, 12);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", status);
        return -1;
    }

    // Combine low and high bytes for gyroscope
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine low and high bytes for accelerometer
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to g and dps
    data->accel_x = (float)accel_x_raw / 16384.0f * ACCEL_RANGE; // 16384 counts/g for +-2g
    data->accel_y = (float)accel_y_raw / 16384.0f * ACCEL_RANGE;
    data->accel_z = (float)accel_z_raw / 16384.0f * ACCEL_RANGE;
    data->gyro_x = (float)gyro_x_raw / 16384.0f * GYRO_RANGE;   // 16384 counts/dps for +-250 dps
    data->gyro_y = (float)gyro_y_raw / 16384.0f * GYRO_RANGE;
    data->gyro_z = (float)gyro_z_raw / 16384.0f * GYRO_RANGE;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Function to log data to file
void log_data(sensor_data_t data, float acceleration_magnitude) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%f,%f,%f,%f,%f,%f,%f\n",
            timestamp_ms, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z, acceleration_magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to implement fall detection state machine
void fall_detection(sensor_data_t data, float acceleration_magnitude) {
    static enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    static struct timespec freefall_start_time;
    static struct timespec impact_start_time;

    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    switch (state) {
        case IDLE:
            if (acceleration_magnitude < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                clock_gettime(CLOCK_REALTIME, &freefall_start_time);
            }
            break;
        case FREEFALL:
            if (acceleration_magnitude >= FREEFALL_THRESHOLD) {
                state = IDLE;
            } else {
                double time_diff = (current_time.tv_sec - freefall_start_time.tv_sec) + (current_time.tv_nsec - freefall_start_time.tv_nsec) / 1000000000.0;
                if (time_diff >= FALL_WINDOW) {
                    state = IMPACT;
                    clock_gettime(CLOCK_REALTIME, &impact_start_time);
                }
            }
            break;
        case IMPACT:
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                printf("FALL DETECTED!\n");
                state = IDLE;
            } else {
                double time_diff = (current_time.tv_sec - impact_start_time.tv_sec) + (current_time.tv_nsec - impact_start_time.tv_nsec) / 1000000000.0;
                if (time_diff >= FALL_WINDOW) {
                    state = IDLE;
                }
            }
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z,acceleration_magnitude\n");

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate acceleration magnitude
            float acceleration_magnitude = calculate_acceleration_magnitude(sensor_data);

            // Log data
            log_data(sensor_data, acceleration_magnitude);

            // Perform fall detection
            fall_detection(sensor_data, acceleration_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for approximately 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

