#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define WHO_AM_I_REG 0x02
#define X_GYRO_OUT_REG 0x14

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling factor
#define GYRO_SCALE 0.0305

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg, uint16_t *data);
int spi_write_register(int handle, uint8_t reg, uint16_t data);
int verify_who_am_i(int handle);
double read_gyro_data(int handle);
void log_data(FILE *fp, double gyro_rate);
void signal_handler(int signal);

// Function to read a register via SPI
int spi_read_register(int handle, uint8_t reg, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: spiXfer failed (read) with code %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a register via SPI
