#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope registers
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Sensitivity (mdps/LSB)
#define SENSITIVITY 8.75

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
int read_gyro_data(gyro_data_t *data);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Verify WHO_AM_I register
    while (retries > 0) {
        char buf[1];
        buf[0] = WHO_AM_I;
        status = i2cWriteDevice(i2c_handle, buf, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing to WHO_AM_I register: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        char read_buf[1];
        status = i2cReadDevice(i2c_handle, read_buf, 1);
        if (status != 0) {
            fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        if (read_buf[0] == 0xD3) {
            printf("Gyroscope WHO_AM_I value: 0x%02X\n", read_buf[0]);
            break;
        } else {
            fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", read_buf[0]);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to verify WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled)
    retries = 3;
    while (retries > 0) {
        char buf[2];
        buf[0] = CTRL_REG1;
        buf[1] = 0x0F;
        status = i2cWriteDevice(i2c_handle, buf, 2);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG1 register: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }
        break; // Success, exit the loop
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (+-250 dps full-scale range)
    retries = 3;
    while (retries > 0) {
        char buf[2];
        buf[0] = CTRL_REG4;
        buf[1] = 0x00;
        status = i2cWriteDevice(i2c_handle, buf, 2);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG4 register: %s\n", strerror(errno));
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }
        break; // Success, exit the loop
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[1];
    char read_buf[6];
    int status;

    buf[0] = OUT_X_L;
    status = i2cWriteDevice(i2c_handle, buf, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to OUT_X_L register: %s\n", strerror(errno));
        return -1;
    }

    status = i2cReadDevice(i2c_handle, read_buf, 6);
    if (status != 0) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to degrees per second
    int16_t raw_x = (int16_t)((read_buf[1] << 8) | read_buf[0]);
    int16_t raw_y = (int16_t)((read_buf[3] << 8) | read_buf[2]);
    int16_t raw_z = (int16_t)((read_buf[5] << 8) | read_buf[4]);

    data->x = (float)raw_x / 114.285;
    data->y = (float)raw_y / 114.285;
    data->z = (float)raw_z / 114.285;

    return 0;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f\n", ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
        }
        gpioDelay(10000); // 10ms delay
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

