#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_I2C_ADDR 0x53
#define ACCEL_X_LSB_REG 0x28
#define ACCEL_X_MSB_REG 0x29
#define ACCEL_Y_LSB_REG 0x2A
#define ACCEL_Y_MSB_REG 0x2B
#define ACCEL_Z_LSB_REG 0x2C
#define ACCEL_Z_MSB_REG 0x2D
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int read_register(int fd, uint8_t reg);
int write_register(int fd, uint8_t reg, uint8_t value);
sensor_data_t read_acceleration(int fd);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read a single register from the I2C device
int read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return value;
}

// Write a single register to the I2C device
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
sensor_data_t read_acceleration(int fd) {
    sensor_data_t data;
    int x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    x_lsb = read_register(fd, ACCEL_X_LSB_REG);
    x_msb = read_register(fd, ACCEL_X_MSB_REG);
    y_lsb = read_register(fd, ACCEL_Y_LSB_REG);
    y_msb = read_register(fd, ACCEL_Y_MSB_REG);
    z_lsb = read_register(fd, ACCEL_Z_LSB_REG);
    z_msb = read_register(fd, ACCEL_Z_MSB_REG);

    if (x_lsb == -1 || x_msb == -1 || y_lsb == -1 || y_msb == -1 || z_lsb == -1 || z_msb == -1) {
        data.x = 0; // Or some error value
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((x_msb << 8) | x_lsb);
    data.y = (int16_t)((y_msb << 8) | y_lsb);
    data.z = (int16_t)((z_msb << 8) | z_lsb);

    return data;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_buffer;
}

// Log data to CSV file
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, D7S_I2C_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    char timestamp[32];
    sensor_data_t accel_data;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        accel_data = read_acceleration(i2c_fd);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(log_file, timestamp, accel_data.x, accel_data.y, accel_data.z) != 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }

        fflush(log_file); // Flush the buffer to ensure data is written

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

