// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int pin);
void log_data(FILE *fp, int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

// Function to read the state of a sensor
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log data to the file
void log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    sprintf(timestamp + strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
    fflush(fp); // Ensure data is written to the file immediately
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Conveyor Halted!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Setup function to initialize pigpio and GPIO pins
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

