    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    printf("Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor1_state = read_sensor(SENSOR1_PIN);
        int sensor2_state = read_sensor(SENSOR2_PIN);

        log_data(log_file, sensor1_state, sensor2_state);

        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        gpioDelay(50); // Wait 50 milliseconds
    }

    cleanup();
    printf("Conveyor belt safety system stopped.\n");
    return 0;
}

