    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize MMA8452Q function
int init_mma8452q(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x2A\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    int ctrl_reg1 = i2c_read_reg(fd, CTRL_REG1);
    if (ctrl_reg1 < 0) return -1;
    ctrl_reg1 &= ~0x01; // Clear active bit
    if (i2c_write_reg(fd, CTRL_REG1, ctrl_reg1) < 0) return -1;

    // Set data rate to 100 Hz (0b010)
    ctrl_reg1 &= ~0x38; // Clear data rate bits
    ctrl_reg1 |= 0x08;  // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG1, ctrl_reg1) < 0) return -1;

    // Set to active mode
    ctrl_reg1 |= 0x01; // Set active bit
    if (i2c_write_reg(fd, CTRL_REG1, ctrl_reg1) < 0) return -1;

    return 0;
}

// Read accelerometer data function
void read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[DATA_LENGTH];
    if (i2c_read_block(fd, DATA_START_REG, data, DATA_LENGTH) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        *x = *y = *z = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    // Combine MSB and LSB, right-shift by 4
    *x = ((int16_t)data[0] << 8 | data[1]) >> 4;
    *y = ((int16_t)data[2] << 8 | data[3]) >> 4;
    *z = ((int16_t)data[4] << 8 | data[5]) >> 4;
}

// Calculate tilt angle function
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 2048.0f; // Assuming +/- 2g range
    float y_g = (float)y / 2048.0f;
    float z_g = (float)z / 2048.0f;

    float tilt_angle = atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0f / PI;
    return tilt_angle;
}

// Log fall event function
void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    running = false;
    printf("Caught signal %d, exiting...\n", sig);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

