        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8452Q
    if (init_mma8452q(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MMA8452Q\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float tilt_angle;

    // Main loop
    while (running) {
        read_accelerometer_data(i2c_fd, &x, &y, &z);
        tilt_angle = calculate_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            log_fall_event(x, y, z);
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(i2c_fd);
    fclose(log_file);

