#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "magnetic_log.txt"
#define METAL_THRESHOLD 800.0 // mG
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE_HZ)

// LIS3MDL Registers
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Calibration Constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Global Variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_lis3mdl(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t x, int16_t y, int16_t z, float *x_calibrated, float *y_calibrated, float *z_calibrated);
float convert_to_mG(int16_t raw_value);
void log_data(float x, float y, float z);
void check_metal_detection(float x, float y, float z);
void signal_handler(int sig);
int init_i2c(const char *device, int address);

// I2C Read Function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, value, 1) != 1) {
    perror("Failed to read register value");
    return -1;
  }
  return 0;
}

// I2C Write Function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("Failed to write register and value");
    return -1;
  }
  return 0;
}

// Initialize LIS3MDL
int init_lis3mdl(int fd) {
  uint8_t who_am_i;

  // Verify sensor presence
  if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) != 0) {
    fprintf(stderr, "Error reading WHO_AM_I register.\n");
    return -1;
  }

  if (who_am_i != 0x3D) {
    fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D.\n", who_am_i);
    return -1;
  }

  // Configure sensor
  if (i2c_write_reg(fd, CTRL_REG1, 0x70) != 0) { // Continuous conversion, 80 Hz ODR
    fprintf(stderr, "Error writing to CTRL_REG1.\n");
    return -1;
  }
  if (i2c_write_reg(fd, CTRL_REG4, 0x0C) != 0) { // High-performance mode
    fprintf(stderr, "Error writing to CTRL_REG4.\n");
    return -1;
  }
  if (i2c_write_reg(fd, CTRL_REG3, 0x00) != 0) { // No interrupt
    fprintf(stderr, "Error writing to CTRL_REG3.\n");
    return -1;
  }

  return 0;
}

// Read Magnetometer Data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t buffer[6];

  if (read(fd, buffer, 6) != 6) {
    perror("Failed to read magnetometer data");
    return -1;
  }

  *x = (int16_t)((buffer[1] << 8) | buffer[0]);
  *y = (int16_t)((buffer[3] << 8) | buffer[2]);
  *z = (int16_t)((buffer[5] << 8) | buffer[4]);

  return 0;
}

// Calibrate Data
void calibrate_data(int16_t x, int16_t y, int16_t z, float *x_calibrated, float *y_calibrated, float *z_calibrated) {
  *x_calibrated = (float)x * X_SCALE + X_OFFSET;
  *y_calibrated = (float)y * Y_SCALE + Y_OFFSET;
  *z_calibrated = (float)z * Z_SCALE + Z_OFFSET;
}

// Convert to mG
float convert_to_mG(int16_t raw_value) {
  return (float)raw_value * 0.146; // 0.146 mG/LSB
}

// Log Data
void log_data(float x, float y, float z) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[64];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
  fflush(log_file); // Ensure data is written to disk immediately
}

// Check Metal Detection
void check_metal_detection(float x, float y, float z) {
  float magnitude = sqrt(x * x + y * y + z * z);
  if (magnitude > METAL_THRESHOLD) {
    fprintf(stderr, "Metal Detected! Magnitude: %.3f mG\n", magnitude);
  }
}

// Signal Handler
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

// Initialize I2C
int init_i2c(const char *device, int address) {
  int fd = open(device, O_RDWR);
  if (fd < 0) {
    perror("Failed to open I2C device");
    return -1;
  }

  if (ioctl(fd, I2C_SLAVE, address) < 0) {
    perror("Failed to set I2C slave address");
    close(fd);
    return -1;
  }

  return fd;
}

int main() {
  int init_attempts = 0;
  int16_t raw_x, raw_y, raw_z;
  float calibrated_x, calibrated_y, calibrated_z;

  // Signal Handling
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize WiringPi
  if (wiringPiSetup() == -1) {
    fprintf(stderr, "WiringPi initialization failed!\n");
    return 1;
  }

  // Initialize SPI
  if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
    fprintf(stderr, "SPI initialization failed!\n");
    return 1;
  }

  // Open Log File
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    return 1;
  }

  // Initialize I2C
  while (init_attempts < 3) {
    i2c_fd = init_i2c(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_fd != -1) {
      if (init_lis3mdl(i2c_fd) == 0) {
        fprintf(stderr, "LIS3MDL initialized successfully.\n");
        break;
      } else {
        fprintf(stderr, "LIS3MDL initialization failed. Attempt %d/3.\n", init_attempts + 1);
        close(i2c_fd);
        i2c_fd = -1;
      }
    } else {
      fprintf(stderr, "I2C initialization failed. Attempt %d/3.\n", init_attempts + 1);
    }
    init_attempts++;
    sleep(1); // Wait before retrying
  }

  if (i2c_fd == -1) {
    fprintf(stderr, "Failed to initialize LIS3MDL after multiple attempts.\n");
    fclose(log_file);
    return 1;
  }

  // Main Loop
  struct timespec sleep_time = {0, SAMPLE_PERIOD_NS};
  while (!terminate) {
    if (read_magnetometer_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
      calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);
      log_data(calibrated_x, calibrated_y, calibrated_z);
      check_metal_detection(calibrated_x, calibrated_y, calibrated_z);
    } else {
      fprintf(stderr, "Failed to read magnetometer data. Re-initializing...\n");
      close(i2c_fd);
      i2c_fd = init_i2c(I2C_DEVICE, I2C_ADDRESS);
      if (i2c_fd != -1) {
        if (init_lis3mdl(i2c_fd) != 0) {
          fprintf(stderr, "LIS3MDL re-initialization failed.\n");
          terminate = 1; // Exit loop if re-initialization fails
        }
      } else {
        fprintf(stderr, "I2C re-initialization failed.\n");
        terminate = 1; // Exit loop if re-initialization fails
      }
    }
    nanosleep(&sleep_time, NULL);
  }

  // Cleanup
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (log_file != NULL) {
    fclose(log_file);
  }

  fprintf(stderr, "Program terminated.\n");
  return 0;
}

