#include <unistd.h>

// ADXL354B Register Addresses
#define RESET_REG       0x1F
#define POWER_CTL       0x2D
#define STATUS_REG      0x04
#define PARTID_REG      0x01
#define XDATA_REG       0x08
#define YDATA_REG       0x0B
#define ZDATA_REG       0x0E

// SPI Configuration
#define SPI_CHANNEL     0
#define SPI_SPEED       1000000 // 1 MHz
#define SPI_MODE        0

// Sensitivity (g/LSB)
#define SENSITIVITY     0.0000039

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int adxl354b_init();
int adxl354b_read_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len);

// Structure for ADXL354B configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    float sensitivity;
} adxl354b_config_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to perform SPI transfer with retries
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (result = %d), retrying...\n", result);
            gpioDelay(1000); // 1 ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries.\n");
    return -1; // Failure
}

// Function to initialize the ADXL354B
int adxl354b_init() {
    uint8_t tx_buf[2], rx_buf[2];
    int result;

    // Reset the device
    tx_buf[0] = RESET_REG | 0x80; // Write bit
    tx_buf[1] = 0x52;
    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B.\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Verify PARTID
    tx_buf[0] = PARTID_REG | 0x80; // Read bit
    tx_buf[1] = 0x00; // Dummy data
    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Failed to read PARTID.\n");
        return -1;
    }

    if (rx_buf[1] != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", rx_buf[1]);
        return -1;
    }

    // Set measurement mode (clear RUN bit in POWER_CTL)
    tx_buf[0] = POWER_CTL | 0x80; // Write bit
    tx_buf[1] = 0x00; // Clear RUN bit
    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Failed to set measurement mode (clear RUN).\n");
        return -1;
    }

    // Wait for STABLE bit in STATUS to be set
    tx_buf[0] = STATUS_REG | 0x80; // Read bit
    tx_buf[1] = 0x00; // Dummy data
    int timeout = 100; // Timeout after 100 attempts
    while (timeout > 0) {
        if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
            fprintf(stderr, "Failed to read STATUS.\n");
            return -1;
        }
        if (rx_buf[1] & 0x01) {
            break; // STABLE bit is set
        }
        gpioDelay(1000); // 1 ms delay
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for STABLE bit.\n");
        return -1;
    }

    // Set RUN bit in POWER_CTL
    tx_buf[0] = POWER_CTL | 0x80; // Write bit
    tx_buf[1] = 0x01; // Set RUN bit
    if (spi_transfer(tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Failed to set measurement mode (set RUN).\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_data(float *x, float *y, float *z) {
    uint8_t tx_buf[7], rx_buf[7];
    int32_t raw_x, raw_y, raw_z;

    // Read X, Y, and Z data (3 bytes each)
    tx_buf[0] = XDATA_REG | 0xC0; // Read bit + multi-byte bit
    memset(tx_buf + 1, 0x00, 6); // Dummy data

    if (spi_transfer(tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Failed to read acceleration data.\n");
        return -1;
    }

    // Combine the bytes to form 20-bit signed integers
    raw_x = ((int32_t)rx_buf[1] << 12) | ((int32_t)rx_buf[2] << 4) | ((int32_t)rx_buf[3] >> 4);
    raw_x = (raw_x << 12) >> 12; // Sign extend to 32 bits

    raw_y = ((int32_t)rx_buf[3] << 12) | ((int32_t)rx_buf[4] << 4) | ((int32_t)rx_buf[5] >> 4);
    raw_y = (raw_y << 12) >> 12; // Sign extend to 32 bits

    raw_z = ((int32_t)rx_buf[5] << 12) | ((int32_t)rx_buf[6] << 4);
    raw_z = (raw_z << 12) >> 12; // Sign extend to 32 bits

    // Convert to g's
    *x = (float)raw_x * SENSITIVITY;
    *y = (float)raw_y * SENSITIVITY;
    *z = (float)raw_z * SENSITIVITY;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (adxl354b_read_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read data, retrying initialization...\n");
            adxl354b_init(); // Attempt to re-initialize
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

