#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR1_PIN);
    *sensor2_value = gpioRead(SENSOR2_PIN);

    // Validate sensor readings
    if (*sensor1_value != 0 && *sensor1_value != 1) {
        fprintf(stderr, "Error: Invalid sensor 1 reading: %d\n", *sensor1_value);
        return -1; // Indicate an error
    }
    if (*sensor2_value != 0 && *sensor2_value != 1) {
        fprintf(stderr, "Error: Invalid sensor 2 reading: %d\n", *sensor2_value);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor1_value, sensor2_value;

        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            // Log the data
            log_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensors, skipping logging.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

