#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// ADIS16266 Register Addresses
#define MSC_CTRL_REG 0x24
#define XGYRO_OUT_REG 0x04
#define YGYRO_OUT_REG 0x06
#define ZGYRO_OUT_REG 0x08

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// GPIO Configuration
#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(const char *chip, int line);
int gpio_set_value(struct gpiod_line *line, int value);
int adis16266_write_register(int fd, uint8_t reg, uint16_t value);
int adis16266_read_register(int fd, uint8_t reg, uint16_t *value);
void signal_handler(int sig);

// SPI Initialization Function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer Function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO Initialization Function
int gpio_init(const char *chip, int line) {
    struct gpiod_chip *chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_handle = gpiod_chip_get_line(chip_handle, line);
    if (!line_handle) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_handle);
        return -1;
    }

    if (gpiod_line_request_output_flags(line_handle, "adis16266_cs", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_handle);
        gpiod_line_release(line_handle);
        return -1;
    }

    return 0;
}

// GPIO Set Value Function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// ADIS16266 Write Register Function
int adis16266_write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = (value >> 8) & 0xFF; // MSB
    tx_buf[2] = value & 0xFF; // LSB

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// ADIS16266 Read Register Function
int adis16266_read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t tx_buf[1];
    uint8_t rx_buf[3];

    tx_buf[0] = reg | 0x80; // Set MSB for read

    if (spi_transfer(fd, tx_buf, rx_buf, 1) < 0) {
        fprintf(stderr, "Error sending read command to register 0x%02X\n", reg);
        return -1;
    }

    if (spi_transfer(fd, rx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)rx_buf[1] << 8) | rx_buf[2];

    return 0;
}

// Signal Handler Function
