#define CS_GPIO_LINE 8

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(const char *chip, int line);
int gpio_set_value(struct gpiod_line *line, int value);
int adis16266_write_register(int fd, uint8_t reg, uint16_t value);
int adis16266_read_register(int fd, uint8_t reg, uint16_t *value);
void signal_handler(int sig);

// SPI Initialization Function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer Function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO Initialization Function
int gpio_init(const char *chip, int line) {
    struct gpiod_chip *chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line_handle = gpiod_chip_get_line(chip_handle, line);
    if (!line_handle) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip_handle);
        return -1;
    }

    if (gpiod_line_request_output_flags(line_handle, "adis16266_cs", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip_handle);
        gpiod_line_release(line_handle);
        return -1;
    }

    return 0;
}

