#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr()
{
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%X (expected 0x6B)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer (CTRL1_XL = 0x42)
    int status = i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL1_XL register: %d\n", status);
        return -1;
    }

    // Configure gyroscope (CTRL2_G = 0x42)
    status = i2cWriteByteData(i2c_handle, CTRL2_G, 0x42);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL2_G register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_lsm6dsr_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z)
{
    char buffer[12];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);

    if (bytes_read != 12) {
        fprintf(stderr, "Error reading data: %d bytes read (expected 12)\n", bytes_read);
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

// Function to convert raw data to physical units
void convert_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw,
                  float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g)
{
    *gyro_x_dps = gyro_x_raw * 0.00875f;
    *gyro_y_dps = gyro_y_raw * 0.00875f;
    *gyro_z_dps = gyro_z_raw * 0.00875f;
    *accel_x_g = accel_x_raw * 0.000061f;
    *accel_y_g = accel_y_raw * 0.000061f;
    *accel_z_g = accel_z_raw * 0.000061f;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw;
        float gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g;

        // Read data from LSM6DSR
        if (read_lsm6dsr_data(&gyro_x_raw, &gyro_y_raw, &gyro_z_raw, &accel_x_raw, &accel_y_raw, &accel_z_raw) == 0) {
            // Convert data to physical units
            convert_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, accel_x_raw, accel_y_raw, accel_z_raw,
                         &gyro_x_dps, &gyro_y_dps, &gyro_z_dps, &accel_x_g, &accel_y_g, &accel_z_g);

            // Print data to stdout
            printf("GyroX: %.2f dps, GyroY: %.2f dps, GyroZ: %.2f dps, AccelX: %.2f g, AccelY: %.2f g, AccelZ: %.2f g\n",
                   gyro_x_dps, gyro_y_dps, gyro_z_dps, accel_x_g, accel_y_g, accel_z_g);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

