#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor(int handle) {
    // Verify sensor presence
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Hybrid mode, 100 Hz ODR)
    if (write_register(handle, CTRL_REG1, 0x39) < 0) return -1;

    // Configure CTRL_REG2 (Active mode)
    if (write_register(handle, CTRL_REG2, 0x02) < 0) return -1;

    // Configure M_CTRL_REG1 (Magnetometer active mode)
    if (write_register(handle, M_CTRL_REG1, 0x1F) < 0) return -1;

    // Configure M_CTRL_REG2 (Magnetometer hybrid mode)
    if (write_register(handle, M_CTRL_REG2, 0x00) < 0) return -1;

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(handle, OUT_X_MSB, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract accelerometer data (14-bit left-aligned)
    *accel_x = ((int16_t)buffer[0] << 6) | (buffer[1] >> 2);
    *accel_y = ((int16_t)buffer[2] << 6) | (buffer[3] >> 2);
    *accel_z = ((int16_t)buffer[4] << 6) | (buffer[5] >> 2);

    // Extract magnetometer data (16-bit)
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

