#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Tilt threshold in degrees
#define TILT_THRESHOLD 30.0

// Log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_tilt_event(double angle);
void signal_handler(int signal);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
  if (write(fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }
  if (read(fd, value, 1) != 1) {
    perror("Failed to read register value");
    return -1;
  }
  return 0;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("Failed to write register value");
    return -1;
  }
  return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t x0, x1, y0, y1, z0, z1;

  if (i2c_read_reg(fd, ADXL345_REG_DATAX0, &x0) != 0) return -1;
  if (i2c_read_reg(fd, ADXL345_REG_DATAX1, &x1) != 0) return -1;
  if (i2c_read_reg(fd, ADXL345_REG_DATAY0, &y0) != 0) return -1;
  if (i2c_read_reg(fd, ADXL345_REG_DATAY1, &y1) != 0) return -1;
  if (i2c_read_reg(fd, ADXL345_REG_DATAZ0, &z0) != 0) return -1;
  if (i2c_read_reg(fd, ADXL345_REG_DATAZ1, &z1) != 0) return -1;

  *x = (int16_t)((x1 << 8) | x0);
  *y = (int16_t)((y1 << 8) | y0);
  *z = (int16_t)((z1 << 8) | z0);

  return 0;
}

// Calculate tilt angle function
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
  double angle = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
  return angle;
}

// Log tilt event function
void log_tilt_event(double angle) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[64];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  fprintf(log_file, "%s - Tilt angle exceeded threshold: %.2f degrees\n", timestamp, angle);
  fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
  program_running = 0;
  printf("Caught signal %d, exiting...\n", signal);
}

int main() {
  // Register signal handler
  signal(SIGINT, signal_handler);

  // Open I2C device
  i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C device");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    close(i2c_fd);
    return 1;
  }

  // Initialize ADXL345 (wake up)
  if (i2c_write_reg(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
    fprintf(stderr, "Failed to initialize ADXL345\n");
    fclose(log_file);
    close(i2c_fd);
    return 1;
  }

  int16_t x, y, z;
  double angle;

  // Main loop
  while (program_running) {
    // Read accelerometer data
    if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
      // Calculate tilt angle
      angle = calculate_tilt_angle(x, y, z);

      // Check if tilt angle exceeds threshold
      if (fabs(angle) > TILT_THRESHOLD) {
        log_tilt_event(angle);
      }
    } else {
      fprintf(stderr, "Failed to read accelerometer data\n");
    }

    // Wait 100ms
    usleep(100000);
  }

  // Close I2C device and log file
  close(i2c_fd);
  fclose(log_file);

  return 0;
}

