#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define WINDOW_DURATION_MS 5000
#define SAMPLE_INTERVAL_MS 1
#define SAMPLES_PER_WINDOW (WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS)

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;

    // Validate command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int high_count;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    while (program_running) {
        high_count = 0;

        // Sample GPIO pin for 5 seconds
        for (int i = 0; i < SAMPLES_PER_WINDOW; ++i) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
        }

        // Check if threshold is exceeded
        if (high_count > threshold) {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print ALERT message
            printf("%s ALERT: Noise level exceeded threshold (%d > %d)\n", timestamp, high_count, threshold);
        } else {
            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print normal status line
            printf("%s Status: Noise level below threshold (%d <= %d)\n", timestamp, high_count, threshold);
        }

        // Pause for 1 second
        sleep(1);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

