#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *door_a_line;
static struct gpiod_line *door_b_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void signal_handler(int sig);
int generate_random_code(char *code);
int prompt_for_code(char *code);
int unlock_door_a(void);
int log_access(const char *code);
void clear_input_buffer(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        return -1;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(door_a_line);
        gpiod_line_release(door_b_line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0);
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Generate a random 6-digit code
int generate_random_code(char *code) {
    srand(time(NULL));
    int random_number = (rand() % 900000) + 100000;
    sprintf(code, "%d", random_number);
    return 0;
}

// Prompt the user for a 6-digit code
int prompt_for_code(char *code) {
    printf("Enter the 6-digit security code: ");
    if (fgets(code, 7, stdin) == NULL) {
        fprintf(stderr, "Error reading input\n");
        return -1;
    }

    // Remove trailing newline character
    code[strcspn(code, "\n")] = 0;

    // Validate input
    for (int i = 0; i < strlen(code); i++) {
        if (code[i] < '0' || code[i] > '9') {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            clear_input_buffer();
            return -1;
        }
    }

    if (strlen(code) != 6) {
        fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
        clear_input_buffer();
        return -1;
    }

    return 0;
}

// Unlock Door A for 5 seconds
int unlock_door_a(void) {
    if (gpiod_line_set_value(door_a_line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line %d HIGH: %s\n", DOOR_A_PIN, strerror(errno));
        return -1;
    }
    sleep(5);
    if (gpiod_line_set_value(door_a_line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line %d LOW: %s\n", DOOR_A_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

// Log access to file
int log_access(const char *code) {
    FILE *fp = fopen("access_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening access_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%s\n", timestamp, code);
    fclose(fp);
    return 0;
}

// Clear input buffer
void clear_input_buffer(void) {
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    char code[7];
    char entered_code[7];

    // Generate initial code
    if (generate_random_code(code) < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    printf("Initial security code: %s\n", code);

    // Main loop
    while (!terminate) {
        // Prompt for code
        if (prompt_for_code(entered_code) < 0) {
            continue; // Skip to the next iteration if input is invalid
        }

        // Compare codes
        if (strcmp(code, entered_code) == 0) {
            printf("Access granted!\n");
            if (unlock_door_a() < 0) {
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            if (log_access(code) < 0) {
                cleanup_gpio();
                return EXIT_FAILURE;
            }

            // Generate new code
            if (generate_random_code(code) < 0) {
                cleanup_gpio();
                return EXIT_FAILURE;
            }
            printf("New security code: %s\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return EXIT_SUCCESS;
}

