#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x21
#define LUX_CONVERSION_FACTOR 1.2
#define LOG_FILE "light_log.txt"
#define SLEEP_SECONDS 5

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to the I2C device
int write_i2c(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int read_i2c(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read illuminance from the BH1750FVI sensor
float read_illuminance(int fd) {
    unsigned char data[2];

    // Send the One-Time High-Resolution Mode 2 command
    if (write_i2c(fd, BH1750_CMD) < 0) {
        return -1.0;
    }

    // Wait for the conversion time (180ms)
    usleep(180000);

    // Read the 2 bytes of data
    if (read_i2c(fd, data, 2) < 0) {
        return -1.0;
    }

    // Combine the bytes into a 16-bit value
    unsigned int raw_value = (data[0] << 8) | data[1];

    // Calculate the illuminance in lux
    float lux = (float)raw_value / LUX_CONVERSION_FACTOR;

    return lux;
}

// Function to log the illuminance data to a file
int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);

    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Read the illuminance
        float lux = read_illuminance(i2c_fd);

        // Check for errors
        if (lux < 0) {
            fprintf(stderr, "Error reading illuminance, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Log the data
        if (log_data(lux) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_SECONDS);
    }

    // This point should not be reached due to the signal handler
    close(i2c_fd);
    return 0;
}

