volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(int *touch_data);
float map_touch_to_frequency(int touch_value);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);
void cleanup();

// Function to initialize the MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Configure electrode sensitivity and release thresholds
    for (int i = 0x41; i <= 0x5A; i++) {
        if (i2cWriteByteData(i2c_handle, i, 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i - 0x41);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, i + 0x0C, 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i - 0x41);
            return -1;
        }
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Enable electrodes 0-11
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Configure MPR121 to operate in run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable all electrodes\n");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }

    *touch_data = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Function to map touch data to a frequency using a logarithmic scale
float map_touch_to_frequency(int touch_value) {
    // Assuming touch_value ranges from 0 to 2047 (12 electrodes, 14-bit data)
    float normalized_value = (float)touch_value / 2047.0;
    float frequency_range = MAX_FREQUENCY - MIN_FREQUENCY;
    float frequency = MIN_FREQUENCY + frequency_range * pow(normalized_value, 2.0); // Logarithmic mapping
    return frequency;
}

// Function to play a tone using hardware PWM
void play_tone(float frequency) {
    int duty_cycle = (int)(PWM_RANGE * 0.5); // 50% duty cycle
    gpioPWM(PWM_GPIO, duty_cycle);
    gpioSetPWMfrequency(PWM_GPIO, (int)frequency);
}

// Function to log the frequency to a file
void log_frequency(float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %.2f Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        return;
    }

    // Check for motion detection message
    if (strncmp(buffer, MOTION_PREFIX, strlen(MOTION_PREFIX)) == 0) {
        char *secret_key_start = strstr(buffer, SECRET_KEY);
        if (secret_key_start != NULL) {
            // Motion detected and secret key found
            printf("Motion detected! Playing theremin.\n");

            int touch_data;
            float frequency;
            time_t start_time = time(NULL);

            while (time(NULL) - start_time < PLAYBACK_DURATION && !terminate) {
                if (read_touch_data(&touch_data) == 0) {
                    frequency = map_touch_to_frequency(touch_data);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading touch data during playback.\n");
                }
                gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
            }

            gpioPWM(PWM_GPIO, 0); // Stop PWM after playback
            printf("Playback finished.\n");
        } else {
            fprintf(stderr, "Error: Secret key not found in message.\n");
        }
    } else {
        printf("Received message: %s\n", buffer);
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO mode
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept connections and handle clients
    while (!terminate) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&client_address_len);
        if (new_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));
        handle_client(new_socket);
    }

    cleanup();
    return 0;
}

