#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <stdbool.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "magnetometer.log"

// Global variables (minimize usage)
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int lsm303_init(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int gpio_init(int gpio);
int pwm_init(int chip, int channel, int period);
int set_pwm_duty_cycle(int chip, int channel, int duty_cycle);
void cleanup(int signal);

// I2C initialization function
int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// LSM303 initialization function
int lsm303_init(int fd) {
    // Enable continuous conversion at 10 Hz
    if (i2c_write_byte(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Error initializing LSM303");
        return -1;
    }
    return 0;
}

// Read magnetometer data function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, OUT_X_L_M, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Calculate magnitude function
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// GPIO initialization function
int gpio_init(int gpio) {
    gpio_chip = gpiod_chip_open_by_number(PWM_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, gpio);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(led_line, "magnetometer_led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// PWM initialization function
int pwm_init(int chip, int channel, int period) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "pwmchip%d", chip);

    char export_path[50];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/%s/export", chip_name);

    FILE *export_file = fopen(export_path, "w");
    if (!export_file) {
        perror("Error opening PWM export file");
        return -1;
    }

    fprintf(export_file, "%d", channel);
    fclose(export_file);

    char period_path[50];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/%s/pwm%d/period", chip_name, channel);

    FILE *period_file = fopen(period_path, "w");
    if (!period_file) {
        perror("Error opening PWM period file");
        return -1;
    }

    fprintf(period_file, "%d", period);
    fclose(period_file);

    char enable_path[50];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/%s/pwm%d/enable", chip_name, channel);

    FILE *enable_file = fopen(enable_path, "w");
    if (!enable_file) {
        perror("Error opening PWM enable file");
        return -1;
    }

    fprintf(enable_file, "1");
    fclose(enable_file);

    return 0;
}

// Set PWM duty cycle function
int set_pwm_duty_cycle(int chip, int channel, int duty_cycle) {
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "pwmchip%d", chip);

    char duty_cycle_path[50];
    snprintf(duty_cycle_path, sizeof(duty_cycle_path), "/sys/class/pwm/%s/pwm%d/duty_cycle", chip_name, channel);

    FILE *duty_cycle_file = fopen(duty_cycle_path, "w");
    if (!duty_cycle_file) {
        perror("Error opening PWM duty cycle file");
        return -1;
    }

    fprintf(duty_cycle_file, "%d", duty_cycle);
    fclose(duty_cycle_file);

    return 0;
}

// Cleanup function
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");

    // Disable PWM
    set_pwm_duty_cycle(PWM_CHIP, PWM_CHANNEL, 0);

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Release GPIO line
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Signal handling
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize logging
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(log_file, "%ld: I2C initialization failed\n", time(NULL));
        fclose(log_file);
        return 1;
    }

    // Initialize LSM303
    if (lsm303_init(i2c_fd) < 0) {
        fprintf(log_file, "%ld: LSM303 initialization failed\n", time(NULL));
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(LED_GPIO) < 0) {
        fprintf(log_file, "%ld: GPIO initialization failed\n", time(NULL));
        close(i2c_fd);
        fclose(log_file);
        return 1;
    }

    // Initialize PWM
    if (pwm_init(PWM_CHIP, PWM_CHANNEL, PWM_PERIOD) < 0) {
        fprintf(log_file, "%ld: PWM initialization failed\n", time(NULL));
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    double magnitude;
    int duty_cycle;

    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Map magnitude to duty cycle (0-100%)
            duty_cycle = (int)((magnitude / 1000.0) * PWM_PERIOD); // Scale magnitude to 0-1000
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > PWM_PERIOD) duty_cycle = PWM_PERIOD;

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(PWM_CHIP, PWM_CHANNEL, duty_cycle) < 0) {
                fprintf(log_file, "%ld: Failed to set PWM duty cycle\n", time(NULL));
            }

            // Log data
            fprintf(log_file, "%ld: X=%d, Y=%d, Z=%d, Magnitude=%.2f, Duty Cycle=%d\n", time(NULL), x, y, z, magnitude, duty_cycle);
            fflush(log_file);
        } else {
            fprintf(log_file, "%ld: Failed to read magnetometer data\n", time(NULL));
            fflush(log_file);
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    return 0;
}

