// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define CONFIG_A_VALUE 0x70
#define CONFIG_B_VALUE 0x20
#define MODE_CONTINUOUS 0x00

// Number of samples for hard-iron offset calculation
#define NUM_SAMPLES 100

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Write configuration register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Error writing to configuration register A\n");
        return -1;
    }

    // Write configuration register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Error writing to configuration register B\n");
        return -1;
    }

    // Write mode register
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes of data (X, Z, Y)
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate hard-iron offsets
void calculate_offsets(int16_t x, int16_t y, int16_t z, int16_t *x_offset, int16_t *y_offset, int16_t *z_offset, int *sample_count) {
    static int16_t x_sum = 0;
    static int16_t y_sum = 0;
    static int16_t z_sum = 0;

    x_sum += x;
    y_sum += y;
    z_sum += z;

    (*sample_count)++;

    if (*sample_count >= NUM_SAMPLES) {
        *x_offset = x_sum / NUM_SAMPLES;
        *y_offset = y_sum / NUM_SAMPLES;
        *z_offset = z_sum / NUM_SAMPLES;
        *sample_count = 0; // Reset sample count
        x_sum = 0; // Reset sums
        y_sum = 0;
        z_sum = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    int sample_count = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 ms

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&x, &y, &z) == 0) {
            // Calculate offsets
            calculate_offsets(x, y, z, &x_offset, &y_offset, &z_offset, &sample_count);

            // Apply offsets
            int16_t x_corrected = x - x_offset;
            int16_t y_corrected = y - y_offset;
            int16_t z_corrected = z - z_offset;

            // Print corrected values
            printf("X: %d, Y: %d, Z: %d\n", x_corrected, y_corrected, z_corrected);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

