// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Circular buffer structure
typedef struct {
    acceleration_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
