        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Get line for solenoid 1
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting line %d: %s\n", SOLENOID1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line for solenoid 2
    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting line %d: %s\n", SOLENOID2_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Configure line request
    memset(&config, 0, sizeof(config));
    config.consumer = "solenoid_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    // Request line for solenoid 1
    ret = gpiod_line_request(solenoid1_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", SOLENOID1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line for solenoid 2
    ret = gpiod_line_request(solenoid2_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", SOLENOID2_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the state of a solenoid
int set_solenoid_state(int solenoid, int state) {
    struct gpiod_line *line;
    int ret;

    if (solenoid == 1) {
        line = solenoid1_line;
    } else if (solenoid == 2) {
        line = solenoid2_line;
    } else {
        fprintf(stderr, "Invalid solenoid number: %d\n", solenoid);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for solenoid %d: %s\n", solenoid, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to alternate solenoid states
int alternate_solenoids(void) {
    struct timespec delay = {0, 500000000}; // 500 ms
    int ret;

    // Energize solenoid 1
    ret = set_solenoid_state(1, 1);
    if (ret < 0) return -1;
    ret = set_solenoid_state(2, 0);
    if (ret < 0) return -1;
    nanosleep(&delay, NULL);

    // De-energize solenoid 1, energize solenoid 2
    ret = set_solenoid_state(1, 0);
    if (ret < 0) return -1;
    ret = set_solenoid_state(2, 1);
    if (ret < 0) return -1;
    nanosleep(&delay, NULL);

    // De-energize solenoid 2
    ret = set_solenoid_state(2, 0);
    if (ret < 0) return -1;
    nanosleep(&delay, NULL);

    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(void) {
    if (solenoid1_line) {
        gpiod_line_set_value(solenoid1_line, 0);
        gpiod_line_release(solenoid1_line);
    }
    if (solenoid2_line) {
        gpiod_line_set_value(solenoid2_line, 0);
        gpiod_line_release(solenoid2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        if (alternate_solenoids() < 0) {
            fprintf(stderr, "Error alternating solenoids, exiting.\n");
            cleanup_gpio();
            return 1;
        }
    }

