// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

// Function to open a UART device
int open_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, read enable
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode
    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 50; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a 6-digit code from a UART port
int read_code(int fd, char *code, size_t code_len) {
    char buffer[1];
    size_t i = 0;
    time_t start_time = time(NULL);

    while (program_running) {
        ssize_t bytes_read = read(fd, buffer, 1);
        if (bytes_read > 0) {
            if (buffer[0] >= '0' && buffer[0] <= '9') {
                code[i++] = buffer[0];
                if (i == code_len) {
                    code[i] = '\0';
                    return 0; // Success
                }
            } else {
                // Reset the buffer on non-digit characters
                i = 0;
                code[0] = '\0';
            }
        } else if (bytes_read < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1; // Error
        }

        if (time(NULL) - start_time >= 5) {
            code[0] = '\0'; // Timeout
            return -2; // Timeout
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }
    return -3; // Program terminated
}

// Function to compare two codes securely
int compare_codes(const char *code1, const char *code2) {
    if (code1 == NULL || code2 == NULL) {
