}

// Function to lock the doors
void lock_doors() {
    if (gpioWrite(LOCK1_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", LOCK1_GPIO, strerror(errno));
    }
    if (gpioWrite(LOCK2_GPIO, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", LOCK2_GPIO, strerror(errno));
    }
}

