        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char primary_code[CODE_LENGTH + 1] = {0};
    char secondary_code[CODE_LENGTH + 1] = {0};

    // Main loop
    while (program_running) {
        int primary_result = read_code(primary_fd, primary_code, CODE_LENGTH);
        int secondary_result = read_code(secondary_fd, secondary_code, CODE_LENGTH);

        if (primary_result == 0 && secondary_result == 0) {
            if (compare_codes(primary_code, secondary_code) && compare_codes(primary_code, EXPECTED_CODE)) {
                unlock_doors();
                lock_doors();
                primary_code[0] = '\0'; // Reset codes
                secondary_code[0] = '\0';
            } else {
                fprintf(stderr, "Authentication failed: Codes do not match or are incorrect.\n");
                primary_code[0] = '\0'; // Reset codes
                secondary_code[0] = '\0';
            }
        } else if (primary_result == -1 || secondary_result == -1) {
            fprintf(stderr, "Error reading from UART. Exiting.\n");
            program_running = 0;
        } else if (primary_result == -2 || secondary_result == -2) {
            // Timeout occurred, reset codes
            primary_code[0] = '\0';
            secondary_code[0] = '\0';
        } else if (primary_result == -3 || secondary_result == -3) {
            // Program terminated, exit loop
            break;
        }

        usleep(10000); // Small delay to avoid busy-waiting
    }

    // Clean up
    close(primary_fd);
    close(secondary_fd);
    lock_doors(); // Ensure doors are locked on exit
    gpioTerminate();

