#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define constants
#define RELAY_ON_DURATION_MS 1000
#define FAILSAFE_TIMEOUT_S 10
#define POLL_INTERVAL_MS 50

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
void log_event(int priority, const char *message);
void signal_handler(int sig);
void cleanup_gpio(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        log_event(LOG_INFO, "Received termination signal, shutting down...");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Get PIR line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Error getting PIR line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR line as input
    ret = gpiod_line_request_input(pir_line, "motion_detector");
    if (ret < 0) {
        syslog(LOG_ERR, "Error requesting PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get Relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Error getting Relay line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request Relay line as output
    ret = gpiod_line_request_output(relay_line, "motion_detector", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Error requesting Relay line as output: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading PIR sensor value: %s", strerror(errno));
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Error setting relay state: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Log events to syslog
void log_event(int priority, const char *message) {
    syslog(priority, message);
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (relay_line) {
        control_relay(0); // Ensure relay is off
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main(void) {
    int pir_value;
    time_t motion_start_time = 0;
    int failsafe_triggered = 0;

    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_event(LOG_ERR, "GPIO initialization failed, exiting.");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Motion detector started.");

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            log_event(LOG_ERR, "Error reading PIR sensor, exiting.");
            break;
        }

        if (pir_value == 1) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                log_event(LOG_INFO, "Motion detected!");
            }

            if (!failsafe_triggered) {
                // Activate relay
                if (control_relay(1) == 0) {
                    log_event(LOG_INFO, "Relay activated.");
                } else {
                    log_event(LOG_ERR, "Failed to activate relay.");
                }

                // Wait for relay activation duration
                usleep(RELAY_ON_DURATION_MS * 1000); // Convert ms to microseconds

                // Deactivate relay
                if (control_relay(0) == 0) {
                    log_event(LOG_INFO, "Relay deactivated.");
                } else {
                    log_event(LOG_ERR, "Failed to deactivate relay.");
                }
            }
        } else {
            motion_start_time = 0;
            failsafe_triggered = 0;
        }

        // Failsafe mechanism
        if (motion_start_time != 0 && !failsafe_triggered) {
            time_t current_time = time(NULL);
            if (difftime(current_time, motion_start_time) >= FAILSAFE_TIMEOUT_S) {
                log_event(LOG_WARNING, "Failsafe triggered: PIR sensor HIGH for too long.");
                if (control_relay(0) == 0) {
                    log_event(LOG_INFO, "Relay deactivated due to failsafe.");
                } else {
                    log_event(LOG_ERR, "Failed to deactivate relay during failsafe.");
                }
                failsafe_triggered = 1;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    // Cleanup and exit
    log_event(LOG_INFO, "Exiting motion detector.");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

