#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define constants for the state machine
#define STATE_INIT 0
#define STATE_RELAY1 1
#define STATE_RELAY2 2
#define STATE_RELAY3 3
#define STATE_RELAY4 4
#define STATE_PAUSE 5

// Define constants for timer intervals (in seconds)
#define RELAY_ON_TIME 300
#define PAUSE_TIME 60

// Global variables
volatile sig_atomic_t program_running = 1;
int current_state = STATE_INIT;
int timer_id = 0;

// Function prototypes
void relay_on(int pin);
void relay_off(int pin);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to turn a relay ON (active-LOW)
void relay_on(int pin) {
    gpioWrite(pin, 0); // Set GPIO LOW to activate the relay
    char message[100];
    snprintf(message, sizeof(message), "Relay on GPIO %d activated", pin);
    log_message(LOG_INFO, message);
}

// Function to turn a relay OFF (active-LOW)
void relay_off(int pin) {
    gpioWrite(pin, 1); // Set GPIO HIGH to deactivate the relay
    char message[100];
    snprintf(message, sizeof(message), "Relay on GPIO %d deactivated", pin);
    log_message(LOG_INFO, message);
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    switch (current_state) {
        case STATE_INIT:
            // Initialize all relays to OFF
            relay_off(RELAY1_PIN);
            relay_off(RELAY2_PIN);
            relay_off(RELAY3_PIN);
            relay_off(RELAY4_PIN);
            current_state = STATE_RELAY1;
            gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME, timer_callback, NULL); // Start timer for relay 1
            break;
        case STATE_RELAY1:
            relay_on(RELAY1_PIN);
            current_state = STATE_PAUSE;
            gpioSetTimerFuncEx(timer_id, PAUSE_TIME, timer_callback, NULL); // Start pause timer
            break;
        case STATE_RELAY2:
            relay_on(RELAY2_PIN);
            current_state = STATE_PAUSE;
            gpioSetTimerFuncEx(timer_id, PAUSE_TIME, timer_callback, NULL); // Start pause timer
            break;
        case STATE_RELAY3:
            relay_on(RELAY3_PIN);
            current_state = STATE_PAUSE;
            gpioSetTimerFuncEx(timer_id, PAUSE_TIME, timer_callback, NULL); // Start pause timer
            break;
        case STATE_RELAY4:
            relay_on(RELAY4_PIN);
            current_state = STATE_PAUSE;
            gpioSetTimerFuncEx(timer_id, PAUSE_TIME, timer_callback, NULL); // Start pause timer
            break;
        case STATE_PAUSE:
            // Deactivate the previously activated relay
            switch (current_state) {
                case STATE_RELAY1:
                    relay_off(RELAY1_PIN);
                    current_state = STATE_RELAY2;
                    gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME, timer_callback, NULL); // Start timer for relay 2
                    break;
                case STATE_RELAY2:
                    relay_off(RELAY2_PIN);
                    current_state = STATE_RELAY3;
                    gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME, timer_callback, NULL); // Start timer for relay 3
                    break;
                case STATE_RELAY3:
                    relay_off(RELAY3_PIN);
                    current_state = STATE_RELAY4;
                    gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME, timer_callback, NULL); // Start timer for relay 4
                    break;
                case STATE_RELAY4:
                    relay_off(RELAY4_PIN);
                    current_state = STATE_RELAY1;
                    gpioSetTimerFuncEx(timer_id, RELAY_ON_TIME, timer_callback, NULL); // Start timer for relay 1
                    break;
                default:
                    log_message(LOG_ERR, "Invalid state in pause handler");
                    break;
            }
            break;
        default:
            log_message(LOG_ERR, "Invalid state in timer callback");
            break;
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");

    // Deactivate all relays
    relay_off(RELAY1_PIN);
    relay_off(RELAY2_PIN);
    relay_off(RELAY3_PIN);
    relay_off(RELAY4_PIN);

    // Cancel the timer
    gpioSetTimerFuncEx(timer_id, 0, NULL, NULL);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    exit(0);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial relay states to OFF
    relay_off(RELAY1_PIN);
    relay_off(RELAY2_PIN);
    relay_off(RELAY3_PIN);
    relay_off(RELAY4_PIN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer function
    timer_id = 0; // Timer ID is always 0 with gpioSetTimerFuncEx
    gpioSetTimerFuncEx(timer_id, 1, timer_callback, NULL); // Initial timer call to start the sequence

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to avoid busy-waiting
    }

    return 0;
}

