#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Accelerometer range
#define ACCEL_RANGE_2G 0x00

// Sampling rate
#define SAMPLE_RATE 100 // Hz

// Circular buffer size
#define BUFFER_SIZE 100

// Sysfs path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel/latest"

// Global variables
int i2c_fd = -1;
int sysfs_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold acceleration data
typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

// Circular buffer
accel_data_t accel_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int init_mpu6050(int fd);
void sample_acceleration(int fd);
void signal_handler(int sig);
int create_sysfs_file();
int write_sysfs_data();
void cleanup();

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, ACCEL_RANGE_2G) != 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    return 0;
}

// Sample acceleration data function
void sample_acceleration(int fd) {
    uint8_t data[6];
    int16_t x, y, z;

    // Read acceleration data
    if (i2c_read_reg(fd, ACCEL_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return;
    }

    // Combine high and low bytes
    x = (int16_t)((data[0] << 8) | data[1]);
    y = (int16_t)((data[2] << 8) | data[3]);
    z = (int16_t)((data[4] << 8) | data[5]);

    // Scale to g
    accel_buffer[buffer_index].x = (float)x / 16384.0f;
    accel_buffer[buffer_index].y = (float)y / 16384.0f;
    accel_buffer[buffer_index].z = (float)z / 16384.0f;

    // Update buffer index
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Write to sysfs
    write_sysfs_data();
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Create sysfs file function
int create_sysfs_file() {
    // Create the directory if it doesn't exist
    if (mkdir("/sys/kernel/mpu6050_accel", 0755) == -1 && errno != EEXIST) {
        perror("Failed to create directory");
        return -1;
    }

    // Create the file
    sysfs_fd = open(SYSFS_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (sysfs_fd == -1) {
        perror("Failed to create sysfs file");
        return -1;
    }

    return 0;
}

// Write to sysfs file function
int write_sysfs_data() {
    char buffer[256];
    int len;

    // Format the data
    len = snprintf(buffer, sizeof(buffer), "%.3f,%.3f,%.3f\n", accel_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE].x, accel_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE].y, accel_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE].z);

    // Write to the file
    if (write(sysfs_fd, buffer, len) != len) {
        perror("Failed to write to sysfs file");
        return -1;
    }

    // Seek to the beginning of the file
    if (lseek(sysfs_fd, 0, SEEK_SET) == -1) {
        perror("Failed to seek to beginning of sysfs file");
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close sysfs file
    if (sysfs_fd != -1) {
        close(sysfs_fd);
    }

    // Remove sysfs file and directory
    unlink(SYSFS_PATH);
    rmdir("/sys/kernel/mpu6050_accel");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        cleanup();
        return 1;
    }

    // Create sysfs file
    if (create_sysfs_file() != 0) {
        fprintf(stderr, "Failed to create sysfs file\n");
        cleanup();
        return 1;
    }

    // Set up timer
    struct sigevent sev;
    struct itimerspec its;
    timer_t timerid;

    // Configure the sigevent structure
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timerid;

    // Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, &timerid) == -1) {
        perror("Failed to create timer");
        cleanup();
        return 1;
    }

    // Configure the timer interval
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms (100Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms (100Hz)

    // Start the timer
    if (timer_settime(timerid, 0, &its, NULL) == -1) {
        perror("Failed to set timer");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for timer signal
