#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals for each relay (in seconds)
#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void toggle_relay(struct gpiod_line *line, int pin, int interval);
void signal_handler(int sig);

// Structure to hold relay information
typedef struct {
    int pin;
    int interval;
    struct gpiod_line *line;
} relay_t;

// Array of relays
relay_t relays[] = {
    {RELAY1_PIN, RELAY1_INTERVAL, NULL},
    {RELAY2_PIN, RELAY2_INTERVAL, NULL},
    {RELAY3_PIN, RELAY3_INTERVAL, NULL},
    {RELAY4_PIN, RELAY4_INTERVAL, NULL}
};

int num_relays = sizeof(relays) / sizeof(relays[0]);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    int i, ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines for each relay
    for (i = 0; i < num_relays; i++) {
        relays[i].line = gpiod_chip_get_line(chip, relays[i].pin);
        if (!relays[i].line) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return -1;
        }

        // Request GPIO line for output
        ret = gpiod_line_request_output(relays[i].line, "smart-lighting", 0);
        if (ret < 0) {
            perror("Error requesting GPIO line for output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    int i;

    // Release GPIO lines
    for (i = 0; i < num_relays; i++) {
        if (relays[i].line) {
            gpiod_line_release(relays[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Toggle relay based on interval
void toggle_relay(struct gpiod_line *line, int pin, int interval) {
    struct timespec ts;
    int value = 0; // Initial value is off
    int ret;

    // Set initial value
    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return;
    }

    while (1) {
        // Calculate next toggle time
        ts.tv_sec = interval;
        ts.tv_nsec = 0;

        // Toggle relay state
        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("Error setting GPIO line value");
            return;
        }

        // Wait for the specified interval
        nanosleep(&ts, NULL);
    }
}

int main(void) {
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Create threads for each relay (simulated with separate processes)
    for (i = 0; i < num_relays; i++) {
        pid_t pid = fork();

        if (pid == 0) {
            // Child process
            toggle_relay(relays[i].line, relays[i].pin, relays[i].interval);
            exit(0); // Exit child process after toggling
        } else if (pid < 0) {
            perror("Error forking process");
            cleanup_gpio();
            return 1;
        }
        // Parent process continues to the next relay
    }

    // Wait for child processes to finish (which they won't, they toggle forever)
    while (1) {
        pause(); // Wait for a signal
    }

    return 0;
}

