#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define ALARM_DURATION 3 // seconds
#define DEBOUNCE_TIME 1 // seconds
#define POLL_INTERVAL 100 // milliseconds

// Global variables
static volatile int running = 1;
static volatile int relay_active = 0;
static time_t last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_alarm();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay
int activate_relay() {
    if (relay_active) {
        return 0; // Relay is already active
    }

    time_t now = time(NULL);
    if (difftime(now, last_activation_time) < DEBOUNCE_TIME) {
        return 0; // Debounce period
    }

    gpioWrite(RELAY_PIN, 1); // Turn relay on
    relay_active = 1;
    last_activation_time = now;

    printf("Relay activated!\n");
    return 1;
}

// Log alarm event to file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);

    printf("Alarm logged to alarm_log.txt\n");
    return 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn relay off
    gpioTerminate(); // Terminate pigpio
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Activate relay if sound is detected
        if (sound_detected) {
            if (activate_relay()) {
                log_alarm();
                gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration (microseconds)
                gpioWrite(RELAY_PIN, 0); // Turn relay off
                relay_active = 0;
                printf("Relay deactivated!\n");
            }
        }

        gpioDelay(POLL_INTERVAL * 1000); // Poll every 100ms (microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

