#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity (LSB/deg/s) for +/- 250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity magnitude (deg/s)
#define THRESHOLD 50.0

// GPIO pin for LED
#define LED_PIN 17

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
float calculate_magnitude(gyro_data_t data);
void check_threshold(float magnitude);
void signal_handler(int signal);
void cleanup(int fd);

// Initialize I2C bus
int init_i2c(int address) {
    int fd = wiringPiI2CSetup(address);
    if (fd == -1) {
        perror("Failed to initialize I2C bus");
        return -1;
    }
    return fd;
}

// Initialize MPU-6050 sensor
int init_mpu6050(int fd) {
    // Wake up the sensor (clear sleep bit)
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) < 0) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = wiringPiI2CReadReg8(fd, WHO_AM_I);
    if (who_am_i < 0) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    raw_x = wiringPiI2CReadReg16(fd, GYRO_XOUT_H);
    if (raw_x < 0) {
        perror("Failed to read GYRO_XOUT_H");
        return -1;
    }

    raw_y = wiringPiI2CReadReg16(fd, GYRO_XOUT_H + 2);
    if (raw_y < 0) {
        perror("Failed to read GYRO_YOUT_H");
        return -1;
    }

    raw_z = wiringPiI2CReadReg16(fd, GYRO_XOUT_H + 4);
    if (raw_z < 0) {
        perror("Failed to read GYRO_ZOUT_H");
        return -1;
    }

    // Convert raw data to degrees per second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the magnitude exceeds the threshold
void check_threshold(float magnitude) {
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
        digitalWrite(LED_PIN, HIGH); // Turn on LED
        delay(1000);                 // Wait for 1 second
        digitalWrite(LED_PIN, LOW);  // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup resources
void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
    digitalWrite(LED_PIN, LOW); // Ensure LED is off
    printf("Cleanup complete\n");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Failed to initialize WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    digitalWrite(LED_PIN, LOW); // Ensure LED is off initially

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) == -1) {
        cleanup(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    gyro_data_t gyro_data;
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Calculate magnitude
            float magnitude = calculate_magnitude(gyro_data);

            // Check threshold
            check_threshold(magnitude);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        delay(10); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup(i2c_fd);
    return 0;
}

