#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define READ_COMMAND_LENGTH 9
#define RESPONSE_LENGTH 9
#define TIMEOUT_MS 1000

// Global variables for signal handling
static volatile int running = 1;
static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_file = NULL;

// Function prototypes
int initialize_uart();
int send_read_command();
int read_sensor_data(unsigned char *buffer);
int validate_checksum(const unsigned char *buffer);
int extract_co2(const unsigned char *buffer);
int log_data(int co2_ppm, int error_flag);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    if (uart_handle != -1) {
        serClose(uart_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (error_file != NULL) {
        fclose(error_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to initialize the UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    return 0;
}

// Function to send the read command to the MH-Z19B sensor
int send_read_command() {
    unsigned char command[READ_COMMAND_LENGTH] = READ_COMMAND;
    int result = serWrite(uart_handle, command, READ_COMMAND_LENGTH);
    if (result != READ_COMMAND_LENGTH) {
        log_error("Failed to send read command");
        return -1;
    }
    return 0;
}

// Function to read data from the sensor with timeout
int read_sensor_data(unsigned char *buffer) {
    int bytes_read = 0;
    int start_time = time(NULL) * 1000; // Current time in milliseconds

    while (bytes_read < RESPONSE_LENGTH) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int result = serRead(uart_handle, buffer + bytes_read, available);
            if (result > 0) {
                bytes_read += result;
            } else {
                log_error("Error reading from UART");
                return -1;
            }
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        int current_time = time(NULL) * 1000;
        if (current_time - start_time > TIMEOUT_MS) {
            log_error("Timeout reading sensor data");
            return -1;
        }
    }

    return 0;
}

// Function to validate the checksum of the received data
int validate_checksum(const unsigned char *buffer) {
    unsigned char checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += buffer[i];
    }
    checksum = 256 - checksum;
    checksum += 1;

    if (checksum != buffer[8]) {
        log_error("Checksum mismatch");
        return -1;
    }
    return 0;
}

// Function to extract the CO2 concentration from the received data
int extract_co2(const unsigned char *buffer) {
    return (buffer[2] << 8) | buffer[3];
}

// Function to log the data to a file and print to stdout
int log_data(int co2_ppm, int error_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    fprintf(log_file, "{\"timestamp\": %ld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_us, co2_ppm, error_flag);
    fflush(log_file);

    printf("{\"timestamp\": %ld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_us, co2_ppm, error_flag);
    return 0;
}

// Function to log errors to a file
void log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + (ts.tv_nsec / 1000);

    fprintf(error_file, "%ld: %s\n", timestamp_us, message);
    fflush(error_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(CO2_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        fclose(log_file);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char buffer[RESPONSE_LENGTH];
    int co2_ppm;
    int error_flag;

    // Main loop
    while (running) {
        error_flag = 0;

        // Send read command
        if (send_read_command() != 0) {
            error_flag = 1;
        } else {
            gpioDelay(100); // Wait for sensor to respond

            // Read sensor data
            if (read_sensor_data(buffer) != 0) {
                error_flag = 1;
            } else {
                // Validate checksum
                if (validate_checksum(buffer) != 0) {
                    error_flag = 1;
                } else {
                    // Extract CO2 concentration
                    co2_ppm = extract_co2(buffer);
                }
            }
        }

        // Log the data
        log_data(error_flag ? -1 : co2_ppm, error_flag);

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();

    return 0;
}

