#include <math.h>
#include <signal.h>
#include <unistd.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03

// Hard-iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Target heading
#define TARGET_HEADING 90.0

// GPIO pin for output
#define GPIO_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// I2C handle
int i2c_handle;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void compensate_hard_iron(int16_t *x, int16_t *y);
void update_gpio(float heading);
void add_to_buffer(float heading);
float get_average_heading();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B\n");
        return -1;
    }

    // Configure register MODE
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, DATA_START, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    // Convert data to signed 16-bit integers
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y, (float)x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Compensate for hard-iron distortion
void compensate_hard_iron(int16_t *x, int16_t *y) {
    *x -= X_OFFSET;
    *y -= Y_OFFSET;
}

// Update GPIO based on heading deviation
void update_gpio(float heading) {
    float deviation = fabs(heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(GPIO_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(GPIO_PIN, 0); // Set GPIO low
    }
}

// Add heading to circular buffer
void add_to_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get average heading from circular buffer
float get_average_heading() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += heading_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to low

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Compensate for hard-iron distortion
            compensate_hard_iron(&x, &y);

            // Calculate heading
            heading = calculate_heading(x, y);

            // Update GPIO
            update_gpio(heading);

            // Add heading to buffer
            add_to_buffer(heading);

            // Print heading and average heading
            printf("Heading: %.2f, Average Heading: %.2f\n", heading, get_average_heading());
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

