#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and BH1750 address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define BH1750 command for continuous high-resolution mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Define lux thresholds
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_MEDIUM 150
#define LUX_THRESHOLD_HIGH 300

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio(void);
int init_i2c(void);
int read_bh1750(float *lux);
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Initialize GPIO lines
int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "smart-lighting";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(red_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for RED relay");
        return -1;
    }
    if (gpiod_line_request(green_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for GREEN relay");
        return -1;
    }
    if (gpiod_line_request(blue_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for BLUE relay");
        return -1;
    }

    return 0;
}

// Initialize I2C bus
int init_i2c(void) {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Wait for the first conversion (at least 120ms)
    usleep(150000); // 150ms

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buffer[2];

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control relays based on lux value
void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;

    if (lux < LUX_THRESHOLD_LOW) {
        red_state = 1;
    } else if (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MEDIUM) {
        green_state = 1;
    } else if (lux >= LUX_THRESHOLD_MEDIUM && lux < LUX_THRESHOLD_HIGH) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    gpiod_line_set_value(red_line, red_state);
    gpiod_line_set_value(green_line, green_state);
    gpiod_line_set_value(blue_line, blue_state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup(0);
        return 1;
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup(0);
        return 1;
    }

    float lux;
    int red_state, green_state, blue_state;

    // Main loop
    while (1) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Control relays
            control_relays(lux);

            // Get relay states
            red_state = gpiod_line_get_value(red_line);
            green_state = gpiod_line_get_value(green_line);
            blue_state = gpiod_line_get_value(blue_line);

            // Log data
            log_data(lux, red_state, green_state, blue_state);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

