// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, stopping motors and exiting...\n");
}

// Function to calculate PWM duty cycle based on distance
int calculate_duty_cycle(int distance) {
    if (distance < 10) {
        distance = 10; // Clamp to minimum distance
    } else if (distance > 100) {
        distance = 100; // Clamp to maximum distance
    }

    // Map distance to duty cycle (10cm -> 255, 100cm -> 0)
    int duty_cycle = 255 - (int)(((float)(distance - 10) / (100 - 10)) * 255);

    return duty_cycle;
}

// Function to control a motor
void control_motor(int in1, int in2, int distance) {
    int duty_cycle = calculate_duty_cycle(distance);

    if (distance < 50) {
        // Forward
        gpioWrite(in1, 1);
        gpioPWM(in2, duty_cycle);
    } else {
        // Backward
        gpioWrite(in1, 0);
        gpioPWM(in2, duty_cycle);
    }
}

int main(int argc, char *argv[]) {
    // Check for correct number of arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    // Initialize pigpio
