    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Control motors
        control_motor(MOTOR_A_IN1, MOTOR_A_IN2, distance_a);
        control_motor(MOTOR_B_IN3, MOTOR_B_IN4, distance_b);

        // Sleep for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

