#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PITCH_ROLL_SCALE 180.0 / M_PI
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_PERIOD 20000        // us (20ms)
#define PWM_CHIP "pwmchip2"
#define PWM_NUM 0
#define PWM_PATH_FORMAT "/sys/class/pwm/%s/pwm%d"
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd = -1;
int pwm_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_reg(int fd, uint8_t reg, uint8_t data);
int mpu6050_init(int fd);
int mpu6050_read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
int export_pwm(const char *chip, int num);
int unexport_pwm(const char *chip, int num);
int enable_pwm(const char *chip, int num);
int disable_pwm(const char *chip, int num);
int set_pwm_period(const char *chip, int num, int period);
int set_pwm_duty_cycle(const char *chip, int num, int duty_cycle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int sig);

// I2C read function with exponential backoff
int i2c_read_reg(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 5;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Error: Could not write register address");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Error: Could not read data");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Error: Failed to read I2C register after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t data) {
    int retries = 5;
    int delay_ms = 10;
    uint8_t buf[2];
    int result;

    buf[0] = reg;
    buf[1] = data;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Error: Could not set I2C slave address");
            return -1;
        }

        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Error: Could not write data");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "Error: Failed to write I2C register after multiple retries.\n");
    return -1; // Failure
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050 (set sleep bit to 0)
    if (i2c_write_reg(fd, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050.\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2c_write_reg(fd, 0x1C, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range.\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 deg/s)
    if (i2c_write_reg(fd, 0x1B, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range.\n");
        return -1;
    }

    return 0;
}

// MPU6050 data reading function
int mpu6050_read_raw_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[14];

    if (i2c_read_reg(fd, 0x3B, data, 14) < 0) {
        fprintf(stderr, "Error: Could not read raw data from MPU6050.\n");
        return -1;
    }

    *accel_x = (int16_t)((data[0] << 8) | data[1]);
    *accel_y = (int16_t)((data[2] << 8) | data[3]);
    *accel_z = (int16_t)((data[4] << 8) | data[5]);
    *gyro_x = (int16_t)((data[8] << 8) | data[9]);
    *gyro_y = (int16_t)((data[10] << 8) | data[11]);
    *gyro_z = (int16_t)((data[12] << 8) | data[13]);

    return 0;
}

// Pitch and roll calculation function
void calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *pitch, float *roll) {
    float accel_x_g = (float)accel_x / 16384.0; // Assuming +/- 2g range
    float accel_y_g = (float)accel_y / 16384.0;
    float accel_z_g = (float)accel_z / 16384.0;

    *pitch = atan2(accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * PITCH_ROLL_SCALE;
    *roll = atan2(accel_y_g, sqrt(accel_x_g * accel_x_g + accel_z_g * accel_z_g)) * PITCH_ROLL_SCALE;
}

// Servo control function
