#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state; // 1 for ON, 0 for OFF
} schedule_entry_t;

// Global variables
volatile sig_atomic_t program_running = 1;
pthread_mutex_t schedule_mutex = PTHREAD_MUTEX_INITIALIZER;
schedule_entry_t *schedule = NULL;
int schedule_size = 0;

// Function prototypes
