int match_time(const schedule_entry_t *entry);
void set_relay_state(int relay_pin, int state);
void fade_lamp(int relay_pin, int target_brightness);
void signal_handler(int signal);
void cleanup();

// Function to read the schedule from a file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of lines in the file
    int num_lines = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        num_lines++;
    }
    rewind(fp);

