#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 30.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TRIGGER_PULSE_LENGTH 10 // Trigger pulse length in microseconds
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
float getDistance();
float mapDistanceToFrequency(float distance);
void setBuzzerFrequency(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        setBuzzerFrequency(0.0); // Silence the buzzer
        gpioTerminate();          // Terminate pigpio
        exit(0);
    }
}

// Function to generate a trigger pulse
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(TRIGGER_PULSE_LENGTH); // Wait for 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the distance using the HC-SR04 sensor
float getDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    triggerSensor();

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout.\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout.\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate the pulse width in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate the distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    // Clamp the distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linearly map the distance to the frequency range
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency using PWM
void setBuzzerFrequency(float frequency) {
    if (frequency > 0.0) {
        // Calculate the PWM duty cycle (50% for a square wave)
        int dutycycle = 128; // 50% duty cycle for 8-bit PWM

        // Set the PWM frequency
        gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);

        // Set the PWM duty cycle
        gpioPWM(BUZZER_PIN, dutycycle);
    } else {
        // Turn off the buzzer
        gpioPWM(BUZZER_PIN, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended for finer control)
    gpioSetPWMrange(BUZZER_PIN, 255); // Set PWM range to 255

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (program_running) {
        // Measure the distance
        float distance = getDistance();

        // Check for errors
        if (distance < 0.0) {
            fprintf(stderr, "Error: Distance measurement failed.\n");
        } else {
            // Map the distance to a frequency
            float frequency = mapDistanceToFrequency(distance);

            // Set the buzzer frequency
            setBuzzerFrequency(frequency);

            // Print the distance and frequency (for debugging)
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        }

        // Delay to avoid overwhelming the sensor and buzzer
        gpioDelay(20); // 50 Hz loop rate (approximately)
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    setBuzzerFrequency(0.0); // Silence the buzzer
    gpioTerminate();          // Terminate pigpio
    return 0;
}

