#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to calculate RGB values based on proximity value
void calculate_rgb(float proximity, int *red, int *green, int *blue) {
    // Map proximity value (0.0 to 1.0) to RGB color space
    if (proximity < 0.33) {
        // Red to Green
        *red = (int)(255 * (1 - proximity * 3));
        *green = (int)(255 * proximity * 3);
        *blue = 0;
    } else if (proximity < 0.66) {
        // Green to Blue
        *red = 0;
        *green = (int)(255 * (1 - (proximity - 0.33) * 3));
        *blue = (int)(255 * ((proximity - 0.33) * 3));
    } else {
        // Blue to Red
        *red = (int)(255 * ((proximity - 0.66) * 3));
        *green = 0;
        *blue = (int)(255 * (1 - (proximity - 0.66) * 3));
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float proximity = 0.0;
    int red, green, blue;
    while (program_running) {
        // Calculate proximity value using a sine wave
        proximity = 0.5 * sin(gpioTick() / 1000000.0) + 0.5; // Sine wave between 0.0 and 1.0

        // Calculate RGB values
        calculate_rgb(proximity, &red, &green, &blue);

        // Set RGB LED color
        set_rgb_color(red, green, blue);

        // Delay for a short period
        usleep(10000); // 10 ms
    }

    // Turn off the LED
    set_rgb_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

