#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity factor for ±250 deg/s range
#define GYRO_SENSITIVITY 131.0f

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    uint8_t wake_up = 0x00;
    if (write(fd, &wake_up, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buffer[6];
    int16_t gyro_x, gyro_y, gyro_z;

    // Read 6 bytes of gyroscope data
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine high and low bytes for each axis
    gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees/second
    data->x = (float)gyro_x / GYRO_SENSITIVITY;
    data->y = (float)gyro_y / GYRO_SENSITIVITY;
    data->z = (float)gyro_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to log gyroscope data to a file
int log_gyro_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log gyroscope data
            if (log_gyro_data(log_file, gyro_data) != 0) {
                terminate = 1; // Stop if logging fails
            }
        } else {
            terminate = 1; // Stop if reading fails
        }

        // Wait 100 milliseconds
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

