#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define melody notes (frequency, duration in ms)
typedef struct {
    int frequency;
    int duration;
} Note;

const Note melody[] = {
    {440, 200},   // A4
    {494, 200},   // B4
    {523, 200},   // C5
    {587, 200},   // D5
    {0, 100},     // Pause
    {587, 200},   // D5
    {523, 200},   // C5
    {494, 200},   // B4
    {440, 200}    // A4
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int playback_active = 0;
int current_note_index = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 0) { // Button pressed (active-low)
        if (!button_pressed) {
            button_pressed = 1;
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            if (!playback_active) {
                play_melody();
            } else {
                stop_melody();
            }
        }
    } else {
        button_pressed = 0; // Button released
    }
}

// Function to play the melody
void play_melody() {
    playback_active = 1;
    current_note_index = 0;

    while (playback_active && current_note_index < melody_length) {
        Note note = melody[current_note_index];
        if (note.frequency > 0) {
            gpioHardwarePWM(BUZZER_GPIO, note.frequency, 500000); // 50% duty cycle
        } else {
            gpioHardwarePWM(BUZZER_GPIO, 0, 0); // Stop PWM for pause
        }
        gpioDelay(note.duration * 1000); // Delay for note duration
        current_note_index++;
    }

    stop_melody(); // Ensure melody stops after playback
}

// Function to stop the melody
void stop_melody() {
    playback_active = 0;
    gpioHardwarePWM(BUZZER_GPIO, 0, 0); // Stop PWM
    current_note_index = 0; // Reset note index
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody(); // Stop any ongoing playback
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-up resistor on button GPIO
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set up interrupt service routine for button
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO%d\n", BUTTON_GPIO);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    return 0;
}

