#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <stdbool.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

// Structure to hold program state
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    int poll_timeout_ms;
    volatile sig_atomic_t terminate;
} ProgramState;

// Function prototypes
int init_gpio(ProgramState *state);
int open_log_file(ProgramState *state);
int read_sensor(ProgramState *state, int *value);
int log_event(ProgramState *state, int value);
void check_earthquake(ProgramState *state, int value);
void signal_handler(int sig);
void cleanup(ProgramState *state);

// Global program state
ProgramState state;

// Circular buffer for earthquake detection
int event_window[WINDOW_SIZE];
int window_index = 0;

int main(int argc, char *argv[]) {
    // Initialize program state
    state.chip = NULL;
    state.line = NULL;
    state.log_file = NULL;
    state.poll_timeout_ms = 1000; // Default timeout
    state.terminate = 0;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        state.poll_timeout_ms = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || state.poll_timeout_ms <= 0) {
            fprintf(stderr, "Error: Invalid poll timeout value. Using default (1000 ms).\n");
            state.poll_timeout_ms = 1000;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&state) != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Open log file
    if (open_log_file(&state) != 0) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup(&state);
        return 1;
    }

    // Main loop
    int value;
    while (!state.terminate) {
        if (read_sensor(&state, &value) == 0) {
            log_event(&state, value);
            check_earthquake(&state, value);
        } else {
            fprintf(stderr, "Error: Failed to read sensor value.\n");
        }
        usleep(state.poll_timeout_ms * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup(&state);
    return 0;
}

// Initialize GPIO
int init_gpio(ProgramState *state) {
    state->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!state->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    state->line = gpiod_chip_get_line(state->chip, GPIO_PIN);
    if (!state->line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(state->chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(state->line, &config, 0) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(state->chip);
        return -1;
    }

    return 0;
}

// Open log file
int open_log_file(ProgramState *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

// Read sensor value
int read_sensor(ProgramState *state, int *value) {
    int ret = gpiod_line_get_value(state->line);
    if (ret < 0) {
        perror("Error reading GPIO line value");
        return -1;
    }
    *value = ret;
    return 0;
}

// Log event to file
int log_event(ProgramState *state, int value) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (fprintf(state->log_file, "%s,%d\n", buf, value) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(state->log_file);
    return 0;
}

// Check for earthquake
void check_earthquake(ProgramState *state, int value) {
    event_window[window_index] = value;
    window_index = (window_index + 1) % WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (event_window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *tstruct = gmtime(&now);
