#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Configuration
#define I2C_DEVICE "/dev/i2c-1"
#define LSM303_ADDRESS 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define DATA_REG_START 0x03
#define NUM_DATA_REG 6

// Calibration offsets
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

// Data structure for magnetometer readings
typedef struct {
    float x;
    float y;
    float z;
    float heading;
    char direction[3];
} MagnetometerData;

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *device, int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
MagnetometerData read_magnetometer_data(int fd);
MagnetometerData calibrate_data(MagnetometerData raw_data);
float calculate_heading(float x, float y);
char* map_heading_to_direction(float heading);
int log_data(FILE *fp, MagnetometerData data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// I2C read registers function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read magnetometer data function
MagnetometerData read_magnetometer_data(int fd) {
    MagnetometerData data;
    uint8_t raw_data[NUM_DATA_REG];
    int16_t x, y, z;

    if (i2c_read_regs(fd, DATA_REG_START, raw_data, NUM_DATA_REG) < 0) {
        data.x = 0.0f; // Set to 0.0f on error
        data.y = 0.0f;
        data.z = 0.0f;
        data.heading = 0.0f;
        strcpy(data.direction, "ERR");
        return data;
    }

    x = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    z = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    y = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    data.x = (float)x;
    data.y = (float)y;
    data.z = (float)z;

    return data;
}

// Calibrate data function
MagnetometerData calibrate_data(MagnetometerData raw_data) {
    MagnetometerData calibrated_data;

    calibrated_data.x = raw_data.x - X_OFFSET;
    calibrated_data.y = raw_data.y - Y_OFFSET;
    calibrated_data.z = raw_data.z - Z_OFFSET;

    return calibrated_data;
}

// Calculate heading function
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;

    if (heading < 0) {
        heading += 360.0f;
    }

    return heading;
}

// Map heading to direction function
char* map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data function
int log_data(FILE *fp, MagnetometerData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, data.x, data.y, data.z, data.heading, data.direction) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_DEVICE, LSM303_ADDRESS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure magnetometer
    if (i2c_write_reg(i2c_fd, CRA_REG_M, 0x14) < 0) { // 15 Hz
        close(i2c_fd);
        return 1;
    }
    if (i2c_write_reg(i2c_fd, MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        MagnetometerData raw_data = read_magnetometer_data(i2c_fd);

        // Calibrate data
        MagnetometerData calibrated_data = calibrate_data(raw_data);

        // Calculate heading
        calibrated_data.heading = calculate_heading(calibrated_data.x, calibrated_data.y);

        // Map heading to direction
        strcpy(calibrated_data.direction, map_heading_to_direction(calibrated_data.heading));

        // Log data
        if (log_data(log_file, calibrated_data) < 0) {
            terminate = 1; // Stop if logging fails
        }

        // Print heading to console
        printf("Heading: %.2f degrees (%s)\n", calibrated_data.heading, calibrated_data.direction);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

