#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_MS 200

static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log relay state to JSON file
int log_relay_state(int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to get timestamp.\n");
        return -1;
    }

    const char *relay_status = (state == 1) ? "ON" : "OFF";

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_status);
    fflush(log_file); // Ensure data is written to file immediately
    free(timestamp); // Free the allocated memory
    return 0;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    if (log_relay_state(relay_state) != 0) {
        fprintf(stderr, "Error: Failed to log relay state.\n");
    }
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, unsigned int tick) {
    unsigned long current_time = gpioTick();

    if (level == 1) { // Touch detected (HIGH)
        if (current_time - last_touch_time > DEBOUNCE_MS * 1000) { // Debounce
            toggle_relay();
            last_touch_time = current_time;
