#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_moisture_sensor(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fprintf(stderr, "Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int i;
    int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pins[i], strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Read simulated moisture sensor value
int read_moisture_sensor(void) {
    return rand() % 101; // Returns a value between 0 and 100
}

// Activate a relay
void activate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
        return;
    }

    if (gpiod_line_set_value(relay_lines[relay_number - 1], 0) < 0) {
        fprintf(stderr, "Error setting GPIO line %d to 0: %s\n", (relay_number == 1 ? RELAY1_PIN : (relay_number == 2 ? RELAY2_PIN : (relay_number == 3 ? RELAY3_PIN : RELAY4_PIN))), strerror(errno));
    }
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    if (relay_number < 1 || relay_number > 4) {
        fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
        return;
    }

    if (gpiod_line_set_value(relay_lines[relay_number - 1], 1) < 0) {
        fprintf(stderr, "Error setting GPIO line %d to 1: %s\n", (relay_number == 1 ? RELAY1_PIN : (relay_number == 2 ? RELAY2_PIN : (relay_number == 3 ? RELAY3_PIN : RELAY4_PIN))), strerror(errno));
    }
}

// Log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file);
}

// Cleanup GPIO lines and close the chip
void cleanup_gpio(void) {
    int i;

    // Deactivate all relays
    for (i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        moisture_level = read_moisture_sensor();
        printf("Moisture level: %d\n", moisture_level);

        if (moisture_level < 30) {
            for (i = 1; i <= 4; i++) {
                activate_relay(i);
                log_event(i, moisture_level);
                sleep(5);
                deactivate_relay(i);
                sleep(1);
            }
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

