#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for servos
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture levels
int moisture_levels[] = {20, 40, 60, 80, 100};
int moisture_index = 0;

// Define servo pulse widths
#define VALVE_CLOSED 500
#define VALVE_OPEN 1500
#define NOZZLE_0 500
#define NOZZLE_45 1000
#define NOZZLE_90 1500
#define NOZZLE_135 2000
#define NOZZLE_180 2500

// Define watering parameters
#define MOISTURE_THRESHOLD 50
#define NOZZLE_DELAY 2000 // milliseconds
#define WATERING_HOLD 5000 // milliseconds

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to set servo pulse width with retry
int set_servo_pulse(int pin, int pulse_width) {
    int retries = 3;
    int result = 0;
    while (retries > 0) {
        result = gpioServo(pin, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo %d to %d, retrying...\n", pin, pulse_width);
            gpioDelay(100); // 100 ms backoff
            retries--;
        }
    }
    fprintf(stderr, "Critical error: Failed to set servo %d to %d after multiple retries.\n", pin, pulse_width);
    return -1; // Failure
}

// Function to open the water valve
int open_valve() {
    if (set_servo_pulse(VALVE_SERVO_PIN, VALVE_OPEN) != 0) {
        fprintf(stderr, "Critical error: Failed to open valve.\n");
        return -1; // Failure
    }
    return 0; // Success
}

// Function to close the water valve
int close_valve() {
    if (set_servo_pulse(VALVE_SERVO_PIN, VALVE_CLOSED) != 0) {
        fprintf(stderr, "Error: Failed to close valve.\n");
        return -1; // Failure
    }
    return 0; // Success
}

// Function to sweep the nozzle
int sweep_nozzle() {
    int nozzle_positions[] = {NOZZLE_0, NOZZLE_45, NOZZLE_90, NOZZLE_135, NOZZLE_180};
    for (int i = 0; i < 5; i++) {
        if (set_servo_pulse(NOZZLE_SERVO_PIN, nozzle_positions[i]) != 0) {
            fprintf(stderr, "Error: Failed to set nozzle to position %d.\n", nozzle_positions[i]);
            return -1; // Failure
        }
        gpioDelay(NOZZLE_DELAY);
    }
    return 0; // Success
}

// Function to perform watering cycle
int watering_cycle() {
    if (moisture_levels[moisture_index] < MOISTURE_THRESHOLD) {
        printf("Moisture level below threshold, initiating watering cycle.\n");
        if (open_valve() != 0) {
            fprintf(stderr, "Critical error: Valve failed to open, skipping watering.\n");
            return -1; // Failure
        }
        if (sweep_nozzle() != 0) {
            fprintf(stderr, "Error: Nozzle sweep failed.\n");
        }
        gpioDelay(WATERING_HOLD);
        if (close_valve() != 0) {
            fprintf(stderr, "Error: Valve failed to close.\n");
        }
    } else {
        printf("Moisture level above threshold, skipping watering.\n");
    }
    return 0; // Success
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        printf("Current moisture level: %d\n", moisture_levels[moisture_index]);
        watering_cycle();

        // Update moisture level index
        moisture_index = (moisture_index + 1) % 5;

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Stop servos
    set_servo_pulse(VALVE_SERVO_PIN, 0);
    set_servo_pulse(NOZZLE_SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

