#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 500 // 50 cm in mm
#define I2C_RETRY_COUNT 3

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_FIRMWARE_VERSION 0x00c2
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008a
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_relay(int distance);
void signal_handler(int signal);
int i2c_write_byte(int handle, uint8_t reg, uint8_t data);
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data);
int i2c_read_word(int handle, uint8_t reg, uint16_t *data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// I2C write byte function with retry
int i2c_write_byte(int handle, uint8_t reg, uint8_t data) {
    int result, retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = i2cWriteByteData(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02x, data 0x%02x): %d, retry %d\n", reg, data, result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02x, data 0x%02x)\n", I2C_RETRY_COUNT, reg, data);
    return -1; // Failure
}

// I2C read byte function with retry
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data) {
    int result, retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *data = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02x): %d, retry %d\n", reg, result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02x)\n", I2C_RETRY_COUNT, reg);
    return -1; // Failure
}

// I2C read word function with retry
int i2c_read_word(int handle, uint8_t reg, uint16_t *data) {
    int result, retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *data = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02x): %d, retry %d\n", reg, result, retries + 1);
            gpioDelay(1000); // Wait 1 ms before retrying
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02x)\n", I2C_RETRY_COUNT, reg);
    return -1; // Failure
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id, firmware_version;

    // Check sensor ID
    if (i2c_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Check firmware version
    if (i2c_read_byte(i2c_handle, VL53L1X_REG_FIRMWARE_VERSION, &firmware_version) != 0) {
        fprintf(stderr, "Error reading firmware version\n");
        return -1;
    }

    // Software reset
    if (i2c_write_byte(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error performing software reset\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms after reset

    // Set I2C address (optional, using default)
    // if (i2c_write_byte(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) != 0) {
    //     fprintf(stderr, "Error setting I2C address\n");
    //     return -1;
    // }

    // Start continuous ranging
    if (i2c_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance(int *distance) {
    uint8_t range_status;
    uint16_t distance_mm;

    // Check for data ready
    if (i2c_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    if ((range_status & 0x01) == 0) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read distance
    if (i2c_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    *distance = (int)distance_mm;
    return 0;
}

// Control the relay based on distance
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Open door
    } else {
        gpioWrite(GPIO_RELAY, 0); // Close door
    }
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_relay(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

