        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

