#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the watering cycle interval (24 hours in seconds)
#define WATERING_INTERVAL 86400

// Define the watering duration (5 seconds)
#define WATERING_DURATION 5

// Define the polling interval (60 seconds)
#define POLLING_INTERVAL 60

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static time_t last_watering_time = 0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_watering_cycle(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up and exiting...\n", sig);
        terminate = 1;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the line handles for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request the lines as outputs with active-low bias
    ret = gpiod_line_request_output(relay1_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay2_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay3_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(relay4_line, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Activate a relay
void activate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    int ret;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    ret = gpiod_line_set_value(line, 0); // Active low
    if (ret < 0) {
        perror("Error setting GPIO line value");
    }
}

// Deactivate a relay
void deactivate_relay(int relay_number) {
    struct gpiod_line *line = NULL;
    int ret;

    switch (relay_number) {
        case 1:
            line = relay1_line;
            break;
        case 2:
            line = relay2_line;
            break;
        case 3:
            line = relay3_line;
            break;
        case 4:
            line = relay4_line;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    ret = gpiod_line_set_value(line, 1); // Inactive high
    if (ret < 0) {
        perror("Error setting GPIO line value");
    }
}

// Log watering cycle
void log_watering_cycle(void) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening watering_log.txt");
        return;
    }

    fprintf(fp, "%s: Watering cycle started\n", timestamp);
    fclose(fp);
}

int main(void) {
    time_t current_time;
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        time(&current_time);

        // Check if it's time to start the watering cycle
        if (difftime(current_time, last_watering_time) >= WATERING_INTERVAL) {
            printf("Starting watering cycle...\n");
            log_watering_cycle();

            // Activate relays sequentially
            for (i = 1; i <= 4; i++) {
                activate_relay(i);
                sleep(WATERING_DURATION);
                deactivate_relay(i);
            }

            // Update the last watering time
            last_watering_time = current_time;
            printf("Watering cycle complete.\n");
        }

        // Sleep for the polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

