#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, struct timespec ts, float x, float y, float z);
int check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    int result;

    while (retries > 0) {
        // Wake up the MPU-6050
        result = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set sample rate divider
        result = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
        if (result < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set gyroscope configuration
        result = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Verify WHO_AM_I register
        result = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (result < 0) {
            fprintf(stderr, "Error reading WHO_AM_I: %d\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        if (result != 0x68) {
            fprintf(stderr, "WHO_AM_I returned incorrect value: 0x%x\n", result);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
    }

    // Convert big-endian data to signed 16-bit integers
    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    // Convert to degrees/second (sensitivity: 131 LSB/deg/s)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec ts, float x, float y, float z) {
    buffer->data[buffer->head].timestamp = ts;
    buffer->data[buffer->head].x = x;
    buffer->data[buffer->head].y = y;
    buffer->data[buffer->head].z = z;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check if any axis exceeds the threshold
int check_threshold(float x, float y, float z) {
    if (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0) {
        return 1; // Threshold exceeded
    } else {
        return 0; // Threshold not exceeded
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec ts;
    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);

            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, ts, x, y, z);

            // Check threshold and control LED
            if (check_threshold(x, y, z)) {
                gpioWrite(LED_PIN, 1); // Turn LED on
            } else {
                gpioWrite(LED_PIN, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading gyro data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // 1 second delay
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_mpu6050() != 0) {
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(50000); // 50ms delay (20Hz sample rate)
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

