#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_SENSITIVITY 131.0f
#define RETRY_COUNT 3

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(const char *chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int read_gyro_data(int fd, struct gpiod_line *line, int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);

// SPI Initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// GPIO Initialization function
int gpio_init(const char *chip, int pin) {
    struct gpiod_chip *chip_handle = gpiod_chip_open_by_name(chip);
    if (!chip_handle) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip, strerror(errno));
        return -1;
    }

    struct gpiod_line *line_handle = gpiod_chip_get_line(chip_handle, pin);
    if (!line_handle) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip_handle);
        return -1;
    }

    if (gpiod_line_request_output_flags(line_handle, "gyro_cs", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip_handle);
        gpiod_line_release(line_handle);
        return -1;
