        return -1;
    }
    return 0;
}

// Read Gyro Data function
int read_gyro_data(int fd, struct gpiod_line *line, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[1] = {0x43}; // Start register address
    uint8_t rx_buf[6] = {0}; // 6 bytes to read (X_H, X_L, Y_H, Y_L, Z_H, Z_L)
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (gpio_set_value(line, 0) < 0) { // Assert CS low
            fprintf(stderr, "Error setting CS low, retrying...\n");
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }

        if (spi_transfer(fd, tx_buf, rx_buf, 1) < 0) {
            fprintf(stderr, "Error during SPI transfer, retrying...\n");
            gpio_set_value(line, 1); // De-assert CS high
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }

        if (spi_transfer(fd, NULL, rx_buf, 6) < 0) {
            fprintf(stderr, "Error during SPI transfer (read), retrying...\n");
            gpio_set_value(line, 1); // De-assert CS high
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }

        if (gpio_set_value(line, 1) < 0) { // De-assert CS high
            fprintf(stderr, "Error setting CS high, retrying...\n");
            retries--;
            usleep(1000); // Wait before retrying
            continue;
        }

        // Combine high and low bytes for each axis
        *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
        *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
        *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

        return 0; // Success
    }

    fprintf(stderr, "Persistent SPI communication failure.\n");
    return -1; // Failure after multiple retries
}

// Convert to Degrees Per Second function
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Log Data function
int log_data(FILE *fp, struct timespec ts, float x_rate, float y_rate, float z_rate) {
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), 10, ".%09ldZ", ts.tv_nsec);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal Handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output_flags(gpio_line, "gyro_cs", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN, 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    struct timespec ts;
    int16_t raw_x, raw_y, raw_z;
    float x_rate, y_rate, z_rate;

    while (!terminate) {
        if (read_gyro_data(spi_fd, gpio_line, &raw_x, &raw_y, &raw_z) == 0) {
            x_rate = convert_to_dps(raw_x);
            y_rate = convert_to_dps(raw_y);
            z_rate = convert_to_dps(raw_z);

            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                if (log_data(log_file, ts, x_rate, y_rate, z_rate) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

