#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 3900000 // 3.9 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LED_PIN 17        // GPIO17
#define BUFFER_SIZE 64
#define SENSITIVITY 131.0
#define THRESHOLD 200.0
#define BLINK_INTERVAL 500000 // 500 ms in microseconds

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_line *led_line = NULL;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_gyro_data(int reg, int16_t *data);
float convert_to_dps(int16_t raw_data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void print_buffer(circular_buffer_t *buffer);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(cs_line, "mpu6050_cs", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting CS line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(led_line, "mpu6050_led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Error requesting LED line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Initialize CS line to high (inactive)
    gpiod_line_set_value(cs_line, 1);

    return 0;
}

// Function to read data from the gyroscope
int read_gyro_data(int reg, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];
    struct spi_ioc_transfer transfer[1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte for reading

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 2;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    gpiod_line_set_value(cs_line, 0); // Assert CS
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }
    gpiod_line_set_value(cs_line, 1); // Deassert CS

    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / SENSITIVITY;
}

