        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        gyro_data_t data = get_from_buffer(buffer, index);
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&data.timestamp.tv_sec));
        printf("%s.%09ld,%.2f,%.2f,%.2f\n", timestamp_str, data.timestamp.tv_nsec, data.x, data.y, data.z);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting...\n", sig);
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
