#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"
#define PROXIMITY_THRESHOLD 100
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void signal_handler(int sig);

// I2C read function with retries
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    int retries = I2C_RETRY_COUNT;
    uint8_t buf[1];
    buf[0] = reg;

    while (retries > 0) {
        if (write(fd, buf, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            perror("I2C read (register value) failed");
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        uint8_t low_byte = buf[0];

        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (read(fd, buf, 1) != 1) {
            perror("I2C read (register value) failed");
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        uint8_t high_byte = buf[0];

        *value = (high_byte << 8) | low_byte;
        return 0; // Success
    }

    fprintf(stderr, "I2C read failed after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// I2C write function with retries
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = I2C_RETRY_COUNT;
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("GPIO set value failed");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint16_t ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "biometric_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (i2c_read_word(i2c_fd, AMBIENT_LIGHT_REG, &ambient_light) != 0) {
            fprintf(stderr, "Failed to read ambient light\n");
        }
        if (i2c_read_word(i2c_fd, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity\n");
        }

        // Log data
        log_data(log_file, ambient_light, proximity);

        // Control LED based on proximity
        if (proximity > PROXIMITY_THRESHOLD) {
            gpio_set_value(gpio_line, 1); // Turn LED on
        } else {
            gpio_set_value(gpio_line, 0); // Turn LED off
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup
    gpiod_line_set_value(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    close(i2c_fd);

    fprintf(stderr, "Cleanup complete, exiting.\n");
    return 0;
}

