#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define SENSITIVITY 200.0f
#define SAMPLE_DELAY_US 10000 // 10 ms
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int spi_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_axis(int axis_reg, int16_t *rate);
int log_data(struct timespec ts, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);

// Structure for grouping gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from a gyroscope axis
int read_gyro_axis(int axis_reg, int16_t *rate) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = axis_reg | 0x80; // Set read bit
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Function to log data to a CSV file
int log_data(struct timespec ts, int16_t x_rate, int16_t y_rate) {
    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL\n");
        return -1;
    }

    fprintf(fp, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int reinit_attempts = 0;
    struct timespec ts;
    gyro_data_t gyro_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open the data file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,X_rate,Y_rate\n");

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        fclose(fp);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_axis(GYRO_X_REG, &gyro_data.x_rate) != 0) {
            fprintf(stderr, "Error reading X axis data\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            if (init_spi() != 0) {
                reinit_attempts++;
                fprintf(stderr, "SPI re-initialisation failed (attempt %d/%d)\n", reinit_attempts, MAX_REINIT_ATTEMPTS);
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                    break;
                }
            }
            continue; // Skip to the next iteration
        }

        if (read_gyro_axis(GYRO_Y_REG, &gyro_data.y_rate) != 0) {
            fprintf(stderr, "Error reading Y axis data\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            if (init_spi() != 0) {
                reinit_attempts++;
                fprintf(stderr, "SPI re-initialisation failed (attempt %d/%d)\n", reinit_attempts, MAX_REINIT_ATTEMPTS);
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Max re-initialisation attempts reached. Exiting.\n");
                    break;
                }
            }
            continue; // Skip to the next iteration
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp\n");
            break; // Exit loop on error
        }

        // Log data
        if (log_data(ts, gyro_data.x_rate, gyro_data.y_rate) != 0) {
            fprintf(stderr, "Error logging data\n");
            break; // Exit loop on error
        }

        // Delay for 10 ms
        gpioDelay(SAMPLE_DELAY_US);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

