#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_XL_REG 0x02
#define GYRO_XH_REG 0x03
#define GYRO_YL_REG 0x04
#define GYRO_YH_REG 0x05
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s
#define LED_GPIO 17
#define THRESHOLD 20.0 // deg/s
#define BUFFER_SIZE 100

// Data structure for circular buffer entries
typedef struct {
    struct timespec timestamp;
    float x_rate;
    float y_rate;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_spi();
int read_gyro_register(int reg);
int16_t combine_bytes(uint8_t low, uint8_t high);
float convert_to_degrees_per_second(int16_t raw_data);
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x_rate, float y_rate);
int get_from_buffer(circular_buffer_t *buffer, int index, gyro_data_t *data);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read a single byte from the specified gyroscope register
int read_gyro_register(int reg) {
    char tx[2];
    char rx[2];

    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(spi_handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return rx[1];
}

// Combine two 8-bit bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t low, uint8_t high) {
    return (int16_t)((high << 8) | low);
}

// Convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float x_rate, float y_rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].x_rate = x_rate;
    buffer->buffer[buffer->head].y_rate = y_rate;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from the circular buffer
int get_from_buffer(circular_buffer_t *buffer, int index, gyro_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Control the LED (on/off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    control_led(0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int xl = read_gyro_register(GYRO_XL_REG);
        int xh = read_gyro_register(GYRO_XH_REG);
        int yl = read_gyro_register(GYRO_YL_REG);
        int yh = read_gyro_register(GYRO_YH_REG);

        if (xl < 0 || xh < 0 || yl < 0 || yh < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Combine bytes and convert to degrees per second
        int16_t raw_x_rate = combine_bytes((uint8_t)xl, (uint8_t)xh);
        int16_t raw_y_rate = combine_bytes((uint8_t)yl, (uint8_t)yh);
        float x_rate = convert_to_degrees_per_second(raw_x_rate);
        float y_rate = convert_to_degrees_per_second(raw_y_rate);

        // Get timestamp
        struct timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        // Add data to circular buffer
        add_to_buffer(&gyro_buffer, timestamp, x_rate, y_rate);

        // Control LED based on threshold
        if (abs(x_rate) > THRESHOLD || abs(y_rate) > THRESHOLD) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        // Delay for 10ms (100 Hz sampling rate)
        gpioDelay(10000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

