#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the relays
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define ALL_CLEAR_PIN 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all GPIO lines
    if (chip) {
        struct gpiod_line *red_line = gpiod_chip_get_line(chip, RED_PIN);
        struct gpiod_line *yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
        struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_PIN);
        struct gpiod_line *all_clear_line = gpiod_chip_get_line(chip, ALL_CLEAR_PIN);

        if (red_line) {
            gpiod_line_release(red_line);
        }
        if (yellow_line) {
            gpiod_line_release(yellow_line);
        }
        if (green_line) {
            gpiod_line_release(green_line);
        }
        if (all_clear_line) {
            gpiod_line_release(all_clear_line);
        }

        // Close the GPIO chip
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to turn on a relay (set GPIO LOW)
int relay_on(struct gpiod_line *line)
{
    return set_gpio_state(line, 0);
}

// Function to turn off a relay (set GPIO HIGH)
int relay_off(struct gpiod_line *line)
{
    return set_gpio_state(line, 1);
}

// Function to set the traffic light state
int set_traffic_light_state(struct gpiod_line *red_line, struct gpiod_line *yellow_line, struct gpiod_line *green_line, struct gpiod_line *all_clear_line, const char *state)
{
    printf("Setting state: %s\n", state);

    if (strcmp(state, "red") == 0) {
        relay_on(red_line);
        relay_off(yellow_line);
        relay_off(green_line);
        relay_off(all_clear_line);
    } else if (strcmp(state, "red_yellow") == 0) {
        relay_on(red_line);
        relay_on(yellow_line);
        relay_off(green_line);
        relay_off(all_clear_line);
    } else if (strcmp(state, "green") == 0) {
        relay_off(red_line);
        relay_off(yellow_line);
        relay_on(green_line);
        relay_off(all_clear_line);
    } else if (strcmp(state, "yellow") == 0) {
        relay_off(red_line);
        relay_on(yellow_line);
        relay_off(green_line);
        relay_off(all_clear_line);
    } else if (strcmp(state, "all_clear") == 0) {
        relay_off(red_line);
        relay_off(yellow_line);
        relay_off(green_line);
        relay_on(all_clear_line);
    } else {
        fprintf(stderr, "Invalid state: %s\n", state);
        return -1;
    }

    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    struct gpiod_line *red_line = gpiod_chip_get_line(chip, RED_PIN);
    struct gpiod_line *yellow_line = gpiod_chip_get_line(chip, YELLOW_PIN);
    struct gpiod_line *green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    struct gpiod_line *all_clear_line = gpiod_chip_get_line(chip, ALL_CLEAR_PIN);

    if (!red_line || !yellow_line || !green_line || !all_clear_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(red_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(yellow_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(green_line, "traffic_light", 1) < 0 ||
        gpiod_line_request_output(all_clear_line, "traffic_light", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        if (set_traffic_light_state(red_line, yellow_line, green_line, all_clear_line, "red") < 0) break;
        sleep(10);

        if (set_traffic_light_state(red_line, yellow_line, green_line, all_clear_line, "red_yellow") < 0) break;
        sleep(2);

        if (set_traffic_light_state(red_line, yellow_line, green_line, all_clear_line, "green") < 0) break;
        sleep(10);

        if (set_traffic_light_state(red_line, yellow_line, green_line, all_clear_line, "yellow") < 0) break;
        sleep(3);

        if (set_traffic_light_state(red_line, yellow_line, green_line, all_clear_line, "all_clear") < 0) break;
        sleep(5);
    }

    // Cleanup (in case of error)
    gpiod_line_release(red_line);
    gpiod_line_release(yellow_line);
    gpiod_line_release(green_line);
    gpiod_line_release(all_clear_line);
    gpiod_chip_close(chip);

    return 0;
}

