#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_DELAY 100 // milliseconds
#define READ_INTERVAL 10    // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;
int relay_state = 0; // 0 = off, 1 = on

// Function prototypes
int init_pigpio();
int init_i2c();
int init_mpr121();
int read_touch_status();
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    log_message("pigpio initialised successfully");
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("I2C open failed");
        return -1;
    }
    log_message("I2C initialised successfully");
    return 0;
}

// Function to initialize MPR121
int init_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("MPR121 reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) {
        log_message("MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("MPR121 electrode enable failed");
        return -1;
    }

    // Touch threshold
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("MPR121 touch threshold failed");
        return -1;
    }

    // Release threshold
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("MPR121 release threshold failed");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("MPR121 debounce failed");
        return -1;
    }

    // Charge time
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("MPR121 charge time failed");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("MPR121 run mode failed");
        return -1;
    }

    log_message("MPR121 initialised successfully");
    return 0;
}

// Function to read touch status
int read_touch_status() {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("MPR121 touch status read failed");
        return -1;
    }
    return ((buf[1] << 8) | buf[0]);
}

// Function to toggle the relay
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    char message[50];
    snprintf(message, sizeof(message), "Relay toggled to %s", relay_state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_message("Signal received, terminating...");
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    log_message("Cleanup complete, exiting");
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        cleanup();
        return 1;
    }

    log_message("System initialised, running...");

    // Main loop
    int last_touch_status = 0;
    while (!terminate) {
        int touch_status = read_touch_status();
        if (touch_status >= 0) {
            if (touch_status & 0x01) { // Check if electrode 0 is touched
                if (!(last_touch_status & 0x01)) { // Check if it was not touched before
                    toggle_relay();
                    gpioDelay(DEBOUNCE_DELAY); // Debounce
                }
            }
            last_touch_status = touch_status;
        }
        gpioDelay(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

