    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Release GPIO resources before exiting
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_flame_sensor() == 0) {
            activate_alarm();
        } else {
            deactivate_alarm();
        }
        gpioDelay(100); // Check every 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

