// Define delay between dispenses (in milliseconds)
#define DISPENSE_DELAY 5000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void dispense_cycle();
void log_dispense_event(int solenoid_pin, int duration_ms);
void deactivate_solenoids();
void signal_handler(int signal);

