    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to perform a dispense cycle
void dispense_cycle() {
    // Activate solenoid 1 for half the duration
    gpioWrite(SOLENOID_1_PIN, 1); // Turn on solenoid 1
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Delay for half the duration
    gpioWrite(SOLENOID_1_PIN, 0); // Turn off solenoid 1

    // Activate solenoid 2 for the remaining half
    gpioWrite(SOLENOID_2_PIN, 1); // Turn on solenoid 2
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Delay for half the duration
    gpioWrite(SOLENOID_2_PIN, 0); // Turn off solenoid 2

    // Log the dispense event
    log_dispense_event(SOLENOID_1_PIN, DISPENSE_DURATION / 2);
    log_dispense_event(SOLENOID_2_PIN, DISPENSE_DURATION / 2);
