        dispense_cycle();
        gpioDelay(DISPENSE_DELAY * 1000); // Delay between dispenses
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    deactivate_solenoids();
    gpioTerminate();
    return 0;
}

