#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

#define PWM_FREQUENCY 1000 // Hz
#define MAX_PWM_VALUE 255
#define MIN_PWM_VALUE 0

#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0

#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0

#define OBSTACLE_DISTANCE_THRESHOLD 20.0
#define OBSTACLE_REVERSE_SPEED 128

#define LOG_FILE "balance_log.txt"

// PID Gains
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
void motor_forward(int motor, int speed);
void motor_backward(int motor, int speed);
void motor_stop(int motor);
float simulate_tilt_error();
float simulate_distance();
void pid_control(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Motor control functions
void motor_forward(int motor, int speed) {
    if (speed < MIN_PWM_VALUE || speed > MAX_PWM_VALUE) {
        fprintf(stderr, "Error: Invalid motor speed: %d\n", speed);
        return;
    }

    if (motor == 'A') {
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_A_FORWARD, speed);
    } else if (motor == 'B') {
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(MOTOR_B_FORWARD, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
    }
}

void motor_backward(int motor, int speed) {
    if (speed < MIN_PWM_VALUE || speed > MAX_PWM_VALUE) {
        fprintf(stderr, "Error: Invalid motor speed: %d\n", speed);
        return;
    }

    if (motor == 'A') {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioPWM(MOTOR_A_BACKWARD, speed);
    } else if (motor == 'B') {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioPWM(MOTOR_B_BACKWARD, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
    }
}

void motor_stop(int motor) {
    if (motor == 'A') {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor == 'B') {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
    }
}

// Simulation functions
float simulate_tilt_error() {
    return (float)(rand() % 201 - 100) / 10.0; // Generates a float between -10.0 and 10.0
}

float simulate_distance() {
    return (float)(rand() % 398 + 2); // Generates a float between 2.0 and 400.0
}

// PID control function
void pid_control(float tilt_error, float distance, int *motor_a_speed, int *motor_b_speed) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    float proportional = Kp * tilt_error;
    integral += Ki * tilt_error;
    float derivative = Kd * (tilt_error - previous_error);

    float output = proportional + integral + derivative;

    // Obstacle avoidance
    if (distance < OBSTACLE_DISTANCE_THRESHOLD) {
        *motor_a_speed = -OBSTACLE_REVERSE_SPEED;
        *motor_b_speed = -OBSTACLE_REVERSE_SPEED;
    } else {
        *motor_a_speed = (int)output;
        *motor_b_speed = (int)output;
    }

    // Clamp motor speeds
    if (*motor_a_speed > MAX_PWM_VALUE) *motor_a_speed = MAX_PWM_VALUE;
    if (*motor_a_speed < -MAX_PWM_VALUE) *motor_a_speed = -MAX_PWM_VALUE;
    if (*motor_b_speed > MAX_PWM_VALUE) *motor_b_speed = MAX_PWM_VALUE;
    if (*motor_b_speed < -MAX_PWM_VALUE) *motor_b_speed = -MAX_PWM_VALUE;

    previous_error = tilt_error;
}

