#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default ALSA configuration
#define ALSA_DEVICE "default"
#define SAMPLE_RATE 8000
#define SAMPLE_SIZE 16 // bits
#define CHANNELS 1
#define PERIOD_SIZE 1024

// Default sensitivity scaling factor
#define DEFAULT_SENSITIVITY 1.0

// Global variables
static volatile int running = 1;
static float sensitivity = DEFAULT_SENSITIVITY;

// ALSA includes and definitions
#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
static snd_pcm_t *pcm_handle;
#endif

// Function prototypes
void signal_handler(int signal);
float calculate_rms(const short *samples, int num_samples);
void map_amplitude_to_rgb(float rms_amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
#ifdef ALSA_AVAILABLE
int init_alsa(void);
void cleanup_alsa(void);
#endif
void simulate_audio(float *rms_amplitude);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to calculate RMS amplitude
float calculate_rms(const short *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to map RMS amplitude to RGB values
void map_amplitude_to_rgb(float rms_amplitude, int *red, int *green, int *blue) {
    // Normalize RMS amplitude to a range of 0-1
    float normalized_amplitude = rms_amplitude / 32768.0; // Assuming 16-bit samples

    // Apply sensitivity scaling
    normalized_amplitude *= sensitivity;

    // Clamp the normalized amplitude to the range [0, 1]
    if (normalized_amplitude < 0.0) normalized_amplitude = 0.0;
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0;

    // Non-linear mapping (cool to warm)
    float cool_factor = 1.0 - normalized_amplitude;
    float warm_factor = normalized_amplitude;

    // Map to RGB values
    *red   = (int)(255.0 * warm_factor);
    *green = (int)(255.0 * (0.5 + 0.5 * warm_factor));
    *blue  = (int)(255.0 * cool_factor);
}

// Function to set the RGB LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

#ifdef ALSA_AVAILABLE
// Function to initialize ALSA
int init_alsa(void) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device %s: %s\n", ALSA_DEVICE, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to cleanup ALSA
void cleanup_alsa(void) {
    if (pcm_handle) {
        snd_pcm_close(pcm_handle);
    }
}
#endif

// Function to simulate audio input with a sine wave
void simulate_audio(float *rms_amplitude) {
    static float phase = 0.0;
    float amplitude = 0.5 + 0.5 * sinf(phase);
    *rms_amplitude = amplitude * 32768.0; // Scale to 16-bit range
    phase += 0.01; // Adjust phase increment for desired frequency
    if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        sensitivity = strtof(argv[1], &endptr);
        if (*endptr != '\0' || sensitivity <= 0.0) {
            fprintf(stderr, "Error: Invalid sensitivity value. Using default value of %.2f.\n", DEFAULT_SENSITIVITY);
            sensitivity = DEFAULT_SENSITIVITY;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA (if available)
#ifdef ALSA_AVAILABLE
    if (init_alsa() != 0) {
        fprintf(stderr, "Error: ALSA initialisation failed. Falling back to simulation.\n");
        // Continue without ALSA, using simulation
    }
#endif

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        short *samples = NULL;
        float rms_amplitude = 0.0;
        int red, green, blue;

#ifdef ALSA_AVAILABLE
        if (pcm_handle) {
            // Allocate buffer for audio samples
            samples = (short *)malloc(PERIOD_SIZE * sizeof(short));
            if (samples == NULL) {
                fprintf(stderr, "Error: Failed to allocate memory for audio samples\n");
                running = 0; // Exit loop if memory allocation fails
                continue;     // Skip to cleanup
            }

            // Read audio samples
            int err = snd_pcm_readi(pcm_handle, samples, PERIOD_SIZE);
            if (err == -EPIPE) {
                fprintf(stderr, "Error: ALSA buffer overrun. Recovering...\n");
                snd_pcm_prepare(pcm_handle);
            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "Error: ALSA suspended. Resuming...\n");
                snd_pcm_resume(pcm_handle);
            } else if (err < 0) {
                fprintf(stderr, "Error: ALSA read error: %s\n", snd_strerror(err));
                running = 0; // Exit loop on critical error
                free(samples);
                continue;     // Skip to cleanup
            } else if (err != PERIOD_SIZE) {
                fprintf(stderr, "Warning: ALSA read incomplete (%d frames)\n", err);
            }

            // Calculate RMS amplitude
            rms_amplitude = calculate_rms(samples, PERIOD_SIZE);
            free(samples);
        } else {
            // Use simulation if ALSA is not available
            simulate_audio(&rms_amplitude);
        }
#else
        // Use simulation if ALSA is not available
        simulate_audio(&rms_amplitude);
#endif

        // Map amplitude to RGB values
        map_amplitude_to_rgb(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for 10ms
        gpioDelay(10000); // 10ms = 10000 microseconds
    }

    // Cleanup
    gpioWrite(RED_PIN, 0);   // Turn off LED
    gpioWrite(GREEN_PIN, 0); // Turn off LED
    gpioWrite(BLUE_PIN, 0);  // Turn off LED
    gpioTerminate();         // Terminate pigpio

#ifdef ALSA_AVAILABLE
    cleanup_alsa();          // Close ALSA device
#endif

    return 0;
}

