void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Turn off all relays
    if (line17) gpiod_line_set_value(line17, 1);
    if (line27) gpiod_line_set_value(line27, 1);
    if (line22) gpiod_line_set_value(line22, 1);
    if (line23) gpiod_line_set_value(line23, 1);

    // Release GPIO lines
    if (line17) gpiod_line_release(line17);
    if (line27) gpiod_line_release(line27);
    if (line22) gpiod_line_release(line22);
    if (line23) gpiod_line_release(line23);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value) {
    if (!line) {
        fprintf(stderr, "Error: Line is NULL\n");
        return -1;
    }
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value\n");
        return -1;
    }
    return 0;
}

// Function to simulate sunrise/sunset by toggling relays
void simulate_brightness(int duty_cycle) {
    // Calculate the number of iterations and delay based on duty cycle
    int on_time = (duty_cycle * 100000) / 100; // microseconds
    int off_time = (1000000 - on_time) / 100; // microseconds

    // Turn on relays for 'on_time' microseconds
    if (set_gpio_state(line17, 0) < 0) return;
    if (set_gpio_state(line27, 0) < 0) return;
    if (set_gpio_state(line22, 0) < 0) return;
    if (set_gpio_state(line23, 0) < 0) return;
    usleep(on_time);

    // Turn off relays for 'off_time' microseconds
    if (set_gpio_state(line17, 1) < 0) return;
    if (set_gpio_state(line27, 1) < 0) return;
    if (set_gpio_state(line22, 1) < 0) return;
    if (set_gpio_state(line23, 1) < 0) return;
    usleep(off_time);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    line23 = gpiod_chip_get_line(chip, GPIO_23);

    if (!line17 || !line27 || !line22 || !line23) {
        fprintf(stderr, "Error getting GPIO line\n");
        // Release already acquired lines
        if (line17) gpiod_line_release(line17);
        if (line27) gpiod_line_release(line27);
        if (line22) gpiod_line_release(line22);
        if (line23) gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(line17, "lamp_control", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line27, "lamp_control", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line22, "lamp_control", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line23, "lamp_control", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_line_release(line22);
        gpiod_line_release(line23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Sunrise (1 hour)
        for (int i = 0; i <= 100; i++) {
            simulate_brightness(i);
        }

        // Daytime (6 hours)
        for (int i = 0; i < 21600; i++) {
            simulate_brightness(100);
        }

        // Sunset (1 hour)
        for (int i = 100; i >= 0; i--) {
            simulate_brightness(i);
        }

        // Nighttime (14.4 hours)
        for (int i = 0; i < 52560; i++) {
            simulate_brightness(0);
        }
    }

    return 0;
}

