#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"
#define DEBOUNCE_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
void log_message(const char *message) {
    if (log_file != NULL) {
        char *timestamp = get_iso8601_timestamp();
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
        free(timestamp);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to record a video using raspivid
void record_video() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[50];
    char command[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", timeinfo);
    snprintf(command, sizeof(command), "raspivid -o %s%s -t 5000", VIDEO_DIR, filename);

    int status = system(command);
    if (status == -1) {
        log_message("Error: Failed to execute raspivid command.");
    } else {
        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Video recorded: %s%s", VIDEO_DIR, filename);
        log_message(log_message_buffer);
    }
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Obstacle detected (active low)
        if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Debounce
            log_message("Motion detected!");
            record_video();
            last_tick = current_tick;
        }
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Create video directory if it doesn't exist
    struct stat st = {0};
    if (stat(VIDEO_DIR, &st) == -1) {
        if (mkdir(VIDEO_DIR, 0777) == -1) {
            perror("Error creating video directory");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor (if needed, depends on sensor)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Register the callback function
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Motion detection started.");

    // Keep the program running until a signal is received
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

