#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity (LSB/°/s)
#define GYRO_SENSITIVITY 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_degps(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps);
int log_data(float x_degps, float y_degps, float z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Set sample rate divider to 125 Hz
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error: Could not set sample rate divider. Retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range. Retrying...\n");
            retries--;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Error: MPU-6050 initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_degps(int16_t x, int16_t y, int16_t z, float *x_degps, float *y_degps, float *z_degps) {
    *x_degps = (float)x / GYRO_SENSITIVITY;
    *y_degps = (float)y / GYRO_SENSITIVITY;
    *z_degps = (float)z / GYRO_SENSITIVITY;
}

// Log data to CSV file
int log_data(float x_degps, float y_degps, float z_degps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    if (fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x_degps, y_degps, z_degps) < 0) {
        fprintf(stderr, "Error: Could not write to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    float x_degps, y_degps, z_degps;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            convert_to_degps(x_raw, y_raw, z_raw, &x_degps, &y_degps, &z_degps);

            // Log data
            if (log_data(x_degps, y_degps, z_degps) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Attempting re-initialization.\n");
            init_mpu6050(); // Attempt re-initialization
        }

        gpioDelay(10000); // 10ms delay (100 Hz sampling rate)
    }

    // Close log file and I2C device
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

