#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Scale factor for converting raw data to g
#define SCALE_FACTOR 256.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void trigger_alarm();
void log_freefall_event(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Set alarm pin low
    gpioWrite(ALARM_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Set DATA_FORMAT register to enable full resolution and ±2g range
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    // Read 6 bytes of data starting from DATAX0 register
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0; // Set default values in case of error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes to form 16-bit signed integers
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert raw data to g-force units
    data.x = (float)x / SCALE_FACTOR;
    data.y = (float)y / SCALE_FACTOR;
    data.z = (float)z / SCALE_FACTOR;

    return data;
}

// Function to detect freefall
int detect_freefall(accelerometer_data_t data) {
    // Check if all axes are below the freefall threshold
    if (fabs(data.x) < FREEFALL_THRESHOLD &&
        fabs(data.y) < FREEFALL_THRESHOLD &&
        fabs(data.z) < FREEFALL_THRESHOLD) {
        return 1; // Freefall detected
    } else {
        return 0; // No freefall
    }
}

// Function to trigger the alarm
void trigger_alarm() {
    // Set alarm pin high
    gpioWrite(ALARM_PIN, 1);

    // Wait for 5 seconds
    gpioDelay(5000000); // 5 seconds in microseconds

    // Set alarm pin low
    gpioWrite(ALARM_PIN, 0);
}

// Function to log freefall event
void log_freefall_event(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm pin as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Detect freefall
        if (detect_freefall(data)) {
            // Wait for 0.5 seconds
            gpioDelay(FREEFALL_DURATION * 1000000); // Convert seconds to microseconds

            // Read accelerometer data again
            accelerometer_data_t data2 = read_accelerometer_data();

            // Confirm freefall
            if (detect_freefall(data2)) {
                printf("Freefall detected!\n");

                // Trigger alarm
                trigger_alarm();

                // Log freefall event
                log_freefall_event(data);
            }
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms in microseconds
    }

    return 0;
}

