#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MAX_PULSE_WIDTH 23200      // microseconds (4 meters)
#define TIMEOUT_DURATION 100       // milliseconds
#define SPEED_OF_SOUND 34300       // cm/s

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void trigger_pulse();
void rising_edge_callback(int gpio, int level, uint32_t tick);
void falling_edge_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for rising edge of ECHO signal
void rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    rising_tick = tick;
    echo_received = 1; // Indicate that a rising edge has been received
    pthread_mutex_unlock(&pulse_mutex);
}

// Interrupt handler for falling edge of ECHO signal
void falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    falling_tick = tick;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 1000000.0 to convert us to s, then by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
