#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <string.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default thresholds
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
float calculate_magnitude(float x, float y, float z);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    float freefall_threshold;
    float impact_threshold;
} Config;

// Function to parse command-line arguments
Config parse_arguments(int argc, char *argv[]) {
    Config config = {DEFAULT_FREEFALL_THRESHOLD, DEFAULT_IMPACT_THRESHOLD};
    int opt;

    while ((opt = getopt(argc, argv, "f:i:")) != -1) {
        switch (opt) {
            case 'f':
                config.freefall_threshold = atof(optarg);
                break;
            case 'i':
                config.impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-f freefall_threshold] [-i impact_threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    return config;
}

int main(int argc, char *argv[]) {
    Config config = parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH configuration failed\n");
        cleanup();
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float x_g, y_g, z_g, magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Convert to g
            x_g = convert_to_g(x);
            y_g = convert_to_g(y);
            z_g = convert_to_g(z);

            // Calculate magnitude
            magnitude = calculate_magnitude(x_g, y_g, z_g);

            // Fall detection logic
            if (magnitude < config.freefall_threshold) {
                // Freefall detected, wait for impact
                gpioDelay(100); // Small delay to avoid false triggers
                if (read_acceleration(&x, &y, &z) == 0) {
                    x_g = convert_to_g(x);
                    y_g = convert_to_g(y);
                    z_g = convert_to_g(z);
                    magnitude = calculate_magnitude(x_g, y_g, z_g);
                    if (magnitude > config.impact_threshold) {
                        // Impact detected, activate buzzer
                        activate_buzzer();
                    }
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(10); // Delay for 10ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // I2C bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure LIS3DH
int config_lis3dh() {
    int retries = 3;
    int result;

    // Configure CTRL_REG1 (0x77 for 100Hz, enable all axes)
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
        gpioDelay(10); // Small delay before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries\n");
        return 1;
    }

    // Configure CTRL_REG4 (0x00 for ±2g full scale)
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
        gpioDelay(10); // Small delay before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries\n");
        return 1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (result == 6) break; // Success
        fprintf(stderr, "Error reading acceleration data, retrying...\n");
        gpioDelay(10); // Small delay before retry
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read acceleration data after multiple retries\n");
        return 1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw value to g
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 16384.0f;
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();
}

