#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <math.h>
#include <pigpio.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define DEFAULT_LOG_FILE "/var/log/high_acceleration.log"

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;
static char *log_file = DEFAULT_LOG_FILE;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int configure_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_event(const char *log_file, float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LIS3DH accelerometer
int configure_lis3dh(int i2c_handle) {
    // CTRL_REG1: 0x57 (ODR = 100Hz, Enable X, Y, Z axes)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // CTRL_REG4: 0x88 (High-resolution mode, +/-2g range)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0f;
        *y = 0.0f;
        *z = 0.0f;
        return -1;
    }

    // Combine high and low bytes, shift right 4 bits, and scale
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]) >> 4;
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]) >> 4;
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]) >> 4;

    *x = (float)raw_x * 0.0009765625f;
    *y = (float)raw_y * 0.0009765625f;
    *z = (float)raw_z * 0.0009765625f;

    return 0;
}

// Function to log an event to a file
void log_event(const char *log_file, float x, float y, float z) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: X=%.4f g, Y=%.4f g, Z=%.4f g\n", s, x, y, z);
    fclose(fp);
}

// Function to shut down the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:l:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            case 'l':
                log_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-l log_file]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    AccelerationData accel_data;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Check if acceleration exceeds threshold
            if (fabs(accel_data.x) > threshold || fabs(accel_data.y) > threshold || fabs(accel_data.z) > threshold) {
                log_event(log_file, accel_data.x, accel_data.y, accel_data.z);
                shutdown_system();
                break; // Exit loop after shutdown
            }
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

