#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Define constants
#define BUFFER_SIZE 5
#define ALERT_DURATION 2 // seconds
#define POLL_INTERVAL 10 // milliseconds

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void update_buffer(CircularBuffer *cb, int value);
int check_center_sensor(CircularBuffer *cb);
void line_following_logic(int left, int center, int right);
void set_alert(int state);
void signal_handler(int sig);
void cleanup();

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to update circular buffer
void update_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to check if center sensor reads 'no line' for 5 consecutive readings
int check_center_sensor(CircularBuffer *cb) {
    if (cb->count < BUFFER_SIZE) {
        return 0; // Not enough data yet
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (cb->buffer[i] == 0) {
            return 0; // Center sensor detected a line
        }
    }
    return 1; // Center sensor read 'no line' for 5 consecutive readings
}

// Function to implement line-following logic
void line_following_logic(int left, int center, int right) {
    if (center == 0) {
        // Move forward
        printf("Move Forward\n");
    } else if (left == 0) {
        // Turn left
        printf("Turn Left\n");
    } else if (right == 0) {
        // Turn right
        printf("Turn Right\n");
    } else {
        // Stop
        printf("Stop\n");
    }
}

// Function to set alert state
void set_alert(int state) {
    int ret = gpiod_line_set_value(alert_line, state);
    if (ret < 0) {
        perror("Error setting alert state");
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (center_line) {
        gpiod_line_release(center_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

