#define ALERT_PIN 22

// Define constants
#define BUFFER_SIZE 5
#define ALERT_DURATION 2 // seconds
#define POLL_INTERVAL 10 // milliseconds

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line, *alert_line;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(struct gpiod_line *line);
void update_buffer(CircularBuffer *cb, int value);
int check_center_sensor(CircularBuffer *cb);
void line_following_logic(int left, int center, int right);
void set_alert(int state);
void signal_handler(int sig);
void cleanup();

// Function to read sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to update circular buffer
void update_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to check if center sensor reads 'no line' for 5 consecutive readings
int check_center_sensor(CircularBuffer *cb) {
    if (cb->count < BUFFER_SIZE) {
        return 0; // Not enough data yet
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (cb->buffer[i] == 0) {
            return 0; // Center sensor detected a line
        }
    }
    return 1; // Center sensor read 'no line' for 5 consecutive readings
}

