#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define MEASURE_REG 0xC1
#define DATA_REG 0xC0
#define RELAY_GPIO 17
#define THRESHOLD_MILLI_TESLA 500 // 5.0 mT * 100
#define TIMEOUT_ATTEMPTS 50
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_sensor_data(int16_t *field_raw);
float convert_to_mT(int16_t field_raw);
void control_relay(float field_mT);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int relay_gpio;
    float threshold_mT;
} sensor_config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int16_t *field_raw) {
    int attempts = 0;
    int status;

    // Start measurement
    if (i2cWriteByteData(i2c_handle, MEASURE_REG, 0x01) < 0) {
        log_event("ERROR", "Failed to start measurement");
        return -1;
    }

    // Poll for measurement completion
    do {
        status = i2cReadByteData(i2c_handle, MEASURE_REG);
        if (status < 0) {
            log_event("ERROR", "Failed to read measurement status");
            return -1;
        }
        if (status == 0) break; // Measurement complete
        gpioDelay(1); // Small delay to avoid busy-waiting
        attempts++;
    } while (attempts < TIMEOUT_ATTEMPTS);

    if (attempts >= TIMEOUT_ATTEMPTS) {
        log_event("ERROR", "Measurement timeout");
        return -1;
    }

    // Read data
    int lsb = i2cReadByteData(i2c_handle, DATA_REG);
    if (lsb < 0) {
        log_event("ERROR", "Failed to read LSB");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, DATA_REG + 1);
    if (msb < 0) {
        log_event("ERROR", "Failed to read MSB");
        return -1;
    }

    *field_raw = (int16_t)((msb << 8) | lsb);
    return 0;
}

// Function to convert raw data to milliTesla
float convert_to_mT(int16_t field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

// Function to control the relay
void control_relay(float field_mT) {
    if (field_mT > THRESHOLD_MILLI_TESLA) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
        log_event("RELAY", "Activated");
    } else {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
        log_event("RELAY", "Deactivated");
    }
}

// Function to log events
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("SHUTDOWN", "Received signal, shutting down...");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    int16_t field_raw;
    float field_mT;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&field_raw) == 0) {
            field_mT = convert_to_mT(field_raw);
            char message[50];
            snprintf(message, sizeof(message), "Field: %.2f mT", field_mT);
            log_event("DATA", message);
            control_relay(field_mT);
        } else {
            gpioWrite(RELAY_GPIO, 0); // Deactivate relay on error
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
    fclose(log_file);

    return 0;
}

