#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to log events with timestamp
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    char log_message[100];
    sprintf(log_message, "Signal received: %d. Shutting down gracefully...", signum);
    log_event(log_message);

    // Close sockets
    if (new_socket > 0) close(new_socket);
    if (server_fd > 0) close(server_fd);

    // Close log file
    if (log_file != NULL) fclose(log_file);

    // Turn off relay
    gpioWrite(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    log_event("GPIO initialized successfully");
    return 0;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    char log_message[200];

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0'; // Null-terminate the received data

        // Remove trailing whitespace
        char *command = buffer;
        while (*command == ' ') command++;
        char *end = command + strlen(command) - 1;
        while (end > command && *end == ' ') end--;
        *(end + 1) = '\0';

        // Convert to uppercase
        for (int i = 0; command[i]; i++) {
            command[i] = toupper(command[i]);
        }

        if (strcmp(command, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            log_event("Relay activated");
        } else if (strcmp(command, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            log_event("Relay deactivated");
        } else {
            sprintf(log_message, "Invalid command received: %s", buffer);
            log_event(log_message);
        }
    }

    if (bytes_received == 0) {
        log_event("Client disconnected");
    } else if (bytes_received < 0) {
        perror("recv failed");
        log_event("Error receiving data from client");
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_event("Setsockopt failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Socket listen failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_event("Server listening on port 5000");

    // Accept connections in a loop
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_event("Socket accept failed");
            close(server_fd);
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(address.sin_addr), client_ip, INET_ADDRSTRLEN);
        sprintf(log_message, "Connection accepted from %s:%d", client_ip, ntohs(address.sin_port));
        log_event(log_message);

        handle_client(new_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_fd);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

