#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0 / 1500.0
#define LOG_FILE "flow_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_pigpio();
int open_i2c_handle(int bus, int addr);
int write_i2c_command(int handle, const char *command, int len);
int read_i2c_data(int handle, char *data, int len);
uint8_t calculate_crc8(const char *data, int len);
float convert_to_ml_min(int16_t raw_value);
void control_relay(int state);
void log_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 lookup table
static const uint8_t crc8_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xb9, 0x88, 0xdb, 0xea, 0x7d, 0x4c, 0x1f, 0x2e
};

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open an I2C handle
int open_i2c_handle(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to write an I2C command
int write_i2c_command(int handle, const char *command, int len) {
    int result = i2cWriteDevice(handle, command, len);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read I2C data
int read_i2c_data(int handle, char *data, int len) {
    int result = i2cReadDevice(handle, data, len);
    if (result != len) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc8(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        crc = (crc >> 4) ^ crc8_table[crc & 0x0F];
        crc = (crc >> 4) ^ crc8_table[crc & 0x0F];
    }
    return crc;
}

// Function to convert raw value to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log data to file
void log_data(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = open_i2c_handle(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = open_i2c_handle(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); // De-energize relay initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Start measurement command
    char start_command[] = {0x36, 0x08};

    // Main loop
    while (running) {
        // Send start measurement command to sensor 1
        if (write_i2c_command(i2c_handle1, start_command, sizeof(start_command)) != 0) {
            fprintf(stderr, "Error sending start command to sensor 1\n");
        }

        // Send start measurement command to sensor 2
        if (write_i2c_command(i2c_handle2, start_command, sizeof(start_command)) != 0) {
            fprintf(stderr, "Error sending start command to sensor 2\n");
        }

        // Read data from sensor 1
        char data1[3];
        if (read_i2c_data(i2c_handle1, data1, sizeof(data1)) == 0) {
            // Validate CRC-8 for sensor 1
            uint8_t crc1 = calculate_crc8(data1, 2);
            if (crc1 == (uint8_t)data1[2]) {
                // Convert raw value to ml/min for sensor 1
                int16_t raw_value1 = (data1[0] << 8) | data1[1];
                float flow1 = convert_to_ml_min(raw_value1);

                // Read data from sensor 2
                char data2[3];
                if (read_i2c_data(i2c_handle2, data2, sizeof(data2)) == 0) {
                    // Validate CRC-8 for sensor 2
                    uint8_t crc2 = calculate_crc8(data2, 2);
                    if (crc2 == (uint8_t)data2[2]) {
                        // Convert raw value to ml/min for sensor 2
                        int16_t raw_value2 = (data2[0] << 8) | data2[1];
                        float flow2 = convert_to_ml_min(raw_value2);

                        // Control relay based on flow rates
                        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                            control_relay(1); // Energize relay
                        } else {
                            control_relay(0); // De-energize relay
                        }

                        // Log data
                        log_data(flow1, flow2);
                    } else {
                        fprintf(stderr, "CRC mismatch for sensor 2\n");
                    }
                } else {
                    fprintf(stderr, "Error reading data from sensor 2\n");
                }
            } else {
                fprintf(stderr, "CRC mismatch for sensor 1\n");
            }
        } else {
            fprintf(stderr, "Error reading data from sensor 1\n");
        }

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Cleanup
    control_relay(0); // De-energize relay
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

