#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5
#define DEBOUNCE_COUNT 3

// Global variables
volatile sig_atomic_t program_running = 1;
int rain_detected = 0;
int debounce_counter = 0;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_message(LOG_ERR, "Failed to read rain sensor value.");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to close the window
void close_window() {
    log_message(LOG_INFO, "Closing window...");
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN HIGH.");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN HIGH.");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN LOW.");
    }

    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Delay for motor run time

    stop_motor();
    log_message(LOG_INFO, "Window closed.");
}

// Function to stop the motor
void stop_motor() {
    log_message(LOG_INFO, "Stopping motor...");
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN LOW.");
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN LOW.");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN2_PIN LOW.");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
    stop_motor();
    gpioTerminate();
    log_message(LOG_INFO, "pigpio terminated.");
    closelog();
    exit(0);
}

// Function to log messages using syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }
    log_message(LOG_INFO, "pigpio initialised successfully");

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        log_message(LOG_ERR, "Failed to set RAIN_SENSOR_PIN as input.");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENA_PIN as output.");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_IN1_PIN as output.");
        gpioTerminate();
        closelog();
        return 1;
    }
