#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void lock_door();
void unlock_door();
void handle_button_press(int button_pin, int pulse_width);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);

    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to lock the door
void lock_door() {
    if (gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error setting servo to locked position\n");
    } else {
        printf("Door locked\n");
    }
}

// Function to unlock the door
void unlock_door() {
    if (gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error setting servo to unlocked position\n");
    } else {
        printf("Door unlocked\n");
    }
}

// Function to handle button press with debouncing
void handle_button_press(int button_pin, int pulse_width) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (low signal)
        gpioServo(SERVO_PIN, pulse_width);
        if (pulse_width == LOCK_PULSE_WIDTH) {
            printf("Door locked\n");
        } else {
            printf("Door unlocked\n");
        }

        // Debounce: Wait for button release
        while (gpioRead(button_pin) == 0 && program_running) {
            gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
        }

        // Additional debounce delay after release
        gpioDelay(DEBOUNCE_DELAY * 1000);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        handle_button_press(LOCK_BUTTON_PIN, LOCK_PULSE_WIDTH);
        handle_button_press(UNLOCK_BUTTON_PIN, UNLOCK_PULSE_WIDTH);
        gpioDelay(10000); // Small delay to reduce CPU usage (10ms)
    }

    return 0;
}

