#define FLOODLIGHT_DURATION 60

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_floodlight();
int deactivate_floodlight();
int log_event(const char *event_type, double duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int pir_pin;
    int floodlight_pin;
    int floodlight_duration;
    FILE *log_file;
} ProgramState;

ProgramState state = {PIR_SENSOR_PIN, FLOODLIGHT_PIN, FLOODLIGHT_DURATION, NULL};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(state.pir_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR sensor pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(state.floodlight_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin as output\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(state.floodlight_pin, 0); // Ensure floodlight is off initially
    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(state.pir_pin);
}

// Function to activate the floodlight
int activate_floodlight() {
    if (gpioWrite(state.floodlight_pin, 1) != 0) {
        fprintf(stderr, "Failed to activate floodlight\n");
        return 1;
    }
    return 0;
}

// Function to deactivate the floodlight
int deactivate_floodlight() {
    if (gpioWrite(state.floodlight_pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate floodlight\n");
        return 1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, double duration) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state.log_file == NULL) {
        state.log_file = fopen("security_log.txt", "a");
        if (state.log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return 1;
        }
    }

    if (strcmp(event_type, "Activation") == 0) {
        fprintf(state.log_file, "%s - %s\n", timestamp, event_type);
    } else if (strcmp(event_type, "Deactivation") == 0) {
        fprintf(state.log_file, "%s - %s - Duration: %.2f seconds\n", timestamp, event_type, duration);
    } else {
        fprintf(stderr, "Invalid event type\n");
        return 1;
    }

    fflush(state.log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    deactivate_floodlight(); // Ensure floodlight is off
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    gpioTerminate(); // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    int motion_detected = 0;
    time_t start_time, end_time;
    double duration;

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && !motion_detected) {
            printf("Motion detected!\n");
            if (activate_floodlight() == 0) {
                log_event("Activation", 0.0);
                motion_detected = 1;
                time(&start_time);
            } else {
                fprintf(stderr, "Failed to activate floodlight. Exiting.\n");
                cleanup();
                return 1;
            }
        }

        if (motion_detected) {
            time(&end_time);
            duration = difftime(end_time, start_time);
            if (duration >= state.floodlight_duration) {
                printf("Floodlight duration reached. Turning off.\n");
                if (deactivate_floodlight() == 0) {
                    log_event("Deactivation", duration);
                    motion_detected = 0;
                } else {
                    fprintf(stderr, "Failed to deactivate floodlight. Exiting.\n");
                    cleanup();
                    return 1;
                }
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

