    uint8_t auto_config0;
    uint8_t auto_config1;
    uint8_t auto_config2;
} mpr121_config_t;

// MPR121 configuration values
mpr121_config_t mpr121_config = {
    .mhd = 0x01,
    .nhd = 0x01,
    .ncl = 0x0E,
    .fdl = 0x00,
    .debounce = 0x10,
    .ffi = 0x01,
    .sfi = 0x01,
    .cdt = 0x05,
    .auto_config0 = 0x0B,
    .auto_config1 = 0x05,
    .auto_config2 = 0x00
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on startup

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

