    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, mpr121_config.mhd) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2C, mpr121_config.nhd) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2D, mpr121_config.ncl) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2E, mpr121_config.fdl) < 0) return -1;

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, mpr121_config.debounce) < 0) return -1;

    // Set FFI/SFI/CDT
    uint8_t ffi_sfi_cdt = (mpr121_config.ffi << 4) | (mpr121_config.sfi << 2) | mpr121_config.cdt;
    if (i2cWriteByteData(i2c_handle, 0x2C, ffi_sfi_cdt) < 0) return -1;

    // Set auto-config registers
    if (i2cWriteByteData(i2c_handle, 0x7B, mpr121_config.auto_config0) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x7C, mpr121_config.auto_config1) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x7D, mpr121_config.auto_config2) < 0) return -1;

    // Enable all 12 electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    printf("Relay toggled to %d\n", !current_state);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

