#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <errno.h>
#include <gpiod.h>

// Constants
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PWM_FREQUENCY 50 // Hz
#define PWM_PERIOD (1000000000 / PWM_FREQUENCY) // nanoseconds
#define SERVO_MIN_PULSE_WIDTH 1000000 // 1 ms
#define SERVO_MAX_PULSE_WIDTH 2000000 // 2 ms
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define PORT 5000
#define LOG_FILE "security.log"

// Global variables
static volatile int running = 1;
static int servo_angle = 90; // Initial servo angle
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
void signal_handler(int sig);
int init_gpio(void);
void cleanup_gpio(void);
void *pwm_thread_func(void *arg);
int handle_client(int client_socket);
int parse_command(const char *command, char *response, size_t response_size);
int set_servo_angle(int angle);
int read_pir_sensor(void);

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...", sig);
    running = 0;
}

// GPIO initialization function
int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Get servo line
    servo_line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!servo_line) {
        log_message(LOG_ERR, "Error getting servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get PIR line
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_message(LOG_ERR, "Error getting PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        return -1;
    }

    // Configure servo line as output
    memset(&config, 0, sizeof(config));
    config.consumer = "servo";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(servo_line, &config, 0) != 0) {
        log_message(LOG_ERR, "Error requesting servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Configure PIR line as input
    memset(&config, 0, sizeof(config));
    config.consumer = "pir";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(pir_line, &config, 0) != 0) {
        log_message(LOG_ERR, "Error requesting PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_release(servo_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
}

// PWM thread function
void *pwm_thread_func(void *arg) {
    struct timespec on_time, off_time;
    long pulse_width;

    while (running) {
        // Calculate pulse width based on servo angle
        pulse_width = SERVO_MIN_PULSE_WIDTH + (long)(((float)servo_angle / 180.0) * SERVO_RANGE);

        // Set servo line high
        if (gpiod_line_set_value(servo_line, 1) != 0) {
            log_message(LOG_ERR, "Error setting servo line high: %s", strerror(errno));
            break;
        }

        // Calculate on time
        on_time.tv_sec = 0;
        on_time.tv_nsec = pulse_width;

        // Wait for on time
        nanosleep(&on_time, NULL);

        // Set servo line low
        if (gpiod_line_set_value(servo_line, 0) != 0) {
            log_message(LOG_ERR, "Error setting servo line low: %s", strerror(errno));
            break;
        }

        // Calculate off time
        off_time.tv_sec = 0;
        off_time.tv_nsec = PWM_PERIOD - pulse_width;

        // Wait for off time
        nanosleep(&off_time, NULL);
    }

    pthread_exit(NULL);
}

// Client handling function
int handle_client(int client_socket) {
    char buffer[1024];
    char response[1024];
    ssize_t bytes_received;

    // Receive data from client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        log_message(LOG_ERR, "Error receiving data: %s", strerror(errno));
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Parse command
    if (parse_command(buffer, response, sizeof(response)) != 0) {
        snprintf(response, sizeof(response), "Invalid command");
    }

    // Send response to client
    if (send(client_socket, response, strlen(response), 0) < 0) {
        log_message(LOG_ERR, "Error sending data: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Command parsing function
int parse_command(const char *command, char *response, size_t response_size) {
    char cmd[10];
    int angle;

    if (sscanf(command, "%s", cmd) != 1) {
        return -1;
    }

    if (strcmp(cmd, "SERVO") == 0) {
        if (sscanf(command, "%s %d", cmd, &angle) != 2) {
            return -1;
        }
        if (angle < 0 || angle > 180) {
            snprintf(response, response_size, "Invalid angle");
            return -1;
        }
        if (set_servo_angle(angle) != 0) {
            snprintf(response, response_size, "Error setting servo angle");
            return -1;
        }
        snprintf(response, response_size, "OK");
        return 0;
    } else if (strcmp(cmd, "PIR") == 0) {
        int pir_value = read_pir_sensor();
        snprintf(response, response_size, "PIR:%d", pir_value);
        return 0;
    } else {
        return -1;
    }
}

// Servo angle setting function
int set_servo_angle(int angle) {
    servo_angle = angle;
    return 0;
}

// PIR sensor reading function
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Error reading PIR sensor: %s", strerror(errno));
        return 0; // Return 0 on error
    }
    return value;
}

int main(void) {
    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);
    pthread_t pwm_thread;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Log program start
    log_message(LOG_INFO, "Starting security system...");

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed. Exiting.");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    // Create server socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        log_message(LOG_ERR, "Error creating socket: %s", strerror(errno));
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message(LOG_ERR, "Error binding socket: %s", strerror(errno));
        close(server_socket);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    // Listen for connections
    if (listen(server_socket, 5) < 0) {
        log_message(LOG_ERR, "Error listening on socket: %s", strerror(errno));
        close(server_socket);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    // Create PWM thread
    if (pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL) != 0) {
        log_message(LOG_ERR, "Error creating PWM thread: %s", strerror(errno));
        close(server_socket);
        cleanup_gpio();
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Accept connection
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            log_message(LOG_ERR, "Error accepting connection: %s", strerror(errno));
            continue; // Continue listening for other connections
        }

        // Handle client
        if (handle_client(client_socket) != 0) {
            log_message(LOG_ERR, "Error handling client connection.");
        }

        // Close client socket
        close(client_socket);
    }

    // Clean up
    log_message(LOG_INFO, "Shutting down...");

    // Cancel PWM thread
    pthread_cancel(pwm_thread);
    pthread_join(pwm_thread, NULL);

    // Close server socket
    close(server_socket);

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    fclose(log_file);

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

