#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <getopt.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *hx711_dout_line;
static struct gpiod_line *hx711_sck_line;
static struct gpiod_line *solenoid_line;
static volatile sig_atomic_t terminate = 0;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_offset = 0;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(int activate);
void tare_hx711();
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Cleanup function to release GPIO resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

    if (solenoid_line) {
        gpiod_line_set_value(solenoid_line, 0);
        gpiod_line_release(solenoid_line);
    }
    if (hx711_sck_line) {
        gpiod_line_release(hx711_sck_line);
    }
    if (hx711_dout_line) {
        gpiod_line_release(hx711_dout_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    closelog();
}

// Function to read data from HX711
int read_hx711() {
    int i;
    int data = 0;
    int timeout_count = 0;
    struct timespec timeout = {1, 0}; // 1 second timeout

    // Wait for DOUT to go LOW (data ready)
    while (gpiod_line_get_value(hx711_dout_line) == 1) {
        nanosleep(&timeout, NULL);
        timeout_count++;
        if (timeout_count > 3) {
            syslog(LOG_ERR, "HX711 timeout error: DOUT did not go LOW");
            return -1; // Indicate error
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(hx711_sck_line, 1);
        gpiod_line_set_value(hx711_sck_line, 0);
        data = data << 1;
        if (gpiod_line_get_value(hx711_dout_line) == 1) {
            data++;
        }
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpiod_line_set_value(hx711_sck_line, 1);
    gpiod_line_set_value(hx711_sck_line, 0);

    // Convert 24-bit two's-complement reading to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)(raw_value - tare_offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int activate) {
    if (activate) {
        syslog(LOG_INFO, "Activating solenoid for %d ms", duration);
        gpiod_line_set_value(solenoid_line, 1);
        usleep(duration * 1000); // Convert ms to microseconds
        gpiod_line_set_value(solenoid_line, 0);
        syslog(LOG_INFO, "Solenoid deactivated");
    } else {
        gpiod_line_set_value(solenoid_line, 0);
    }
}

// Function to perform tare calibration
void tare_hx711() {
    int i;
    long sum = 0;
    int raw_value;

    syslog(LOG_INFO, "Taring HX711...");
    for (i = 0; i < 10; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Tare failed: HX711 read error");
            return;
        }
        sum += raw_value;
        usleep(100000); // 100 ms delay
    }
    tare_offset = sum / 10;
    syslog(LOG_INFO, "Tare offset: %d", tare_offset);
}

int main(int argc, char *argv[]) {
    int opt;
    int raw_value;
    double weight;
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip");
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get GPIO lines
    hx711_dout_line = gpiod_chip_get_line(chip, HX711_DOUT);
    hx711_sck_line = gpiod_chip_get_line(chip, HX711_SCK);
    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!hx711_dout_line || !hx711_sck_line || !solenoid_line) {
        syslog(LOG_ERR, "Error getting GPIO line");
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(solenoid_line, "weight_monitor", 0) < 0) {
        syslog(LOG_ERR, "Error requesting solenoid line for output");
        perror("gpiod_line_request_output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(hx711_dout_line, "weight_monitor") < 0) {
        syslog(LOG_ERR, "Error requesting HX711 DOUT line for input");
        perror("gpiod_line_request_input");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(hx711_sck_line, "weight_monitor", 0) < 0) {
        syslog(LOG_ERR, "Error requesting HX711 SCK line for output");
        perror("gpiod_line_request_output");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Perform tare calibration
    tare_hx711();

    // Main loop
    while (!terminate) {
        // Read raw value from HX711
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading HX711, retrying...");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Calculate weight
        weight = calculate_weight(raw_value);

        // Log weight
        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        // Check if weight exceeds threshold
        if (weight > threshold) {
            control_solenoid(1);
        }

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

