#include <unistd.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

// Function to handle MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    if (result == MOSQ_ERR_SUCCESS)
    {
        log_message(LOG_INFO, "MQTT connected to broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS)
        {
            log_message(LOG_ERR, "Failed to subscribe to topic");
        }
    }
    else
    {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_connack_string(result));
        log_message(LOG_ERR, error_message);
    }
}

// Function to handle MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    if (rc != 0)
    {
        log_message(LOG_WARNING, "MQTT disconnected unexpectedly");
    }
    else
    {
        log_message(LOG_INFO, "MQTT disconnected cleanly");
    }
}

// Function to handle MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message)
{
    if (message->payloadlen > 0)
    {
        char *payload = (char *)message->payload;
        char log_message_buffer[200];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Received message on topic %s: %s", message->topic, payload);
        log_message(LOG_INFO, log_message_buffer);

        if (strcmp(payload, "ON") == 0)
        {
            gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            log_message(LOG_INFO, "Relay turned ON");
        }
        else if (strcmp(payload, "OFF") == 0)
        {
            gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            log_message(LOG_INFO, "Relay turned OFF");
        }
        else
        {
            log_message(LOG_ERR, "Invalid payload received");
        }
    }
    else
    {
        log_message(LOG_ERR, "Empty payload received");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum)
{
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

int main()
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq)
    {
        log_message(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running)
    {
        int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS)
        {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
            log_message(LOG_ERR, error_message);
            sleep(5);
            continue;
        }

        rc = mosquitto_loop(mosq, -1, 1); // -1 means loop forever, 1 is max 1 message processed per loop
        if (rc != MOSQ_ERR_SUCCESS)
        {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "MQTT loop error: %s", mosquitto_strerror(rc));
            log_message(LOG_ERR, error_message);
            mosquitto_disconnect(mosq);
            sleep(5);
        }
    }

    // Cleanup
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    closelog();

    return 0;
}

