int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency to 50 Hz (20 ms period)
    gpioSetPWMfrequency(SERVO1, 50);
    gpioSetPWMfrequency(SERVO2, 50);
    gpioSetPWMfrequency(SERVO3, 50);
    gpioSetPWMfrequency(SERVO4, 50);
    gpioSetPWMfrequency(SERVO5, 50);

    // Set PWM range to 2000 (representing 20 ms period)
    gpioSetPWMrange(SERVO1, 2000);
    gpioSetPWMrange(SERVO2, 2000);
    gpioSetPWMrange(SERVO3, 2000);
    gpioSetPWMrange(SERVO4, 2000);
    gpioSetPWMrange(SERVO5, 2000);

    // Set pulse widths for each servo
    gpioPWM(SERVO1, 1000); // 1000 us
    gpioPWM(SERVO2, 1500); // 1500 us
    gpioPWM(SERVO3, 2000); // 2000 us
    gpioPWM(SERVO4, 500);  // 500 us
    gpioPWM(SERVO5, 2500); // 2500 us

    // Hold the signals for 3 seconds
    sleep(3);

    // Stop PWM and release resources
    gpioPWM(SERVO1, 0);
    gpioPWM(SERVO2, 0);
    gpioPWM(SERVO3, 0);
    gpioPWM(SERVO4, 0);
    gpioPWM(SERVO5, 0);

    gpioTerminate();

    return 0;
}

