#include <pthread.h>
#include <string.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

// Motor B
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

// Encoder A
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

// Encoder B
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

#define TARGET_RPM 50.0
#define ENCODER_TICKS_PER_REV 64.0
#define PWM_FREQUENCY 10000.0 // 10 kHz
#define CONTROL_PERIOD_MS 100
#define STALL_TIMEOUT_S 2.0

// PI Controller Gains
#define Kp 0.5
#define Ki 0.05

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int stall_flag_a = 0;
volatile int stall_flag_b = 0;
pthread_mutex_t encoder_mutex;

// Function prototypes
void motor_a_forward(int speed);
void motor_a_backward(int speed);
void motor_a_stop();
void motor_b_forward(int speed);
void motor_b_backward(int speed);
void motor_b_stop();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count, double time_elapsed);
double pi_controller(double target_rpm, double actual_rpm, double *integral, double dt);
void *control_loop(void *arg);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward(int speed) {
    gpioPWM(MOTOR_A_PWM_PIN, speed);
    gpioWrite(MOTOR_A_DIR_PIN, 1);
}

void motor_a_backward(int speed) {
    gpioPWM(MOTOR_A_PWM_PIN, speed);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
}

void motor_a_stop() {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioWrite(MOTOR_A_DIR_PIN, 0);
}

void motor_b_forward(int speed) {
    gpioPWM(MOTOR_B_PWM_PIN, speed);
    gpioWrite(MOTOR_B_DIR_PIN, 1);
}

void motor_b_backward(int speed) {
    gpioPWM(MOTOR_B_PWM_PIN, speed);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

void motor_b_stop() {
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioWrite(MOTOR_B_DIR_PIN, 0);
}

// Encoder interrupt service routines
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    pthread_mutex_lock(&encoder_mutex);
    encoder_a_count++;
    pthread_mutex_unlock(&encoder_mutex);
}

