#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define RELAY_GPIO 17
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_bh1750(float *lux);
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold system state
typedef struct {
    int relay_state;
} SystemState;

SystemState state = {0}; // Initialize relay state to OFF

int main() {
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750 sensor
        if (read_bh1750(&lux) == 0) {
            // Control the relay based on lux value and hysteresis
            if (lux < LUX_THRESHOLD_LOW && relay_state == 0) {
                control_relay(1); // Turn ON
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state == 1) {
                control_relay(0); // Turn OFF
                relay_state = 0;
                log_data(lux, relay_state);
            } else {
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

// Initialize pigpio, I2C, and log file
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send One-Time High-Resolution Mode 2 command (0x21)
    result = i2cWriteByte(i2c_handle, 0x21);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }

    // Wait for at least 180 ms
    gpioDelay(180000); // 180 ms in microseconds

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the relay (ON or OFF)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Log data to file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Turn off the relay
    control_relay(0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

