#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Calibration factor (pulses per liter)
#define PULSES_PER_LITER 450.0

// Thresholds for LPM (Liters Per Minute)
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5

// Debounce timeout in milliseconds
#define DEBOUNCE_TIMEOUT 1000

// Global variables
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile int solenoid_state = 1; // 1 = open, 0 = closed
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulses);
void control_solenoid(double lpm);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff > DEBOUNCE_TIMEOUT) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = tick;
    }
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulses) {
    return (pulses / PULSES_PER_LITER) * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        // Close the solenoid
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_state = 0;
        log_message("Solenoid closed");
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        // Open the solenoid
        gpioWrite(SOLENOID_PIN, 1);
        solenoid_state = 1;
        log_message("Solenoid opened");
    }
}

// Function to log messages to a file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char message[50];
    sprintf(message, "Received signal %d, shutting down...", signal);
    log_message(message);
    running = 0; // Stop the main loop
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLOW_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Set initial solenoid state to open
    gpioWrite(SOLENOID_PIN, 1);
    solenoid_state = 1;

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close solenoid valve
    gpioWrite(SOLENOID_PIN, 1);
    solenoid_state = 1;
    log_message("Solenoid opened (cleanup)");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds

        // Lock the mutex
        pthread_mutex_lock(&pulse_mutex);

        // Read pulse count
        int current_pulse_count = pulse_count;

        // Reset pulse count
        pulse_count = 0;

        // Unlock the mutex
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control the solenoid
        control_solenoid(lpm);

        // Log the LPM reading
        char message[50];
        sprintf(message, "LPM: %.2f", lpm);
        log_message(message);
    }

    return 0;
}

