#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <ini.h>

// Configuration structure
typedef struct {
    double calibration_factor;
    char server_ip[20];
    int server_port;
} Config;

// Global variables
int hx711_data_pin = 23;
int hx711_sck_pin = 24;
int servo_pin = 18;
int server_socket = -1;
int client_socket = -1;
Config config;
double known_weight = 100.0; // Known weight for calibration (e.g., 100g)
double target_weight = 50.0;  // Target weight to dispense (e.g., 50g)
int servo_pulse_width = 1500; // Initial servo pulse width (1.5ms)

// Function prototypes
int read_config(const char *filename, Config *config);
long read_hx711();
double calibrate_hx711(long raw_value, double known_weight, double calibration_factor);
void set_servo_pulse_width(int pulse_width);
void dispense_ingredient(double target_weight);
void handle_client(int client_socket);
void log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// Configuration file parser
static int handler(void* user, const char* section, const char* name, const char* value)
{
    Config* pconfig = (Config*)user;

    #define MATCH(s, n) strcmp(section, s) == 0 && strcmp(name, n) == 0
    if (MATCH("server", "ip")) {
        strncpy(pconfig->server_ip, value, sizeof(pconfig->server_ip) - 1);
    } else if (MATCH("server", "port")) {
        pconfig->server_port = atoi(value);
    } else if (MATCH("hx711", "calibration_factor")) {
        pconfig->calibration_factor = atof(value);
    } else {
        return 0;  /* unknown section/name, error */
    }
    return 1;
}

int read_config(const char *filename, Config *config) {
    config->calibration_factor = 1.0; // Default calibration factor
    strncpy(config->server_ip, "127.0.0.1", sizeof(config->server_ip) - 1);
    config->server_port = 12345;

    if (ini_parse(filename, handler, config) < 0) {
        fprintf(stderr, "Can't load 'config.ini'\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// HX711 reading function
long read_hx711() {
    long value = 0;
    int i;

    gpioSetMode(hx711_data_pin, PI_INPUT);
    gpioSetMode(hx711_sck_pin, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout = 0;
    while (gpioRead(hx711_data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // 1 ms delay
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 not ready (DATA pin HIGH for too long).\n");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_pin, 1);
        gpioDelay(1); // 1 us clock pulse width
        value = value << 1;
        if (gpioRead(hx711_data_pin)) {
            value++;
        }
        gpioWrite(hx711_sck_pin, 0);
        gpioDelay(1); // 1 us clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(hx711_sck_pin, 1);
    gpioDelay(1); // 1 us clock pulse width
    gpioWrite(hx711_sck_pin, 0);
    gpioDelay(1); // 1 us clock pulse width

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Calibration function
double calibrate_hx711(long raw_value, double known_weight, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Servo control function
void set_servo_pulse_width(int pulse_width) {
    gpioServo(servo_pin, pulse_width);
    servo_pulse_width = pulse_width; // Update global variable
}

// Dispensing function
void dispense_ingredient(double target_weight) {
    long raw_value;
    double actual_weight;

    // Open the servo (e.g., to 2000 us)
    set_servo_pulse_width(2000);
    gpioDelay(1000); // Wait 1 second

    // Read the actual weight from the HX711
    raw_value = read_hx711();
    if (raw_value == -1) {
        log_event(target_weight, 0.0, "Error reading HX711 during dispensing.");
        return;
    }
    actual_weight = calibrate_hx711(raw_value, known_weight, config.calibration_factor);

    // Close the servo (e.g., back to 1000 us)
    set_servo_pulse_width(1000);
    gpioDelay(100); // Short delay after closing

    // Log the event
    log_event(target_weight, actual_weight, NULL);
}

// Client handling function
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    // Receive the target weight from the client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        target_weight = atof(buffer);
        printf("Received target weight: %.2f grams\n", target_weight);

        // Dispense the ingredient
        dispense_ingredient(target_weight);

        // Send the actual weight back to the client
        long raw_value = read_hx711();
        if (raw_value != -1) {
            double actual_weight = calibrate_hx711(raw_value, known_weight, config.calibration_factor);
            snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
            send(client_socket, buffer, strlen(buffer), 0);
        } else {
            send(client_socket, "Error reading weight", strlen("Error reading weight"), 0);
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected.\n");
    } else {
        perror("Error receiving data");
