void set_servo_pulse_width(int pulse_width);
void dispense_ingredient(double target_weight);
void handle_client(int client_socket);
void log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// Configuration file parser
static int handler(void* user, const char* section, const char* name, const char* value)
{
    Config* pconfig = (Config*)user;

    #define MATCH(s, n) strcmp(section, s) == 0 && strcmp(name, n) == 0
    if (MATCH("server", "ip")) {
        strncpy(pconfig->server_ip, value, sizeof(pconfig->server_ip) - 1);
    } else if (MATCH("server", "port")) {
        pconfig->server_port = atoi(value);
    } else if (MATCH("hx711", "calibration_factor")) {
        pconfig->calibration_factor = atof(value);
    } else {
        return 0;  /* unknown section/name, error */
    }
    return 1;
}

int read_config(const char *filename, Config *config) {
    config->calibration_factor = 1.0; // Default calibration factor
    strncpy(config->server_ip, "127.0.0.1", sizeof(config->server_ip) - 1);
    config->server_port = 12345;

    if (ini_parse(filename, handler, config) < 0) {
        fprintf(stderr, "Can't load 'config.ini'\n");
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// HX711 reading function
long read_hx711() {
    long value = 0;
    int i;

    gpioSetMode(hx711_data_pin, PI_INPUT);
    gpioSetMode(hx711_sck_pin, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int timeout = 0;
    while (gpioRead(hx711_data_pin) == 1 && timeout < 1000) {
        gpioDelay(1); // 1 ms delay
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 not ready (DATA pin HIGH for too long).\n");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(hx711_sck_pin, 1);
        gpioDelay(1); // 1 us clock pulse width
        value = value << 1;
        if (gpioRead(hx711_data_pin)) {
            value++;
        }
        gpioWrite(hx711_sck_pin, 0);
        gpioDelay(1); // 1 us clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(hx711_sck_pin, 1);
    gpioDelay(1); // 1 us clock pulse width
    gpioWrite(hx711_sck_pin, 0);
    gpioDelay(1); // 1 us clock pulse width

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

// Calibration function
double calibrate_hx711(long raw_value, double known_weight, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Servo control function
