    actual_weight = calibrate_hx711(raw_value, known_weight, config.calibration_factor);

    // Close the servo (e.g., back to 1000 us)
    set_servo_pulse_width(1000);
    gpioDelay(100); // Short delay after closing

    // Log the event
    log_event(target_weight, actual_weight, NULL);
}

// Client handling function
void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    // Receive the target weight from the client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        target_weight = atof(buffer);
