#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static int relay_state = 0; // 0 = OFF, 1 = ON
static int debounce_time = DEFAULT_DEBOUNCE_TIME;

// Function prototypes
int read_touch_sensor();
int debounce(int sensor_value, int debounce_time);
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Function to read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor input
int debounce(int sensor_value, int debounce_time) {
    if (sensor_value == 1) {
        gpioDelay(debounce_time * 1000); // Convert milliseconds to microseconds
        if (read_touch_sensor() == 1) {
            return 1; // Valid rising edge
        }
    }
    return 0; // No valid rising edge
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate(); // Release pigpio resources
    printf("pigpio terminated.\n");
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_time = atoi(argv[2]);
            if (debounce_time <= 0) {
                fprintf(stderr, "Error: Invalid debounce time. Using default value (%d ms).\n", DEFAULT_DEBOUNCE_TIME);
                debounce_time = DEFAULT_DEBOUNCE_TIME;
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_PIN);
        cleanup();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch-controlled relay switch started. Debounce time: %d ms\n", debounce_time);

    // Main loop
    while (running) {
        if (debounce(read_touch_sensor(), debounce_time)) {
            toggle_relay();
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

