#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define INITIAL_ANGLE 90

static volatile int running = 1;
static struct termios original_termios;

// Function to set terminal to raw mode
void set_raw_mode() {
    struct termios raw_termios = original_termios;
    raw_termios.c_lflag &= ~(ICANON | ECHO);
    raw_termios.c_cc[VMIN] = 0;      // Non-blocking read
    raw_termios.c_cc[VTIME] = 0;     // No timeout
    tcsetattr(STDIN_FILENO, TCSANOW, &raw_termios);
}

// Function to restore original terminal settings
void restore_terminal_settings() {
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set the servo pulse width using gpioServo
    gpioServo(SERVO_PIN, pulse_width);

    return 0;
}

int main() {
    // Save original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr failed");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency (though gpioServo doesn't directly use this, it's good practice)
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo angle
    int current_angle = INITIAL_ANGLE;
    if (set_servo_angle(current_angle) != 0) {
        gpioTerminate();
        restore_terminal_settings();
        return 1;
    }
    printf("Initial angle: %d\n", current_angle);

    // Set terminal to raw mode
    set_raw_mode();

    // Main loop to read keyboard input
    char input;
    while (running) {
        if (read(STDIN_FILENO, &input, 1) > 0) {
            switch (input) {
                case '+':
                    current_angle += 10;
                    if (current_angle > 180) {
                        current_angle = 180;
                    }
                    if (set_servo_angle(current_angle) == 0) {
                        printf("Angle: %d\n", current_angle);
                    }
                    break;
                case '-':
                    current_angle -= 10;
                    if (current_angle < 0) {
                        current_angle = 0;
                    }
                    if (set_servo_angle(current_angle) == 0) {
                        printf("Angle: %d\n", current_angle);
                    }
                    break;
                case 'q':
                    running = 0;
                    break;
                default:
                    // Ignore other characters
                    break;
            }
        }
        usleep(10000); // Small delay to prevent busy-waiting
    }

    // Stop PWM pulses and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();

    // Restore original terminal settings
    restore_terminal_settings();

    return 0;
}

