#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_NS 2000000 // 2 milliseconds in nanoseconds
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    unsigned long long pulse_count;
} program_state_t;

program_state_t state;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(unsigned long long pulse_count) {
    return (double)pulse_count / SAMPLE_INTERVAL_SEC * 60.0;
}

// Function to log RPM data to file
int log_rpm_data(FILE *log_file, double rpm) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log entry.\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    free(timestamp); // Free the allocated memory

    if (result < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Function to print RPM to stdout
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Function to handle GPIO events
int handle_gpio_event(struct gpiod_line *line) {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_wait(line, NULL);
    if (ret < 0) {
        perror("Error waiting for GPIO event");
        return -1;
    }

    ret = gpiod_line_event_read(line, &event);
    if (ret < 0) {
        perror("Error reading GPIO event");
        return -1;
    }

    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        state.pulse_count++;
    }

    return 0;
}

int main() {
    struct timespec debounce_delay = {0, DEBOUNCE_DELAY_NS};
    struct timespec sample_interval = {SAMPLE_INTERVAL_SEC, 0};
    struct timespec remaining_time;
    unsigned long long pulse_count;
    double rpm;

    // Initialize program state
    state.chip = NULL;
    state.line = NULL;
    state.log_file = NULL;
    state.pulse_count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }
    state.chip = chip; // Update program state

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    state.line = line; // Update program state

    // Request GPIO line as input with pull-up
    int ret = gpiod_line_request_input_flags(line, "conveyor_monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    state.log_file = log_file; // Update program state

    printf("Monitoring conveyor belt motor on GPIO %d...\n", GPIO_PIN);

    while (keep_running) {
        pulse_count = state.pulse_count; // Capture current pulse count
        state.pulse_count = 0; // Reset pulse count for the next interval

        // Debounce delay
        nanosleep(&debounce_delay, &remaining_time);

        // Main loop
        while (keep_running && state.pulse_count == pulse_count) {
            if (handle_gpio_event(line) != 0) {
                fprintf(stderr, "Error handling GPIO event, exiting.\n");
                keep_running = 0;
                break;
            }
        }

        // Calculate RPM
        rpm = calculate_rpm(pulse_count);

        // Log RPM data
        if (log_rpm_data(log_file, rpm) != 0) {
            fprintf(stderr, "Error logging RPM data.\n");
        }

        // Print RPM to stdout
        print_rpm(rpm);

        // Wait for the next sample interval
        nanosleep(&sample_interval, &remaining_time);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

