#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLLING_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = 0; // 0 = OFF, 1 = ON
time_t touch_start_time = 0;

// Function prototypes
int read_touch_sensor();
int toggle_relay(int current_state);
void handle_signal(int signal);
void log_message(const char *message);

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    log_message("Signal received, exiting...");
}

// Function to read the touch sensor
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_value < 0) {
        log_message("Error reading touch sensor!");
        return -1; // Indicate an error
    }
    return touch_value;
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    int result = gpioWrite(RELAY_PIN, new_state);
    if (result != 0) {
        log_message("Error writing to relay!");
        return -1; // Indicate an error
    }
    return new_state;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        log_message("Error setting touch sensor pin mode!");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_message("Error setting relay pin mode!");
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int touch_value = read_touch_sensor();
        if (touch_value < 0) {
            // Error reading touch sensor, exit
            break;
        }

        if (touch_value == 1) {
            // Touch detected
            if (touch_start_time == 0) {
                // First touch, record the start time
                touch_start_time = time(NULL);
            } else {
                // Check for failsafe timeout
                time_t current_time = time(NULL);
                if (difftime(current_time, touch_start_time) > FAILSAFE_TIMEOUT_S) {
                    // Failsafe timeout reached, force relay OFF
                    log_message("Failsafe timeout reached, forcing relay OFF");
                    relay_state = 0;
                    gpioWrite(RELAY_PIN, 0);
                    touch_start_time = 0; // Reset touch start time
                }
            }

            // Toggle relay state
            relay_state = toggle_relay(relay_state);
            if (relay_state < 0) {
                // Error toggling relay, exit
                break;
            }
            touch_start_time = 0; // Reset touch start time after toggle
        } else {
            // No touch detected, reset touch start time
            touch_start_time = 0;
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup
    log_message("Cleaning up...");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio

    log_message("Program finished");
    return 0;
}

