#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define SENSOR_GPIO 24
#define PULSES_PER_LITER 450.0
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 100
#define KP 1.0

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double time_interval);
int proportional_control(double target_flow_rate, double actual_flow_rate);
void log_data(long long timestamp_ms, double flow_rate, int valve_position);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double time_interval) {
    return (double)pulse_count / PULSES_PER_LITER / (time_interval / 1000.0) * 60.0;
}

// Proportional controller function
int proportional_control(double target_flow_rate, double actual_flow_rate) {
    int duty_cycle = (int)((target_flow_rate - actual_flow_rate) * KP);
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }
    return duty_cycle;
}

// Function to log data to a CSV file
void log_data(long long timestamp_ms, double flow_rate, int valve_position) {
    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set VALVE_GPIO mode\n");
        return 1;
    }
    if (gpioSetMode(ENABLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set ENABLE_GPIO mode\n");
        return 1;
    }
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set SENSOR_GPIO mode\n");
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Enable the valve
    gpioWrite(ENABLE_GPIO, 1);

    // Open the log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Register interrupt service routine
    if (gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR\n");
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
