#define ENABLE_GPIO 23
#define SENSOR_GPIO 24
#define PULSES_PER_LITER 450.0
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 100
#define KP 1.0

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double time_interval);
int proportional_control(double target_flow_rate, double actual_flow_rate);
void log_data(long long timestamp_ms, double flow_rate, int valve_position);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for pulse counting
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double time_interval) {
    return (double)pulse_count / PULSES_PER_LITER / (time_interval / 1000.0) * 60.0;
}

// Proportional controller function
int proportional_control(double target_flow_rate, double actual_flow_rate) {
    int duty_cycle = (int)((target_flow_rate - actual_flow_rate) * KP);
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }
    return duty_cycle;
}

