#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid(unsigned char *tag);
int validate_tag(const unsigned char *tag);
int read_button();
void control_locks(int lock1_state, int lock2_state);
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid(unsigned char *tag) {
    char tx_buf[10] = {0}; // Transmit buffer (dummy data)
    char rx_buf[10];      // Receive buffer

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 0) {
        log_event("ERROR", "SPI read failed");
        return -1; // Indicate failure
    }

    memcpy(tag, rx_buf, 10);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    return (memcmp(tag, valid_tag, 10) == 0);
}

// Function to read button state with debouncing
int read_button() {
    int button_state = gpioRead(BUTTON_PIN);
    gpioDelay(50); // Debounce delay
    return (button_state == 0); // Return 1 if pressed (active-low)
}

// Function to control the locks
void control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK1_PIN, lock1_state);
    gpioWrite(LOCK2_PIN, lock2_state);
}

// Function to log events to file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("INFO", "Received termination signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        log_event("ERROR", "SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set initial lock state (engaged)
    control_locks(1, 1);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char rfid_tag[10];
    int tag_valid = 0;

    log_event("INFO", "System started");

    // Main loop
    while (!terminate) {
        // Read RFID tag
        if (read_rfid(rfid_tag) == 0) {
            // Validate RFID tag
            if (validate_tag(rfid_tag)) {
                log_event("INFO", "Valid RFID tag read");
                tag_valid = 1;
            } else {
                log_event("WARNING", "Invalid RFID tag read");
                tag_valid = 0;
            }
        } else {
            // RFID read failure already logged in read_rfid function
        }

        // Read button state
        if (read_button()) {
            if (tag_valid) {
                log_event("INFO", "Button pressed, unlocking doors");
                // Unlock doors
                control_locks(0, 0);
                gpioDelay(5000); // Keep unlocked for 5 seconds
                // Re-lock doors
                control_locks(1, 1);
                log_event("INFO", "Doors re-locked");
                tag_valid = 0; // Reset tag validity after successful auth
            } else {
                log_event("WARNING", "Button pressed without valid RFID tag");
            }
        }

        gpioDelay(100); // Polling delay
    }

    // Clean up
    spiClose(spi_handle);
    control_locks(1, 1); // Ensure locks are engaged on exit
    fclose(log_file);
    gpioTerminate();

    log_event("INFO", "System stopped");

    return 0;
}

