#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR1_ENC_A 5
#define MOTOR1_ENC_B 6

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define MOTOR2_ENC_A 26
#define MOTOR2_ENC_B 19

#define TARGET_RPM 60.0
#define ENCODER_PULSES_PER_REV 600.0
#define PWM_FREQUENCY 100.0 // Hz
#define PWM_PERIOD (1.0 / PWM_FREQUENCY) // seconds
#define PWM_DUTY_CYCLE_MIN 0.0
#define PWM_DUTY_CYCLE_MAX 1.0

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *motor1_ena_line, *motor1_in1_line, *motor1_in2_line, *motor1_enc_a_line, *motor1_enc_b_line;
struct gpiod_line *motor2_enb_line, *motor2_in3_line, *motor2_in4_line, *motor2_enc_a_line, *motor2_enc_b_line;

volatile int motor1_encoder_count = 0;
volatile int motor2_encoder_count = 0;
pthread_mutex_t motor1_encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t motor2_encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void *encoder_monitor(void *arg);
double calculate_rpm(int encoder_count);
double pid_control(double target_rpm, double actual_rpm, double *integral, double *previous_error);
void set_motor_speed(int motor, double duty_cycle);
void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output);
void signal_handler(int sig);

int main() {
    pthread_t motor1_encoder_thread, motor2_encoder_thread;
    double motor1_integral = 0.0, motor1_previous_error = 0.0;
    double motor2_integral = 0.0, motor2_previous_error = 0.0;
    double motor1_rpm, motor2_rpm;
    double motor1_pid_output, motor2_pid_output;
    double motor1_p, motor1_i, motor1_d, motor2_p, motor2_i, motor2_d;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");
    fflush(log_file);

    // Create encoder monitoring threads
    if (pthread_create(&motor1_encoder_thread, NULL, encoder_monitor, (void *)(intptr_t)1) != 0) {
        perror("Error creating motor 1 encoder thread");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }
    if (pthread_create(&motor2_encoder_thread, NULL, encoder_monitor, (void *)(intptr_t)2) != 0) {
        perror("Error creating motor 2 encoder thread");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    // Main control loop
    while (program_running) {
        // Read encoder counts
        pthread_mutex_lock(&motor1_encoder_mutex);
        int motor1_encoder_count_local = motor1_encoder_count;
        motor1_encoder_count = 0; // Reset count
        pthread_mutex_unlock(&motor1_encoder_mutex);

        pthread_mutex_lock(&motor2_encoder_mutex);
        int motor2_encoder_count_local = motor2_encoder_count;
        motor2_encoder_count = 0; // Reset count
        pthread_mutex_unlock(&motor2_encoder_mutex);

        // Calculate RPM
        motor1_rpm = calculate_rpm(motor1_encoder_count_local);
        motor2_rpm = calculate_rpm(motor2_encoder_count_local);

        // PID control
        motor1_pid_output = pid_control(TARGET_RPM, motor1_rpm, &motor1_integral, &motor1_previous_error);
        motor2_pid_output = pid_control(TARGET_RPM, motor2_rpm, &motor2_integral, &motor2_previous_error);

        // Set motor speeds
        set_motor_speed(1, motor1_pid_output);
        set_motor_speed(2, motor2_pid_output);

        // Log data
        log_data(motor1_rpm, motor2_rpm, motor1_p, motor1_i, motor1_d, motor1_pid_output, motor2_p, motor2_i, motor2_d, motor2_pid_output);

        // Sleep for 100ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100ms
        nanosleep(&sleep_time, NULL);
    }

    // Join threads
    pthread_join(motor1_encoder_thread, NULL);
    pthread_join(motor2_encoder_thread, NULL);

    // Cleanup
    cleanup_gpio();
    fclose(log_file);

    return 0;
}

int initialize_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    motor1_ena_line = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1_line = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2_line = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor1_enc_a_line = gpiod_chip_get_line(chip, MOTOR1_ENC_A);
    motor1_enc_b_line = gpiod_chip_get_line(chip, MOTOR1_ENC_B);

    motor2_enb_line = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3_line = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4_line = gpiod_chip_get_line(chip, MOTOR2_IN4);
    motor2_enc_a_line = gpiod_chip_get_line(chip, MOTOR2_ENC_A);
    motor2_enc_b_line = gpiod_chip_get_line(chip, MOTOR2_ENC_B);

    if (!motor1_ena_line || !motor1_in1_line || !motor1_in2_line || !motor1_enc_a_line || !motor1_enc_b_line ||
        !motor2_enb_line || !motor2_in3_line || !motor2_in4_line || !motor2_enc_a_line || !motor2_enc_b_line) {
