#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 Initialization function
int mpr121_init() {
    int result;

    // Soft reset
    result = i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63);
    if (result != 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed (Error code: %d)\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Configuration register (enable all electrodes)
    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable electrodes 0-11
    if (result != 0) {
        fprintf(stderr, "Error: MPR121 electrode config failed (Error code: %d)\n", result);
        return -1;
    }

    // Set touch and release thresholds for all electrodes (example values)
    for (int i = 0; i < 12; i++) {
        result = i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30); // Touch threshold
        if (result != 0) {
            fprintf(stderr, "Error: MPR121 touch threshold write failed for electrode %d (Error code: %d)\n", i, result);
            return -1;
        }
        result = i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10); // Release threshold
        if (result != 0) {
            fprintf(stderr, "Error: MPR121 release threshold write failed for electrode %d (Error code: %d)\n", i, result);
            return -1;
        }
    }

    // Enable run mode
    result = i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C); // Enable electrodes 0-11
    if (result != 0) {
        fprintf(stderr, "Error: MPR121 electrode config failed (Error code: %d)\n", result);
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: MPR121 touch status read failed (Error code: %d)\n", result);
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
