#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO lines and log file
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int activate_valve(struct gpiod_line *valve_line, int duration_ms);
int deactivate_valve(struct gpiod_line *valve_line);
int log_event(const char *message);
void cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal %d, cleaning up and exiting...\n", signal);
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    struct gpiod_chip *chip;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line for Valve 1
    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("Error getting line for Valve 1");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line for Valve 2
    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("Error getting line for Valve 2");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        return -1;
    }

    // Request line for Valve 1 as output
    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        perror("Error requesting line for Valve 1 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    // Request line for Valve 2 as output
    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        perror("Error requesting line for Valve 2 as output");
        gpiod_chip_close(chip);
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to activate a valve for a specified duration
int activate_valve(struct gpiod_line *valve_line, int duration_ms) {
    if (!valve_line) {
        fprintf(stderr, "Error: Invalid valve line.\n");
        return -1;
    }

    if (gpiod_line_set_value(valve_line, 1) < 0) {
        perror("Error setting valve HIGH");
        return -1;
    }

    // Log the event
    char message[100];
    snprintf(message, sizeof(message), "Valve activated for %d ms", duration_ms);
    log_event(message);

    usleep(duration_ms * 1000); // Convert ms to microseconds

    return 0;
}

// Function to deactivate a valve
int deactivate_valve(struct gpiod_line *valve_line) {
    if (!valve_line) {
        fprintf(stderr, "Error: Invalid valve line.\n");
        return -1;
    }

    if (gpiod_line_set_value(valve_line, 0) < 0) {
        perror("Error setting valve LOW");
        return -1;
    }

    // Log the event
    log_event("Valve deactivated");

    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write timestamp and message to log file
    fprintf(log_file, "%s: %s\n", timestamp, message);

    // Close log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (valve1_line) {
        deactivate_valve(valve1_line);
        gpiod_line_release(valve1_line);
    }
    if (valve2_line) {
        deactivate_valve(valve2_line);
        gpiod_line_release(valve2_line);
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1 for 500 ms
        if (activate_valve(valve1_line, 500) < 0) {
            fprintf(stderr, "Error activating Valve 1. Continuing.\n");
        }

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2 for 1000 ms
        if (activate_valve(valve2_line, 1000) < 0) {
            fprintf(stderr, "Error activating Valve 2. Continuing.\n");
        }

        // Pause for 10 seconds
        sleep(10);
    }

    return 0;
}

