#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;
unsigned long last_event_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int unlock_door();
void log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to unlock the door
int unlock_door() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    return 0;
}

// Function to log events
void log_event(const char *event_type, int gpio_pin) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    char milliseconds[5];
    snprintf(milliseconds, sizeof(milliseconds), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s%s - %s - GPIO %d\n", timestamp, milliseconds, event_type, gpio_pin);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        unsigned long current_time = ts.tv_sec * 1000 + ts.tv_nsec / 1000000; // Milliseconds

        // Check for motion on sensor 1
        if (read_sensor(PIR_SENSOR_1) == 1) {
            if (current_time - last_event_time > RATE_LIMIT_MS) {
                log_event("Motion Detected", PIR_SENSOR_1);
                unlock_door();
                log_event("Door Unlocked", PIR_SENSOR_1);
                last_event_time = current_time;
            } else {
                log_event("Rate Limited", PIR_SENSOR_1);
            }
        }

        // Check for motion on sensor 2
        if (read_sensor(PIR_SENSOR_2) == 1) {
            if (current_time - last_event_time > RATE_LIMIT_MS) {
                log_event("Motion Detected", PIR_SENSOR_2);
                unlock_door();
                log_event("Door Unlocked", PIR_SENSOR_2);
                last_event_time = current_time;
            } else {
                log_event("Rate Limited", PIR_SENSOR_2);
            }
        }

        gpioDelay(50 * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

