#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the range of PWM duty cycles
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Define the range of step durations in milliseconds
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the range of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Global variable to indicate program shutdown
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    shutdown_flag = 1;
    fprintf(stderr, "\nCaught signal, shutting down...\n");
}

// Function to generate a random haptic feedback pattern
void generate_pattern(int *duty_cycles1, int *duty_cycles2, int *durations, int *num_steps) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number of steps between MIN_STEPS and MAX_STEPS
    *num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

    // Allocate memory for the duty cycles, durations, and number of steps
    duty_cycles1 = (int *)malloc(*num_steps * sizeof(int));
    duty_cycles2 = (int *)malloc(*num_steps * sizeof(int));
    durations = (int *)malloc(*num_steps * sizeof(int));

    if (duty_cycles1 == NULL || duty_cycles2 == NULL || durations == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for pattern.\n");
        // Handle memory allocation failure (e.g., exit or use default values)
        exit(EXIT_FAILURE);
    }

    // Generate random duty cycles and durations for each step
    for (int i = 0; i < *num_steps; i++) {
        duty_cycles1[i] = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        duty_cycles2[i] = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
        durations[i] = (rand() % (MAX_DURATION - MIN_DURATION + 1)) + MIN_DURATION;
    }
}

// Function to play the haptic feedback pattern
void play_pattern(int *duty_cycles1, int *duty_cycles2, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        // Set the PWM duty cycles for both motors
        gpioPWM(MOTOR1_GPIO, duty_cycles1[i]);
        gpioPWM(MOTOR2_GPIO, duty_cycles2[i]);

        // Delay for the specified duration
        gpioDelay(durations[i] * 1000); // Convert milliseconds to microseconds

        // Stop the motors after each step
        gpioPWM(MOTOR1_GPIO, 0);
        gpioPWM(MOTOR2_GPIO, 0);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to generate and play patterns indefinitely
    while (!shutdown_flag) {
        int *duty_cycles1 = NULL;
        int *duty_cycles2 = NULL;
        int *durations = NULL;
        int num_steps = 0;

        generate_pattern(duty_cycles1, duty_cycles2, durations, &num_steps);

        if (duty_cycles1 != NULL && duty_cycles2 != NULL && durations != NULL) {
            play_pattern(duty_cycles1, duty_cycles2, durations, num_steps);

            free(duty_cycles1);
            free(duty_cycles2);
            free(durations);
        }

        // Small delay between patterns
        gpioDelay(100000); // 100ms
    }

    // Stop the motors
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

