#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define CALIBRATION_THRESHOLD 10.0
#define TIMEOUT_US 500000 // 0.5 seconds

// Global variables
double scale_factor = 1.0;
double offset = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
double calibrate_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_weight(double weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read data from HX711 with timeout
int read_hx711() {
    int32_t data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 data pin timeout\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    data = data ^ 0x800000; // Invert the sign bit

    return data;
}

// Function to calibrate the HX711
double calibrate_hx711() {
    double sum = 0.0;
    int i;
    int raw_value;

    printf("Calibrating HX711... Please ensure no weight is applied.\n");
    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Calibration failed due to HX711 timeout.\n");
            return -1.0; // Indicate calibration failure
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %lf\n", offset);
    return offset;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > CALIBRATION_THRESHOLD) {
