    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        if (read_rain_sensor()) {
            close_window();
        }
        gpioDelay(60000000); // Check every 60 seconds (60 * 1000000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

