#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100.0

// Define solenoid activation duration (in seconds)
#define SOLENOID_DURATION 5

// Define HX711 read timeout (in milliseconds)
#define HX711_TIMEOUT 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Calibration factor (adjust this based on your setup)
static float calibration_factor = 1.0; // Initial value, needs calibration

// Function prototypes
int read_hx711();
float convert_to_grams(int raw_value);
void activate_solenoid();
void log_event(const char *event);
void signal_handler(int signal);
void calibrate_hx711();

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low (data ready)
    int timeout_counter = 0;
    while (gpioRead(HX711_DT) == 1 && timeout_counter < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to grams
float convert_to_grams(int raw_value) {
    return (float)raw_value / calibration_factor;
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(SOLENOID_DURATION * 1000); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

// Function to log events to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Deactivate solenoid
    gpioWrite(SOLENOID_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to calibrate the HX711
void calibrate_hx711() {
    float known_weight;
    int raw_value;

    printf("Calibration Mode\n");
    printf("Place a known weight on the load cell (in grams): ");
    if (scanf("%f", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return;
    }

    printf("Reading raw value from HX711...\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return;
    }

    calibration_factor = (float)raw_value / known_weight;
    printf("Calibration factor: %f\n", calibration_factor);
    printf("Calibration complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate the HX711
    calibrate_hx711();

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 value.\n");
            log_event("Error: Failed to read HX711 value.");
        } else {
            float weight = convert_to_grams(raw_value);
            printf("Weight: %.2f g\n", weight);

            if (weight < WEIGHT_THRESHOLD) {
                printf("Weight below threshold! Activating solenoid.\n");
                log_event("Weight below threshold. Activating solenoid.");
                activate_solenoid();
                log_event("Solenoid deactivated.");
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

