#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "relay_events.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
int toggle_relay(void);
int log_event(int relay_state);
void cleanup(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Received signal %d, terminating...\n", sig);
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Error getting sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request sensor line as input
    ret = gpiod_line_request(sensor_line, "obstacle_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        perror("Error requesting sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Error getting relay line");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request(relay_line, "relay_control", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting relay line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(sensor_line);
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        perror("Error reading sensor value");
        return -1;
    }
    return value;
}

// Toggle relay state
int toggle_relay(void) {
    int ret;

    relay_state = !relay_state; // Toggle the state

    ret = gpiod_line_set_value(relay_line, relay_state);
    if (ret < 0) {
        perror("Error setting relay value");
        return -1;
    }

    return 0;
}

// Log event to file
int log_event(int relay_state) {
    time_t now;
    struct tm timeinfo;
    char timestamp[32];

    // Get current time
    time(&now);
    localtime_r(&now, &timeinfo);

    // Format timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write log entry
    fprintf(log_file, "%s Relay state: %s\n", timestamp, relay_state ? "ON" : "OFF");

    // Close log file
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int sensor_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor value
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check for obstacle (sensor_value == 0)
        if (sensor_value == 0) {
            // Toggle relay
            if (toggle_relay() < 0) {
                fprintf(stderr, "Error toggling relay, retrying...\n");
                sleep(1); // Wait before retrying
                continue;
            }

            // Log event
            if (log_event(relay_state) < 0) {
                fprintf(stderr, "Error logging event.\n");
            }

            printf("Obstacle detected! Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Obstacle avoidance system stopped.\n");

    return EXIT_SUCCESS;
}

