#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    log_message("Signal received, shutting down...");
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: Configuration file is empty.\n");
        } else {
            perror("Error reading configuration file");
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid configuration file format.\n");
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid configuration file format (missing duration value).\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid duration value in configuration file.\n");
        return -1;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration value out of range (must be between 1 and 3600).\n");
        return -1;
    }

    return (int)duration;
}

// Function to initialize the GPIO line
int initialize_gpio(const char *chipname, int pin) {
    chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0; // No flags needed for output

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to sleep for a specified duration in seconds
void sleep_seconds(int seconds) {
    struct timespec req = {seconds, 0};
    while (nanosleep(&req, &req) == -1 && errno == EINTR && !terminate) {
        // Interrupted by signal, continue sleeping
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_message("Starting watering system...");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    int duration = read_watering_duration(CONFIG_FILE);
    if (duration < 0) {
        log_message("Failed to read watering duration, exiting.");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    char duration_str[20];
    snprintf(duration_str, sizeof(duration_str), "Watering duration: %d seconds", duration);
    log_message(duration_str);

    // Initialize GPIO
    if (initialize_gpio(GPIO_CHIP, GPIO_PIN) < 0) {
        log_message("Failed to initialize GPIO, exiting.");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Activate the valve
    if (set_gpio_value(line, 1) < 0) {
        log_message("Failed to activate valve, exiting.");
        cleanup_gpio(chip, line);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_message("Valve activated.");

    // Sleep for the specified duration
    sleep_seconds(duration);

    // Deactivate the valve
    if (set_gpio_value(line, 0) < 0) {
        log_message("Failed to deactivate valve, exiting.");
        cleanup_gpio(chip, line);
        fclose(log_file);
        return EXIT_FAILURE;
    }
    log_message("Valve deactivated.");

    // Cleanup GPIO resources
    cleanup_gpio(chip, line);

    log_message("Watering system stopped.");

    fclose(log_file);

    return EXIT_SUCCESS;
}

