void set_motor_speed(int forward_pin, int backward_pin, int speed) {
    if (speed > 0) {
        gpioPWM(forward_pin, speed);
        gpioWrite(backward_pin, 0); // Ensure backward pin is off
    } else if (speed < 0) {
        gpioPWM(backward_pin, -speed);
        gpioWrite(forward_pin, 0); // Ensure forward pin is off
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
