void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us): %d\n", pulse_width);
        return;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to lock the door
void lock_door() {
    set_servo_pulse_width(LOCKED_PULSE_WIDTH);
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    set_servo_pulse_width(UNLOCKED_PULSE_WIDTH);
    printf("Door unlocked.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors (if needed, depends on your wiring)
    // gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    // gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            lock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (in microseconds)
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            unlock_door();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (in microseconds)
        }

        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

