#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>
#include <gpiod.h>

// Configuration structure
typedef struct {
    char *mode;
    char *zmq_endpoint;
    int led_gpio;
    int sound_sensor_gpio;
    int udp_port;
    char *udp_address;
} Config;

// Global variables (minimize usage)
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *sound_sensor_line = NULL;
static void *zmq_context = NULL;
static void *zmq_socket = NULL;

// Default configuration values
static Config config = {
    .mode = "sound_sensor",
    .zmq_endpoint = "tcp://*:5555",
    .led_gpio = 27,
    .sound_sensor_gpio = 17,
    .udp_port = 5556,
    .udp_address = "127.0.0.1"
};

// Function prototypes
void signal_handler(int sig);
int parse_arguments(int argc, char *argv[]);
int initialize_gpio(int gpio_pin, struct gpiod_line **line, const char *consumer);
int initialize_zmq_publisher(const char *endpoint);
int initialize_zmq_subscriber(const char *endpoint);
int publish_alert(const char *message);
int subscribe_alerts(void (*callback)(const char *));
void alarm_callback(const char *message);
void sound_sensor_callback(const char *message);
int initialize_udp_server(int port);
int initialize_udp_client(const char *address, int port);
int send_udp_message(int sockfd, const char *message);
int receive_udp_message(int sockfd, char *buffer, size_t buffer_size);
void cleanup(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Parse command-line arguments
int parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "m:z:l:s:u:a:")) != -1) {
        switch (opt) {
            case 'm':
                config.mode = optarg;
                break;
            case 'z':
                config.zmq_endpoint = optarg;
                break;
            case 'l':
                config.led_gpio = atoi(optarg);
                break;
            case 's':
                config.sound_sensor_gpio = atoi(optarg);
                break;
            case 'u':
                config.udp_port = atoi(optarg);
                break;
            case 'a':
                config.udp_address = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-m mode] [-z zmq_endpoint] [-l led_gpio] [-s sound_sensor_gpio] [-u udp_port] [-a udp_address]\n", argv[0]);
                return 1;
        }
    }
    return 0;
}

// Initialize GPIO line
int initialize_gpio(int gpio_pin, struct gpiod_line **line, const char *consumer) {
    char chipname[20];
    snprintf(chipname, sizeof(chipname), "gpiochip0"); // Assuming GPIO chip 0

    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!*line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = consumer;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(*line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Initialize ZeroMQ publisher
int initialize_zmq_publisher(const char *endpoint) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    if (zmq_bind(zmq_socket, endpoint) < 0) {
        perror("zmq_bind");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Initialize ZeroMQ subscriber
int initialize_zmq_subscriber(const char *endpoint) {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_SUB);
    if (!zmq_socket) {
        perror("zmq_socket");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    if (zmq_connect(zmq_socket, endpoint) < 0) {
        perror("zmq_connect");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    if (zmq_setsockopt(zmq_socket, ZMQ_SUBSCRIBE, "SOUND_ALERTS", strlen("SOUND_ALERTS")) < 0) {
        perror("zmq_setsockopt");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Publish alert message
int publish_alert(const char *message) {
    zmq_msg_t topic_msg, content_msg;
    int rc;

    rc = zmq_msg_init_size(&topic_msg, strlen("SOUND_ALERTS"));
    if (rc != 0) {
        perror("zmq_msg_init_size (topic)");
        return -1;
    }
    memcpy(zmq_msg_data(&topic_msg), "SOUND_ALERTS", strlen("SOUND_ALERTS"));

    rc = zmq_msg_init_size(&content_msg, strlen(message));
    if (rc != 0) {
        perror("zmq_msg_init_size (content)");
        zmq_msg_close(&topic_msg);
        return -1;
    }
    memcpy(zmq_msg_data(&content_msg), message, strlen(message));

    rc = zmq_msg_send(&topic_msg, zmq_socket, ZMQ_SNDMORE);
    if (rc == -1) {
        perror("zmq_msg_send (topic)");
        zmq_msg_close(&topic_msg);
        zmq_msg_close(&content_msg);
        return -1;
    }

    rc = zmq_msg_send(&content_msg, zmq_socket, 0);
    if (rc == -1) {
        perror("zmq_msg_send (content)");
        zmq_msg_close(&content_msg);
        return -1;
    }

    zmq_msg_close(&topic_msg);
    zmq_msg_close(&content_msg);

    return 0;
}

// Subscribe to alerts and call callback function
int subscribe_alerts(void (*callback)(const char *)) {
    zmq_msg_t topic_msg, content_msg;
    int rc;
    char buffer[256];

    while (!terminate) {
        rc = zmq_msg_init(&topic_msg);
        if (rc != 0) {
            perror("zmq_msg_init (topic)");
            break;
        }

        rc = zmq_msg_recv(&topic_msg, zmq_socket, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                zmq_msg_close(&topic_msg);
                break;
            }
            perror("zmq_msg_recv (topic)");
            zmq_msg_close(&topic_msg);
            break;
        }

        if (strncmp(zmq_msg_data(&topic_msg), "SOUND_ALERTS", zmq_msg_size(&topic_msg)) != 0) {
            zmq_msg_close(&topic_msg);
            continue;
        }

        rc = zmq_msg_init(&content_msg);
        if (rc != 0) {
            perror("zmq_msg_init (content)");
            zmq_msg_close(&topic_msg);
            break;
        }

        rc = zmq_msg_recv(&content_msg, zmq_socket, 0);
        if (rc == -1) {
            if (errno == EINTR) {
                zmq_msg_close(&topic_msg);
                zmq_msg_close(&content_msg);
                break;
            }
            perror("zmq_msg_recv (content)");
            zmq_msg_close(&topic_msg);
            zmq_msg_close(&content_msg);
            break;
        }

        strncpy(buffer, zmq_msg_data(&content_msg), sizeof(buffer) - 1);
        buffer[sizeof(buffer) - 1] = '\0';

        zmq_msg_close(&topic_msg);
        zmq_msg_close(&content_msg);

        callback(buffer);
    }

    return 0;
}

// Alarm callback function
void alarm_callback(const char *message) {
    printf("Alarm triggered: %s\n", message);
    if (led_line) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value (on)");
        }
        usleep(1000000); // 1 second
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value (off)");
        }
    }
}

// Sound sensor callback function
void sound_sensor_callback(const char *message) {
    printf("Sound alert received: %s\n", message);
    // In a real distributed system, this would trigger the alarm node
    // by sending a message to the alarm node.
    // For this example, we'll just print a message.
    printf("Simulating alarm trigger due to sound alert.\n");
}

// Initialize UDP server
int initialize_udp_server(int port) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = INADDR_ANY;
    servaddr.sin_port = htons(port);

    if (bind(sockfd, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Initialize UDP client
int initialize_udp_client(const char *address, int port) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, address, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Send UDP message
int send_udp_message(int sockfd, const char *message) {
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(config.udp_port);
    if (inet_pton(AF_INET, config.udp_address, &servaddr.sin_addr) <= 0) {
        perror("inet_pton");
        return -1;
    }

    if (sendto(sockfd, message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto");
        return -1;
    }

    return 0;
}

// Receive UDP message
int receive_udp_message(int sockfd, char *buffer, size_t buffer_size) {
    struct sockaddr_in cliaddr;
    socklen_t len = sizeof(cliaddr);
    ssize_t n = recvfrom(sockfd, buffer, buffer_size - 1, 0, (struct sockaddr *)&cliaddr, &len);
    if (n < 0) {
        if (errno == EINTR) return -1; // Interrupted by signal
        perror("recvfrom");
        return -1;
    }
    buffer[n] = '\0';
    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }
}

int main(int argc, char *argv[]) {
    if (parse_arguments(argc, argv) != 0) {
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (strcmp(config.mode, "sound_sensor") == 0) {
        printf("Running in sound_sensor mode\n");

        if (initialize_gpio(config.sound_sensor_gpio, &sound_sensor_line, "sound_sensor") != 0) {
            fprintf(stderr, "Failed to initialize sound sensor GPIO\n");
            return 1;
        }

        if (initialize_zmq_publisher(config.zmq_endpoint) != 0) {
            fprintf(stderr, "Failed to initialize ZeroMQ publisher\n");
            cleanup();
            return 1;
        }

        int udp_sockfd = initialize_udp_server(config.udp_port);
        if (udp_sockfd < 0) {
            fprintf(stderr, "Failed to initialize UDP server\n");
            cleanup();
            return 1;
        }

        char udp_buffer[256];

        while (!terminate) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value < 0) {
                perror("gpiod_line_get_value");
                break;
            }

            if (value == 0) { // Sound detected (active low)
                time_t now = time(NULL);
                char message[64];
                snprintf(message, sizeof(message), "Sound detected at %ld", now);
                printf("Sound detected, publishing alert: %s\n", message);

                if (publish_alert(message) != 0) {
                    fprintf(stderr, "Failed to publish alert\n");
                    break;
                }

                // Send UDP message to alarm node
                if (send_udp_message(udp_sockfd, message) != 0) {
                    fprintf(stderr, "Failed to send UDP message\n");
                    break;
                }

                usleep(100000); // Debounce
            }

            // Receive UDP messages (if any)
            if (receive_udp_message(udp_sockfd, udp_buffer, sizeof(udp_buffer)) == 0) {
                printf("Received UDP message: %s\n", udp_buffer);
            }

            usleep(10000); // Poll every 10ms
        }

        close(udp_sockfd);

    } else if (strcmp(config.mode, "alarm_node") == 0) {
        printf("Running in alarm_node mode\n");

        if (initialize_gpio(config.led_gpio, &led_line, "alarm_node") != 0) {
            fprintf(stderr, "Failed to initialize LED GPIO\n");
            return 1;
        }

        if (initialize_zmq_subscriber(config.zmq_endpoint) != 0) {
            fprintf(stderr, "Failed to initialize ZeroMQ subscriber\n");
            cleanup();
            return 1;
        }

        int udp_sockfd = initialize_udp_client(config.udp_address, config.udp_port);
        if (udp_sockfd < 0) {
            fprintf(stderr, "Failed to initialize UDP client\n");
            cleanup();
            return 1;
        }

        char udp_buffer[256];

        while (!terminate) {
            // Receive UDP messages (if any)
            if (receive_udp_message(udp_sockfd, udp_buffer, sizeof(udp_buffer)) == 0) {
                printf("Received UDP message: %s\n", udp_buffer);
                alarm_callback(udp_buffer);
            }

            subscribe_alerts(alarm_callback);
        }

        close(udp_sockfd);

    } else {
        fprintf(stderr, "Invalid mode: %s\n", config.mode);
        return 1;
    }

    cleanup();
    printf("Exiting cleanly\n");
    return 0;
}

