#include <pigpio.h>
#include <MQTTClient.h>

#define GPIO_PIN 17
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_ir_decoder"
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100

// NEC timing constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_0 560
#define NEC_BIT_SPACE_1 1690

// Global variables
static volatile int running = 1;
static MQTTClient mqtt_client;
static int pulse_buffer[PULSE_BUFFER_SIZE];
static int pulse_count = 0;
static unsigned int last_tick = 0;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_mqtt();
void cleanup();
void alert_callback(int gpio, int level, unsigned int tick);
int decode_nec(int *pulse_buffer, int pulse_count, unsigned int *address, unsigned int *command);
int publish_mqtt(unsigned int address, unsigned int command);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFunc(GPIO_PIN, alert_callback);

    log_message(LOG_INFO, "GPIO initialized");
    return 0;
}

// Initialize MQTT client
int init_mqtt() {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(mqtt_client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        return -1;
    }

    log_message(LOG_INFO, "MQTT initialized");
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");

    // Disconnect from MQTT broker
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);

    // Terminate pigpio
    gpioTerminate();

    log_message(LOG_INFO, "Cleanup complete");
    closelog();
}

// Callback function for GPIO alerts
void alert_callback(int gpio, int level, unsigned int tick) {
    if (level == 0) { // Falling edge
        unsigned int pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            log_message(LOG_WARNING, "Pulse buffer overflow");
        }
    }
}

// Decode NEC IR signal
int decode_nec(int *pulse_buffer, int pulse_count, unsigned int *address, unsigned int *command) {
    if (pulse_count < 68) {
        log_message(LOG_WARNING, "Not enough pulses for a complete NEC frame");
        return -1;
    }

    // Validate header
    if (pulse_buffer[0] < NEC_HEADER_MARK * 0.8 || pulse_buffer[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_buffer[1] < NEC_HEADER_SPACE * 0.8 || pulse_buffer[1] > NEC_HEADER_SPACE * 1.2) {
        log_message(LOG_WARNING, "Invalid NEC header");
        return -1;
    }

    unsigned int addr = 0;
    unsigned int cmd = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        addr <<= 1;
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_WARNING, "Invalid bit mark");
            return -1;
        }
        if (pulse_buffer[2 * i + 1] > NEC_BIT_SPACE_0 * 0.8 && pulse_buffer[2 * i + 1] < NEC_BIT_SPACE_0 * 1.2) {
            // Logic 0
        } else if (pulse_buffer[2 * i + 1] > NEC_BIT_SPACE_1 * 0.8 && pulse_buffer[2 * i + 1] < NEC_BIT_SPACE_1 * 1.2) {
            // Logic 1
            addr |= 1;
        } else {
            log_message(LOG_WARNING, "Invalid bit space");
            return -1;
        }
    }

    // Decode command (8 bits)
    for (int i = 10; i < 18; i++) {
        cmd <<= 1;
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_WARNING, "Invalid bit mark");
            return -1;
        }
        if (pulse_buffer[2 * i + 1] > NEC_BIT_SPACE_0 * 0.8 && pulse_buffer[2 * i + 1] < NEC_BIT_SPACE_0 * 1.2) {
            // Logic 0
        } else if (pulse_buffer[2 * i + 1] > NEC_BIT_SPACE_1 * 0.8 && pulse_buffer[2 * i + 1] < NEC_BIT_SPACE_1 * 1.2) {
            // Logic 1
            cmd |= 1;
        } else {
            log_message(LOG_WARNING, "Invalid bit space");
            return -1;
        }
    }

    // Checksum validation (command == ~address)
    if ((cmd & 0xFF) != (~((cmd >> 8) & 0xFF) & 0xFF)) {
        log_message(LOG_WARNING, "Checksum validation failed");
        return -1;
    }

    *address = addr;
    *command = cmd;

    return 0;
}

// Publish decoded command to MQTT broker
int publish_mqtt(unsigned int address, unsigned int command) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\": %u, \"command\": %u}", address, command);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish message");
        return -1;
    }

    log_message(LOG_INFO, "Message published");
    return 0;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        // Process received pulses
        if (pulse_count > 0) {
            unsigned int address, command;
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                log_message(LOG_INFO, "Decoded NEC frame");
                char log_msg[100];
                snprintf(log_msg, sizeof(log_msg), "Address: %u, Command: %u", address, command);
                log_message(LOG_INFO, log_msg);

                if (publish_mqtt(address, command) != 0) {
                    log_message(LOG_ERR, "Failed to publish MQTT message");
                }
            } else {
                log_message(LOG_WARNING, "NEC decoding failed");
            }
            pulse_count = 0; // Reset pulse count after processing
        }

        // Service MQTT network loop
        MQTTClient_yield();

        // Sleep for a short interval
        usleep(10000); // 10ms
    }

    // Cleanup resources
    cleanup();

    return 0;
}

