#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read light level from a BH1750 sensor
float read_bh1750(int fd, int address) {
    unsigned char data[2];
    int retries = 3;

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Write the One-Time High-Resolution Mode command
    unsigned char mode = 0x20;
    if (write(fd, &mode, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Wait for conversion (at least 180ms)
    usleep(180000);

    // Read the 2-byte data
    while (retries > 0) {
        if (read(fd, data, 2) == 2) {
            // Convert the data to lux
            unsigned int raw_value = (data[0] << 8) | data[1];
            float lux = (float)raw_value / 1.2;
            return lux;
        } else {
            fprintf(stderr, "Error reading from I2C device 0x%02x, retrying... (%d retries left): %s\n", address, retries, strerror(errno));
            retries--;
            usleep(10000); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read from I2C device 0x%02x after multiple retries.\n", address);
    return NAN;
}

// Function to format the sensor data into a string
char* format_data(float lux_values[], int num_sensors) {
    char *buffer = malloc(256); // Allocate memory for the buffer
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for data buffer.\n");
        return NULL;
    }
    buffer[0] = '\0'; // Initialize as an empty string

    for (int i = 0; i < num_sensors; i++) {
        char sensor_data[64];
        snprintf(sensor_data, sizeof(sensor_data), "%d,%.2f", i + 1, lux_values[i]);
        strcat(buffer, sensor_data);
        if (i < num_sensors - 1) {
            strcat(buffer, ";");
        }
    }

    return buffer;
}

// Function to send the data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    int ttl = 1; // Time-to-live for multicast packets

    // Create a UDP socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set the TTL for multicast packets
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure the destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send the data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close the socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float lux_values[NUM_SENSORS];
    char *data_string;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read light levels from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_bh1750(i2c_fd, sensor_addresses[i]);
        }

        // Format the data
        data_string = format_data(lux_values, NUM_SENSORS);
        if (data_string == NULL) {
            fprintf(stderr, "Error formatting data, skipping UDP send.\n");
            continue; // Skip UDP send if formatting fails
        }

        // Send the data via UDP multicast
        if (send_udp_multicast(data_string) < 0) {
            fprintf(stderr, "Error sending UDP multicast packet.\n");
        }

        free(data_string); // Free the allocated memory

        // Wait for 1 second
        sleep(1);
    }

    // Close the I2C bus
    close(i2c_fd);

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

