#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int i2c_read_data(int fd, uint16_t *data);
float convert_to_slpm(uint16_t raw_value);
int log_data(FILE *fp, float flow_rate);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        stop_flag = 1;
    }
}

// I2C read data function with retry logic
int i2c_read_data(int fd, uint16_t *data) {
    int retries = RETRY_COUNT;
    int bytes_read;
    unsigned char buf[2];

    while (retries > 0) {
        bytes_read = read(fd, buf, 2);
        if (bytes_read == 2) {
            *data = (buf[0] << 8) | buf[1];
            *data &= 0x3FFF; // Mask to 14 bits
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", RETRY_COUNT - retries + 1, strerror(errno));
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent.\n");
                return -1; // Sensor absent
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error.\n");
                return -2; // I2C bus error
            }
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -3; // Max retries reached
}

// Convert raw value to SLPM
float convert_to_slpm(uint16_t raw_value) {
    return (raw_value - 3277) * 0.1;
}

// Log data to file
int log_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f SLPM\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    uint16_t raw_value;
    float flow_rate;

    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Read data from sensor
        if (i2c_read_data(i2c_fd, &raw_value) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_value);

            // Log data
            if (log_data(log_file, flow_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1); // Sample every second
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

