int i2c_read_data(int fd, uint16_t *data) {
    int retries = RETRY_COUNT;
    int bytes_read;
    unsigned char buf[2];

    while (retries > 0) {
        bytes_read = read(fd, buf, 2);
        if (bytes_read == 2) {
            *data = (buf[0] << 8) | buf[1];
            *data &= 0x3FFF; // Mask to 14 bits
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", RETRY_COUNT - retries + 1, strerror(errno));
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent.\n");
                return -1; // Sensor absent
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error.\n");
                return -2; // I2C bus error
            }
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -3; // Max retries reached
}

// Convert raw value to SLPM
float convert_to_slpm(uint16_t raw_value) {
    return (raw_value - 3277) * 0.1;
}

