        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!stop_flag) {
        // Read data from sensor
        if (i2c_read_data(i2c_fd, &raw_value) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_value);

            // Log data
            if (log_data(log_file, flow_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(1); // Sample every second
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

