#define DEFAULT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_LOG "seismic_error.log"
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_REG 0x28
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static char *error_filename = DEFAULT_ERROR_LOG;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t data);
int16_t convert_to_g(int16_t raw);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
int log_error(FILE *fp, const char *message);
void signal_handler(int sig);
int setup_i2c(int address);
int setup_files(const char *data_filename, const char *error_filename);
void cleanup(void);

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
            log_error(error_file, "Failed to acquire bus access and/or talk to slave.");
            return -1;
        }

        result = write(fd, &reg, 1);
        if (result != 1) {
            log_error(error_file, "Failed to write register address.");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            log_error(error_file, "Failed to read data.");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    log_error(error_file, "I2C read failed after multiple retries.");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t data) {
    int retries = RETRY_COUNT;
    uint8_t buf[2];
    int result;

    buf[0] = reg;
    buf[1] = data;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, i2c_address) < 0) {
            log_error(error_file, "Failed to acquire bus access and/or talk to slave.");
            return -1;
        }

        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            log_error(error_file, "Failed to write data.");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
        }
    }

    log_error(error_file, "I2C write failed after multiple retries.");
    return -1; // Failure
}

// Convert raw data to g
int16_t convert_to_g(int16_t raw) {
    return (int16_t)(raw * 0.000244);
}

// Log data to CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        log_error(error_file, "Failed to write data to file.");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Log errors to error log file
int log_error(FILE *fp, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "%s: %s (errno: %d)\n", timestamp, message, errno) < 0) {
        perror("Failed to write error to file");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Setup I2C communication
int setup_i2c(int address) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    i2c_address = address;
    return 0;
}

// Setup data and error log files
int setup_files(const char *data_filename, const char *error_filename) {
    data_file = fopen(data_filename, "a");
    if (data_file == NULL) {
        perror("Failed to open data file");
        return -1;
    }

    error_file = fopen(error_filename, "a");
    if (error_file == NULL) {
        perror("Failed to open error file");
        fclose(data_file);
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:e:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            case 'e':
                error_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename] [-e error_filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup I2C
    if (setup_i2c(i2c_address) < 0) {
        return EXIT_FAILURE;
    }

    // Setup files
    if (setup_files(filename, error_filename) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        uint8_t raw_data[6];
        int16_t x_raw, y_raw, z_raw;
        int16_t x_g, y_g, z_g;

        // Read data from sensor
        if (i2c_read_bytes(i2c_fd, ACCEL_REG, raw_data, 6) == 0) {
            // Combine high and low bytes
            x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
            y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
            z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

            // Convert to g
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);

            // Log data
            if (log_data(data_file, x_g, y_g, z_g) != 0) {
                log_error(error_file, "Failed to log data.");
            }
        } else {
            log_error(error_file, "Failed to read sensor data.");
        }

        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

