#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define LUX_CONVERSION_FACTOR 1.2

int i2c_fd = -1;
int udp_socket = -1;

// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    uint8_t power_on_cmd = 0x01;
    uint8_t continuous_high_res_mode_cmd = 0x10;

    if (write(fd, &power_on_cmd, 1) != 1) {
        perror("Failed to write power-on command");
        return -1;
    }
    usleep(10000); // Small delay after power-on

    if (write(fd, &continuous_high_res_mode_cmd, 1) != 1) {
        perror("Failed to write continuous high-resolution mode command");
        return -1;
    }
    usleep(10000); // Small delay after mode setting

    return 0;
}

// Function to read the raw light value from the BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read light value");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / LUX_CONVERSION_FACTOR;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char message[32];

    snprintf(message, sizeof(message), "%.2f", lux_value);

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Failed to send UDP multicast");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

int main() {
    uint16_t raw_value;
    float lux_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Retrying in 1 second.\n");
        close(i2c_fd);
        sleep(1);
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            return 1;
        }
        if (init_bh1750(i2c_fd) < 0) {
            fprintf(stderr, "Failed to initialize BH1750 sensor after retry. Exiting.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        // Read light value
        if (read_bh1750(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Failed to read light value. Retrying in 1 second.\n");
            close(i2c_fd);
            sleep(1);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                return 1;
            }
            if (init_bh1750(i2c_fd) < 0) {
                fprintf(stderr, "Failed to initialize BH1750 sensor after retry. Exiting.\n");
                close(i2c_fd);
                close(udp_socket);
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_value);

        // Send over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

