    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Retrying in 1 second.\n");
        close(i2c_fd);
        sleep(1);
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C bus");
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            return 1;
        }
        if (init_bh1750(i2c_fd) < 0) {
            fprintf(stderr, "Failed to initialize BH1750 sensor after retry. Exiting.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        // Read light value
        if (read_bh1750(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Failed to read light value. Retrying in 1 second.\n");
            close(i2c_fd);
            sleep(1);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                return 1;
            }
            if (init_bh1750(i2c_fd) < 0) {
                fprintf(stderr, "Failed to initialize BH1750 sensor after retry. Exiting.\n");
                close(i2c_fd);
                close(udp_socket);
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_value);

        // Send over UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

