#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600

// Define magic word for synchronization
#define MAGIC_WORD_SIZE 8
const unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

// Define TLV header structure
typedef struct {
    unsigned short type;
    unsigned short length;
} tlv_header_t;

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_uart();
void close_uart();
int find_magic_word(unsigned char *buffer, int buffer_size);
int parse_tlv_stream(unsigned char *buffer, int buffer_size);
int extract_object_data(unsigned char *tlv_data, int tlv_length, int object_index, float *range, float *velocity);
int write_data_to_csv(time_t timestamp, int object_index, float range, float velocity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Close UART
void close_uart() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
}

// Find magic word in the buffer
int find_magic_word(unsigned char *buffer, int buffer_size) {
    if (buffer_size < MAGIC_WORD_SIZE) {
        return -1; // Not enough data to find magic word
    }

    for (int i = 0; i <= buffer_size - MAGIC_WORD_SIZE; i++) {
        if (memcmp(buffer + i, magic_word, MAGIC_WORD_SIZE) == 0) {
            return i; // Magic word found at index i
        }
    }

    return -1; // Magic word not found
}

// Parse TLV stream
int parse_tlv_stream(unsigned char *buffer, int buffer_size) {
    int offset = 0;
    while (offset < buffer_size - sizeof(tlv_header_t)) {
        tlv_header_t *header = (tlv_header_t *)(buffer + offset);
        unsigned short type = header->type;
        unsigned short length = header->length;

        if (offset + sizeof(tlv_header_t) + length > buffer_size) {
            fprintf(stderr, "TLV length exceeds buffer size, skipping frame.\n");
            return -1; // Malformed TLV
        }

        if (type == 6) { // Example TLV type for detected objects
            for (int i = 0; i < length / 16; i++) { // Assuming each object is 16 bytes
                float range, velocity;
                if (extract_object_data(buffer + offset + sizeof(tlv_header_t) + i * 16, length, i, &range, &velocity) == 0) {
                    time_t now = time(NULL);
                    write_data_to_csv(now, i, range, velocity);
                }
            }
        }

        offset += sizeof(tlv_header_t) + length;
    }
    return 0;
}

// Extract object data from TLV data
int extract_object_data(unsigned char *tlv_data, int tlv_length, int object_index, float *range, float *velocity) {
    // Example: Assuming range is at offset 0 (4 bytes) and velocity at offset 8 (4 bytes)
    if (tlv_length < 16) {
        fprintf(stderr, "TLV data too short to extract object data.\n");
        return -1;
    }

    memcpy(range, tlv_data, sizeof(float));
    memcpy(velocity, tlv_data + 8, sizeof(float));

    // Basic validation (example)
    if (*range < 0 || *range > 100) { // Range should be between 0 and 100 meters
        fprintf(stderr, "Invalid range value: %f\n", *range);
        return -1;
    }
    if (*velocity < -10 || *velocity > 10) { // Velocity should be between -10 and 10 m/s
        fprintf(stderr, "Invalid velocity value: %f\n", *velocity);
        return -1;
    }

    return 0;
}

// Write data to CSV file
int write_data_to_csv(time_t timestamp, int object_index, float range, float velocity) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%.2f,%.2f\n", timestamp_str, object_index, range, velocity);
    fflush(csv_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        close_uart();
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    unsigned char buffer[4096]; // Buffer for UART data
    int buffer_index = 0;

    // Main loop
    while (!terminate) {
        int bytes_available = serDataAvailable(uart_handle);
        if (bytes_available > 0) {
            int bytes_to_read = (bytes_available > sizeof(buffer) - buffer_index) ? sizeof(buffer) - buffer_index : bytes_available;
            int bytes_read = serRead(uart_handle, buffer + buffer_index, bytes_to_read);

            if (bytes_read > 0) {
                buffer_index += bytes_read;

                // Find magic word
                int magic_word_index = find_magic_word(buffer, buffer_index);
                if (magic_word_index != -1) {
                    // Parse TLV stream starting from the magic word
                    parse_tlv_stream(buffer + magic_word_index, buffer_index - magic_word_index);

                    // Shift the remaining data to the beginning of the buffer
                    memmove(buffer, buffer + magic_word_index + MAGIC_WORD_SIZE, buffer_index - magic_word_index - MAGIC_WORD_SIZE);
                    buffer_index = buffer_index - magic_word_index - MAGIC_WORD_SIZE;
                } else {
                    // No magic word found, continue reading
                }
            } else {
                fprintf(stderr, "Error reading from UART\n");
                break;
            }
        } else {
            // No data available, sleep for a short time
            gpioDelay(1000); // 1 ms
        }
    }

    // Cleanup
    close_uart();
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

