#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUFFER_SIZE 256
#define INTER_BYTE_TIMEOUT_MS 500
#define SELECT_TIMEOUT_SEC 2

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = INTER_BYTE_TIMEOUT_MS / 100; // Timeout in deciseconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_radar_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int retval;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = SELECT_TIMEOUT_SEC;
    timeout.tv_usec = 0;

    retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() error");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("read() error");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

int parse_radar_data(const char *line, time_t *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token != NULL) {
        *timestamp = (time_t)strtol(token, NULL, 10);
        token = strtok(NULL, ",");
        if (token != NULL) {
            *range = strtof(token, NULL);
            free(line_copy);
            return 0;
        } else {
            fprintf(stderr, "Error: Missing range value\n");
            free(line_copy);
            return -1;
        }
    } else {
        fprintf(stderr, "Error: Missing timestamp\n");
        free(line_copy);
        return -1;
    }
}

void log_radar_data(time_t timestamp, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    char line_buffer[LINE_BUFFER_SIZE];
    size_t line_buffer_index = 0;
    time_t timestamp;
    float range;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open() failed");
        return EXIT_FAILURE;
    }

    // Configure the UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_radar_data(uart_fd, line_buffer + line_buffer_index, LINE_BUFFER_SIZE - line_buffer_index);
        if (bytes_read > 0) {
            line_buffer_index += bytes_read;

            // Check for newline character in the buffer
            char *newline_ptr = strchr(line_buffer, '\n');
            if (newline_ptr != NULL) {
                *newline_ptr = '\0'; // Null-terminate the line

                // Parse the radar data
                if (parse_radar_data(line_buffer, &timestamp, &range) == 0) {
                    // Log the radar data
                    log_radar_data(timestamp, range);
                }

                // Reset the line buffer index
                line_buffer_index = newline_ptr - line_buffer + 1; // Move index past newline
                memmove(line_buffer, newline_ptr + 1, LINE_BUFFER_SIZE - line_buffer_index); // Shift remaining data to beginning
                line_buffer[LINE_BUFFER_SIZE - line_buffer_index] = '\0'; // Null terminate
            } else if (line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                fprintf(stderr, "Error: Line buffer overflow\n");
                line_buffer_index = 0; // Reset buffer to avoid further overflow
                line_buffer[0] = '\0';
            }
        } else if (bytes_read < 0) {
            // Handle read error, but continue running
            fprintf(stderr, "Error reading from UART, continuing...\n");
        }
    }

    // Close the UART device
    close(uart_fd);

    printf("Radar data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

