        }
    }
}

int parse_radar_data(const char *line, time_t *timestamp, float *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token != NULL) {
        *timestamp = (time_t)strtol(token, NULL, 10);
        token = strtok(NULL, ",");
        if (token != NULL) {
            *range = strtof(token, NULL);
            free(line_copy);
            return 0;
        } else {
            fprintf(stderr, "Error: Missing range value\n");
            free(line_copy);
            return -1;
        }
    } else {
        fprintf(stderr, "Error: Missing timestamp\n");
        free(line_copy);
        return -1;
    }
}

void log_radar_data(time_t timestamp, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    char line_buffer[LINE_BUFFER_SIZE];
    size_t line_buffer_index = 0;
    time_t timestamp;
    float range;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the UART device
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open() failed");
        return EXIT_FAILURE;
    }

    // Configure the UART
    if (configure_uart(uart_fd) != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("Radar data acquisition started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int bytes_read = read_radar_data(uart_fd, line_buffer + line_buffer_index, LINE_BUFFER_SIZE - line_buffer_index);
        if (bytes_read > 0) {
            line_buffer_index += bytes_read;

            // Check for newline character in the buffer
            char *newline_ptr = strchr(line_buffer, '\n');
            if (newline_ptr != NULL) {
                *newline_ptr = '\0'; // Null-terminate the line

                // Parse the radar data
                if (parse_radar_data(line_buffer, &timestamp, &range) == 0) {
                    // Log the radar data
                    log_radar_data(timestamp, range);
                }

                // Reset the line buffer index
                line_buffer_index = newline_ptr - line_buffer + 1; // Move index past newline
                memmove(line_buffer, newline_ptr + 1, LINE_BUFFER_SIZE - line_buffer_index); // Shift remaining data to beginning
                line_buffer[LINE_BUFFER_SIZE - line_buffer_index] = '\0'; // Null terminate
            } else if (line_buffer_index >= LINE_BUFFER_SIZE - 1) {
                fprintf(stderr, "Error: Line buffer overflow\n");
                line_buffer_index = 0; // Reset buffer to avoid further overflow
                line_buffer[0] = '\0';
            }
        } else if (bytes_read < 0) {
            // Handle read error, but continue running
            fprintf(stderr, "Error reading from UART, continuing...\n");
        }
    }

    // Close the UART device
    close(uart_fd);

    printf("Radar data acquisition stopped.\n");

    return EXIT_SUCCESS;
}

