#include <termios.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variable for the serial port file descriptor
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop();
void signal_handler(int signal);
int setup_serial_port();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the serial port if it's open
    if (serial_fd != -1) {
        close(serial_fd);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send an emergency stop message over the serial port
void emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));

    if (bytes_written < 0) {
        perror("Error writing to serial port");
    }
}

// Function to set up the serial port
int setup_serial_port() {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios options;
    tcgetattr(serial_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);

    options.c_cflag &= ~PARENB; // No parity
    options.c_cflag &= ~CSTOPB; // 1 stop bit
    options.c_cflag &= ~CSIZE;  // Clear size bits
    options.c_cflag |= CS8;   // 8 data bits
    options.c_cflag &= ~CRTSCTS; // Disable hardware flow control

    options.c_cflag |= CREAD | CLOCAL; // Enable read and ignore control lines

    options.c_iflag &= ~(IXON | IXOFF | IXANY); // Disable software flow control
    options.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    options.c_oflag &= ~OPOST; // Raw output

    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode

    tcsetattr(serial_fd, TCSANOW, &options);

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Set up the serial port
    if (setup_serial_port() != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int middle = read_sensor(MIDDLE_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        // Log sensor data
        if (left != -1 && middle != -1 && right != -1) {
            log_sensor_data(left, middle, right);

            // Check for emergency stop condition
            if (left == 0 && middle == 0 && right == 0) {
                emergency_stop();
            }
        }

        // Delay for 100 milliseconds (10 Hz)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // This point should not be reached due to the infinite loop
    return 0;
}

